INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2436', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects credential dumping attempts targeting the NTDS.dit database by monitoring shadow copy creation, suspicious file access to %SystemRoot%\\NTDS\\ntds.dit, and the use of tooling like ntdsutil.exe or volume management APIs.", "external_references": [{"external_id": "AN1611", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0586#AN1611"}], "id": "x-mitre-analytic--1c715030-9564-482d-98b7-22072bf28c97", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1611", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Volume Shadow Copy Creation", "name": "WinEventLog:Microsoft-Windows-VSS", "x_mitre_data_component_ref": "x-mitre-data-component--dad75cc7-5bae-4175-adb4-ca1962d8650e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable for NTDS file location or backup paths if organization uses custom domain controller storage structure.", "field": "TargetFilePath"}, {"description": "Can suppress backup-related parent processes to reduce false positives.", "field": "ParentProcessName"}, {"description": "Temporal correlation between shadow copy creation and NTDS file access (e.g., 5 min window).", "field": "TimeWindow"}, {"description": "Tune based on expected privileged user/service account behavior.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2436', 0, 154, '09-mitre-attack', 'retrieved', 'F04C8FA5BA4605F93105544D56B02A6D2B7667B0EBAD0D3DA00E10F7164B5B30', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
