INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2438', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Initiation of remote desktop sessions via AnyDesk, TeamViewer, or Chrome Remote Desktop accompanied by unexpected user logins or system modifications", "external_references": [{"external_id": "AN0716", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0259#AN0716"}], "id": "x-mitre-analytic--1d46bf4d-a090-4865-9205-e271d223da42", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0716", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launch of remote desktop app or helper binary", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "network sessions initiated by remote desktop apps", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "App may be notarized and signed differently depending on distribution method (App Store vs .pkg)", "field": "process_signature"}, {"description": "If the remote desktop tool circumvents sandbox, it may produce additional telemetry in local TCC logs", "field": "sandbox_exception"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2438', 0, 121, '09-mitre-attack', 'retrieved', 'EFDBF254D908A8ECEF8197B21FAB37ED3FC654E597699FA5FD23CE9199A576B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
