VALUES ('doc-09-mitre-attack-p0-2439', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Password guessing attempts against web-based apps (e.g., Dropbox, Google Workspace) reflected in API or sign-in logs", "external_references": [{"external_id": "AN1526", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0551#AN1526"}], "id": "x-mitre-analytic--1d8bc80f-8719-41f0-a73e-127d6830f516", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1526", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Failed sign-in events", "name": "GCPAuditLogs:login.googleapis.com", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Which SaaS apps should be monitored for brute force attempts", "field": "AppContext"}, {"description": "Limit scope to enterprise domains or service accounts", "field": "EmailPattern"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2439', 0, 87, '09-mitre-attack', 'retrieved', 'C3951B81311085172AD29DF6124FC277D39E1E5A74BFDDBCD6CFA8F7B165B645', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
