INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2440', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe attempts to disable dedicated crypto hardware on network devices, often visible through anomalous CLI commands, unexpected firmware or configuration updates, and degraded encryption performance. Suspicious indicators include commands that alter hardware acceleration settings (e.g., disabling AES-NI or crypto engines), modification of system image files, or logs showing fallback from hardware to software encryption. Network traffic analysis may also reveal a sudden downgrade in throughput or cipher negotiation behavior consistent with the absence of hardware acceleration.", "external_references": [{"external_id": "AN1360", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0494#AN1360"}], "id": "x-mitre-analytic--1dd7c76f-ff71-4597-8785-f7a730101a00", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1360", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of commands disabling crypto hardware acceleration (e.g., ''no crypto engine enable'')", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Configuration changes referencing cryptographic hardware modules or disabling hardware acceleration", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Degraded encryption throughput or switch to weaker cipher suites compared to historical baselines", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines trusted administrator accounts allowed to modify encryption hardware settings; deviations trigger alerts.", "field": "AuthorizedAdminAccounts"}, {"description": "Expected performance metrics with hardware acceleration enabled; drops may indicate tampering.", "field": "BaselineThroughput"}, {"description": "Whitelist of vendor-signed firmware versions; unexpected updates could signal malicious modification.", "field": "ApprovedFirmwareVersions"}, {"description": "Period of correlation between configuration change and observed traffic downgrade; tunable to reduce false positives.", "field": "TimeWindow"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2440', 0, 230, '09-mitre-attack', 'retrieved', '8FF3E6F0ABCF37B5BC00C95EAD27AA2ABAFBC286E882361EF915EDD47A14248A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
