VALUES ('doc-09-mitre-attack-p0-2442', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Internal spearphishing via SaaS applications (e.g., Slack, Teams, Gmail): message sent from compromised user with attachment or URL, followed by click and credential access behavior.", "external_references": [{"external_id": "AN0150", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0054#AN0150"}], "id": "x-mitre-analytic--1e2211b9-1730-4645-89f6-11259b35e0a4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0150", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file_upload, message_send, message_click", "name": "saas:slack", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Volume or timing of messages sent after compromise", "field": "UserAnomalyThreshold"}, {"description": "Whether SaaS DLP assigns risk scores to attachments", "field": "FileRiskScoring"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2442', 0, 94, '09-mitre-attack', 'retrieved', '8DAF2F3D2C7FBA003EB7E495E006FBCE84583D2DB2E5E047B417B459D86FAA7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
