INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2443', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses a process to establish outbound connections that transmit uniform packet sizes at a consistent interval, avoiding threshold-based network alerts.", "external_references": [{"external_id": "AN0596", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0213#AN0596"}], "id": "x-mitre-analytic--1e9fdc71-d073-403a-9ee9-bab091318454", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0596", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "NetFlow/sFlow/PCAP", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum repetitive size in bytes to consider as anomalous behavior (e.g., 512B or 1024B)", "field": "PacketSizeThreshold"}, {"description": "Timeframe over which repeated, evenly spaced transfers are flagged", "field": "IntervalRepeatWindow"}, {"description": "Common ports expected to exhibit protocol behavior; outliers flagged if not matching expected usage", "field": "KnownServicePorts"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2443', 0, 119, '09-mitre-attack', 'retrieved', 'B60B965D82DE5BEF6C792F633945FC1A180DED21D1D9F046009AF631E4505658', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
