VALUES ('doc-09-mitre-attack-p0-2444', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Non-interactive system processes making encrypted HTTPS connections to well-known web services followed by high outbound traffic volume or scripted upload patterns.", "external_references": [{"external_id": "AN0101", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0035#AN0101"}], "id": "x-mitre-analytic--1edab644-3ec0-4c5d-bc26-18744fbc7a6e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0101", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "ssl.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Bias detection toward sessions with larger upload vs download volume", "field": "UploadDirectionality"}, {"description": "List of known public Web services used for dead drops or C2 (e.g., GitHub, Twitter)", "field": "HostnameRegexList"}, {"description": "Shell interpreter or automated job parent used for filtering (e.g., /usr/bin/python)", "field": "ScriptParentName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2444', 0, 123, '09-mitre-attack', 'retrieved', '8B89E8011