VALUES ('doc-09-mitre-attack-p0-2445', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Web protocol misuse such as encoded HTTP headers, WebSocket upgrade requests with abnormal payloads, or TLS handshake anomalies suggesting embedded C2 channels.", "external_references": [{"external_id": "AN0079", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0027#AN0079"}], "id": "x-mitre-analytic--1f1ed319-a6f9-4f30-9254-e0b1927a6bd9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0079", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "http.log, ssl.log, websocket.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Base64, hex, or UTF-16 encoding in URI, cookie, or host", "field": "HeaderEncodingPattern"}, {"description": "JA3 hash deviation from known clients", "field": "TLSFingerprintMismatch"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2445', 0, 93, '09-mitre-attack', 'retrieved', '86C2C943D9B82516BA67FEBF9398503F4C3EAC275562DFD88821708EA9F47282', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
