VALUES ('doc-09-mitre-attack-p0-2446', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "File access to NetworkManager connection configs and attempts to read PSK credentials from `/etc/NetworkManager/system-connections/*`.", "external_references": [{"external_id": "AN1281", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0464#AN1281"}], "id": "x-mitre-analytic--1f3a6d61-9658-4c9b-92af-5c711206e3fa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1281", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file read", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for filenames like *.nmconnection or profiles containing SSID names", "field": "FilenamePattern"}, {"description": "Distinguish between root/admin script usage vs. non-privileged terminal access", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2446', 0, 91, '09-mitre-attack', 'retrieved', 'A92AB58C7A3C4BE80295CB6EFD2BE5EA3E0C0548D51A036ACCB45D1FC2226279', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
