INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2447', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect abnormally high volume of inbound email messages or repetitive attachments being delivered to a single mailbox within a short time window. Defenders should look for anomalous spikes in message counts and repetitive attachment file creation events correlated with targeted users.", "external_references": [{"external_id": "AN1008", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0355#AN1008"}], "id": "x-mitre-analytic--1f515cf2-91a5-4bed-95a1-ed8fc8b24a87", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1008", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Send/Receive: Unusual spikes in inbound messages to a single recipient", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the aggregation interval (e.g., 5 minutes, 1 hour) for detecting spikes in inbound email traffic.", "field": "TimeWindow"}, {"description": "Defines maximum number of acceptable messages per user before triggering anomaly.", "field": "RecipientThreshold"}, {"description": "Defines the size threshold for repetitive attachments to be flagged.", "field": "AttachmentSizeThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2447', 0, 147, '09-mitre-attack', 'retrieved', '1E161E13BCEF96E828A11A6F9D48F9E4925F6D94F310395BAA6320D5577C47C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
