INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2449', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects deletion or overwriting of bash history, syslog, audit logs, and .ssh metadata following privilege elevation or suspicious process spawning.", "external_references": [{"external_id": "AN0521", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0184#AN0521"}], "id": "x-mitre-analytic--1fbe9da1-a760-4ac9-8ab0-59203a50fb82", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0521", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unlink, rename, open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "cleared or truncated .bash_history", "name": "linux:cli", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust based on syslog/auditd file paths (/var/log/messages, /var/log/audit/audit.log)", "field": "MonitoredPaths"}, {"description": "Scope to root/sudo usage or anomalous user behavior", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2449', 0, 98, '09-mitre-attack', 'retrieved', '68A1A0546AAD8D2739576C405B55278AEC1BAD4A950870179F523ECF6D5B71D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
