VALUES ('doc-09-mitre-attack-p0-2452', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of firewall changes using esxcli network firewall set or vSphere API modifications. Sudden disabling of firewall rules across management interfaces is a strong adversarial signal.", "external_references": [{"external_id": "AN0409", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0145#AN0409"}], "id": "x-mitre-analytic--1fecb6f7-e72f-452e-a078-3298cba8d481", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0409", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli network firewall set commands", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "vSphere API calls modifying firewall settings", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of authorized vSphere API methods for firewall configuration.", "field": "APIMethods"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2452', 0, 98, '09-mitre-attack', 'retrieved', 'A75696B4A1B76BE93B3F1359E91FE24A39FFD16F859196077E3B57BA153E9D54', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
