VALUES ('doc-09-mitre-attack-p0-2453', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of obfuscated commands via shell, osascript, or AppleScript interpreters using unusual tokens, encoding, variable substitution, or runtime string reconstruction.", "external_references": [{"external_id": "AN1396", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0505#AN1396"}], "id": "x-mitre-analytic--20157d55-1760-483c-a3b1-c6e219eeb75c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1396", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process:spawn, process:exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limits detection scope to shell or scripting interpreters like zsh, bash, osascript", "field": "InterpreterParentFilter"}, {"description": "Minimum entropy required to consider the command or script obfuscated", "field": "ScriptEntropyThreshold"}, {"description": "Deviation from baseline for long or highly nested arguments", "field": "ArgumentLengthDeviation"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2453', 0, 112, '09-mitre-attack', 'retrieved', '6DE85D3386F0628EB99B9EB7641155B4C402C3648CCA96BDAA8B8003854F0C29', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
