INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2455', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ransomware encrypts .vmdk, .vmx, .log, or VM config files in VMFS datastores. May rename to .locked or delete/overwrite with encrypted versions. Often correlates with shell commands run through `dcui`, SSH, or vSphere.", "external_references": [{"external_id": "AN0605", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0215#AN0605"}], "id": "x-mitre-analytic--203586e5-e178-4d41-bbae-93a86f04977b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0605", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "rename .vmdk to .*.locked|datastore write spike", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "openssl|tar|dd", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect renames or write patterns involving .vmdk, .vmx, .nvram.", "field": "FileType"}, {"description": "Identify shell sessions opened by root or unexpected users outside maintenance window.", "field": "UserContext"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2455', 0, 115, '09-mitre-attack', 'retrieved', '3642C348EA984079A30552019F78F3F33C7B1BCD8C0F4CFAE7BBE94B20657C34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
