INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2456', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized access to Windows Credential Manager through anomalous process execution (vaultcmd.exe, rundll32.exe keymgr.dll), suspicious API calls (CredEnumerateA), or direct file access to Credential Locker files. Correlates process creation with subsequent file reads of .vcrd/.vpol files under user Credential Locker directories.", "external_references": [{"external_id": "AN0378", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0134#AN0378"}], "id": "x-mitre-analytic--207b58a9-7e3b-41ca-bb5a-c66b24210a83", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0378", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Credential Locker paths such as %Systemdrive%\\Users\\*\\AppData\\Local\\Microsoft\\Credentials and %Systemdrive%\\Users\\*\\AppData\\Local\\Microsoft\\Vault", "field": "MonitoredPaths"}, {"description": "Correlation window between process execution, file access, and API calls", "field": "TimeWindow"}, {"description": "Baseline of expected administrative/service accounts with legitimate Credential Manager access", "field": "PrivilegedUsers"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2456', 0, 135, '09-mitre-attack', 'retrieved', 'CE4A01FFFBB4E9E4B2553CAF6B6546E2CA453FBE8318BB7FF2FEA3D48089A934', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
