INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2457', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of service management commands like `systemctl list-units`, `service --status-all`, or direct reading of `/etc/init.d`.", "external_references": [{"external_id": "AN1326", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0483#AN1326"}], "id": "x-mitre-analytic--20879a60-f16c-4a90-bd71-2c8865c99481", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1326", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Includes service enumeration commands like `systemctl`, `service`, or custom scripts.", "field": "CommandPattern"}, {"description": "Tunable by user context (e.g., root vs. standard user).", "field": "ExecutionUser"}, {"description": "Used for correlation with privilege escalation or lateral movement.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2457', 0, 97, '09-mitre-attack', 'retrieved', '84A55FF07153E7CFDF22D8F3FEE99E93A3659156E45E05B09A03C799C6544CA3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
