INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2458', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized changes to IAM authentication configurations such as disabling MFA, creating backdoor access keys, or altering trust policies. Correlates identity policy updates with unusual login behavior.", "external_references": [{"external_id": "AN0291", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0104#AN0291"}], "id": "x-mitre-analytic--20b6d23a-d1cc-494c-ac67-e7358835c674", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0291", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "UpdateLoginProfile", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "UpdateAccountPasswordPolicy", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline list of service accounts expected to modify IAM authentication policies.", "field": "ApprovedAccounts"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2458', 0, 92, '09-mitre-attack', 'retrieved', '07FA88D24947E03F9059ED294CB56A099D9AEECD66B2A67F24D6937D804FC74A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
