VALUES ('doc-09-mitre-attack-p0-2460', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual use of screen capture APIs (e.g., CopyFromScreen) or command-line tools to write image files to disk.", "external_references": [{"external_id": "AN0980", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0346#AN0980"}], "id": "x-mitre-analytic--20e00aff-6389-4c8a-8e38-3b63924e1612", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0980", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Depends on allowed parent process behaviors in the environment (e.g., explorer.exe vs powershell.exe)", "field": "ParentProcessName"}, {"description": "Can tune alert thresholds for rapid or scheduled screenshots (e.g., interval-based screen capture)", "field": "TimeWindow"}, {"description": "To detect file writes (e.g., .bmp, .png) that deviate from typical user activity", "field": "ImageExtension"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2460', 0, 116, '09-mitre-attack', 'retrieved', '770727478BE1BD35AFB39F37898CCA9A9EBCA00D2DD37B5D15BE41DF891B1BEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version