VALUES ('doc-09-mitre-attack-p0-2461', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unexpected encrypted outbound connections from management components or guest VMs using TLS, particularly after data volume spikes or script-based orchestration from within guest environments.", "external_references": [{"external_id": "AN1416", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0512#AN1416"}], "id": "x-mitre-analytic--20ecf7be-864a-4ae0-be66-cf26ffa9a217", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1416", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "event stream", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "egress logs", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected traffic routes for monitored VMs.", "field": "VMToEgressPathWatchlist"}, {"description": "Applications allowed to initiate TLS sessions from hypervisor level.", "field": "TLSClientAppIdentifier"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2461', 0, 99, '09-mitre-attack', 'retrieved', 'E806E7A330087CE4D9772103BE684FCE64F13CAB362BA2AD0A86E15F126635E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
