VALUES ('doc-09-mitre-attack-p0-2462', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Container process uses mounted cloud credentials or token cache to authenticate without known orchestration.", "external_references": [{"external_id": "AN0958", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0958"}], "id": "x-mitre-analytic--2127b359-24b0-40e2-a202-67e53d5be3b0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0958", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of cloud CLI tool (e.g., aws, az) inside container", "name": "docker:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "AssumeRole", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict to prod workloads or certain namespaces", "field": "ContainerLabel"}, {"description": "Path used to mount sensitive tokens (e.g., /.aws/credentials)", "field": "CredentialPath"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2462', 0, 95, '09-mitre-attack', 'retrieved', '427D787032546FFDFEFF2793D2CF6992C233EAD6F057B57FA24EA4508715E1D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
