INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2463', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the use of message-based injection by monitoring for sequences involving FindWindow (EnumWindows or EnumChildWindows), VirtualAllocEx or related API calls, combined with suspicious PostMessage/SendMessage (e.g., LVM_SETITEMPOSITION) use to SysListView32 controls, followed by LVM_SORTITEMS invocation instead of WriteProcessMemory.", "external_references": [{"external_id": "AN0941", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0331#AN0941"}], "id": "x-mitre-analytic--217128c5-144d-492b-ab72-bd0704348221", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0941", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=8", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "SendMessage, PostMessage, LVM_*", "name": "etw:Microsoft-Windows-Win32k", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines temporal distance between payload copy and execution trigger", "field": "TimeWindow_PostMessage_to_LVM_SORTITEMS"}, {"description": "Restrict detection to SysListView32 or similar GUI elements", "field": "TargetWindowClassName"}, {"description": "Adjusts detection sensitivity to users sending window messages across session boundaries", "field": "UserContextAnomalyThreshold"}, {"description": "Raise alert when rate of message-passing to foreign GUI processes exceeds baseline", "field": "InterprocessWindowMessagingFrequency"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2463', 0, 154, '09-mitre-attack', 'retrieved', '69A28926F6FA81AA9AB188F4FB23CFDF7904E07DE47E7CC37B04DA82B4DC3FE8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
