VALUES ('doc-09-mitre-attack-p0-2464', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access to shell history or GUI input state (xdotool, xinput) for presence validation prior to payload execution.", "external_references": [{"external_id": "AN1183", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0420#AN1183"}], "id": "x-mitre-analytic--21773356-1c94-4edc-b368-008c86a5929e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1183", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Reads of ~/.bash_history, ~/.mozilla, or access to /dev/input", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Execution of xev, xdotool, or input activity emulators", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of distinct user files accessed before trigger", "field": "ArtifactCountThreshold"}, {"description": "Suppress expected automation tools", "field": "KnownToolSignatures"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2464', 0, 100, '09-mitre-attack', 'retrieved', '8154AE72DFE26D43D6FC17B307609D8EF04E5FEA3255BBF6EC4686BA04DFC82B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
