INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2465', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Atypical access to Slack or Teams conversations via APIs, automation tokens, or bulk message export functionality, particularly after an account takeover or rare sign-in pattern. Often includes mass retrieval of chat history, download of message content, or scraping of workspace/channel metadata.", "external_references": [{"external_id": "AN1565", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0567#AN1565"}], "id": "x-mitre-analytic--222cf26f-e5cc-4b60-a7b2-39118b5c20d6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1565", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "conversations.history, files.list, users.info, audit_logs", "name": "saas:slack", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "UserLoggedIn", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time interval to observe post-login message scraping behavior", "field": "TimeWindow"}, {"description": "Number of messages or files accessed/downloaded to flag for review", "field": "MessageExportThreshold"}, {"description": "User privilege level, team membership, or role context to suppress false positives", "field": "UserContext"}, {"description": "Direct user access vs API token, OAuth app, or bot interaction", "field": "AccessMethod"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2465', 0, 148, '09-mitre-attack', 'retrieved', 'B5D5DAB50278F9CC1B8C695A7BD3C1A43DCF14227369B951491EBF370CC226B9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
