VALUES ('doc-09-mitre-attack-p0-2469', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use unified logs to identify processes issuing repeated DNS queries where the resolved IP addresses change frequently within very short TTL values. Correlate with outbound network traffic to validate C2-like patterns.", "external_references": [{"external_id": "AN1333", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0485#AN1333"}], "id": "x-mitre-analytic--22d28e80-ecae-4fa4-8901-ef9125c99e9f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1333", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Rapid domain-to-IP resolution changes for same domain", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Unexpected apps generating frequent DNS queries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Rate of IP churn per domain to trigger detection", "field": "DNSRotationRate"}, {"description": "Flag if domain was registered recently (e.g., < 30 days)", "field": "NewDomainThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2469', 0, 118, '09-mitre-attack', 'retrieved', '2EB06A3A89FEEC5A2A479FCDAFCD3DDFA7077DDC68A8EDA7B4A2AAD602EEAD2F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
