VALUES ('doc-09-mitre-attack-p0-2470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Modification of Thunderbird message filters file or execution of CLI tools (e.g., formail/procmail) that alter .forward behavior.", "external_references": [{"external_id": "AN1592", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0576#AN1592"}], "id": "x-mitre-analytic--22e6f5f4-e4cc-449c-9dba-280788935ce5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1592", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "/home/*/.bash_history", "name": "linux:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "User-based home directories; tune for specific user patterns.", "field": ".forwardPath"}, {"description": "Expected email client behavior may trigger similar file edits.", "field": "ExecContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2470', 0, 91, '09-mitre-attack', 'retrieved', '744CA21C4883DD1F295A44E3ED85A4FC18F4E92704811AB963487370C0EF8364', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
