VALUES ('doc-09-mitre-attack-p0-2471', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A remote source rapidly touches a short sequence of closed ports (SYN→RST/S0) on a Windows host. Within a short window the host changes firewall state (WFP rule added/modified or service starts listening) and then the same source completes the first successful handshake to the newly opened port.", "external_references": [{"external_id": "AN0842", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0302#AN0842"}], "id": "x-mitre-analytic--22ff1717-6ba8-4908-b795-edf0c41a997e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0842", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=2004, 2005, 2006", "name": "WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Seconds to correlate knock sequence → rule change → successful connect (60–300s typical).", "field": "TimeWindow"}, {"description": "Minimum number of distinct destination ports in the sequence (≥3 by default).", "field": "MinSequenceLen"}, {"description": "Accounts/processes allowed to adjust Windows Firewall (e.g., update agents).", "field": "RuleChangeAllowList"}, {"description": "Ports of interest to flag when opened (e.g., 22,23,2323,8022,3389,8080).", "field": "WatchedPorts"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2471', 0, 166, '09-mitre-attack', 'retrieved', '709C8E037287A598F680EDCF194400A9121D90653C712513E988794E4A48368D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
