VALUES ('doc-09-mitre-attack-p0-2474', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of domain group enumeration through command-line utilities such as ''net group /domain'' or PowerShell cmdlets, followed by suspicious access to API calls or LSASS memory.", "external_references": [{"external_id": "AN1025", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0360#AN1025"}], "id": "x-mitre-analytic--2385f397-5d17-4b37-ba07-bb52a52ff66c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1025", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjustable window to track chained discovery activity (e.g., 5-10 minutes).", "field": "TimeWindow"}, {"description": "Tune to focus on non-admin users or service accounts performing enumeration.", "field": "UserContext"}, {"description": "How far back the parent-child process chain is correlated.", "field": "ProcessLineageDepth"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2474', 0, 119, '09-mitre-attack', 'retrieved', '27D34854219E0B319B726C2EFC351AFA8ADD667B6AF52040626B0BDB14D92756', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
