VALUES ('doc-09-mitre-attack-p0-2475', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor sensitive data files such as plist-based storage, mail archives, or Office files for unexpected modifications. Detect anomalous processes modifying stored data outside expected update cycles using FSEvents and Unified Logs.", "external_references": [{"external_id": "AN0557", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0193#AN0557"}], "id": "x-mitre-analytic--23b6aee9-90fc-46b8-bf8b-36043218f393", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0557", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unexpected creation or modification of stored data files in protected directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "CREATE, DELETE, WRITE: Stored data manipulation attempts by unauthorized processes", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline hash values or metadata for stored data files to detect manipulation.", "field": "FileIntegrityBaseline"}, {"description": "Whitelisted applications permitted to update stored data (e.g., Outlook, MySQL).", "field": "AllowedEditors"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2475', 0, 129, '09-mitre-attack', 'retrieved', '6761A26F75B78DFF96EE2160CF037254D52FB2C9C4EDDEEE57E3B