VALUES ('doc-09-mitre-attack-p0-2476', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Token creation or access delegation where a user impersonates a higher-privileged service account or performs domain-wide delegation actions, such as GCP''s serviceAccountTokenCreator or Workspace impersonation.", "external_references": [{"external_id": "AN1106", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0393#AN1106"}], "id": "x-mitre-analytic--23b9a5cd-9c49-48d8-9d0d-71e35ad78337", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1106", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PrincipalEmail with serviceAccountTokenCreator impersonating new identity", "name": "gcp:iam", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "Token Generation via Domain Delegation", "name": "gcp:workspaceaudit", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on legitimate service accounts allowed to impersonate user accounts.", "field": "userEmailFilter"}, {"description": "Limit delegated access to specific scopes relevant to business functions.", "field": "delegatedScope"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2476', 0, 113, '09-mitre-attack', 'retrieved', 'B1FD4694E9742C4D8A3F4B26E06B9E9D3BCFF0EA407684DD6A6094DC7882CE6E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved"