VALUES ('doc-09-mitre-attack-p0-2477', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider analyzing code signing certificates for features that may be associated with the adversary and/or their developers, such as the thumbprint, algorithm used, validity period, common name, and certificate authority. Malware repositories can also be used to identify additional samples associated with the adversary and identify patterns an adversary has used in procuring code signing certificates.\nMuch of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related follow-on behavior, such as [Code Signing](https://attack.mitre.org/techniques/T1553/002) or [Install Root Certificate](https://attack.mitre.org/techniques/T1553/004).", "external_references": [{"external_id": "AN2007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0875#AN2007"}], "id": "x-mitre-analytic--23b9c988-be01-4092-b9c4-0ddec8d58891", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 2007", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "Malware Repository", "x_mitre_data_component_ref": "x-mitre-data-component--93a6e38c-02a5-44d8-9035-b2e08459f31f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2477', 0, 137, '09-mitre-attack', 'retrieved', '2B764EE8CD4B45464BE37EDAE6EB59E79D8DD9DD786BA6E56246D697F5BA2026', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
