INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2478', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Credential stuffing attempts against Kubernetes API or containerized login shells using stolen or leaked user credentials", "external_references": [{"external_id": "AN1268", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1268"}], "id": "x-mitre-analytic--23c7fff8-de08-49dd-a101-0c35ad40bd7e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1268", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authentication.k8s.io/v1beta1", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect attempts across multiple pods/namespaces using same IP", "field": "PodAccessScope"}, {"description": "Number of username/password pairs used in attack attempt", "field": "CredentialSetSize"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2478', 0, 83, '09-mitre-attack', 'retrieved', '85DCACC42A778E02B80E1F4A6341D03027B212EC7424985729446B26967CAF1F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
