VALUES ('doc-09-mitre-attack-p0-2480', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of domain groups using dscacheutil or dscl commands, often following initial login or domain trust queries.", "external_references": [{"external_id": "AN1027", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0360#AN1027"}], "id": "x-mitre-analytic--23fa40ac-79d0-400a-a017-8e06cfc67e6c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1027", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how strictly command patterns must match known enumeration syntax.", "field": "CommandSignatureThreshold"}, {"description": "Adjustable window to correlate chained behavior such as group enumeration followed by user targeting.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2480', 0, 93, '09-mitre-attack', 'retrieved', 'F121B2F4D07C20396E565966FDD468C11D9A09CEA781ABFFBC51A874BCC99287', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
