INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2482', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Tools such as `tor`, `nglite`, `proxychains`, `chisel`, or custom daemons repeatedly initiate outbound sessions to multiple nodes before final destination. This behavior is abnormal for Linux services outside of VPN, monitoring, or CDN relay contexts.", "external_references": [{"external_id": "AN1021", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0359#AN1021"}], "id": "x-mitre-analytic--2416a634-3ad9-4f91-a894-8fb0d9d83b76", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1021", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve for proxy tools", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "conn.log + ssl.log with Tor fingerprinting", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Forwarded packets log", "name": "Netfilter/iptables", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match known proxy tools, tuned for environment.", "field": "ExecutablePath"}, {"description": "Detect outbound chaining behavior through >2 IPs in short succession.", "field": "RelayCount"}, {"description": "Allow filtering by ICMP, TCP/443, UDP for obfuscation channels.", "field": "ProtocolType"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2482', 0, 137, '09-mitre-attack', 'retrieved', 'C903FFD70F680F97A82C46062BD8FC8C5FA98C04CDED36E0BAD3BBB00D9A9956', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
