VALUES ('doc-09-mitre-attack-p0-2485', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of account enumeration through directory service queries or system utilities accessing account metadata stores, followed by structured enumeration output.", "external_references": [{"external_id": "AN1614", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1614"}], "id": "x-mitre-analytic--24aa5ee9-ba7f-4991-b32a-27d40ee2d010", "modified": "2026-05-12T16:30:18.376Z", "name": "Analytic 1614", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process event", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "DirectoryService queries retrieving account information", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for dscl -list, dscacheutil -q user, id -un, etc.", "field": "CommandLine"}, {"description": "Alert if enumeration is performed in non-console session or by unusual users.", "field": "ExecutionContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-2485', 0, 106, '09-mitre-attack', 'retrieved', '1EDBA9F6A3C4F72368C1675DC3D1A48168EF41C7DBD91FCA096DBE40F379B00D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
