VALUES ('doc-09-mitre-attack-p0-2486', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor scp, rsync, curl, sftp, or ftp processes initiating transfers to internal systems combined with file creation events in unusual directories. Correlate transfer activity with subsequent execution of those binaries.", "external_references": [{"external_id": "AN0517", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0183#AN0517"}], "id": "x-mitre-analytic--24af9441-602e-4202-a2e7-04a46c008406", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0517", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Invocation of scp, rsync, curl, or sftp", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "create: New file created in system binaries or temp directories", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define legitimate transfer utilities expected in the environment", "field": "AllowedTools"}, {"description": "Restrict to suspicious or non-standard directories for transferred files", "field": "DestinationDirectories"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2486', 0, 120, '09-mitre-attack', 'retrieved', '2568C4F0361B9659B97D5BFC18FAFE9E2D951500DF1B5F8DFDF37C96C27F17BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_vers