VALUES ('doc-09-mitre-attack-p0-2488', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Same source IP performing multiple authentication attempts using known breached username/password combinations across different identities in Azure AD, Okta, or Duo", "external_references": [{"external_id": "AN1265", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1265"}], "id": "x-mitre-analytic--24e6cefb-6e1c-4676-9bb8-74f6a731703c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1265", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "status = failure", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Optional enrichment using known leaked credentials database", "field": "BreachedCredentialSourceMatch"}, {"description": "Targeting only federated or hybrid identity auth flows", "field": "SSOServiceScope"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2488', 0, 90, '09-mitre-attack', 'retrieved', 'C76E7721727BDD0B6B9ADFA5A1153AFD720A799CD7153AC7C3260757CB3F8114', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
