VALUES ('doc-09-mitre-attack-p0-2489', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor Office Suite applications (Outlook, Word mail merge, Excel macros) for abnormal automated message sending, especially when macros or scripts trigger email delivery. Detect patterns of impersonation language (urgent, payment, executive request) combined with anomalous execution of Office macros.", "external_references": [{"external_id": "AN0796", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0286#AN0796"}], "id": "x-mitre-analytic--250d2977-7b94-4041-a299-0f2f1532eb95", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0796", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SendOnBehalf/SendAs: Office Suite initiated messages using impersonated identities", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for correlating macro execution with email sending activity.", "field": "MacroExecutionThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2489', 0, 104, '09-mitre-attack', 'retrieved', '93C24B71D7701AD8D76D8C22D6C1E762592C54B5C541A6D1A5A3EDD31D344C26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
