VALUES ('doc-09-mitre-attack-p0-2490', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process/script execution of systemsetup -gettimezone, date, ioreg, or API usage (timeIntervalSinceNow, gettimeofday) followed by time-based scheduling (launchd plist modification) or sleep-based execution.", "external_references": [{"external_id": "AN0432", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0151#AN0432"}], "id": "x-mitre-analytic--252e5c07-8ae0-4ef8-9a98-c11b6c6d4d46", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0432", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process exec events of systemsetup, date, ioreg with command_line parameters indicating time discovery", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "New/modified launchd plist (persistence/scheduling) within TimeWindow after time query", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organization-specific list of allowed launchd write locations to filter benign agents.", "field": "LaunchdPaths"}, {"description": "Correlation window to link time discovery to launchd persistence/scheduling.", "field": "TimeWindow"}, {"description": "Known management agents (e.g., JAMF) that legitimately call systemsetup/date.", "field": "AllowedCallers"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2490', 0, 131, '09-mitre-attack', 'retrieved', '40A0B59871848B012F68AFA2708C0911E9288383A0D3E03EEBF44D4D1553C7A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
