VALUES ('doc-09-mitre-attack-p0-2494', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Phishing attempts via iCloud Mail, Gmail, or social media apps accessed on macOS systems. Defender view includes Mail.app or Safari downloads of files followed by osascript, Terminal, or abnormal child process execution.", "external_references": [{"external_id": "AN0322", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0115#AN0322"}], "id": "x-mitre-analytic--262ce2a7-2c09-4f6d-8e9f-de57b814a2a2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0322", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Received messages containing embedded links or attachments from non-enterprise services", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Execution of osascript, bash, or Terminal initiated from Mail.app or Safari", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Suspicious outbound HTTPS requests to domains flagged as newly registered or untrusted after spearphishing message interaction", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flagging mismatched or self-signed certificates during outbound connections initiated after spearphishing messages.", "field": "CertificateChecks"}, {"description": "Window of time between attachment download and subsequent suspicious execution.", "field": "ExecutionDelay"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2494', 0, 151, '09-mitre-attack', 'retrieved', '2C1BA758F839CCE2E51D172A12E8E70F774F21FBE4A12A4288ABF68118C8AAF5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
