VALUES ('doc-09-mitre-attack-p0-2495', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Node.js or JavaScript interpreter execution from web shells, cron jobs, or local users. Correlates execution with reverse shell behavior, file modifications, or abnormal outbound connections.", "external_references": [{"external_id": "AN0735", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0264#AN0735"}], "id": "x-mitre-analytic--26520d1c-1e0a-443b-817e-7ec1846a0476", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0735", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/syslog", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Script launched from /tmp, /var/tmp, or hidden dot directories.", "field": "ScriptPath"}, {"description": "Custom compiled JS binaries like node_shell or interpreter disguises.", "field": "BinaryName"}, {"description": "Execution by service accounts or low-privilege users running cron scripts.", "field": "UserExecutionContext"}, {"description": "Connection attempts to C2 post-node.js execution.", "field": "NetworkFollowUp"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2495', 0, 123, '09-mitre-attack', 'retrieved', '1CE862B592377AC3A469E96156D06033F37EF0E528C344EC121520619A2BFE86', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
