VALUES ('doc-09-mitre-attack-p0-2496', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects access to SSSD or Quest VAS cached credential databases using tdbdump or other file access patterns, requiring sudo/root access.", "external_references": [{"external_id": "AN1418", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0513#AN1418"}], "id": "x-mitre-analytic--26940057-e464-49f9-8f76-ceaca4b9d982", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1418", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EXECVE", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "process_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "SSSD and Quest cache paths differ by deployment and OS variant.", "field": "filepath"}, {"description": "Tunable to capture specific tools (e.g., tdbdump, cat) or scripts accessing cache files.", "field": "CommandLine"}, {"description": "Time between elevation and file access can be adjusted to account for legitimate system behavior.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2496', 0, 125, '09-mitre-attack', 'retrieved', '593F3D84413180D59F61D166C8AEC7E4B4C