VALUES ('doc-09-mitre-attack-p0-2497', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution patterns where a child process is detached from its original parent, often showing up under ''launchd'' (PID 1) with no parent lineage. These breakages in the process tree are indicative of evasive techniques using `daemon()`, `fork()` or background execution flags.", "external_references": [{"external_id": "AN1224", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0443#AN1224"}], "id": "x-mitre-analytic--269ab5e4-4c45-4f7a-8d82-c235492ff83a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1224", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process creation with parent PID of 1 (launchd)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Detached process execution with no associated parent", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Triggering PID used to flag abnormal child adoption (commonly PID 1)", "field": "AnomalyParentPID"}, {"description": "Allowlist of background daemons legitimately using launchd as parent", "field": "AllowedServices"}, {"description": "Entropy score threshold for abnormal process names in detached state", "field": "ProcessNameEntropy"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2497', 0, 145, '09-mitre-attack', 'retrieved', '0C572B96C198D9CC7394FE902B3A9C3FAE7237B820E6F715C48951EB87A69B03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
