VALUES ('doc-09-mitre-attack-p0-2498', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects interactive or service logins from local accounts outside expected operational context or at anomalous times.", "external_references": [{"external_id": "AN1138", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0407#AN1138"}], "id": "x-mitre-analytic--269f36b6-77fa-4959-9e63-e30036c991d7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1138", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "USER_LOGIN", "name": "auditd:USER_LOGIN", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "sshd login", "name": "linux:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define operational hours or expected login times per host.", "field": "TimeWindow"}, {"description": "Differentiate expected behavior for server vs. workstation.", "field": "HostRole"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2498', 0, 90, '09-mitre-attack', 'retrieved', '9CB0C0FE947917D85FE590F05D20E088CE22E7193F48A400FF69A3C8628A38A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
