VALUES ('doc-09-mitre-attack-p0-2499', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects hijacking of an existing thread (OpenThread) through a behavioral chain involving thread suspension (SuspendThread), memory modification (VirtualAllocEx + WriteProcessMemory), context manipulation (SetThreadContext), and thread resumption—all within another live process''s address space (ResumeThread).", "external_references": [{"external_id": "AN0822", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0295#AN0822"}], "id": "x-mitre-analytic--26ef9aef-33eb-4df2-ba82-6ace95173c80", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0822", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=8", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "API Calls", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Sensitive processes that should never be targeted for thread hijack attempts", "field": "TargetProcessList"}, {"description": "Expected delay between SuspendThread and ResumeThread events; tight thresholds reduce evasion", "field": "TimeWindow"}, {"description": "Memory regions or offsets that should not be targeted for SetThreadContext", "field": "SuspiciousThreadContextRegions"}, {"description": "Score deviation of the parent/child relationship in a thread injection chain", "field": "ParentProcessAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2499', 0, 153, '09-mitre-attack', 'retrieved', '7AAAF0EA7F780AE78D28C9589DDF6B9511CF796F627539F0A314796AF08D3B18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
