VALUES ('doc-09-mitre-attack-p0-2500', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Reading of sensitive files like .bash_history, /etc/shadow, or private key directories by unauthorized users or unusual processes.", "external_references": [{"external_id": "AN1154", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0412#AN1154"}], "id": "x-mitre-analytic--27213df4-c761-4745-b8ef-f91a46966eb9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1154", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read system calls to ~/.bash_history or /etc/shadow", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execution of tools like cat, grep, or awk on credential files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths to credential files such as /etc/shadow or ~/.bash_history", "field": "SensitivePaths"}, {"description": "Whether the process runs under a privileged or non-interactive session", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2500', 0, 109, '09-mitre-attack', 'retrieved', '71BF2C620EB2D57B3D9E1C9A15DB4B334045E8D1947F7E44AA653A61003479CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
