VALUES ('doc-09-mitre-attack-p0-2501', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of trusted system binaries (e.g., `split`, `tee`, `bash`, `env`) used in uncommon sequences or chained behaviors to execute malicious payloads or perform actions inconsistent with normal system or script behavior.", "external_references": [{"external_id": "AN0227", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0081#AN0227"}], "id": "x-mitre-analytic--273d7b27-6b7d-4017-a7f6-0cd02fd3a128", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0227", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Binaries like `split`, `tee`, `env`, `awk`, `gzip`, often used in benign scripts", "field": "TrustedBinaryList"}, {"description": "Outlier model for process tree and command arguments", "field": "AnomalyScore"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2501', 0, 108, '09-mitre-attack', 'retrieved', '072EA6E672F1FC6EC3089C54B6CD84329EECE9A25E6EEE0EB7824545D652E728', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
