VALUES ('doc-09-mitre-attack-p0-2502', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged cookies on macOS may show up as abnormal access to Safari/Chrome cookie databases in ~/Library/Cookies, combined with unexpected logon sessions authenticated by those cookies. Unified Logs may show cookie injection events or abnormal access patterns to Keychain when linked to browser authentication flows.", "external_references": [{"external_id": "AN0486", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0171#AN0486"}], "id": "x-mitre-analytic--27a0146c-0af8-4323-9c41-fbd3df9af1fa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0486", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Abnormal process access to Safari or Chrome cookie storage", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "New session initiated using cookies without normal MFA or password validation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Applications permitted to use Keychain to generate cookies or tokens.", "field": "AuthorizedKeychainApps"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2502', 0, 126, '09-mitre-attack', 'retrieved', 'D1609CA44F4520E942AE2F2E5A13274AADA9AA771181EB54656EA7D312934172', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
