VALUES ('doc-09-mitre-attack-p0-2503', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious processes initiating encrypted HTTPS connections to common web service domains, followed by abnormal data upload behavior or automated posting behavior indicative of C2 bidirectional traffic.", "external_references": [{"external_id": "AN0100", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0035#AN0100"}], "id": "x-mitre-analytic--27bd3e33-9a61-4dfb-9fba-205a6c880264", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0100", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "HTTPS Inspection", "name": "etw:Microsoft-Windows-WinINet", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Timeframe for evaluating multiple network connections tied to the same process", "field": "TimeWindow"}, {"description": "Regex or string patterns used to identify common Web service infrastructure (e.g., *.googleapis.com)", "field": "DomainPattern"}, {"description": "Minimum data upload size before flagging anomaly", "field": "PayloadSizeThreshold"}, {"description": "Known benign updaters or service processes to reduce false positives", "field": "ProcessNameExclusionList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2503', 0, 138, '09-mitre-attack', 'retrieved', '8FF5C8231D4176024E13BED5057B0E7C23D0629F9987D52B49C9F414FF2911BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
