VALUES ('doc-09-mitre-attack-p0-2504', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects local staging behavior via snapshot creation or files written into VMFS partitions by scripts or unauthorized shell access.", "external_references": [{"external_id": "AN0727", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0261#AN0727"}], "id": "x-mitre-analytic--27caeb90-1cf0-4650-a3f3-c8a1edaecbab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0727", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "snapshot create/write events", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3da222e6-53f3-451c-a239-0b405c009432"}, {"channel": "CLI usage logs", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Rapid creation or deletion of snapshots", "field": "SnapshotThreshold"}, {"description": "Unexpected CLI/script invocation outside maintenance windows", "field": "CLIInvoker"}, {"description": "Volume of data written locally in short time", "field": "VMFSWriteRate"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2504', 0, 103, '09-mitre-attack', 'retrieved', '462CB0832E298DD1B28AA4ABB41A77E71BB73190D0A117A9B0A2FE66C1E84E76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
