VALUES ('doc-09-mitre-attack-p0-2505', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for file access to certificate directories, commands invoking OpenSSL or PKCS#12 utilities to export or modify certificates, and processes accessing sensitive key storage paths.", "external_references": [{"external_id": "AN0672", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0240#AN0672"}], "id": "x-mitre-analytic--27cbe2a7-25a0-4f6d-b2b0-dff50b2c0883", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0672", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read: /etc/ssl/, /etc/pki/, ~/.pki/nssdb/", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve: openssl pkcs12, certutil, keytool", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exempt trusted automated services regularly accessing PKI stores.", "field": "PathExclusions"}, {"description": "Differentiate root/system accounts versus user-level access to key material.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2505', 0, 107, '09-mitre-attack', 'retrieved', '05DF058F02BB35809EF6D736ED388B17C5142AA9CD83396732EA652F477274E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
