INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2506', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe suspicious SNMP MIB enumeration through abnormal queries for large sets of OIDs, repeated SNMP GETBULK/GETNEXT requests, or queries originating from non-administrative IP addresses. Anomalous use of community strings, authentication failures, or enumeration activity outside maintenance windows may also indicate attempts to dump MIB contents. Correlation across syslog, NetFlow, and SNMP audit data can reveal chains of behavior such as repeated authentication failures followed by successful large-scale OID retrieval.", "external_references": [{"external_id": "AN1249", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0453#AN1249"}], "id": "x-mitre-analytic--282d9231-942a-4b97-875c-659aa2c41971", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1249", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Authentication failures, unexpected community string usage, or unauthorized SNMPv1/v2 requests", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "High-volume or repeated SNMP GETBULK/GETNEXT queries from untrusted or external IPs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "SNMP configuration changes, such as enabling read/write access or modifying community strings", "name": "networkdevice:audit", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected IP ranges allowed to query SNMP. Deviation indicates possible misuse.", "field": "AuthorizedAdminIPs"}, {"description": "Baseline frequency and volume of SNMP queries; anomalies above threshold may indicate dumping.", "field": "NormalSNMPQueryRate"}, {"description": "Expected community strings (e.g., hashed or custom values). Unrecognized strings may signal abuse.", "field": "CommunityStringPatterns"}, {"description": "Time periods during which SNMP queries are authorized. Queries outside these hours may be malicious.", "field": "TimeWindow"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2506', 0, 223, '09-mitre-attack', 'retrieved', '9A32361D85F29AEBE3AB92F4270466962301207B346C34BC6669CE33945838AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
