INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2507', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes (e.g., bash, python, custom binaries) dynamically linking libcrypto/libssl for RSA key exchange, then creating external connections with abnormal certificate validation or handshake anomalies. Defender observes syscall traces and outbound asymmetric key exchanges from non-SSL-native processes.", "external_references": [{"external_id": "AN1497", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0543#AN1497"}], "id": "x-mitre-analytic--284edcb8-0141-4fe6-afb2-9fd8a2b82b49", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1497", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve or socket/connect system calls for processes using RSA handshake", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Non-standard processes negotiating SSL/TLS key exchanges", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Processes linked with libssl/libcrypto performing network activity", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline libraries that normally handle asymmetric crypto.", "field": "ExpectedCryptoLibs"}, {"description": "Threshold for client-heavy data sending vs server.", "field": "TrafficAsymmetryRatio"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2507', 0, 133, '09-mitre-attack', 'retrieved', '8D7EC65A25935DE2F40D655DA85580B63FEB396026184F8D56B67E90D255B6EC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
