VALUES ('doc-09-mitre-attack-p0-2508', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of network scanning utilities or scripts performing rapid connections to multiple services or hosts using auditd and netflow/pcap telemetry.", "external_references": [{"external_id": "AN1058", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0376#AN1058"}], "id": "x-mitre-analytic--287661d0-714e-4bb4-a9f7-c272ad0018b1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1058", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound TCP SYN or UDP to multiple ports/hosts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines number of ports targeted per host within a short period.", "field": "PortScanThreshold"}, {"description": "Regex to match common scanner arguments (e.g., `nmap -sS`, `nc -zv`).", "field": "ToolPatternRegex"}, {"description": "Trusted IPs or systems performing routine discovery.", "field": "ExpectedScanSources"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2508', 0, 117, '09-mitre-attack', 'retrieved', '31186ED439BCC269487E961FFCDFCEECADEEAB43EABBBE2196CCC3E6BECFA0C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
