VALUES ('doc-09-mitre-attack-p0-2509', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious SVG file creation or download events followed by script engine execution (e.g., wscript.exe, mshta.exe, rundll32.exe), network callbacks, or browser-based credential collection.", "external_references": [{"external_id": "AN1407", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0510#AN1407"}], "id": "x-mitre-analytic--288a28ac-e1e4-4e7e-9156-d3b975ed45ed", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1407", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold between SVG file write and script execution (e.g., < 60s)", "field": "TimeWindow"}, {"description": "Allowlisted script engines that may invoke browsers or JS in benign cases", "field": "ParentProcessWhitelist"}, {"description": "Regex or string match for .svg, .svgz, or embedded .svg inside HTML or PDF", "field": "FileExtensionPattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2509', 0, 127, '09-mitre-attack', 'retrieved', 'C1FFFBE4E57A6F2823035C7E455D286D5ACCFE20F6BC05B74EC8BEDFFC2673BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
