VALUES ('doc-09-mitre-attack-p0-2510', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects rsync or scp inbound from other hosts that then aggregate content into /Users/Shared or /private/tmp, often involving compressed files or scripts.", "external_references": [{"external_id": "AN0196", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0071#AN0196"}], "id": "x-mitre-analytic--2891bd53-5a81-4330-bb05-ffd731868d06", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0196", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "remote login and transfer", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored remote-to-local write destinations such as /Users/Shared", "field": "StagingPaths"}, {"description": "Presence of .zip, .7z, or tar.gz indicating consolidation", "field": "CompressionIndicators"}, {"description": "Temporal correlation of transfer and staging write operations", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2510', 0, 116, '09-mitre-attack', 'retrieved', '5CCDECE81DC4C87660F486DD2B03728BEACB689CB2205C