VALUES ('doc-09-mitre-attack-p0-2512', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlated use of sleep/delay mechanisms (e.g., kernel32!Sleep, NTDLL APIs) in short-lived processes, combined with parent processes invoking suspicious scripts (e.g., wscript, powershell) with minimal user interaction.", "external_references": [{"external_id": "AN1048", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0372#AN1048"}], "id": "x-mitre-analytic--28e26a6a-e470-4f1c-845f-f2cbd816a1f7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1048", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Delay duration that distinguishes benign scripts from evasive behavior.", "field": "TimeWindow"}, {"description": "Legitimate parent-child combinations may differ across environments.", "field": "ParentProcessName"}, {"description": "Different APIs may be used to invoke sleep (e.g., Sleep, NtDelayExecution).", "field": "SleepFunctionPattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2512', 0, 113, '09-mitre-attack', 'retrieved', '3E7B3FED43E5C222538A2AA03D0013D32575A69C1F8E4F55C41CFBF88741290A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
