VALUES ('doc-09-mitre-attack-p0-2513', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Bonjour-based mDNS enumeration or use of system tools (e.g., dns-sd, nmap) to find active services via multicast probing or targeted scans.", "external_references": [{"external_id": "AN1059", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0376#AN1059"}], "id": "x-mitre-analytic--28fbe1b0-9663-4997-9d4e-ef43803be114", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1059", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dns-sd, mDNSResponder, socket activity", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "mDNS queries such as _ssh._tcp.local that may indicate service discovery.", "field": "MDNSServiceQueryPatterns"}, {"description": "Adjust alerting based on whether discovery activity originates from a background daemon vs. interactive session.", "field": "UserContext"}, {"description": "Expected tools that could trigger mDNS or TCP/UDP scans (e.g., dns-sd, nmap).", "field": "ScanToolList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2513', 0, 122, '09-mitre-attack', 'retrieved', '82E3A41FEB75D42AB1E4A29C1F4100BB1E256FC8FF628031FA08758A7A33B5E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
