VALUES ('doc-09-mitre-attack-p0-2514', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unsigned processes accessing system memory or launching known credential scraping tools (e.g., osascript, dylib injections) to access the Keychain or sensitive memory regions.", "external_references": [{"external_id": "AN0650", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0234#AN0650"}], "id": "x-mitre-analytic--29370f2b-0877-458c-8ade-a9a23b8fb7b2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0650", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Code Execution & Entitlement Access", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "Access to Keychain DB or system.keychain", "name": "macos:keychain", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Invocation of osascript or dylib injection", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to watch for abnormal access, e.g., /Library/Keychains/", "field": "KeychainAccessPath"}, {"description": "Filter out signed/trusted binaries.", "field": "SignedBinaryStatus"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2514', 0, 112, '09-mitre-attack', 'retrieved', 'F356331E25CFA1C40909F7210E78755B059C5AAC5B1A8C996AA0B9BD5A6C82A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
