VALUES ('doc-09-mitre-attack-p0-2515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Automated execution of native utilities and scripts to discover, enumerate, and exfiltrate files and clipboard content. Focus is on detecting repeated file access, scripting engine use, and use of command-line utilities commonly leveraged by collection scripts.", "external_references": [{"external_id": "AN0531", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0186#AN0531"}], "id": "x-mitre-analytic--29433de9-360e-4189-9f6d-fb00c9a57e41", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0531", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the lookback period for identifying burst activity or patterns in process/file events.", "field": "TimeWindow"}, {"description": "Tunable list of file extensions associated with collection (e.g., .pdf, .docx).", "field": "SuspiciousFileExtensions"}, {"description": "The number of times a process executes before considered anomalous.", "field": "ProcessCountThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2515', 0, 130, '09-mitre-attack', 'retrieved', '5DC8D0ED8862FA4F0766A2EF770215BAAA93C492469FFBE06F006AAD1DBC4BC2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
