VALUES ('doc-09-mitre-attack-p0-2516', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders can identify PowerShell profile-based persistence by correlating file creation or modification in known profile locations with subsequent PowerShell process launches that do not use the `-NoProfile` flag. Profile scripts loading unusual modules or launching external programs, particularly under elevated contexts, are suspicious and may represent adversary persistence or privilege escalation.", "external_references": [{"external_id": "AN1245", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0451#AN1245"}], "id": "x-mitre-analytic--298d1a46-ec12-4cd2-acce-7e0f849c384d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1245", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Execution of PowerShell without -NoProfile flag", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom PowerShell host profiles or redirection to alternate profile paths", "field": "ProfilePathList"}, {"description": "Whether profile execution occurs under elevated user (e.g., Administrator, SYSTEM)", "field": "ExecutionContext"}, {"description": "Specific modules or external programs loaded within profile", "field": "ModuleOrScriptName"}, {"description": "Correlation time between profile modification and PowerShell process start", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2516', 0, 168, '09-mitre-attack', 'retrieved', 'A929FB2B834768FA990AA74D305345E57ED2DDC7C1DB04B001F2DE72DD9A6D2B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
