VALUES ('doc-09-mitre-attack-p0-2517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Insertion of public keys into authorized_keys using bash/zsh or editor tools, correlated with suspicious process ancestry.", "external_references": [{"external_id": "AN0351", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0126#AN0351"}], "id": "x-mitre-analytic--29988e3f-2f65-4fe5-9bf7-dae0cb869fc6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0351", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process: exec + filewrite: ~/.ssh/authorized_keys", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "~/.ssh/authorized_keys", "name": "macos:auth", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track unusual parent process writing to SSH config (e.g., curl -> bash)", "field": "ParentProcess"}, {"description": "Flag whether shell session was interactive (normal) or spawned remotely (potential abuse)", "field": "InteractiveSessionFlag"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2517', 0, 101, '09-mitre-attack', 'retrieved', '65366001079BF34977D5A7376E77006CC921036EEC31099AF8286A92669E23F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
