VALUES ('doc-09-mitre-attack-p0-2518', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual TLS tunnels through ports not normally encrypted (e.g., TLS on port 8080, 53). Defender sees NetFlow/IPFIX or packet inspection indicating high-entropy traffic volumes and asymmetric client/server exchange ratios.", "external_references": [{"external_id": "AN0763", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0273#AN0763"}], "id": "x-mitre-analytic--29a00bef-79bd-4eb9-bf92-01651cffe9b0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0763", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Session records with TLS-like byte patterns", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Abnormal certificate chains or non-standard ports carrying TLS", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define expected TLS port usage to flag anomalies.", "field": "PortProfiles"}, {"description": "Sent/received byte thresholds to catch hidden C2.", "field": "TrafficAsymmetryRatio"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2518', 0, 114, '09-mitre-attack', 'retrieved', '7EC7BFA13FD84BB225FCFEDC8CBFE86310D5BAD49214088DA4C9EC1284253D0D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
