VALUES ('doc-09-mitre-attack-p0-2519', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-23T14:51:50.859Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Observation of scripted network requests (e.g., using osascript, curl, or python) that include mismatched or spoofed browser User-Agent strings compared to the typical macOS Safari or Chrome baseline, especially when triggered by non-interactive launch agents, login hooks, or background daemons.", "external_references": [{"external_id": "AN2032", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0898#AN2032"}], "id": "x-mitre-analytic--29ca0e06-e848-44cd-821a-24576276a8af", "modified": "2025-10-24T15:10:57.546Z", "name": "Analytic 2032", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "network connection events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Inbound HTTP POST with suspicious payload size or user-agent", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "exec logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag browser-based sessions", "field": "UserAgentFingerprint"}, {"description": "Specific HTTP header anomalies or patterns (e.g., spoofed User-Agent).", "field": "HeaderSignatureMatch"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2519', 0, 128, '09-mitre-attack', 'retrieved', '4998863A7D0DF5D626811AC748233E9A139A5FC4B6A46857FB671FE3CC18A858', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
