VALUES ('doc-09-mitre-attack-p0-2520', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of phishing through anomalous Mail app activity, such as attachments saved to disk and immediately executed, or Safari/Preview launching URLs and files linked from email messages. Correlate UnifiedLogs events with subsequent process execution.", "external_references": [{"external_id": "AN0190", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0070#AN0190"}], "id": "x-mitre-analytic--2a0cc1a9-db3b-4f05-8c85-29d69507418b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0190", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inbound email activity with suspicious domains or mismatched sender information", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Preview.app, Safari.app, or Mail.app spawning new processes outside normal patterns", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of domains known for phishing activity or suspicious sender infrastructure.", "field": "SuspiciousDomains"}, {"description": "Time threshold between file save and execution considered suspicious.", "field": "ExecutionDelayWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2520', 0, 129, '09-mitre-attack', 'retrieved', '0539F0D32320C88779755943F2A5860573FF7DD3A252A68969B0337C577814D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
