VALUES ('doc-09-mitre-attack-p0-2521', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual or suspicious processes loading critical native API DLLs (e.g., ntdll.dll, kernel32.dll) followed by direct syscall behavior, memory manipulation, or hollowing.", "external_references": [{"external_id": "AN1465", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0529#AN1465"}], "id": "x-mitre-analytic--2a23296d-70f2-4e04-9a97-62d093ad1765", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1465", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May tune DLL filters to focus on low-level API providers (e.g., ntdll.dll)", "field": "DllName"}, {"description": "Tune for expected parent processes (e.g., explorer.exe, winlogon.exe)", "field": "Image"}, {"description": "Scope to suspicious targets like LSASS, csrss, etc.", "field": "TargetProcess"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2521', 0, 115, '09-mitre-attack', 'retrieved', '845BE20D9190560236D83E8CC77CE7665D33F342D7D05C9C21E754A6C5CA9829', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
