INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2522', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider analyzing malware for features that may be associated with the adversary and/or their developers, such as compiler used, debugging artifacts, or code similarities. Malware repositories can also be used to identify additional samples associated with the adversary and identify development patterns over time.\nMonitor for contextual data about a malicious payload, such as compilation times, file hashes, as well as watermarks or other identifiable configuration information. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on post-compromise phases of the adversary lifecycle.", "external_references": [{"external_id": "AN2004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0872#AN2004"}], "id": "x-mitre-analytic--2a3b0030-05b4-4b85-a33c-dda07472f31f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 2004", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "Malware Repository", "x_mitre_data_component_ref": "x-mitre-data-component--167b48f7-76e9-4fcb-9e8d-7121f7bf56c3"}, {"channel": "None", "name": "Malware Repository", "x_mitre_data_component_ref": "x-mitre-data-component--93a6e38c-02a5-44d8-9035-b2e08459f31f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2522', 0, 150, '09-mitre-attack', 'retrieved', '265587830CF0A7D37D9FD25FA9C3FBD230D4100AAEA9A2552A13F7B3D026579E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
