INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2525', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects container breakout behavior via exploitation (e.g., DirtyPipe, CVE-2022-0847), followed by host OS interaction or escalated capability assignment.", "external_references": [{"external_id": "AN1422", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0514#AN1422"}], "id": "x-mitre-analytic--2a93100f-6332-4c91-bad9-fd371d638309", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1422", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "capset or setns", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "e.g., containerd, Docker events", "name": "containerd:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--91b3ed33-d1b5-4c4b-a896-76c55eb3cfd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May vary with CVE technique or custom syscall wrapper.", "field": "NamespaceEscapePattern"}, {"description": "Controls correlation of breakout → host interaction.", "field": "TimeWindow"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2525', 0, 96, '09-mitre-attack', 'retrieved', '9DF693A198B4E2DC47335C5CCC1E8CAC16882A98116CDCBA1B9861B1AA104BF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
