INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2526', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abnormal interaction with memory-based Kerberos ccache (API:{uuid}) or file-based overrides. Focus on processes attempting to enumerate or extract Kerberos tickets outside of built-in utilities. Detects use of open-source tools (e.g., Bifrost, modified Mimikatz ports) that interact with the Kerberos framework APIs.", "external_references": [{"external_id": "AN0070", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0024#AN0070"}], "id": "x-mitre-analytic--2a9d296d-6b36-42de-870c-9d851c0471ed", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0070", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Kerberos framework calls to API:{uuid} cache outside normal process lineage", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Execution of non-standard binaries accessing Kerberos APIs", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected processes using the Kerberos framework (e.g., loginwindow, kinit).", "field": "KerberosAPIProcessBaseline"}, {"description": "List of tools or binaries not normally expected to query Kerberos ccache entries.", "field": "SuspiciousBinaryList"}, {"description": "Window to link suspicious process activity with Kerberos authentication anomalies.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2526', 0, 149, '09-mitre-attack', 'retrieved', '3567B8606172DF8A50F6B43B3D41011AC0DFBFE4D2CEA41DEDE8E6DB2EC5D1A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
