INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2529', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A non-privileged or abnormal process attempts to open a handle with full access (0x1F0FFF) to lsass.exe and subsequently invokes memory dump, file creation, or registry modification indicative of credential scraping. This behavior chain reflects staged credential theft activity.", "external_references": [{"external_id": "AN1030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0363#AN1030"}], "id": "x-mitre-analytic--2b0dd3b6-6949-4dd5-b0dd-7b0b6f431dbe", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1030", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4673", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set to 0x1F0FFF to detect full memory access attempts; can be scoped down to reduce noise.", "field": "AccessMask"}, {"description": "Defines time between LSASS access and dump file creation or registry modification (e.g., 5 minutes).", "field": "TimeWindow"}, {"description": "Allowlist known legitimate tools (e.g., AV/EDR) accessing lsass.exe.", "field": "ParentProcessName"}, {"description": "Paths where memory dumps are written, e.g., %TEMP%, C:\\Windows\\Temp.", "field": "DumpFilePath"}, {"description": "Common dumping syntax like rundll32, procdump, comsvcs.dll, Invoke-Mimikatz.", "field": "CommandLinePattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2529', 0, 179, '09-mitre-attack', 'retrieved', '15D7F4522D7F350BE82FAB88BCC1FC3DC64EB7CBCB447A47F2652520D99BE66D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
