VALUES ('doc-09-mitre-attack-p0-2530', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Authentication failures across different accounts using a repeated or similar password via SSH or PAM stack within a short window", "external_references": [{"external_id": "AN1337", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1337"}], "id": "x-mitre-analytic--2b751817-3de2-4388-b8b9-d43b5ecda671", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1337", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Failed password for invalid user", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Repetition or minor variation of the same password across user attempts", "field": "PasswordReusePattern"}, {"description": "Length of time to observe distributed spray attempts from single source", "field": "IPAggregationWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2530', 0, 97, '09-mitre-attack', 'retrieved', 'B9500DEA48AD0817558803222B241FBE7D6A8E133DA1215425F8BC78510478CA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
