VALUES ('doc-09-mitre-attack-p0-2531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T18:22:06.178Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects esxcli commands disabling syslog, firewall, lockdown mode, or stopping hostd/vpxa; correlates command execution with reduced forwarding activity.", "external_references": [{"external_id": "AN2044", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0497#AN2044"}], "id": "x-mitre-analytic--2b990a38-dedf-4a9a-9bd2-9a805c2f1b46", "modified": "2026-05-12T16:30:18.376Z", "name": "Analytic 2044", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli system syslog config set/reload, services.sh restart/stop", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "service state change", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Authorized management sources.", "field": "ExpectedAdminIPs"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2531', 0, 85, '09-mitre-attack', 'retrieved', '0CD0E6A5E9D255F68D99A72D5359116688F02E51F7625989C1B986F13E577581', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
