VALUES ('doc-09-mitre-attack-p0-2532', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Script-based execution of sleep loops or time delay commands (e.g., sleep, ping delay, while-loops) followed by file creation or network connections.", "external_references": [{"external_id": "AN0397", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0141#AN0397"}], "id": "x-mitre-analytic--2bbe41df-b8a6-4503-8fb0-028b7387cb1d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0397", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of sleep or ping command within script interpreted by bash/python", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file write after sleep delay", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how many loop iterations or sleep cycles are considered anomalous in the monitored environment.", "field": "SleepLoopCount"}, {"description": "Identifies which scripting interpreter is used (e.g., bash, python, perl) to adjust detection logic.", "field": "ExecutionScriptType"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2532', 0, 121, '09-mitre-attack', 'retrieved', 'DF30EB2C4A7C0EBB7558C533BBE8998BD1D48067C7E521565BF384AC86AC2D32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
