INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2533', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects binaries disguised as media or document types through extension-only masquerading or by modifying the file signature. Observes execution of files whose extension is not typically executable (.jpg, .txt), yet have valid Mach-O headers or execute via Terminal or launch services.", "external_references": [{"external_id": "AN0632", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0226#AN0632"}], "id": "x-mitre-analytic--2bce7f8d-90c1-4835-9ce9-832e5e3a37d6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0632", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchservices events for misleading extensions", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope of services monitored for unusual launches (e.g., Finder, Terminal, Preview)", "field": "LaunchAgentScope"}, {"description": "How strictly the detection checks header validity vs. file extension", "field": "SignatureEnforcementLevel"}, {"description": "Time range for linking file modification and execution events", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2533', 0, 129, '09-mitre-attack', 'retrieved', '03D52872C887E2875692E48D68C20030E808379FF2A5ECFFB11E9ADFB0DDCD3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
