VALUES ('doc-09-mitre-attack-p0-2535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes use built-in encoding utilities (e.g., `base64`, `xxd`, or `plutil`) to encode file contents followed by HTTP/HTTPS transfer via curl or custom applications.", "external_references": [{"external_id": "AN0304", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0108#AN0304"}], "id": "x-mitre-analytic--2bf1ce64-970b-4d0d-bf5f-a854fc6d7235", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0304", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "base64 or curl processes chained within short execution window", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "HTTP POST with encoded content in user-agent or cookie field", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum byte size of encoded strings to treat as suspicious", "field": "EncodedCommandLengthThreshold"}, {"description": "Number of chained processes within a short window to treat as a correlated behavior", "field": "SuspiciousProcessChainDepth"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2535', 0, 121, '09-mitre-attack', 'retrieved', 'ED76D54893426369032CDF427E204D20EE786F5A38422408287C1CD5919093A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "