VALUES ('doc-09-mitre-attack-p0-2536', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect repeated failed login events followed by MFA challenges triggered in rapid succession, especially if originating from service accounts or anomalous IP addresses.", "external_references": [{"external_id": "AN0451", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0160#AN0451"}], "id": "x-mitre-analytic--2c0df764-d9bd-4a91-808a-aa13df13511a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0451", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4625", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude specific accounts where automated MFA requests are legitimate", "field": "ServiceAccountExclusion"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2536', 0, 80, '09-mitre-attack', 'retrieved', '11FE138E941181CEC403BD6EB745F5F22AC51B7B67596C6B782E83639F4C5ED9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
