VALUES ('doc-09-mitre-attack-p0-2537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Hidden file creation using leading ''.'' or file attribute changes with chattr (immutable/hidden flags). Defender view: detect execution of chattr, lsattr anomalies, and unusual hidden files appearing in system directories.", "external_references": [{"external_id": "AN1385", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0502#AN1385"}], "id": "x-mitre-analytic--2c3ec402-b9e9-4091-a04d-3b73f260e669", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1385", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of chattr to set +i or +a attributes", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Creation of hidden files (.*) in sensitive directories (/etc, /var, /usr/bin)", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict hidden file detection to privileged system directories.", "field": "DirectoryScope"}, {"description": "Tune for specific chattr flags (+i immutable, +a append-only) most abused for persistence.", "field": "AttributeFlags"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2537', 0, 126, '09-mitre-attack', 'retrieved', 'E65F92A8B3A3611F47F27B21EF15778D88C9138CFB84003CE90038A0B5BD50FB', 'v1', '{"source_id": "09-mitre-attack", "version":