VALUES ('doc-09-mitre-attack-p0-2542', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects rundll32.exe invoked with atypical arguments (.dll, .cpl, javascript:, mshtml). DLLs not normally loaded by rundll32 are mapped into memory. Control_RunDLL or RunHTMLApplication invoked. Suspicious DLLs or scripts accessed from disk or network. Rundll32 reaches out to external domains (e.g., fetching .sct or .hta).", "external_references": [{"external_id": "AN1308", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0475#AN1308"}], "id": "x-mitre-analytic--2cb33f68-48f8-4ffe-86e1-bc857a300398", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1308", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlating rundll32 invocation with DLL load or network activity within X seconds.", "field": "TimeWindow"}, {"description": "Limit detection to suspicious parent processes (e.g., explorer.exe, office apps) vs. trusted installers.", "field": "ParentProcessFilter"}, {"description": "Baseline list of legitimate DLLs frequently executed by rundll32 in the environment.", "field": "AllowedDLLs"}, {"description": "Scope of external IP ranges considered anomalous for rundll32 network connections.", "field": "ExternalIPRange"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2542', 0, 168, '09-mitre-attack', 'retrieved', 'EA7B1C0C720DE85070A5F6A4BB608D2C4C0F77AD438FE92E7B76D8763FD05C80', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
