INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2544', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual access or copying of files from mounted network drives (e.g., NFS, CIFS/SMB) by user shells or scripts followed by large data transfer.", "external_references": [{"external_id": "AN1146", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0410#AN1146"}], "id": "x-mitre-analytic--2d1d5482-b82b-45ff-9563-959766d373ff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1146", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open,read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "mount/umount or file copy logs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organization-specific share mount paths may vary (/mnt/share1, /srv/data etc.)", "field": "MountPoint"}, {"description": "May need to scope to service accounts or user ID patterns specific to enterprise policy.", "field": "UID"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2544', 0, 108, '09-mitre-attack', 'retrieved', 'C36E2F95BA6098B978D934CE547473308D14819C4414E0D7746BA3021C1E4A37', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
