INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2547', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CLI tools (smbclient -L, smbmap, rpcclient, nmblookup) or custom scripts enumerate SMB shares on many internal hosts → corresponding SMB connections (445/139) captured by Zeek/Netflow within a short window.", "external_references": [{"external_id": "AN0514", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0182#AN0514"}], "id": "x-mitre-analytic--2de35397-ef03-4ffe-b531-d7ad61a6f41d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0514", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of smbclient, smbmap, rpcclient, nmblookup, crackmapexec smb", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "connection: TCP connections to ports 139/445 to multiple hosts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "smb_command: TreeConnectAndX to \\\\*\\IPC$ / srvsvc or Trans2/NT_CREATE for listing shares", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum unique hosts to flag (e.g., ≥5).", "field": "BurstHostThreshold"}, {"description": "Correlation window between tool exec and SMB fan-out (default 10m).", "field": "TimeWindow"}, {"description": "IPs of vulnerability scanners or config mgmt systems.", "field": "ApprovedInventoryHosts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2547', 0, 145, '09-mitre-attack', 'retrieved', '93A34FDF2AE666B171269D94A301D1EF33A53367059391E396D6CE603833FA20', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
