VALUES ('doc-09-mitre-attack-p0-2549', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Interactive or remote shell/API invocation of esxcli system clock get or querying time parameters via hostd/vpxa shortly followed by time/ntp configuration checks or scheduled task creation, executed by non-standard accounts or outside maintenance windows.", "external_references": [{"external_id": "AN0433", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0151#AN0433"}], "id": "x-mitre-analytic--2e51d33e-28d3-4e3f-a68a-38bc2d4abdde", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0433", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/shell.log entries containing \"esxcli system clock get\"", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "/var/log/hostd.log API calls reading/altering time/ntp settings", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "/var/log/vpxa.log task invocations tied to time configuration", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Only alert if outside approved ops windows.", "field": "MaintenanceWindow"}, {"description": "Suppress alerts for known service accounts.", "field": "PrivilegedAccountsAllowList"}, {"description": "Whitelist management station IPs.", "field": "RemoteIPAllowList"}, {"description": "Correlation between esxcli time query and subsequent hostd/vpxa config calls.", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2549', 0, 147, '09-mitre-attack', 'retrieved', '4E444F8EC1E03C6A62712BF408C3F282351F44443CFA2F99EB3BFD7F4A988B32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
