VALUES ('doc-09-mitre-attack-p0-2550', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects cloud-native software deployment or management (e.g., SSM Run Command, Intune) initiating script execution on endpoints outside expected org IDs, admin groups, or maintenance windows.", "external_references": [{"external_id": "AN0626", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0223#AN0626"}], "id": "x-mitre-analytic--2e6218d1-1f84-4dc5-8ab5-c24835aafbab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0626", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SSM RunCommand", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved deployment administrators or service accounts", "field": "IAMRoleAllowList"}, {"description": "Expected endpoints targeted by SaaS deployments", "field": "ExecutionTargetList"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2550', 0, 89, '09-mitre-attack', 'retrieved', 'B5F871E3051620577A950A6FE1751A48E082408A9E95FE57F3EA44FBF49ACC36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
