VALUES ('doc-09-mitre-attack-p0-2551', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect unauthorized manipulation of log files, database entries, or system configuration files through auditd and syslog. Correlate shell commands that alter HISTFILE or data-related processes with abnormal file access patterns.", "external_references": [{"external_id": "AN0163", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0059#AN0163"}], "id": "x-mitre-analytic--2e700f3b-bf9c-427c-a099-b80d233c1ccb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0163", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, unlink, rename: Suspicious file access, deletion, or modification of sensitive paths", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Unexpected SQL or application log entries showing tampered or malformed data", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific log or data directories critical to integrity; tune per organization.", "field": "WatchedDirectories"}, {"description": "Legitimate scripts/tools excluded from data manipulation monitoring.", "field": "CommandExclusions"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2551', 0, 126, '09-mitre-attack', 'retrieved', '3864877E8DA8506D75E3B9E844C39053610B1C60BD3DB6ED721BB1547391C341', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
