VALUES ('doc-09-mitre-attack-p0-2552', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Closed-port knock sequence from a remote IP followed by on-host firewall change (iptables/nftables) or daemon starts listening (socket open) and a successful TCP/UDP connect. Optional detection of libpcap/raw-socket sniffers spawning to watch for secret values.", "external_references": [{"external_id": "AN1449", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0524#AN1449"}], "id": "x-mitre-analytic--2e7a9609-3e4b-477b-828f-f486561d7fa7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1449", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Commands altering firewall or enabling listeners (iptables, nft, ufw, firewall-cmd, systemctl start *ssh*/*telnet*, ip route add, tcpdump, tshark)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "socket/bind: Process binds to a new local port shortly after knock", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Knock pattern: multiple REJ/S0 to distinct closed ports then successful connection to service_port", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Packets with unusual flags or payloads outside established flows (e.g., WoL magic FF×6 + 16×MAC)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Port that becomes available post-knock (e.g., 22/8022/2323).", "field": "ServicePort"}, {"description": "Percentage of failed attempts with RST/ICMP vs SYN/SYN-ACK to qualify as closed-port probing.", "field": "KnockResetRatio"}, {"description": "Automation expected to touch firewall/daemon configs (config-mgmt agents).", "field": "ProcessAllowList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2552', 0, 189, '09-mitre-attack', 'retrieved', 'E4C6CFB57ADDC6B5068459AFE3D08004657800CAC61BD094CB47B9CB113ADBE1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
