VALUES ('doc-09-mitre-attack-p0-2554', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of ApplicationImpersonation role assignment or delegated mailbox access to service principals or rarely used users, especially outside of normal hours or geographic norms.", "external_references": [{"external_id": "AN1107", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0393#AN1107"}], "id": "x-mitre-analytic--2ec84f0f-1148-4821-acf0-a5527381865f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1107", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add-MailboxPermission or Set-ManagementRoleAssignment", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unusual sign-in from service principal to user mailbox", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Mailbox of interest where impersonation or access delegation occurs.", "field": "TargetMailbox"}, {"description": "Tune based on expected application or script-based mailbox access.", "field": "UserAgent"}, {"description": "Restrict based on corporate geography or travel expectations.", "field": "GeoLocation"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2554', 0, 120, '09-mitre-attack', 'retrieved', '3D7AD7D7A7DECAAD37C1049F40B4B26B749F6213BBD758F059FB2576F7D51130', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
