VALUES ('doc-09-mitre-attack-p0-2555', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects clearing of unified logs, deletion of plist files tied to persistence, and manipulation of Terminal history after initial execution.", "external_references": [{"external_id": "AN0522", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0184#AN0522"}], "id": "x-mitre-analytic--2f0f5c7a-18ee-462e-b364-b1d8df3b2c02", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0522", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream cleared or truncated", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "unlink, fs_delete", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "File modifications in ~/Library/Preferences/", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define which plist paths relate to LaunchAgents or LaunchDaemons", "field": "PlistTargetPaths"}, {"description": "Allow tuning for multi-process persistence chains", "field": "ExecutionChainDepth"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2555', 0, 106, '09-mitre-attack', 'retrieved', '741990EEA4631B5EFB8540BDF3A59CE04CE94AE8C2F551626D159309813F213F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
