INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2556', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized modification of network device authentication by correlating OS image file changes, checksum mismatches, or memory verification failures with anomalous authentication events. Focus is on behaviors where patched images introduce hardcoded passwords or bypass native authentication.", "external_references": [{"external_id": "AN0758", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0272#AN0758"}], "id": "x-mitre-analytic--2f39584b-59bd-43ec-bd0a-5c2eba258ae2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0758", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unexpected OS image file upload or modification events", "name": "networkconfig", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "repeated successful authentications with previously unknown accounts or anomalous password acceptance", "name": "network:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Trusted baseline cryptographic hashes for OS images, used to detect unauthorized modifications.", "field": "BaselineChecksums"}, {"description": "Threshold for correlating unusual authentication successes following failed attempts or unknown account use.", "field": "AuthFailureThreshold"}, {"description": "Frequency of runtime OS image and memory integrity checks.", "field": "VerificationInterval"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2556', 0, 149, '09-mitre-attack', 'retrieved', '950039638564F04DCD0A2BDAE137C13EF33FC46263D0EF3960192CD4FD8CF5E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
