VALUES ('doc-09-mitre-attack-p0-2557', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User or remote input triggers application crash or segmentation fault (e.g., SIGSEGV) with service recovery attempts, observed via audit logs and systemd journaling.", "external_references": [{"external_id": "AN0851", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0304#AN0851"}], "id": "x-mitre-analytic--2f4d199c-4d62-4d7d-8c6e-3ec358c22e76", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0851", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process segfault or abnormal termination after invoking vulnerable syscall sequence", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}, {"channel": "Segfault or crash log entry associated with specific application binary", "name": "journald:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unusual request pattern leading up to service crash (e.g., malformed or oversized payload)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific binary fault signature or stack trace identifiers unique to the application context", "field": "CrashPattern"}, {"description": "Suspect source IPs for correlation across requests and service failure timing", "field": "ExploitSourceIP"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2557', 0, 140, '09-mitre-attack', 'retrieved', '6384FE5BC010E3365F0B15F3120BBA03CDBA82E3380CF6D72805A83931DF602A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
