VALUES ('doc-09-mitre-attack-p0-2558', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Observation of `blueutil`/`networksetup` commands or low-level APIs toggling Bluetooth or initiating transfers, especially if paired with recent large file read activity by non-GUI processes.", "external_references": [{"external_id": "AN1533", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0554#AN1533"}], "id": "x-mitre-analytic--2f6dd4a5-b0cc-4c13-abb8-e2d747d591b2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1533", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "None", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "None", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit to background processes or scripts with no GUI interaction.", "field": "ProcessContext"}, {"description": "Focus on specific sensitive file types (e.g., zip, docx, keychain db).", "field": "PayloadType"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2558', 0, 108, '09-mitre-attack', 'retrieved', 'D2D0F9EF87E6EA0BF53F8BCFB361B168B32A00F1C76C0482FC8DAFD4F0FC413E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
