VALUES ('doc-09-mitre-attack-p0-2559', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of maintainer scripts (e.g., postinst, preinst) being modified or executed during dpkg or rpm operations. Watch for script content that spawns additional processes or writes outside package scope.", "external_references": [{"external_id": "AN0939", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0330#AN0939"}], "id": "x-mitre-analytic--2f9c7e44-de3a-4fbd-955a-482ef9f341ed", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0939", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of dpkg or rpm followed by fork/execve from within postinst, prerm, etc.", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May be postinst, preinst, prerm, or postrm depending on packaging system", "field": "ScriptName"}, {"description": "Depends on system: dpkg, apt, rpm, yum, etc.", "field": "PackageManager"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2559', 0, 117, '09-mitre-attack', 'retrieved', '49B66E3F5D5949537123AC51F98D142074B1F7A3FC5E7B9EFB9718D3074178C2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
