VALUES ('doc-09-mitre-attack-p0-2560', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious use of ESXi native CLI tools like esxcli and vim-cmd by unauthorized users or outside expected maintenance windows. Focus is on actions such as stopping VMs, reconfiguring network/firewall settings, and enabling SSH or logging.", "external_references": [{"external_id": "AN1537", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0558#AN1537"}], "id": "x-mitre-analytic--2fa4d134-8583-4cbe-bc84-bfc799205116", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1537", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli, vim-cmd invocation", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "SSH session/login", "name": "esxi:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Helps scope detection to off-hours or change control gaps.", "field": "TimeWindow"}, {"description": "Environment-specific users may run these commands as part of normal ops.", "field": "UserContext"}, {"description": "CLI commands vary by adversary intent (e.g., ''stop'', ''reboot'', ''firewall set'')", "field": "CommandPattern"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2560', 0, 130, '09-mitre-attack', 'retrieved', 'FEAE666ADBF0D6C237E12500074A70293A3A3538C5B8A6B592D27DF8F610EB9F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
