VALUES ('doc-09-mitre-attack-p0-2561', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates unusual auto-forwarding rule creation via Exchange Web Services or Outlook rules engine, presence of X-MS-Exchange-Organization-AutoForwarded headers, and logon session anomalies from abnormal IPs.", "external_references": [{"external_id": "AN1312", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0476#AN1312"}], "id": "x-mitre-analytic--2faaefb9-7816-4eb5-a9f5-b4006c99c20b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1312", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set-Mailbox, New-InboxRule", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "MessageTrace logs", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "SignInEvents", "name": "azure:ad", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict rules from non-browser agents", "field": "UserAgentList"}, {"description": "Allow listing for org-sanctioned forwarding domains", "field": "ExternalSMTPDomainList"}, {"description": "Time delta between rule creation and suspicious sign-in", "field": "TimeWindow"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2561', 0, 112, '09-mitre-attack', 'retrieved', '1E14320D3C6D7696329F08C9C2A26D9DBEC5353DAFED17200C57471F59F215A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
