INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2562', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Containerized apps or sidecar containers generating excessive outbound traffic or being leveraged for proxy networks. Includes sudden increases in network interface stats, especially in dormant or low-util apps.", "external_references": [{"external_id": "AN0083", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0028#AN0083"}], "id": "x-mitre-analytic--2fe9bf69-b1a8-4c60-8b20-c11054d31158", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0083", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "bandwidth-intensive command execution from within a container namespace", "name": "containers:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unusual network TX/RX byte deltas", "name": "docker:stats", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline per container must be defined by app purpose and normal traffic.", "field": "ContainerBaselineNetworkUsage"}, {"description": "Certain image names or registries may be prone to abuse (e.g., public image hosting mining or proxyware).", "field": "ImageName"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2562', 0, 125, '09-mitre-attack', 'retrieved', '4AC5FCD289331C96194467F411BD75B6C2760D4B0DA48921FEEFD8DEB001766E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
