VALUES ('doc-09-mitre-attack-p0-2563', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Login activity from default admin credentials (e.g., ''admin'', ''cisco'') on routers, firewalls, and switches.", "external_references": [{"external_id": "AN1287", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0465#AN1287"}], "id": "x-mitre-analytic--305b6a70-6d5b-4b32-a40b-ae0cae342e62", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1287", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authentication logs", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Default usernames vary by vendor; defenders should adapt logic to their specific appliance list.", "field": "Username"}, {"description": "Telnet and HTTP-based access to network devices should be blocked and monitored if enabled.", "field": "InterfaceType"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2563', 0, 95, '09-mitre-attack', 'retrieved', 'B475C95DB83BA434BFD927950310EABCE6EAA274B50B8750CB1DC1BBC22574AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
