VALUES ('doc-09-mitre-attack-p0-2565', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects API calls to cloud secrets/MFA configurations where MFA enforcement policies are disabled or bypassed.", "external_references": [{"external_id": "AN0545", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0190#AN0545"}], "id": "x-mitre-analytic--3090db89-83c0-44bc-a17d-7cb2a6aecb87", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0545", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "UpdateIdentityPolicy or DisableMFA", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific cloud services or IAM policies relevant to MFA enforcement.", "field": "MonitoredServices"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2565', 0, 75, '09-mitre-attack', 'retrieved', 'B1472DCD3730B5D777D4A7F2AAF0C0245431D22EE34BDF7994F15E991179C10F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
