INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2567', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Linux environmental validation behavioral chain: (1) Intensive system enumeration through command execution (uname, hostname, ifconfig, lsblk, mount), (2) File system reconnaissance targeting specific paths, network configurations, and installed packages, (3) Process and user enumeration to validate target environment characteristics, (4) Conditional script execution or binary activation based on environmental criteria, (5) Network connectivity validation and external IP address resolution for geolocation verification", "external_references": [{"external_id": "AN1552", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0562#AN1552"}], "id": "x-mitre-analytic--31027842-f02c-4bc3-8cd6-3e4b533da5ac", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1552", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "openat,connect -k discovery", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "command-line execution patterns for system discovery utilities (uname, hostname, ifconfig, netstat, lsof, ps, mount)", "name": "auditd:PROCTITLE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "authentication and authorization events during environmental validation phase", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Linux commands commonly used for system reconnaissance - customize based on environment-specific discovery patterns", "field": "SystemDiscoveryCommandList"}, {"description": "Number of discovery commands within time window indicating reconnaissance burst - tune based on legitimate administrative activity", "field": "ReconnaissanceBurstThreshold"}, {"description": "File paths and system properties commonly validated by environmental keying - adapt to organizational infrastructure", "field": "EnvironmentalCheckPatterns"}, {"description": "Normal network discovery activity patterns to distinguish from malicious reconnaissance", "field": "NetworkDiscoveryBaseline"}, {"description": "Script patterns and conditional logic indicating environment-based execution decisions", "field": "ConditionalExecutionIndicators"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2567', 0, 233, '09-mitre-attack', 'retrieved', '708C047CBCDC04C0A367193B02FFFA65A2A3F02E6E0B53CAEF04B5D11F85A83A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
