VALUES ('doc-09-mitre-attack-p0-2568', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Excessive resource exhaustion or service crash induced by processes launched by users or scripts that rapidly consume CPU/memory or attempt malformed service interactions.", "external_references": [{"external_id": "AN0584", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0208#AN0584"}], "id": "x-mitre-analytic--3102edb4-6947-4cef-9660-4a35d582a716", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0584", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Service crash, unhandled exception, or application hang warnings for critical services (e.g., IIS, DNS, SQL Server)", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "System shutdowns due to bugcheck (Event ID 1001) or watchdog timer expirations", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of service crashes or high-CPU events within a defined time period", "field": "TimeWindow"}, {"description": "Specific service name or executable targeted for DoS (e.g., svchost.exe, w3wp.exe)", "field": "ServiceTarget"}, {"description": "CPU usage percent considered anomalous over duration", "field": "CPUThresholdPercent"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2568', 0, 145, '09-mitre-attack', 'retrieved', 'FA217D1485424AE6000129CCA80867DE3768E52C3E74178E9B35DB2F5EEF6284', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
