VALUES ('doc-09-mitre-attack-p0-2569', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects enabling of interface sniffing via packet capture tools or AppleScript triggering `tcpdump`. Leverages Unified Logs and process lineage to identify suspicious use of `pfctl`, `tcpdump`, or `libpcap` libraries.", "external_references": [{"external_id": "AN0877", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0314#AN0877"}], "id": "x-mitre-analytic--31098e90-e2a0-477f-80ca-e969430d54c2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0877", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "eventMessage = ''promiscuous''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process_events where path like ''%tcpdump%''", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "access to BPF devices or interface IOCTLs", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist Apple-native tools used by IT admins and mobile device management (MDM).", "field": "AllowedTools"}, {"description": "Prioritize detections from non-admin or low-privilege users performing packet captures.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2569', 0, 126, '09-mitre-attack', 'retrieved', 'CF1582E439795269E1B1E64686DF83041527A323CD474657FB4359F26C1F626D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
