INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2571', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects files collected into user temp or shared directories followed by compression with ditto, zip, or custom scripts.", "external_references": [{"external_id": "AN0042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0014#AN0042"}], "id": "x-mitre-analytic--313de6ca-629b-4f77-b58f-5cf7b490a62e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0042", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "exec logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., ''ditto'', ''zip'', ''tar''", "field": "CompressionUtilityList"}, {"description": "e.g., /Users/Shared/ or /private/tmp/", "field": "SharedDirectoryIndicators"}, {"description": "osascript or Terminal automation by non-GUI processes", "field": "ScriptInvocationContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2571', 0, 95, '09-mitre-attack', 'retrieved', 'EEDD5D59801F619A430EDDA050758CD842126BB1BEFD2E334E8121B5D7118CF0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
