VALUES ('doc-09-mitre-attack-p0-2573', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor esxcli and syslog records for DNS resolver changes or repeated queries to unusual external domains by management agents. Detect unauthorized changes to VM or host network settings that redirect DNS lookups.", "external_references": [{"external_id": "AN0112", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0039#AN0112"}], "id": "x-mitre-analytic--3166927d-91e4-4e08-bfec-abda2783be8c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0112", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli network vswitch or DNS resolver configuration updates", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected resolvers or DNS forwarders in ESXi configurations", "field": "ResolverConfigPaths"}, {"description": "Set of trusted external domains expected for ESXi host activity", "field": "ExternalDomainWhitelist"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2573', 0, 108, '09-mitre-attack', 'retrieved', 'CB2860C5274D916873B6C39CAB1AAD1F4329967E0C7F664C3BB52563ED7870EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
