VALUES ('doc-09-mitre-attack-p0-2574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary drops renamed binaries in uncommon directories (e.g., /tmp, /dev/shm) or uses special characters in names (e.g., trailing space, Unicode RLO). Execution or cronjob registration follows shortly after file drop.", "external_references": [{"external_id": "AN0356", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0127#AN0356"}], "id": "x-mitre-analytic--3191336e-8cdb-4d41-80a4-aa2ab869f7bf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0356", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "rename", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "file_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directories where new binaries are suspicious (e.g., /tmp)", "field": "DropLocationPattern"}, {"description": "Regex for Unicode/RLO/space abuse in filenames", "field": "FilenameAnomalies"}, {"description": "Time range between file write and execution used for joining", "field": "ExecutionDelayWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2574', 0, 120, '09-mitre-attack', 'retrieved', '4B45314942B8EFC19E9601ECABA935BE7207408BA20DB23439722FCE8484198C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
