VALUES ('doc-09-mitre-attack-p0-2575', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Background scripts (e.g., via cron) or daemons transmitting data repeatedly to remote IPs or URLs.", "external_references": [{"external_id": "AN1114", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0397#AN1114"}], "id": "x-mitre-analytic--31adce9b-8935-4abf-aaf2-0a13047e25e4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1114", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound Connections", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable time range for recurring tasks seen creating outbound connections.", "field": "CronJobInterval"}, {"description": "Tunable for scope — service accounts vs user accounts.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2575', 0, 92, '09-mitre-attack', 'retrieved', '3C24EAEC8B7ECA0C3096F55D7A78E3D46C17D2B859133DCD7BE18B6F7CF90B76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
