VALUES ('doc-09-mitre-attack-p0-2576', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor mail server logs (e.g., Postfix, Sendmail) for excessive connections or inbound message counts targeting a single recipient. Correlate with repetitive attachment storage in /var/mail or /var/spool/mail directories.", "external_references": [{"external_id": "AN1009", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0355#AN1009"}], "id": "x-mitre-analytic--31e4c4dc-3094-45b2-9d4d-1b0bf8311498", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1009", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "File creation events in /var/mail or /var/spool/mail exceeding baseline thresholds", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "High-frequency inbound mail activity to a specific recipient address", "name": "Application:Mail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable value for the maximum acceptable emails per minute per user.", "field": "MailVolumeThreshold"}, {"description": "List of suspicious attachment extensions that may be abused for repetitive delivery.", "field": "AttachmentPatternList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2576', 0, 125, '09-mitre-attack', 'retrieved', '8C85738FA03E85083460604DD982FD01D90203F20FE22FB67861C300C742F367', 'v1', '{