VALUES ('doc-09-mitre-attack-p0-2577', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of modification to ESXi rc.local.d or rc scripts that are used to execute on boot.", "external_references": [{"external_id": "AN0314", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0112#AN0314"}], "id": "x-mitre-analytic--32199f21-430f-4c91-b2d7-a0b7409cd5f0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0314", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "boot", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "boot", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Script path or name may vary across hypervisor versions.", "field": "ScriptName"}, {"description": "Log verbosity settings may alter visibility of activity.", "field": "LogSeverity"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2577', 0, 90, '09-mitre-attack', 'retrieved', '94C3037B74664EB04032B3A4C1AE960DD828FB9BE19DE7AEE9C982E821DBD158', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
