VALUES ('doc-09-mitre-attack-p0-2579', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies internal or external site content through manipulated application bundles, hosted content, or web server configs.", "external_references": [{"external_id": "AN0664", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0238#AN0664"}], "id": "x-mitre-analytic--3258db60-8500-4935-837c-78b23f2d83d1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0664", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of unexpected terminal or web scripts modifying /Library/WebServer/Documents", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "File creation or overwrite in common web-hosting folders", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Web root folders will vary depending on how services are configured on macOS (e.g., /Library/WebServer/Documents).", "field": "TargetDirectoryPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2579', 0, 101, '09-mitre-attack', 'retrieved', '6589EDA24617CF3625BD78A8002D089FCFBFF62671638D5A5E7F1702C3DCD11C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
