INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2587', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of renamed or relocated native macOS utilities with uncommon names or non-default paths (e.g., renamed `osascript`, `bash`, or `curl`).", "external_references": [{"external_id": "AN0013", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0005#AN0013"}], "id": "x-mitre-analytic--3349af7c-3cea-4424-b2a4-056fedb63831", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0013", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/quarantine.log", "name": "fs:fileevents", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path deviation from expected directory (e.g., /usr/bin/ vs /tmp/)", "field": "PathDeviation"}, {"description": "Enable tuning based on hash matching known signed versions vs suspicious clones", "field": "BinaryHashReputation"}, {"description": "Scope detections based on non-admin users using admin-level tools", "field": "UserRole"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2587', 0, 116, '09-mitre-attack', 'retrieved', '445CF0B031EC1EA047C84A1BF4F43F5E3EAA82D7AF37D4FBEE49B7A61342BB41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
