VALUES ('doc-09-mitre-attack-p0-2589', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of cron jobs via crontab, /etc/cron.* directories, or systemd timer units with execution by unusual users or non-standard intervals.", "external_references": [{"external_id": "AN0259", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0094#AN0259"}], "id": "x-mitre-analytic--3374a404-06f9-4b32-bf94-5ac688fb9dad", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0259", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write, rename", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "crontab, systemd_timers", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Look for high-frequency or off-hour scheduling patterns.", "field": "CronSchedulePattern"}, {"description": "Unusual users scheduling jobs (e.g., www-data, nobody).", "field": "ServiceUser"}, {"description": "Abnormal scripts or binaries tied to the scheduled job.", "field": "BinaryEntropy"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2589', 0, 114, '09-mitre-attack', 'retrieved', 'AC4FB3EA0737F33C04BD300572047FD9885EF4B65E7657456102962