VALUES ('doc-09-mitre-attack-p0-2590', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects process injection by correlating memory manipulation API calls (e.g., VirtualAllocEx, WriteProcessMemory), suspicious thread creation (e.g., CreateRemoteThread), and unusual DLL loads within another process''s context.", "external_references": [{"external_id": "AN1399", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0508#AN1399"}], "id": "x-mitre-analytic--337976cc-5fd5-49e8-abcb-79f27d19382c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1399", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "API calls", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific access rights used during process handle acquisition, e.g., PROCESS_VM_WRITE", "field": "AccessMask"}, {"description": "Time correlation window between API calls and thread creation events", "field": "TimeWindow"}, {"description": "Known high-value targets often abused for injection (e.g., lsass.exe, explorer.exe)", "field": "InjectedProcessList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2590', 0, 128, '09-mitre-attack', 'retrieved', 'ECB06678CD3E888563F3BB1C405EF87637C6363E07D6ED447AB1DF2986CCDDF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
