VALUES ('doc-09-mitre-attack-p0-2591', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects conditional access policy changes, exclusion of accounts from MFA enforcement, or registration of new MFA factors by non-admin or anomalous users.", "external_references": [{"external_id": "AN0544", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0190#AN0544"}], "id": "x-mitre-analytic--33b7f7b2-b79c-4893-bd5c-2d5638bf5786", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0544", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Modify Conditional Access Policy", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "User excluded from MFA or MFA method registered", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Roles permitted to modify MFA settings in IdP; helps tune detection of unauthorized changes.", "field": "PrivilegedRoles"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2591', 0, 101, '09-mitre-attack', 'retrieved', '4E6DFBCB4C35FEF1C06E4CDBE2920356F4BAF1A36C39A15E23465B1C49E18099', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
