INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2592', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses built-in OS tools or API calls to create local or domain accounts for persistence or lateral movement. Tools such as ''net user'', PowerShell, or MMC snap-ins may be used. Detection focuses on Event ID 4720 paired with process lineage and user context.", "external_references": [{"external_id": "AN1604", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0583#AN1604"}], "id": "x-mitre-analytic--33d574c3-8e9b-462d-b3d1-09e64c2fa8c7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1604", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4720", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation between Event ID 4720 and creating process may vary by environment and automation delays", "field": "TimeWindow"}, {"description": "Tools like net.exe or powershell.exe can be normal or malicious depending on user context", "field": "ParentProcessName"}, {"description": "System vs. administrator vs. low-privilege user context changes alert criticality", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2592', 0, 143, '09-mitre-attack', 'retrieved', 'E4B654D8C03353068FAADB2968A569C99FDB5003C28BC1C66AF2D65D282C6EF7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
