VALUES ('doc-09-mitre-attack-p0-2593', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral detection of domain group enumeration via ldapsearch or custom scripts leveraging LDAP over the network.", "external_references": [{"external_id": "AN1026", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0360#AN1026"}], "id": "x-mitre-analytic--3415a6fa-a447-42f3-8155-68cf5d7cbcb3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1026", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "sshd logs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "ldap.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable based on number of LDAP queries before flagging suspicious behavior.", "field": "LDAPQueryDepth"}, {"description": "Pattern matching against common ldapsearch or shell enumeration flags.", "field": "CommandPattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2593', 0, 100, '09-mitre-attack', 'retrieved', 'B801D5DE6EE7D54C2D8C95227662DE263BCEBC017CE4D6EFA737C3D7FE0DE364', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
