VALUES ('doc-09-mitre-attack-p0-2595', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes attempting raw disk access to overwrite sensitive structures such as the MBR or partition table using \\\\.\\PhysicalDrive notation. Detection relies on correlating process creation, privilege escalation, and raw sector writes in Sysmon and Security logs.", "external_references": [{"external_id": "AN0827", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0297#AN0827"}], "id": "x-mitre-analytic--34560ac3-2e05-4394-8145-0cd6071c1680", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0827", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4673", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "Raw write attempts targeting \\\\.\\PhysicalDrive0 or sector 0 (MBR/partition table)", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}, {"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify which sectors are considered critical (MBR, partition table) to reduce noise.", "field": "SectorRange"}, {"description": "Exclude legitimate low-level disk management or imaging tools used by administrators.", "field": "ProcessWhitelist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2595', 0, 131, '09-mitre-attack', 'retrieved', '2E11D22C39F0F6932275C9CC9EA6538698503A9BDE8D4C595644257EE69A5540', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
