VALUES ('doc-09-mitre-attack-p0-2596', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate MFA push fatigue or unusual consent grant attempts with call activity where adversaries may have socially engineered the user over voice.", "external_references": [{"external_id": "AN0686", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0245#AN0686"}], "id": "x-mitre-analytic--345af006-d658-4f22-aef6-b1cfc0058875", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0686", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unusual MFA requests or OAuth consent events temporally aligned with user-reported vishing call", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of MFA push requests within a timeframe aligned to a suspicious call", "field": "MFARequestThreshold"}, {"description": "Unusual OAuth consent URLs or delegated scopes", "field": "ConsentGrantPatterns"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2596', 0, 106, '09-mitre-attack', 'retrieved', '9F52D072F485AC4F795356BB5AB6C28D30E7A6DE90AE4305B729A0564EDC985B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
