VALUES ('doc-09-mitre-attack-p0-2597', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Logon via RDP or WMI by a user account followed by uncommon command execution, file manipulation, or lateral network connections.", "external_references": [{"external_id": "AN0750", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0269#AN0750"}], "id": "x-mitre-analytic--34c5e959-876b-4851-8ebf-bfaf97e9e609", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0750", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window between remote login and post-access activity", "field": "TimeWindow"}, {"description": "Limit to service accounts or privileged users for higher fidelity", "field": "LogonUser"}, {"description": "Allowlisting known admin jumpboxes or deployment tools", "field": "RemoteHostList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2597', 0, 113, '09-mitre-attack', 'retrieved', 'E0196F30787067A932E454F83C68B075308D3BCDFC98377A4BB0A8E3E6217313', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
