INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2598', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect anomalous use of scp, rsync, curl, or third-party sync apps transferring executables into user directories. Correlate new file creation with immediate execution events.", "external_references": [{"external_id": "AN0518", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0183#AN0518"}], "id": "x-mitre-analytic--34d6af16-fe37-458c-b15c-413ff2d5b2f7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0518", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of scp, rsync, curl with remote destination", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "File created in ~/Library/LaunchAgents or executable directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelisted apps like Dropbox or OneDrive if sanctioned", "field": "SyncApplications"}, {"description": "Adjust threshold for unusual filenames/hashes transferred internally", "field": "EntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2598', 0, 109, '09-mitre-attack', 'retrieved', 'F488E9AF728E10559049C2AD42B70EFF96261BD85E286D689EEDF876F2E85BD7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
