INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2599', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of rogue Domain Controller registration and Active Directory replication abuse by correlating: (1) creation/modification of nTDSDSA and server objects in the Configuration partition, (2) unexpected usage of Directory Replication Service SPNs (GC/ or E3514235-4B06-11D1-AB04-00C04FC2DCD2), (3) replication RPC calls (DrsAddEntry, DrsReplicaAdd, GetNCChanges) originating from non-DC hosts, and (4) Kerberos authentication by non-DC machines using DRS-related SPNs. These events in combination, especially from hosts outside the Domain Controllers OU, may indicate DCShadow or rogue DC activity.", "external_references": [{"external_id": "AN0770", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0276#AN0770"}], "id": "x-mitre-analytic--34fecfa5-24fb-46c1-955f-68ecd4cc402c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0770", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4928", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}, {"channel": "EventCode=4929", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"channel": "EventCode=4662", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}, {"channel": "Replication cookie changes involving Configuration partition with new server/nTDSDSA objects.", "name": "m365:dirsync", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "DrsAddEntry, DrsReplicaAdd, GetNCChanges calls between non-DC and DCs.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Window (seconds) between nTDSDSA object creation and subsequent replication traffic from same host (default 300s).", "field": "TimeWindow"}, {"description": "List of legitimate DCs authorized for replication to reduce false positives.", "field": "AllowedReplicationPartners"}, {"description": "SPNs indicating replication service usage (GC/, GUID E3514235-4B06-11D1-AB04-00C04FC2DCD2).", "field": "SuspiciousSPNs"}, {"description": "Trigger alerts only when AD object creation is by accounts not in Domain Admins or Enterprise Admins groups.", "field": "NonDCObjectCreationAlert"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2599', 0, 224, '09-mitre-attack', 'retrieved', '561D3608ED065677DB55F6F32038DD6AA0626F31B383B17ACDEA710D13C46175', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
