INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2600', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious reuse of SSH agent sockets across multiple users or processes, anomalous access to ~/.ssh/ or /tmp/ssh-* sockets, and abnormal patterns of lateral movement via SSH without new authentication events. Defender view: detect when one process accesses another user''s SSH agent or when an existing SSH connection is used to pivot unexpectedly.", "external_references": [{"external_id": "AN0710", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0256#AN0710"}], "id": "x-mitre-analytic--3517708a-f80e-4335-a122-65b9b3505e8d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0710", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open or connect syscalls on /tmp/ssh-* or $SSH_AUTH_SOCK", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Execution of ssh/scp/sftp without corresponding authentication log", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Missing new login event but session activity continues", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune alerts for cross-user access to SSH agent sockets.", "field": "UserContext"}, {"description": "Correlate lack of authentication with lateral SSH activity within a short timeframe.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2600', 0, 156, '09-mitre-attack', 'retrieved', '43E80F5AA08DCA9B35C114453D3EA15E5419438A31552EE3AFFCFF25491980EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
