VALUES ('doc-09-mitre-attack-p0-2601', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual mounting of loopback or pseudo file systems not aligned with legitimate administrative activity. Defender view: monitoring auditd and syslog for mount commands involving suspicious mount points, reserved blocks, or device mappings indicative of hidden partitions.", "external_references": [{"external_id": "AN1272", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0461#AN1272"}], "id": "x-mitre-analytic--35300a0c-e135-4865-9fe5-9d65a1c77dda", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1272", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "mount or losetup commands creating hidden or encrypted FS", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Sudo or root escalation followed by filesystem mount commands", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist standard mount points to reduce false positives.", "field": "AllowedMountPoints"}, {"description": "Flag root escalation during mount operations.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2601', 0, 123, '09-mitre-attack', 'retrieved', 'B986168785F2E5E3CD6E1BFA2DAD4A5B4672929420B1BE8EE71CE571E9677B24', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
