VALUES ('doc-09-mitre-attack-p0-2602', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal Apple Mail use, including internal email relays followed by file execution or script events (e.g., attachments launched via Preview, terminal triggered from Mail.app)", "external_references": [{"external_id": "AN0149", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0054#AN0149"}], "id": "x-mitre-analytic--3533fba3-e80d-4ad0-be45-62460b28ad7c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0149", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.mail.* exec.*", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "curl|osascript.*open location", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of child processes stemming from Mail.app", "field": "ExecutionChainDepth"}, {"description": "Toggle on scripting detection within mail context", "field": "MailScriptFlag"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2602', 0, 97, '09-mitre-attack', 'retrieved', '0958C827AE9A5DAC9327680B4FF3F32870BF6412EB36F12F2D817D8F14B21C86', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
