VALUES ('doc-09-mitre-attack-p0-2603', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Scripting or CLI tool access to ~/Library/Application Support/Google/Chrome or ~/Library/Safari bookmarks, cookies, or history databases. Detection relies on unexpected processes accessing or reading from these locations.", "external_references": [{"external_id": "AN0039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0013#AN0039"}], "id": "x-mitre-analytic--353e902d-b33c-466b-9276-5f224a259934", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0039", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Access to ~/Library/*/Safari or Chrome directories by non-browser processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "process reading browser configuration paths", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "System-specific paths to browser databases in user Library folders", "field": "BrowserDBPath"}, {"description": "Processes not expected to touch browser DBs (e.g., curl, bash, python)", "field": "NonBrowserProcessList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2603', 0, 115, '09-mitre-attack', 'retrieved', '494B2D753AA9CBBC084378BB3BE66C47732EFD49821C381C1BFF05791C61F2E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", 