VALUES ('doc-09-mitre-attack-p0-2605', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User or script-based access to ~/.ssh or other directories containing private keys followed by unusual shell activity or network connections.", "external_references": [{"external_id": "AN1517", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0549#AN1517"}], "id": "x-mitre-analytic--3577f79d-0891-451b-a861-1a03a3688a93", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1517", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "openat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directory/file path regex for ~/.ssh, *.pem, *.key, *.p12", "field": "FilePathRegex"}, {"description": "Script or user agent seen accessing keys (e.g., cat ~/.ssh/id_rsa, tar ~/.gnupg)", "field": "CommandLineMatch"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2605', 0, 97, '09-mitre-attack', 'retrieved', '4E873F8447B6AEC47922C5675AB23BA929CD9B797FE580FC5D3D8B03914EE01C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
