VALUES ('doc-09-mitre-attack-p0-2606', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "launchd or user-invoked processes (ssh, socat) encapsulating traffic via SSH tunnels, VPN-style tooling, or DNS-over-HTTPS clients. Defender sees outbound TLS traffic with embedded DNS or RDP payloads.", "external_references": [{"external_id": "AN1485", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0538#AN1485"}], "id": "x-mitre-analytic--359ab8ab-f306-4e67-8ff4-f8e1c8ec7db3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1485", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process execution of ssh with -L/-R forwarding flags", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "encrypted outbound traffic carrying unexpected application data", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known legitimate DoH resolvers used in environment.", "field": "ExpectedDoHResolvers"}, {"description": "Flag excessive randomness in payloads on standard ports.", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2606', 0, 112, '09-mitre-attack', 'retrieved', '49BFC4B233B25184B3BAB7188A9EADA1639C8701E4DA040D65B738802CB9FB41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
