VALUES ('doc-09-mitre-attack-p0-2607', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious long-lived or high-throughput connections by non-Apple signed apps or processes not commonly associated with network uploads. Detect background processes using open sockets for data egress.", "external_references": [{"external_id": "AN0082", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0028#AN0082"}], "id": "x-mitre-analytic--35a5d72b-6c69-498a-9118-14cd6c85a57a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0082", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process + network metrics correlation for bandwidth saturation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "exec or spawn calls to proxy tools or torrent clients", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-signed or non-Apple signed binaries can raise confidence levels.", "field": "ProcessSignedStatus"}, {"description": "Observed data rate per process over time (e.g., MB/s).", "field": "DataRateThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2607', 0, 117, '09-mitre-attack', 'retrieved', '04F8B1616767BFD951511AA9C704A2CFCF97205642ED2577F717E830CB28F373', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
