VALUES ('doc-09-mitre-attack-p0-2608', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection correlates abnormal installation or modification of root or code-signing certificates, creation/modification of suspicious registry keys for trust providers, and unusual module loads from non-standard locations. Identifies unsigned or improperly signed executables bypassing trust prompts, combined with persistence artifacts.", "external_references": [{"external_id": "AN1246", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0452#AN1246"}], "id": "x-mitre-analytic--35b0b263-f85d-4e6a-8bcb-5e2c1a9da080", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1246", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline list of approved certificate authorities that should not change frequently", "field": "TrustedPublisherList"}, {"description": "Exclusions for legitimate enterprise-signed binaries stored in unusual directories", "field": "FilePathAllowList"}, {"description": "Correlation window for registry + file + process activity", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2608', 0, 134, '09-mitre-attack', 'retrieved', '90EBEACDDD4B50F2F2C89D751386FC4451CBBCACAC7AEF37AC9CA0DB82B4A558', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
