VALUES ('doc-09-mitre-attack-p0-2609', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Automated scripts or repeated CLI/API requests that trigger application backends to consume high CPU or memory (e.g., Apache/PHP, MySQL, mail servers), resulting in syslog errors and excessive process spawning.", "external_references": [{"external_id": "AN1166", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0415#AN1166"}], "id": "x-mitre-analytic--35c7be24-c1c0-4ddc-9356-dec5e39414be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1166", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Error/warning logs from services indicating load spike or worker exhaustion", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Sustained abnormal inbound request rate targeting application ports (e.g., 80/443/25)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines number of critical errors in logs within time window.", "field": "SyslogErrorRate"}, {"description": "Spike rate on monitored service port triggering alert.", "field": "PortRequestSpikeThreshold"}, {"description": "Rate of process creation that may overwhelm the system.", "field": "ProcessSpawnRate"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2609', 0, 140, '09-mitre-attack', 'retrieved', '0206BC68184677FF9BFF00DEE46E4315102E5BEBE5067E3C8A0AAF7F742AEAD8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
