VALUES ('doc-09-mitre-attack-p0-2611', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-23T14:52:04.808Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this takes place outside the visibility of the target organization, making detection difficult for defenders.\n\nDetection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access.", "external_references": [{"external_id": "AN2059", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0916#AN2059"}], "id": "x-mitre-analytic--360eb601-28db-4418-8474-ad2a432ce534", "modified": "2026-05-12T16:30:18.376Z", "name": "Analytic 2059", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2611', 0, 72, '09-mitre-attack', 'retrieved', 'ADE53E500542170EABA936E246E56CA269BE1CE7F0349DD134ED549F24C03703', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
