INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2612', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious file creation or modification in directories ignored by XProtect or AV exclusions (e.g., ~/Library, temporary cache directories). Defender perspective: monitor file events in ignored paths with correlation to execution or persistence activity.", "external_references": [{"external_id": "AN0141", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0051#AN0141"}], "id": "x-mitre-analytic--3643a313-1aa7-44d1-b3e2-e97ad65c6837", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0141", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file creation in AV exclusion directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "process writes or modifies files in excluded paths", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths ignored by AV/XProtect that should be monitored for abnormal writes.", "field": "AVExclusionPaths"}, {"description": "Expected user or application context writing to excluded directories.", "field": "ProcessContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2612', 0, 122, '09-mitre-attack', 'retrieved', '6847475535A2F05DA9A87B79BD30F8970B620C60CDB0461D0917E3A0E87B09F4', 'v1', '{"source_id": "09-mitre-attack", "version": "