VALUES ('doc-09-mitre-attack-p0-2613', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized access, copying, or modification of Kerberos ccache files (krb5cc_%UID% or krb5.ccache) in /tmp or custom paths defined by KRB5CCNAME. Correlates file access with suspicious processes (e.g., credential dumping tools) and subsequent anomalous Kerberos authentication requests from non-standard processes.", "external_references": [{"external_id": "AN0069", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0024#AN0069"}], "id": "x-mitre-analytic--3651d7d0-dfc7-4b36-aaf2-4eb0eb39167d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0069", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open: File access attempt on /tmp/krb5cc_* or /tmp/krb5.ccache", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve: Execution of klist, kinit, or tools interacting with ccache outside normal user context", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected directories or environment variable (KRB5CCNAME) paths for ccache files in the environment.", "field": "CcachePathBaseline"}, {"description": "Baseline list of processes legitimately interacting with ccache (e.g., klist, kinit).", "field": "AllowedProcesses"}, {"description": "Correlation window for linking file access, process execution, and Kerberos requests.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2613', 0, 155, '09-mitre-attack', 'retrieved', 'CD157992D9E235F771F5C4CFC35714D319E34DA89D94FC3090B0B9E90DAE628A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
