VALUES ('doc-09-mitre-attack-p0-2614', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of SaaS platforms such as Confluence, GitHub, SharePoint Online, or Slack to access excessive internal documentation or export source code/data. Includes use of tokens or browser automation from unapproved IPs.", "external_references": [{"external_id": "AN1162", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0413#AN1162"}], "id": "x-mitre-analytic--3655f892-ed0d-4b76-9173-ecb7eebacd8a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1162", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "access.content", "name": "saas:confluence", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Exported file or accessed admin API", "name": "saas:slack", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of API calls or files accessed before triggering detection.", "field": "APIUsageThreshold"}, {"description": "Whitelist of internal IPs/users that may be excluded from detection.", "field": "KnownSafeIPs"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2614', 0, 113, '09-mitre-attack', 'retrieved', '4C5DC8A0BA790AF126C988FA4FC69575A661D173198E39299588F51FBF224163', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
