VALUES ('doc-09-mitre-attack-p0-2615', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Token replay or impersonation in federated logins without interactive browser session or MFA prompts.", "external_references": [{"external_id": "AN0956", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0956"}], "id": "x-mitre-analytic--367cfbd9-fcfd-4336-863e-b6917ff71cb4", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0956", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TokenIssuanceStart, TokenIssuanceSuccess", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "login using refresh_token with no preceding authentication context", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize for accounts where MFA must always precede token issuance", "field": "MFAContextRequired"}, {"description": "Threshold for number of times a refresh token is reused without re-auth", "field": "RefreshTokenReuseThreshold"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2615', 0, 102, '09-mitre-attack', 'retrieved', '1773EB82A059BE97C2F80DF71A22DE8AF9499CB55F6F3D229E9B77D98F72719D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
