VALUES ('doc-09-mitre-attack-p0-2616', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unsigned or scripting-based processes invoking password cracking binaries or accessing hashed credential artifacts post-login", "external_references": [{"external_id": "AN0294", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0105#AN0294"}], "id": "x-mitre-analytic--3682e3c9-33a7-4328-b0c5-73c8bbcb9b53", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0294", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process and file events via log stream", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to untrusted binaries launched by user", "field": "UnsignedBinaryPath"}, {"description": "Helps distinguish between system and user-launched activity", "field": "UserPrivilegeLevel"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2616', 0, 85, '09-mitre-attack', 'retrieved', 'A1DDAF0D0BAC42E5DBDBE7540CEF6F8619A80BDDEBE4817F97816F2FE789065C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
