VALUES ('doc-09-mitre-attack-p0-2617', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multiple failed login attempts across different users using common password patterns (e.g., ''Welcome2023'')", "external_references": [{"external_id": "AN1338", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1338"}], "id": "x-mitre-analytic--36c2c2fb-0bea-40fe-9032-c0758d381de5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1338", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Login Window and Authd errors", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Total number of attempts before alerting", "field": "RetryCountThreshold"}, {"description": "List of passwords considered suspicious due to widespread use", "field": "CommonPasswordList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2617', 0, 83, '09-mitre-attack', 'retrieved', '6F0ECF05A654160B9D0B0DFF7DC2A50999BB5FB4FDCAFCE8A14D9AAFE8ED2C54', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
