INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2619', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "VMware services or management daemons generating HTTP POST requests to webhook endpoints, chained with unusual datastore or log access. Defender perspective: exfiltration from VM logs or disk images over webhook URLs.", "external_references": [{"external_id": "AN0439", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0153#AN0439"}], "id": "x-mitre-analytic--37166782-8770-4812-b70c-27f3c705489b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0439", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "datastore file access", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "HTTPS POST connections to webhook endpoints", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum data volume to flag exfiltration attempts from VM files.", "field": "DatastoreExfilThreshold"}, {"description": "Whitelisted CI/CD or automation webhooks tied to vSphere/ESXi.", "field": "ApprovedIntegrations"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2619', 0, 113, '09-mitre-attack', 'retrieved', 'A33374563C46FA8DAECDB4F13C202BF714496BF08FB9128B2A1283DB6C4E4ED9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
