VALUES ('doc-09-mitre-attack-p0-2620', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary abuse of Transactional NTFS (TxF) and undocumented process loading mechanisms (e.g., NtCreateProcessEx) to create a hollowed process from an uncommitted, maliciously tainted file image in memory, later executed via NtCreateThreadEx.", "external_references": [{"external_id": "AN1501", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0544#AN1501"}], "id": "x-mitre-analytic--37d6450b-6c90-48dd-b69d-161099913851", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1501", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "CreateTransaction, CreateFileTransacted, RollbackTransaction, NtCreateProcessEx, NtCreateThreadEx", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Pattern of legitimate executables often used as doppelgänging targets (e.g., svchost.exe, calc.exe)", "field": "TransactionExecutableNamePattern"}, {"description": "Time delta between TxF rollback and thread creation in hollowed process", "field": "TimeWindow_TransactionToExecution"}, {"description": "Entropy level of thread start address in memory used to detect obfuscated shellcode", "field": "ThreadStartEntropyThreshold"}, {"description": "Limit on CreateTransaction + RollbackTransaction sequences per process", "field": "TxF API Call Frequency Threshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2620', 0, 159, '09-mitre-attack', 'retrieved', '6D801C7B355EEB493566FDA1C086D8D861DB139B95CBDB6D6F52628ED5BB4747', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
