VALUES ('doc-09-mitre-attack-p0-2621', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects outbound traffic from hostd/vpxa or guest VM interfaces using unauthorized protocols such as FTP, HTTP POST bursts, or long-lived DNS tunnels.", "external_references": [{"external_id": "AN0371", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0131#AN0371"}], "id": "x-mitre-analytic--3810988a-78be-4628-a9a5-500020f9c075", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0371", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "logline inspection", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "protocol egress", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected protocols used by VMs attached to host interfaces.", "field": "GuestTrafficBaseline"}, {"description": "Unexpected network activity from hypervisor processes or monitoring agents.", "field": "ServiceAccountProfile"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2621', 0, 99, '09-mitre-attack', 'retrieved', '454509265E754BDC876E4AEE4927825EEC0D4520C4DA5B8DC4EEAADDC56DE299', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
