VALUES ('doc-09-mitre-attack-p0-2622', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects HTTP or HTTPS communication initiated by shell-based scripts or management daemons, especially those reaching public IPs over ports 80/443 using embedded curl or wget.", "external_references": [{"external_id": "AN0078", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0027#AN0078"}], "id": "x-mitre-analytic--38205f16-18da-4d04-ae54-f5143b75c938", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0078", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SPAN or port-mirrored HTTP/S", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "/root/.ash_history or /etc/init.d/*", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match on commands like `wget https://*`, `curl -s`", "field": "ShellScriptMatch"}, {"description": "Public IPs or external DNS hostnames", "field": "ExternalConnectionFilter"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2622', 0, 101, '09-mitre-attack', 'retrieved', 'AD4986302C87780B9E526F2B3A5DF06AFE761961693F59C14998903CB1766AF8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
