VALUES ('doc-09-mitre-attack-p0-2623', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of pbpaste/pbcopy clipboard access by processes without terminal sessions or linked to launch agents, potentially staged for collection.", "external_references": [{"external_id": "AN0966", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0341#AN0966"}], "id": "x-mitre-analytic--38252d77-0b46-4e00-8732-3ce1f8491472", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0966", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "How many chained or embedded processes to track for correlation.", "field": "ExecutionChainLength"}, {"description": "Whether the pbpaste/pbcopy action is tied to a user terminal.", "field": "TerminalSession"}, {"description": "Adjust if clipboard tooling is relocated (e.g., /opt/empyre/pbpaste).", "field": "BinaryPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2623', 0, 101, '09-mitre-attack', 'retrieved', '7895EFD424957BC2659902FB92A5EF488471C21021750A37D987B518A5D190BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
