VALUES ('doc-09-mitre-attack-p0-2624', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects spoofed emails by analyzing mail server logs (e.g., Postfix, Sendmail) for mismatched header fields, failed SPF/DKIM checks, and anomalies in SMTP proxy logs. Defender observes discrepancies between sending domain, return-path domain, and message metadata.", "external_references": [{"external_id": "AN1203", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0431#AN1203"}], "id": "x-mitre-analytic--38300670-8c96-4f80-bc1b-d69242023a20", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1203", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SPF fail OR DKIM fail OR DMARC fail OR mismatched from_domain vs return_path_domain", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines approved sender domains to suppress alerts for expected mismatches, reducing false positives.", "field": "SenderDomainWhitelist"}, {"description": "Sets correlation period for repeated spoofing attempts to flag campaigns vs. isolated misconfigurations.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2624', 0, 124, '09-mitre-attack', 'retrieved', 'E24569BE331B01795159AB8FBE0188242FF067FABAAE91D346C79854DCCDC3B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
