INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2625', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects snapshot sharing, backup exports, or data object transfers from victim-owned cloud accounts to other cloud identities within the same provider (e.g., AWS, Azure) using snapshot sharing, S3 bucket policy updates, or SAS URI generation.", "external_references": [{"external_id": "AN1580", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0573#AN1580"}], "id": "x-mitre-analytic--383dda28-1d76-4605-a53d-07829f3d7ef8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1580", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ModifySnapshotAttribute", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f1eb6ea9-f3ab-414f-af35-2d5427199984"}, {"channel": "PutBucketPolicy", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}, {"channel": "CreateSnapshot", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--3da222e6-53f3-451c-a239-0b405c009432"}, {"channel": "CopySnapshot", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8bc66f94-54a9-4be4-bdd1-fe90df643774"}, {"channel": "High volume internal-to-internal IP transfer or cross-account cloud transfer", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of external cloud accounts authorized for snapshot or bucket sharing", "field": "CrossAccountIDList"}, {"description": "Geographic region in which the sharing occurs (may impact logging availability)", "field": "Region"}, {"description": "Threshold to alert on snapshot size or object volume", "field": "VolumeSizeThresholdGB"}, {"description": "Temporal window between snapshot creation and external sharing", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2625', 0, 163, '09-mitre-attack', 'retrieved', '5B325E6C260BA1847F3D04E425105F651DC32BFBA821C0BE3D72F5F6D0BDACB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
