INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2628', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of adversary attempts to enumerate containers, pods, nodes, and related resources within containerized environments. Defenders may observe anomalous API calls to Docker or Kubernetes (e.g., ''docker ps'', ''kubectl get pods'', ''kubectl get nodes''), unusual account activity against the Kubernetes dashboard, or unexpected queries against container metadata endpoints. These events should be correlated with user context and network activity to reveal resource discovery attempts.", "external_references": [{"external_id": "AN1352", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0490#AN1352"}], "id": "x-mitre-analytic--3947e311-cada-4eab-b4fd-1ea1f3fc3485", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1352", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "list or get requests against pods, deployments, or nodes", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--07688e40-a7fa-4436-937f-1216674341a0"}, {"channel": "docker ps, docker inspect, or docker images commands", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--91b3ed33-d1b5-4c4b-a896-76c55eb3cfd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines which service accounts and admin roles are expected to perform discovery actions. Activity by non-allowlisted identities may indicate adversary discovery.", "field": "UserAllowList"}, {"description": "Specifies correlation period (e.g., 10m) for linking multiple discovery attempts across API and daemon logs.", "field": "TimeWindow"}, {"description": "Defines threshold for number of pod/node enumeration requests by a single user. Excessive queries may indicate scanning activity.", "field": "PodQueryThreshold"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2628', 0, 193, '09-mitre-attack', 'retrieved', 'F4536360C714BA2BBCBE90ADB92AA931EE9F0991C372CD26714467F934650389', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
