VALUES ('doc-09-mitre-attack-p0-2630', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects binary movement or copying between untrusted and trusted paths (e.g., /tmp/ → /usr/bin/ or /etc/init.d/) that may indicate persistence attempts or cleanup of origin traces.", "external_references": [{"external_id": "AN1217", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0439#AN1217"}], "id": "x-mitre-analytic--39aa9168-6f3b-4179-84f9-a6b8dcf90900", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1217", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PATH", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match movement into known persistence or exclusion directories", "field": "RelocationPathPatterns"}, {"description": "Apply threshold to detect high-entropy relocations (e.g., packed malware)", "field": "BinaryEntropyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2630', 0, 94, '09-mitre-attack', 'retrieved', 'CA168B1076FEDDFAB03E552CD854E6DF7F6A052CD0DF8DE92092639E886912E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
