VALUES ('doc-09-mitre-attack-p0-2632', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Firmware image uploaded via TFTP/SCP or web interface followed by reboot or unexpected loss of connectivity.", "external_references": [{"external_id": "AN0477", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0167#AN0477"}], "id": "x-mitre-analytic--39d675d5-548d-4b35-8a8f-a6605ae3835d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0477", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "large upload to firmware interface port or path", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Firmware update initiated or bootloader tampering detected", "name": "networkdevice:firmware", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Size of firmware images varies by vendor", "field": "UploadSizeThreshold"}, {"description": "Reboots outside of patch maintenance may be suspicious", "field": "RebootWindow"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2632', 0, 102, '09-mitre-attack', 'retrieved', '8E02E7A240CCF1B14A7004E3F422AAB522DBA0A37154ADB65500EC1E44D7AD47', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
