VALUES ('doc-09-mitre-attack-p0-2633', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A source performs a closed-port sequence; the endpoint enables a PF/socketfilterfw rule or a background process binds a port; then a successful connection completes from the same source.", "external_references": [{"external_id": "AN0844", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0302#AN0844"}], "id": "x-mitre-analytic--39da0718-fa22-4f77-8bd2-ea8300087658", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0844", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec: Execution of pfctl, socketfilterfw, launchctl start ssh/telnet, libpcap consumers.", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Firewall/PF anchor load or rule change events.", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Sequence of REJ/S0 then SF success from same src_ip within TimeWindow.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Anchors/confs to monitor (/etc/pf.conf, /etc/pf.anchors/*).", "field": "PFAnchorPaths"}, {"description": "Suppress expected PF testing on developer devices.", "field": "DevMode"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2633', 0, 128, '09-mitre-attack', 'retrieved', '261F626F4B62F6DDFFCCA3D16B2190F0FBDEC225F0FC3FDF7C2D3CFD8436EC00', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
