VALUES ('doc-09-mitre-attack-p0-2634', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects SCCM, Intune, or remote push execution spawning scripts or binaries from SYSTEM context or unusual consoles (e.g., cmtrace.exe launching PowerShell or cmd.exe).", "external_references": [{"external_id": "AN0623", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0223#AN0623"}], "id": "x-mitre-analytic--39ec0aa6-935a-44d3-b206-211981dec3bd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0623", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "SCCM, Intune logs", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlist of known SCCM-related binary spawners (e.g., ''CCMExec.exe'')", "field": "ParentImageList"}, {"description": "Expected deployment activity from scheduled system accounts", "field": "UserContext"}, {"description": "Unusual deployment timing outside standard maintenance hours", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2634', 0, 107, '09-mitre-attack', 'retrieved', '9930061DEF48F01535AFEF8B7A4DD7A58F937323004D877FDB2398329F7F582E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge