VALUES ('doc-09-mitre-attack-p0-2635', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modifications to authorization plugins responsible for MFA enforcement and correlates with suspicious login sessions missing MFA prompts.", "external_references": [{"external_id": "AN0547", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0190#AN0547"}], "id": "x-mitre-analytic--3a19d0ff-833f-47ae-81a0-2516e91c7b25", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0547", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Modification of /Library/Security/SecurityAgentPlugins", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Login success without MFA step", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths to organization-deployed MFA authorization plugins.", "field": "WatchedPluginPaths"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2635', 0, 84, '09-mitre-attack', 'retrieved', 'FA409BEF2F588BFE2772209283ABD497F37EEFE7E51D8B908D3075B666D62C73', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
