VALUES ('doc-09-mitre-attack-p0-2636', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary behavior where a process enumerates and modifies another process''s memory using /proc/[pid]/maps and /proc/[pid]/mem files. This includes identifying gadgets via memory mappings and overwriting process memory via low-level file modification or dd usage.", "external_references": [{"external_id": "AN1494", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0541#AN1494"}], "id": "x-mitre-analytic--3a57e109-235d-497a-9c90-952ab8b749b6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1494", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/write to /proc/*/mem or /proc/*/maps", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve of dd or sed targeting /proc/*/mem", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "/proc/*/maps access", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex list of high-value processes attackers may inject into, such as `sshd`, `nginx`, or `sleep`", "field": "TargetProcNameRegex"}, {"description": "Time span (e.g., 4096 bytes)", "field": "FileWriteThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2636', 0, 129, '09-mitre-attack', 'retrieved', '99ABA99B5A2C61DDC0A3287CADA6688DDF7F919F47CB0835EA4CAB26B73DC233', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
