VALUES ('doc-09-mitre-attack-p0-2637', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of JamPlus.exe to launch malicious payloads via crafted .jam files, resulting in abnormal process creation, command execution, or artifact generation outside of standard development workflows.", "external_references": [{"external_id": "AN1610", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0585#AN1610"}], "id": "x-mitre-analytic--3a5eea3b-b447-47c5-832d-6ced137b1597", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1610", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Unsigned or untrusted modules loaded during JamPlus.exe runtime", "name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation time window (e.g., 0–30 minutes) for JamPlus.exe execution, child processes, and file/network events.", "field": "TimeWindow"}, {"description": "Known developer systems where JamPlus.exe usage is expected; alerts are raised if executed elsewhere.", "field": "AllowedBuildHosts"}, {"description": "Child processes considered anomalous (e.g., PowerShell, cmd, wscript) when spawned by JamPlus.exe.", "field": "SuspiciousChildList"}, {"description": "Regex patterns for non-standard or user-writable paths where JamPlus.exe drops artifacts.", "field": "RarePathRegex"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2637', 0, 160, '09-mitre-attack', 'retrieved', 'EEB3D09F65574B5B8FBD790A12D12D9FE87426D43FE78EDBDB337F9279117FE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
