VALUES ('doc-09-mitre-attack-p0-2638', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain in CI/dev desktops: (1) user triggers container run/pull after opening a doc/link/script, (2) newly created image/container uses unexpected external registry or entrypoint, (3) container starts and immediately egresses to suspicious destinations.", "external_references": [{"external_id": "AN1317", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0478#AN1317"}], "id": "x-mitre-analytic--3a6fdd1a-59c6-4f46-a761-0de502229da0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1317", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "created,started: new container from untrusted registry or unexpected entrypoint", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"channel": "start", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"channel": "container egress to unknown IPs/domains", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved registries/namespaces.", "field": "TrustedRegistries"}, {"description": "Expected CMD/ENTRYPOINT for known images.", "field": "AllowedEntrypoints"}, {"description": "Correlate user action → docker/podman run within 10 minutes.", "field": "TimeWindow"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2638', 0, 127, '09-mitre-attack', 'retrieved', 'C027268932232649265389040B31CB5E1789B8FF15FB20E90E5F1A093791EDFC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
