VALUES ('doc-09-mitre-attack-p0-2640', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes accessing ALSA/PulseAudio devices or executing audio capture binaries like ''arecord'', followed by file creation or suspicious child process spawning.", "external_references": [{"external_id": "AN0620", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0221#AN0620"}], "id": "x-mitre-analytic--3ac9b4c2-9137-4d20-9619-01029d656874", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0620", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=1", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Capture binaries like arecord, parecord, or ffmpeg.", "field": "ExecutableName"}, {"description": "Log attempts to access /dev/snd/*, /dev/dsp, /proc/asound/*.", "field": "DevicePath"}, {"description": "Whether the user has audio access rights or is running under elevated privileges.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2640', 0, 113, '09-mitre-attack', 'retrieved', '23A1FC5083F95AA39F0A57D356383BE28F086657974705538678AAB0397A5383', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
