INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2641', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of package install event with execution of postinstall scripts containing unknown binaries or abnormal CLI usage. Look for `/usr/sbin/installer` execution followed by child processes originating from postinstall script.", "external_references": [{"external_id": "AN0938", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0330#AN0938"}], "id": "x-mitre-analytic--3ae8f3c1-c3a1-4c45-9231-1bb6f9c61ee1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0938", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of /usr/sbin/installer spawning child process from within /private/tmp or package contents", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Creation or modification of postinstall scripts within .pkg or .mpkg contents", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to postinstall script varies depending on .pkg packaging and user temp directories.", "field": "ScriptLocation"}, {"description": "Installers may vary (e.g., /usr/sbin/installer, Jamf, Munki).", "field": "ParentProcessName"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2641', 0, 127, '09-mitre-attack', 'retrieved', '03C9515FC18DA63AC33EB1D1B8886775D52175796521D15E309834B0681600CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
