VALUES ('doc-09-mitre-attack-p0-2642', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modification of shell startup/logout scripts such as ~/.bashrc, ~/.bash_profile, or /etc/profile, followed by anomalous process execution or network connections upon interactive or remote shell login.", "external_references": [{"external_id": "AN0059", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0020#AN0059"}], "id": "x-mitre-analytic--3ae99176-ce61-4598-834b-f48d13802dcb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0059", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AUDIT_SYSCALL (open, write, rename, unlink)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execution of unexpected binaries during user shell startup", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unexpected network activity initiated shortly after shell session starts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how soon after shell startup process execution or network activity is considered suspicious.", "field": "TimeWindow"}, {"description": "Limits detection to specific user accounts or roles such as root or service accounts.", "field": "TargetUser"}, {"description": "Defines what shell configuration paths are considered relevant (e.g., .bashrc, .bash_logout, etc.)", "field": "FilePathRegex"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2642', 0, 151, '09-mitre-attack', 'retrieved', 'C2B9AC6F0256A6B73C05F47EC74A2028457AFF848EC55E2C47A76ACE645AE13C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
