VALUES ('doc-09-mitre-attack-p0-2643', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors programmatic access to user mailboxes in cloud-based email systems (e.g., O365, Exchange Online) using APIs or tokens. Focuses on OAuth misuse, suspicious MailItemsAccessed patterns, scripted keyword searches, and connections from untrusted agents or locations.", "external_references": [{"external_id": "AN0132", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0048#AN0132"}], "id": "x-mitre-analytic--3af413c2-5b26-4f43-b198-11b4dce97a0a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0132", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "MailItemsAccessed, Search-Mailbox events", "name": "m365:purview", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Suspicious login to cloud mailbox system", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Search-Mailbox, Get-MessageTrace, eDiscovery requests", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of emails accessed within time window to flag anomaly.", "field": "MailAccessVolumeThreshold"}, {"description": "Allows tuning based on known app registrations.", "field": "OAuthClientIDAllowList"}, {"description": "Flag high volumes of message searches using suspicious patterns.", "field": "KeywordSearchFrequency"}, {"description": "Trigger when IP geolocation varies significantly from user''s historical profile.", "field": "LoginGeolocationVariance"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2643', 0, 151, '09-mitre-attack', 'retrieved', '9D9DD5BD1ED85097252EA1AAF1C2A359454C61E1E85816C926962540CC7B5BAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
