VALUES ('doc-09-mitre-attack-p0-2644', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of shell interpreters (e.g., bash, sh, python, perl) initiated by users or processes not normally executing them, especially when chaining suspicious utilities like netcat, curl, or ssh.", "external_references": [{"external_id": "AN1429", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0516#AN1429"}], "id": "x-mitre-analytic--3b02d81a-8684-4fc8-8364-127f30359282", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1429", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex to identify which interpreters (bash, python, ruby) to monitor based on typical usage.", "field": "InterpreterName"}, {"description": "Scope to users or service accounts not expected to run interpreters interactively.", "field": "UserContext"}, {"description": "Defines maximum process tree depth to correlate interpreter execution with its effects.", "field": "ExecutionChainLength"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2644', 0, 121, '09-mitre-attack', 'retrieved', 'DF4142BA3BA720E3B621E634333E79A216F8832F3C2876F66041071EB2DD3DF8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
