VALUES ('doc-09-mitre-attack-p0-2645', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Userland or kernel-level ransomware encrypting user files (Documents, Desktop) using `srm`, `gpg`, or compiled payloads. Often correlated with ransom note creation in multiple directories.", "external_references": [{"external_id": "AN0604", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0215#AN0604"}], "id": "x-mitre-analytic--3b18d20b-94c7-41e7-8f82-99148945a74f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0604", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file encrypted|new file with .encrypted extension|disk write burst", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "exec srm|exec openssl|exec gpg", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Encrypted files may use .locked, .enc, or ransom-specific extensions.", "field": "ExtensionPattern"}, {"description": "Detect activity targeting mounted external or backup volumes.", "field": "VolumeTargeted"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2645', 0, 108, '09-mitre-attack', 'retrieved', '055BE6B69A8BA3AE6C4B6E46864427400D86855E90FEA034A70C81068DDE477D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
