VALUES ('doc-09-mitre-attack-p0-2646', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitoring for modification and execution of login hook scripts or LaunchAgents/LaunchDaemons used for persistence.", "external_references": [{"external_id": "AN0313", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0112#AN0313"}], "id": "x-mitre-analytic--3b218f49-59ce-44a5-a10b-889c99e78934", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0313", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "file", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "launchd", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "LaunchAgent or LaunchDaemon label name, often environment-specific.", "field": "Label"}, {"description": "Arguments passed to scripts, which may need tuning by environment.", "field": "ProgramArguments"}, {"description": "Distinguish between user login and system startup agents.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2646', 0, 105, '09-mitre-attack', 'retrieved', '2D6009B676765AD558836060A8177C9BC4F6CA9A15331DFEF1FEDF8963B020FB', 'v1', '{"source_id": "09-mitre-attack", "version": "ret