VALUES ('doc-09-mitre-attack-p0-2648', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects AppleScript or Objective-C usage to generate fake authentication windows (e.g., using display dialog or NSAlert) from user-launched or persistence-related processes.", "external_references": [{"external_id": "AN1442", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0521#AN1442"}], "id": "x-mitre-analytic--3b327a8f-0ea3-4848-b34a-58029e5edf57", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1442", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.Security or com.apple.applescript", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "AppleScript snippets like ''display dialog'' or ''with hidden answer''", "field": "ScriptContent"}, {"description": "Tune out Apple-signed and expected automation tasks", "field": "ProcessPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2648', 0, 96, '09-mitre-attack', 'retrieved', '8A7E514B37683283C320399F2B8061D7D37FAA43700A59344FA82D59B13E5E03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
