VALUES ('doc-09-mitre-attack-p0-2649', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor SaaS financial systems (e.g., QuickBooks, Workday, SAP S/4HANA cloud) for unauthorized access, rule changes, or mass export of financial data. Detect anomalous transfers initiated via SaaS APIs or new MFA-disabled logins targeting finance apps.", "external_references": [{"external_id": "AN1364", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0495#AN1364"}], "id": "x-mitre-analytic--3bac57c4-1539-4048-b325-88032c78ed08", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1364", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Transaction/Transfer: Unusual or large transactions initiated outside business hours or by unusual accounts", "name": "saas:finance", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customizable monetary threshold above which financial transactions should be flagged.", "field": "TransactionThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2649', 0, 105, '09-mitre-attack', 'retrieved', 'EF54059161BAD984926484EA8D83250A72D8EAA96353C4561399028E740E9B68', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
