VALUES ('doc-09-mitre-attack-p0-2652', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates ELF file execution with high-entropy writable memory segments and self-modifying code patterns.", "external_references": [{"external_id": "AN0067", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0023#AN0067"}], "id": "x-mitre-analytic--3cb4d3f4-df71-474c-a9f0-438dbf26bf66", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0067", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "mprotect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Useful for tuning unpacked sections containing high entropy indicative of compression or encryption.", "field": "EntropyThreshold"}, {"description": "Can be tuned to correlate file writes to execution within a set timeframe.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2652', 0, 96, '09-mitre-attack', 'retrieved', 'F6111A20B88CEA5DAA1168463CC0B2138F839131F1031A29A0EFBBD7155757BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
