VALUES ('doc-09-mitre-attack-p0-2653', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged SAML tokens can be observed as authentication attempts with valid signatures but missing expected preceding Kerberos or authentication events. Defenders may correlate SAML assertions with absent Event IDs 4769, 1200, or 1202, or tokens issued with abnormal lifetimes, issuers, or claims compared to baseline.", "external_references": [{"external_id": "AN0418", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0148#AN0418"}], "id": "x-mitre-analytic--3cb835e5-ded1-42c4-a5cc-38911078b0a5", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0418", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SAML-based login with anomalous issuer or NotOnOrAfter lifetime", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "EventCode=4769, 1200, 1202", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the maximum expected lifetime of a SAML token (e.g., >1 hour considered anomalous).", "field": "TokenLifetimeThreshold"}, {"description": "List of approved SAML issuers and certificate thumbprints.", "field": "TrustedIssuerList"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2653', 0, 134, '09-mitre-attack', 'retrieved', '098802B5310D91E76414ECAB8B557DD2803D2D33315EF11EFE52EE28425446DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
