VALUES ('doc-09-mitre-attack-p0-2654', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses cloud-native APIs or CLI (e.g., AWS Systems Manager, Azure Resource Graph) to list installed software on cloud workloads.", "external_references": [{"external_id": "AN1103", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0392#AN1103"}], "id": "x-mitre-analytic--3ccd6662-c579-494f-bbfa-ffc3530e3db2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1103", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ssm:ListInventoryEntries", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "ssm:GetCommandInvocation", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Differentiate access from automated scripts vs. authorized console.", "field": "UserAgent"}, {"description": "May focus on Application or Platform inventory only.", "field": "InventoryType"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2654', 0, 93, '09-mitre-attack', 'retrieved', '79ACBDE2305B2E4E4A58FF88171F47F952EEDCB9880D53F83B419463AC03FCC1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
