VALUES ('doc-09-mitre-attack-p0-2655', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects compilation activity using csc.exe, ilasm.exe, or msbuild.exe initiated by user-space processes outside typical development environments, followed by execution or network activity from newly written binaries.", "external_references": [{"external_id": "AN1381", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0501#AN1381"}], "id": "x-mitre-analytic--3cd889a5-7955-4d38-a49b-89e8d276ceab", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1381", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for unexpected users (non-dev) launching compilers like csc.exe or msbuild.exe", "field": "ParentProcessName"}, {"description": "Adjust paths for sensitive file write zones (e.g., `C:\\Users\\Public\\`, `%TEMP%`, or Desktop)", "field": "OutputDirectoryPath"}, {"description": "Tune the correlation window between compilation and subsequent execution or C2", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2655', 0, 127, '09-mitre-attack', 'retrieved', 'ACA74B305BF0494FC3AD4CC5AA703526E12ABBBBAD50120F314AE7FD4C4FBAAB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
