VALUES ('doc-09-mitre-attack-p0-2656', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized edits to /etc/hosts, /etc/resolv.conf, or suspicious ARP broadcasts. Correlates file modifications with subsequent unexpected network sessions or service creation.", "external_references": [{"external_id": "AN0824", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0296#AN0824"}], "id": "x-mitre-analytic--3cdef7d3-4ca6-4d4a-933b-656af73f8433", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0824", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Unexpected ARP replies or DNS responses inconsistent with authoritative servers", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of system files shaping traffic flow (hosts, resolv.conf, PAM modules).", "field": "MonitoredFiles"}, {"description": "Rate/volume thresholds for ARP/DNS anomalies tuned per subnet.", "field": "ARPThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2656', 0, 107, '09-mitre-attack', 'retrieved', 'BF89D36DC78F8687D18B09958E51FAAB326AE8591BB9268154657AC8D410B27D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
