VALUES ('doc-09-mitre-attack-p0-2659', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious write operations to block devices, modifications of bootloader files (GRUB, initrd, vmlinuz), and unexpected changes within the EFI System Partition. Monitors privileged execution of utilities like dd, grub-install, or efibootmgr that modify boot sectors or loader entries.", "external_references": [{"external_id": "AN0429", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0150#AN0429"}], "id": "x-mitre-analytic--3d209345-1676-4170-b1d0-d6538bce06c4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0429", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write: Write operations targeting /dev/sda, /dev/nvme0n1, or EFI partition mounts", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Block device write errors or unusual bootloader activity", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline checksums of GRUB, kernel, and initramfs images", "field": "BootloaderHashBaseline"}, {"description": "Trusted EFI executables for Linux environments", "field": "EFIFileAllowlist"}, {"description": "Tunable thresholds for triggering alerts on repeated EFI/bootloader writes", "field": "AlertThresholds"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2659', 0, 140, '09-mitre-attack', 'retrieved', 'FE0FE679439D4D1AAEBA5A816015F49F919AF128B6DBD1504A53DF6E8326CACD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
