VALUES ('doc-09-mitre-attack-p0-2660', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Modification of plist files to set apple.awt.UIElement or similar flags hiding app icons and windows, and dscl/command-line activity that suppresses visibility. Defender view: correlation of plist modifications with unexpected hidden user applications.", "external_references": [{"external_id": "AN0362", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0128#AN0362"}], "id": "x-mitre-analytic--3d9fb03c-fcc9-4f19-9c49-09d8321f28b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0362", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Modification of plist with apple.awt.UIElement set to TRUE", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Execution of Java apps or other processes with hidden window attributes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict detection to application plists where UIElement flag is unexpected.", "field": "PlistScope"}, {"description": "Correlate plist modifications with the creating/modifying user to tune results.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2660', 0, 126, '09-mitre-attack', 'retrieved', '327FAE6BF39564928A3277054E70ADD64B87A164D2E936AD7F0CDEF45A6E8A4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
