VALUES ('doc-09-mitre-attack-p0-2661', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized or anomalous use of command-line interfaces (CLI) on network devices. Focuses on remote access sessions (e.g., SSH/Telnet), privilege escalation within CLI sessions, execution of high-risk commands (e.g., config replace, terminal monitor, no logging), and configuration changes outside of approved windows.", "external_references": [{"external_id": "AN0399", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0142#AN0399"}], "id": "x-mitre-analytic--3dc28690-699a-4f6d-ad4b-278aa2dd8c59", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0399", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command_exec", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "remote CLI session detection", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "authorization/accounting logs", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Config changes made outside of maintenance windows are more suspicious.", "field": "TimeWindow"}, {"description": "Unexpected CLI activity by service accounts or users not assigned to manage network devices.", "field": "UserContext"}, {"description": "Regex or keyword match on dangerous or unusual commands (e.g., ''no logging'', ''reload'', ''copy tftp'', ''config replace'').", "field": "CommandPattern"}, {"description": "Remote CLI sessions originating from untrusted networks or jump hosts.", "field": "SourceIP"}, {"description": "Abnormally short or long SSH/Telnet CLI sessions compared to baseline.", "field": "SessionDuration"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2661', 0, 180, '09-mitre-attack', 'retrieved', '514A01128A95379CD006DB81C08E01273FF3ED3C5C4ABEB435D1CF701719402A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
