VALUES ('doc-09-mitre-attack-p0-2662', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized API or console calls to retrieve or reset password credentials, download key material, or modify SSO settings.", "external_references": [{"external_id": "AN1157", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0412#AN1157"}], "id": "x-mitre-analytic--3e30007c-fc51-447f-850a-c8378427be3d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1157", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Reset password or download key from portal", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "GetSecretValue", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Subset of IdP settings monitored for unauthorized changes", "field": "SSOSettingScope"}, {"description": "Which secrets (passwords, keys, tokens) are monitored", "field": "SecretType"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2662', 0, 97, '09-mitre-attack', 'retrieved', '4412CD18979AA9D4CB36819ABEAE9E7D3921F4AE0CC4E60B73E90B07FB1A8845', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
