VALUES ('doc-09-mitre-attack-p0-2663', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of system binaries such as `osascript`, `bash`, or `curl` to download or execute unsigned code or files in conjunction with application proxying.", "external_references": [{"external_id": "AN0228", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0081#AN0228"}], "id": "x-mitre-analytic--3e461dab-922c-48cc-aafc-51f20025bf27", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0228", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec of osascript, bash, curl with suspicious parameters", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "execution of trusted tools interacting with external endpoints", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "macOS binary whitelist including `/usr/bin/osascript`, `/bin/bash`, `/usr/bin/curl`", "field": "TrustedUtilityList"}, {"description": "Used to detect proxy execution from signed binary to unsigned payload", "field": "SignedToUnsignedTransition"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2663', 0, 112, '09-mitre-attack', 'retrieved', 'C2D21D3D9588FFBFA7EE2F330EEA99F054A1A86EF0B2FB541DF937F37AA1B5AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
