VALUES ('doc-09-mitre-attack-p0-2664', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Encrypted sessions detected with asymmetric key exchange anomalies on non-standard ports or with invalid/malformed certs. Defender correlates NetFlow/IPFIX with IDS/IPS detecting RSA exchanges outside expected TLS flows.", "external_references": [{"external_id": "AN1500", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0543#AN1500"}], "id": "x-mitre-analytic--3e5930bf-6d79-4f75-9b9e-97cad9bf9232", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1500", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Flow records with RSA key exchange on unexpected port", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Malformed certs, incomplete asymmetric handshakes, or invalid CAs", "name": "IDS:TLSInspection", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define expected ports for asymmetric cryptography (e.g., 443, 993).", "field": "PortProfiles"}, {"description": "Thresholds for rejecting untrusted/self-signed certs.", "field": "CertValidationPolicy"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2664', 0, 114, '09-mitre-attack', 'retrieved', 'BCAC0D930B3ADABE340BEE2D3725C6FAFB4DE4FA82FECFFB0C160EB697B999CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
