VALUES ('doc-09-mitre-attack-p0-2665', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Registry key modifications under IFEO paths (e.g., Debugger value set under Image File Execution Options), especially for security-related or accessibility binaries, followed by anomalous process execution with debugger flags or SYSTEM-level access at login. Detectable by correlating registry modifications, process creation, and parent-child anomalies with unusual command-line usage or access tokens.", "external_references": [{"external_id": "AN1186", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0422#AN1186"}], "id": "x-mitre-analytic--3e5b15b0-e6b2-402a-9c4f-e483c968a38e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1186", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time delta for correlating registry modification and debugger-triggered execution", "field": "TimeWindow"}, {"description": "Specific executables that trigger defenders’ alerts when IFEO values are set", "field": "TargetBinary"}, {"description": "Tunable logic for detecting parent-child anomalies (e.g., non-standard parent processes)", "field": "ParentProcessAnomaly"}, {"description": "May require tuning based on normal SYSTEM or admin process elevation patterns", "field": "TokenElevationContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2665', 0, 168, '09-mitre-attack', 'retrieved', '54389A7C69E644F3D6CB88A923D31D67CCBCD9822B9ED97547BC421980EA6557', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
