VALUES ('doc-09-mitre-attack-p0-2666', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outbound fallback traffic from low-profile or background launch agents using unusual protocols or destinations after primary channel inactivity.", "external_references": [{"external_id": "AN1378", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0499#AN1378"}], "id": "x-mitre-analytic--3e682b33-5064-4202-aad7-ca1900fde1a5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1378", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "None", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to suppress known legitimate agents.", "field": "LaunchAgentContext"}, {"description": "Can help isolate covert or encrypted fallback traffic.", "field": "PayloadEntropy"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2666', 0, 89, '09-mitre-attack', 'retrieved', '16C2130A0A865BFAA560BA4F7E05FB774005E6259A531ACE302DB658C10CA90D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
