VALUES ('doc-09-mitre-attack-p0-2667', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of gzip, base64, tar, or openssl in scripts or commands that encode/encrypt files after file staging or system enumeration.", "external_references": [{"external_id": "AN1065", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0378#AN1065"}], "id": "x-mitre-analytic--3e7ff1f9-57e2-44f4-8dc1-20d1a1652f73", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1065", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Shell history logs", "name": "linux:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize for tools seen in environment (e.g., gzip, bzip2, xz)", "field": "CommandRegex"}, {"description": "Specify file paths likely targeted for obfuscation (e.g., /etc/, /home/)", "field": "SensitivePathList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2667', 0, 107, '09-mitre-attack', 'retrieved', 'B88F9ECA506710911E1A39F70B3D09E8D6CF46FC7F72D0813C1B56B5767FF6A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_ty