VALUES ('doc-09-mitre-attack-p0-2668', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes generating large outbound connections with disproportionate send/receive ratios, often to uncommon ports or hosts, potentially inserting meaningless data into protocol payloads.", "external_references": [{"external_id": "AN0030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0011#AN0030"}], "id": "x-mitre-analytic--3e852bb9-785d-4bc4-9f7e-b7e43a5d8bc8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0030", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "TCP/UDP", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable threshold for Shannon entropy of network payloads.", "field": "PayloadEntropyThreshold"}, {"description": "Duration of outbound data transfer to evaluate disproportionate upload size.", "field": "TimeWindow"}, {"description": "Filter based on user accounts allowed to generate outbound traffic.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2668', 0, 117, '09-mitre-attack', 'retrieved', '