VALUES ('doc-09-mitre-attack-p0-2669', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of Java-based or CLI database tools (e.g., DBeaver, Beekeeper, mysql, psql) from user profiles not tied to dev/admin roles, especially when followed by file writes and cloud sync activity. Defender correlates GUI tool launches, file write events in ~/Downloads or ~/Documents, and outbound API calls to known cloud services.", "external_references": [{"external_id": "AN0678", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0242#AN0678"}], "id": "x-mitre-analytic--3e87713d-d062-413c-9643-97df331ba651", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0678", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process start of Java or native DB client tools", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Writes of .sql/.csv/.xlsx files to user documents/downloads", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "HTTPS API requests to Dropbox, iCloud, Google Drive, OneDrive shortly after DB tool usage", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "FQDNs of sync services used to detect likely outbound DB leakages", "field": "CloudSyncDomainList"}, {"description": "Whether to treat low-privilege users accessing DB tools as higher risk", "field": "UserPrivilegeLevel"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2669', 0, 162, '09-mitre-attack', 'retrieved', '2A43CD0044CC1A385818A918209EA655A43407A3E2C92ECDA7073A3989BD42DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
