INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2670', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disabling or modifying the Linux Audit system through process termination (auditd killed), service management (systemctl stop auditd), or tampering with rule/configuration files (/etc/audit/audit.rules, audit.conf). Defender view: suspicious execution of auditctl/systemctl commands, file modifications to audit rules, or sudden absence of audit logs correlated with privileged execution.", "external_references": [{"external_id": "AN0171", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0062#AN0171"}], "id": "x-mitre-analytic--3e9734aa-b9b4-4716-927c-27c2c2aa972e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0171", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of auditctl, systemctl stop auditd, or kill -9 auditd", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "kill syscalls targeting auditd process", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "Modification or deletion of /etc/audit/audit.rules or /etc/audit/audit.conf", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "auditd service stopped or disabled", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude legitimate administrative service stops during system maintenance.", "field": "ServiceWhitelist"}, {"description": "Specify monitored paths (/etc/audit/audit.rules, audit.conf) to avoid false positives from unrelated file writes.", "field": "FilePathScope"}, {"description": "Correlate suspicious commands, file modifications, and audit log gaps in short succession.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2670', 0, 174, '09-mitre-attack', 'retrieved', 'F99BDE6104F1CD2AAD9B26C135CD74F15226BD9E61C631E3580CB82A6A1F5235', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
