VALUES ('doc-09-mitre-attack-p0-2671', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects direct modification of crontab entries in /var/spool/cron/crontabs/root or /etc/rc.local.d/local.sh followed by execution of scripts linked to lateral movement or malware persistence.", "external_references": [{"external_id": "AN0807", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0290#AN0807"}], "id": "x-mitre-analytic--3ea6b02e-47e0-4815-9190-4e95eb51e779", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0807", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "modification of crontab or local.sh entries", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execution of scheduled job", "name": "esxi:cron", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "spawned shell or execution environment activity", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Admins may customize paths in hardened deployments.", "field": "CrontabFileMonitored"}, {"description": "Flag shell-based persistence indicators in local.sh or cron payloads.", "field": "ShellCommandPayload"}, {"description": "Time interval of task repetition for outlier identification.", "field": "JobInterval"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2671', 0, 125, '09-mitre-attack', 'retrieved', '766B1E8BB03BEA3DDFC42EB350D562B8A6EFCE8EE10E3AECACE03C4D751C6315', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
