VALUES ('doc-09-mitre-attack-p0-2672', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects CLI tools (e.g., mosquitto_pub, nc, python scripts) interacting with pub/sub brokers using unusual topic names, high-frequency publication rates, or obfuscated payloads to non-standard hosts.", "external_references": [{"external_id": "AN0003", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0002#AN0003"}], "id": "x-mitre-analytic--3ecc4ba2-bf4f-481c-b813-69c169c28c83", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0003", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "mqtt.log or AMQP custom log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known-good brokers used by approved apps and daemons", "field": "BrokerAllowList"}, {"description": "Payload length, entropy, or topic name patterns", "field": "TopicAnomalyScore"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2672', 0, 101, '09-mitre-attack', 'retrieved', '836FF0D60EE60DF3B08F087339E50A654CE376A13AFFD206567D22E0C63220AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
