VALUES ('doc-09-mitre-attack-p0-2674', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of XProtect or AV quarantining a known tool, followed by modification (file size, hash, string) and subsequent re-execution by the same or related user.", "external_references": [{"external_id": "AN0542", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0189#AN0542"}], "id": "x-mitre-analytic--3ef92295-ecbf-417a-b72a-f6cd189ca3a1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0542", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "quarantine or AV-related subsystem", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "File hash delta or binary string diff score to tolerate renamed/mutated variants.", "field": "BinaryChangeThreshold"}, {"description": "User or group expected to use dev tools; reduce false positives from legitimate repacking.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2674', 0, 111, '09-mitre-attack', 'retrieved', 'E4AB814EB0FFA6C02664F2C52C5BCBB3D0FD1AAEF0C9C8406354E19608CBDEA2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
