INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2675', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects JavaScript execution through WSH (wscript.exe, cscript.exe) or HTA (mshta.exe), particularly when spawned from Office macros, web browsers, or abnormal user paths. Correlates script execution with outbound network activity or system modification.", "external_references": [{"external_id": "AN0733", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0264#AN0733"}], "id": "x-mitre-analytic--3f257014-01d4-487d-980c-77d4d2130315", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0733", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ScriptBlockLogging + AMSI", "name": "m365:defender", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Execution of wscript.exe, cscript.exe, or mshta.exe from suspicious parent like Excel or Outlook.", "field": "ParentProcess"}, {"description": "Script loaded from %TEMP%, user download folder, or via UNC/web path.", "field": "ScriptPath"}, {"description": "Execution of JavaScript during non-business or patch windows.", "field": "TimeWindow"}, {"description": "Execution by accounts not typically authorized for scripting (e.g., non-admin users).", "field": "UserContext"}, {"description": "Obfuscated JS with high entropy detected by AMSI or ScriptBlock logging.", "field": "EntropyScore"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2675', 0, 160, '09-mitre-attack', 'retrieved', '8A0F7DA2D91BDF13E505B6A893B9DA45AB99F402C17F2E44212ED131E68E8251', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
