VALUES ('doc-09-mitre-attack-p0-2676', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modification of shared network folders via .app bundles or scripting files with hidden extensions (e.g., double extensions like docx.app).", "external_references": [{"external_id": "AN1300", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0471#AN1300"}], "id": "x-mitre-analytic--3f36a861-3be2-4f6d-bfad-f044cdc01b15", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1300", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Directory events (kFSEventStreamEventFlagItemCreated)", "name": "fs:fsevents", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "file writes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitors use of hidden extensions or double extensions.", "field": "FileExtensionDeception"}, {"description": "Defines sensitive shared folders (e.g., /Users/Shared/HR).", "field": "TargetSharedFolder"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2676', 0, 94, '09-mitre-attack', 'retrieved', 'E8DCB42FD6A3B9D78940CA994BCB93083B4BDAB20CEF1AE98FBEF00FB642FDFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
