VALUES ('doc-09-mitre-attack-p0-2677', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation of authentication daemons or PAM modules. Defender perspective includes failed or anomalous PAM authentications, abnormal segfaults in authentication services, and exploitation attempts followed by successful unauthorized logins. Correlation identifies memory corruption, replay attempts, and privilege escalation tied to credential services.", "external_references": [{"external_id": "AN0494", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0174#AN0494"}], "id": "x-mitre-analytic--3f3ae0da-3005-42d7-afa3-8eaa8da3f700", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0494", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Suspicious binaries or scripts interacting with authentication binaries (sshd, gdm, login)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Repeated failed authentication attempts or replay patterns", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of monitored authentication services (e.g., sshd, gdm, PAM modules).", "field": "AuthServiceList"}, {"description": "Number of failed authentications within a window before escalating to replay suspicion.", "field": "FailureThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2677', 0, 138, '09-mitre-attack', 'retrieved', '302C21E2B9038BDDFFD4C80258042B8F2AD9090760AFFFD8146B9FD46AA4BA6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
