INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2678', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous use of Mach ports, Apple Events, or XPC services for inter-process execution or code injection. Focuses on unexpected processes attempting to send privileged Apple Events (e.g., automation scripts injecting into security-sensitive apps).", "external_references": [{"external_id": "AN1359", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0493#AN1359"}], "id": "x-mitre-analytic--3f42390d-2a44-4094-9cea-429f1286f8aa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1359", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unusual Mach port registration or access attempts between unrelated processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "exec: Unexpected execution of osascript or AppleScript targeting sensitive apps", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelisted app-to-app Apple Event communications (e.g., Finder automation).", "field": "AllowedAppleEventTargets"}, {"description": "Baseline of Mach ports and XPC services normally used in the environment.", "field": "MachPortBaseline"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2678', 0, 129, '09-mitre-attack', 'retrieved', '5015A34B93E19CEC7F88FB4DD795E6CAD1C541D10A4A2169EA7D4A79CE7E5D5E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
