VALUES ('doc-09-mitre-attack-p0-2680', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects manual or scripted removal of logs, artifacts, or malware droppings via `rm` or PowerCLI in ESXi shell. Focus on deletions from /tmp/, /var/core/, or /scratch.", "external_references": [{"external_id": "AN0395", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0140#AN0395"}], "id": "x-mitre-analytic--3f53ca22-5efe-43b3-8225-5fdd4b8a8194", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0395", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/shell.log", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match deletion actions in system-critical locations or malware drop zones.", "field": "LogFilePath"}, {"description": "Typically follows suspicious admin login or unexpected shell session.", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2680', 0, 96, '09-mitre-attack', 'retrieved', '2C5ECF996EDDC2D3A734914B11B83DA15D58A069BAE24030CEF7682C12942741', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
