VALUES ('doc-09-mitre-attack-p0-2681', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) Safari/Chrome/Firefox/Office handles a URL; unified logs show open/click or LSQuarantine assignment, (2) outbound connection to untrusted domain, (3) a new file appears in ~/Downloads or /private/var/folders/* with quarantine flag.", "external_references": [{"external_id": "AN0180", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0066#AN0180"}], "id": "x-mitre-analytic--3f615721-c62f-4229-9c6e-cb873b2591e5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0180", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open URL|clicked link|LSQuarantineAttach", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "New outbound connection from Safari/Chrome/Firefox/Word", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Create in /Users/*/Downloads or /private/var/folders/* with quarantine attribute", "name": "fs:fsevents", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "10–30m correlation.", "field": "TimeWindow"}, {"description": "Alert when com.apple.quarantine missing on newly downloaded executables.", "field": "QuarantinePolicy"}, {"description": "Org-specific risky domains/TLDs.", "field": "SuspiciousTLDs"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2681', 0, 124, '09-mitre-attack', 'retrieved', '0F127B4793DE0BA3768B2011D4D3556E1257C784B70F3A0A27CDAD9A86325E6F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
