VALUES ('doc-09-mitre-attack-p0-2682', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Inspect network telemetry for adversary attempts to blend malicious traffic with legitimate flows using VPNs, proxies, or geolocation spoofing. Defensive teams may observe anomalous tunnels, encrypted sessions to suspicious domains, or geo-mismatched IP activity.", "external_references": [{"external_id": "AN1151", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0411#AN1151"}], "id": "x-mitre-analytic--3f74d068-0a8b-4312-91f3-34da6c630c4a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1151", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Encrypted tunnels or proxy traffic to non-standard destinations", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regions to monitor for unexpected or mismatched geolocation activity.", "field": "GeoIPRanges"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2682', 0, 99, '09-mitre-attack', 'retrieved', 'BD55415FF66F2455600D3104B62E355B99B559E4BE785157781E9A5068906BB1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
