VALUES ('doc-09-mitre-attack-p0-2683', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized access to browser cookie paths (e.g., `~/Library/Application Support/Google/Chrome/Default/Cookies`) or `task_for_pid`/`vm_read` calls to Safari/Chrome memory space.", "external_references": [{"external_id": "AN1404", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0509#AN1404"}], "id": "x-mitre-analytic--3fdd7ef4-b382-4880-9f72-bf0ad696af85", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1404", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "vm_read, task_for_pid, or file open to cookie databases", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "file open for known browser cookie paths", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of processes considered web browsers on macOS", "field": "TargetBrowserList"}, {"description": "Cookie database paths specific to each browser", "field": "BrowserCookiePathList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2683', 0, 102, '09-mitre-attack', 'retrieved', '237AF96C96C88A0581248C0E9287A96A5ADB66642A7541B86909658221269053', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
