VALUES ('doc-09-mitre-attack-p0-2684', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of `show version`, `show hardware`, or `show system` commands through CLI via SSH or console.", "external_references": [{"external_id": "AN1457", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0525#AN1457"}], "id": "x-mitre-analytic--3ff23082-b5c6-47c0-8d76-a2d6fa88e622", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1457", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Privilege-level command execution", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Highlight unexpected users issuing diagnostic commands.", "field": "Username"}, {"description": "Tailor to vendor-specific command syntax.", "field": "CommandList"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2684', 0, 81, '09-mitre-attack', 'retrieved', '9E30C868BA976FFED50890522DE6A7B26C27EBD202327867DD87307B72D5E9B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
