VALUES ('doc-09-mitre-attack-p0-2687', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "VM or cloud instance generating anomalously high network egress targeting same destination IP or service, especially using stateless protocols.", "external_references": [{"external_id": "AN0972", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0343#AN0972"}], "id": "x-mitre-analytic--408b2724-079c-4636-9764-52f435726de7", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0972", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "source instance sends large volume of traffic in short window", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "NetworkOut spike beyond baseline", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alert when egress exceeds normal usage by X%.", "field": "InstanceTrafficThreshold"}, {"description": "Prioritize alerts on stateless protocols such as UDP and ICMP.", "field": "ProtocolType"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2687', 0, 106, '09-mitre-attack', 'retrieved', '80B0C595672A6378B2E78857805FFC6FC6488EA9DAD5D8E315C517A71F264436', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
