VALUES ('doc-09-mitre-attack-p0-2689', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Installation of malicious .mobileconfig profiles or browser extension plist entries followed by abnormal browser child process activity.", "external_references": [{"external_id": "AN0124", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0044#AN0124"}], "id": "x-mitre-analytic--41153f33-d415-4e1d-b3c8-7333b2f1915e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0124", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "profiles install -type=configuration", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Creation or modification of browser extension .plist files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Unexpected child process of Safari or Chrome", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Different versions may store extensions in variant preference folders", "field": "PlistPath"}, {"description": "May vary with OS version; some install flags deprecated in macOS 11+", "field": "CommandLineFlags"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2689', 0, 116, '09-mitre-attack', 'retrieved', '75F3145A13CD8B5645CD8C228D0E86A3C13F901B60E1370296224FB3B7938C