VALUES ('doc-09-mitre-attack-p0-2690', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of commands to enumerate virtualization-related files or processes (e.g., ''/sys/class/dmi/id/product_name'', dmesg, lscpu, lspci), or querying hypervisor interfaces prior to malware execution.", "external_references": [{"external_id": "AN0128", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0046#AN0128"}], "id": "x-mitre-analytic--412b76ec-d44e-4064-9dc1-32cf793f0176", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0128", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve or syscall invoking vm artifact check commands (e.g., dmidecode, lspci, dmesg)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "sleep function usage or loops (nanosleep, usleep) in scripts", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Duration between VM discovery commands and payload execution", "field": "TimeWindow"}, {"description": "Command-line regex patterns indicative of sandbox evasion (e.g., grep QEMU, strings vmware)", "field": "CommandArtifactMatchList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2690', 0, 118, '09-mitre-attack', 'retrieved', '14647116D4866D6D4633878818C9A93FAEE734DB6F35FA31D6485DF7408C4A6C', 'v1', '{"source_id": "09-mitre-attack", "