VALUES ('doc-09-mitre-attack-p0-2691', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of changes to device startup-config files that include boot scripts or scheduled execution routines.", "external_references": [{"external_id": "AN0315", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0112#AN0315"}], "id": "x-mitre-analytic--416b5616-a16d-4ccc-b214-5873f96e5b1f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0315", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "config", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Affected interface or subsystem; varies per device.", "field": "Interface"}, {"description": "Patterns of authorized config changes differ by vendor or policy.", "field": "CommandPattern"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2691', 0, 84, '09-mitre-attack', 'retrieved', '4EF37697A52403341371B50E9BDB80CCDFB878AC6435A88708EDFC527C0CA8F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
