VALUES ('doc-09-mitre-attack-p0-2692', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Traffic originating from ESXi hosts or management interfaces displays SNI-to-Host mismatch behavior, particularly anomalous given typical infrastructure communication patterns.", "external_references": [{"external_id": "AN0567", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0196#AN0567"}], "id": "x-mitre-analytic--4192b311-da7a-4ef1-b09a-a03a8c2a1670", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0567", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TLS/HTTP inspection", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "/var/log/vmkernel.log, /var/log/vmkwarning.log", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "ESXi hosts should rarely initiate external HTTPS—threshold to alert.", "field": "AdminPortAccess"}, {"description": "Define entropy or timing anomalies for TLS handshake.", "field": "TLSHandshakeOutliers"}, {"description": "SNI/Host mismatch occurrence tolerance.", "field": "DomainMismatchThreshold"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2692', 0, 102, '09-mitre-attack', 'retrieved', '859AFF20D19AE9952CE80BB17F436A1433426A50D95E87FC9244587BC0D5B7FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", 