VALUES ('doc-09-mitre-attack-p0-2694', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect suspicious file creation, modification, or deletion in stored data directories (e.g., `/var/lib/mysql/`, `/var/log/`, mail spools). Identify shell commands interacting directly with structured data files instead of legitimate database utilities.", "external_references": [{"external_id": "AN0556", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0193#AN0556"}], "id": "x-mitre-analytic--425a3e89-ac22-4ff3-bc1e-ca1672113075", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0556", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, unlink, rename: File creation or deletion involving critical stored data", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "write: Modification of structured stored data by suspicious processes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment-specific paths where business-critical stored data resides.", "field": "WatchedPaths"}, {"description": "Legitimate scripts/utilities excluded to minimize false positives.", "field": "CommandExclusions"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2694', 0, 119, '09-mitre-attack', 'retrieved', '695ED3FDA480F18B877DCBC48CE8605F5962253B7F42A350867919867C5DBF86', 'v1', '{"