VALUES ('doc-09-mitre-attack-p0-2695', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries use cloud API, CLI, or console to create IAM users or roles. Initial CreateUser is followed by policy/role attachment. Detection monitors temporal chains involving IAM:CreateUser, AttachUserPolicy, and credential generation, especially from automation or foreign IP ranges.", "external_references": [{"external_id": "AN0900", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0319#AN0900"}], "id": "x-mitre-analytic--4264c6fb-20b2-4792-8939-c7d8f204338a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0900", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateUser", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "AttachUserPolicy", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alert when creation happens in unexpected regions", "field": "Region"}, {"description": "Chain CreateUser → AttachPolicy → AccessKey within short timeframe", "field": "TimeWindow"}, {"description": "Monitor API calls from non-console or automation tools", "field": "UserAgent"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2695', 0, 121, '09-mitre-attack', 'retrieved', '9B03E48E743DEF0D65B99817B8AC6FE5517C6954C490DB762640D51E59D3473F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
