VALUES ('doc-09-mitre-attack-p0-2696', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of file or directory discovery commands (e.g., ''ls'', ''find'') from terminal or script-based tooling, especially outside normal user workflows.", "external_references": [{"external_id": "AN1042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0370#AN1042"}], "id": "x-mitre-analytic--42683860-d6df-4585-af65-31f783269f8f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1042", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log collect --predicate", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Filesystem Call Monitoring", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust macOS unified log filter to include/exclude system paths", "field": "PredicateScope"}, {"description": "Tune based on burst access patterns", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2696', 0, 96, '09-mitre-attack', 'retrieved', '178D9C17A214DBC8C63468BD3D2B36A2016BF78BE161F1FD8D9C577615BC511C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
