VALUES ('doc-09-mitre-attack-p0-2697', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects scripting environments (AppleScript, osascript, curl) or non-native tools performing DNS queries with encoded subdomains, often used for data exfiltration or beaconing.", "external_references": [{"external_id": "AN1123", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0400#AN1123"}], "id": "x-mitre-analytic--42a8c7a7-2773-4892-b647-40d3542ae4d2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1123", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream ''eventMessage contains \"dns_request\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable threshold for randomness in subdomain labels", "field": "EntropyThreshold"}, {"description": "Filters on user-launched or cron-based queries", "field": "UncommonProcessContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2697', 0, 90, '09-mitre-attack', 'retrieved', '6EDA4EFEC02101B22ACE817DF58FB9A61B867EB8E27E6B384B3D81C4603F11A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
