VALUES ('doc-09-mitre-attack-p0-2698', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configuration of internal NAT or proxy rules that redirect traffic between client segments internally (e.g., site-to-site port forwarding). Often used to relay internal beaconing or move traffic laterally through trust zones.", "external_references": [{"external_id": "AN0208", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0075#AN0208"}], "id": "x-mitre-analytic--42ba4dcf-0354-4d70-8c29-d0c3a8c90c23", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0208", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Config Change", "name": "Firewall Audit Logs", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"channel": "Inter-segment traffic", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Policy Update", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Internal subnets or endpoint roles allowed for port forwarding.", "field": "ProxyTarget"}, {"description": "Detect changes made outside scheduled or authorized windows.", "field": "ConfigChangeUser"}, {"description": "Volume of data relayed through proxy exceeds historical norms.", "field": "FlowThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2698', 0, 129, '09-mitre-attack', 'retrieved', '97068C1C463C0905284FF4F284C6AD308D68E596DBE82FB1EB0B5D90CB7474B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
