VALUES ('doc-09-mitre-attack-p0-2699', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for cloud API calls that export or collect guest or system logs. Abnormal use of Azure VM Agent’s CollectGuestLogs.exe or AWS CloudWatch GetLogEvents across multiple instances should be correlated with lateral movement or data staging.", "external_references": [{"external_id": "AN0708", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0255#AN0708"}], "id": "x-mitre-analytic--42bae633-1033-40da-bf3a-87bcd1b0297f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0708", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetLogEvents: High frequency log exports from CloudWatch or equivalent services", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "CollectGuestLogs: Unexpected collection of guest logs by Azure VM Agent outside normal maintenance windows", "name": "azure:activity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define thresholds for volume/frequency of log export requests considered suspicious.", "field": "LogExportThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2699', 0, 122, '09-mitre-attack', 'retrieved', 'A4EA89C58B6EE72DD03EEF4E3460C2F535A6111373935F8E2E245E00184A82E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
