VALUES ('doc-09-mitre-attack-p0-2700', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of PowerShell commands that modify mailbox permissions using Exchange cmdlets (e.g., Add-MailboxPermission), often tied to BEC or post-compromise persistence.", "external_references": [{"external_id": "AN1052", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0373#AN1052"}], "id": "x-mitre-analytic--42d5a9d5-f897-4c45-b577-9b2c776c6c0d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1052", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "PowerShell: Add-MailboxPermission", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exchange cmdlets to include or exclude based on scope (e.g., Add-MailboxPermission, Set-MailboxFolderPermission).", "field": "PowerShellCmdletFilter"}, {"description": "Flag suspicious script or interactive shell launch by non-admins.", "field": "ExecutionParent"}, {"description": "Window in which Add-MailboxPermission is followed by anomalous usage (e.g., SendAs events).", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2700', 0, 114, '09-mitre-attack', 'retrieved', '845131D94C00C4C61A4204556B903F4AAEB2EB7C078FD23508445B1C2A6DF8BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
