VALUES ('doc-09-mitre-attack-p0-2701', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects email-sending behavior via Terminal, AppleScript, or Automator that interfaces with SMTP or IMAP, typically using curl or mail-related APIs in unsanctioned contexts.", "external_references": [{"external_id": "AN0381", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0135#AN0381"}], "id": "x-mitre-analytic--43347e24-50d6-446e-923d-a6fd69805a22", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0381", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate ''processImagePath CONTAINS \"curl\" OR \"osascript\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor non-mail client users initiating SMTP/IMAP", "field": "UserContext"}, {"description": "Look for execution of mail commands during off-hours", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2701', 0, 101, '09-mitre-attack', 'retrieved', '94FB88ADBDD04708D7E79F6E3283D663730F288E44236B7B33DB4B66DC3118ED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
