VALUES ('doc-09-mitre-attack-p0-2704', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary mounts a USB device and begins enumerating, copying, or compressing files using scripting engines, cmd, or remote access tools.", "external_references": [{"external_id": "AN1410", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0511#AN1410"}], "id": "x-mitre-analytic--4385bff9-e730-48cd-bdfc-43de56c302aa", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1410", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=2003", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can tune based on known removable device labels or whitelist", "field": "VolumeLabel"}, {"description": "Controls timing between device mount and sensitive file access", "field": "TimeWindow"}, {"description": "Tune for sensitive file extensions (e.g., .docx, .pdf, .csv)", "field": "TargetFileType"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2704', 0, 116, '09-mitre-attack', 'retrieved', 'A7A9487714A99A00A38F436A7AC86DCEA0A2386747AF88FEE