VALUES ('doc-09-mitre-attack-p0-2705', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of AWS STS or GCP IAM APIs to request temporary tokens or federation sessions inconsistent with normal account activity, including from unexpected principals or regions.", "external_references": [{"external_id": "AN0526", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0185#AN0526"}], "id": "x-mitre-analytic--43ccb88d-8d8a-4ddb-9ffd-3d897fba76a3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0526", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AssumeRole, GetFederationToken, GetSessionToken", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "sts:GetFederationToken", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Distance between token creation and resource use locations", "field": "GeoIPDistanceThreshold"}, {"description": "Limit scope of acceptable role assumptions by account type", "field": "RoleScope"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2705', 0, 102, '09-mitre-attack', 'retrieved', '85EC05ECAF679F9FF7865F089C27416E8858B72E1E4726EAAD874A0740519D3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
