INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2706', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized modification of service-related registry keys such as ImagePath, FailureCommand, ServiceDll, or Performance/Parameters keys. Defender correlates registry modifications, anomalous service metadata changes, and subsequent service process executions that deviate from baseline configurations.", "external_references": [{"external_id": "AN1195", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0427#AN1195"}], "id": "x-mitre-analytic--43f5598c-5c63-40f4-b936-2978bd0f3aa0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1195", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=7040", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Registry subkeys for critical services (ImagePath, ServiceDll, FailureCommand, Parameters).", "field": "MonitoredServiceKeys"}, {"description": "Known good service registry configurations and paths for comparison.", "field": "BaselineServiceConfig"}, {"description": "Correlation interval between registry/service modifications and service execution.", "field": "TimeWindow"}, {"description": "Accounts permitted to modify service configurations.", "field": "PrivilegedAccounts"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2706', 0, 133, '09-mitre-attack', 'retrieved', '2136E289366FE78BCC79BE4BEBC8CED6F2E9A5D8992778A8C0A7FC39EF92D93A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
