INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2709', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous use of ICMP or UDP by non-network service processes for data exfiltration or remote control, especially if traffic bypasses proxy infrastructure or shows unusual flow patterns.", "external_references": [{"external_id": "AN1254", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0457#AN1254"}], "id": "x-mitre-analytic--4412fb07-9a44-49de-80af-8746b0be3865", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1254", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "ICMP/UDP traffic (Wireshark, Suricata, Zeek)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Processes normally allowed to use ICMP/UDP (e.g., ping.exe, DNS resolver).", "field": "ProcessContextAllowList"}, {"description": "Suspicion if client sends much more data than it receives (e.g., >90%).", "field": "ByteTransferAnomalyThreshold"}, {"description": "Baseline which protocols are normal per host or segment (ICMP, UDP, etc.).", "field": "ProtocolUsageBaseline"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2709', 0, 126, '09-mitre-attack', 'retrieved', '1AB32681160DBB9B9E21DF19DC01568691A89E1B6E47FC94CB7CFE4D6271B87A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
