INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2711', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of user-level Launch Agents in monitored directories using `.plist` files with suspicious `ProgramArguments` or `RunAtLoad` keys. Correlates file write activity with execution of `launchctl` or unsigned binaries invoked at login.", "external_references": [{"external_id": "AN1208", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0434#AN1208"}], "id": "x-mitre-analytic--441bfb28-3fe5-410b-93a5-2280a7f19dad", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1208", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchctl load or boot-time plist registration", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "write or chmod to ~/Library/LaunchAgents/*.plist", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "modification of existing LaunchAgents plist", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "detection of new launch agents with suspicious paths or unsigned binaries", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored directories (e.g., `/Library/LaunchAgents`, `~/Library/LaunchAgents`) for plist drops", "field": "PlistDirectoryList"}, {"description": "Monitored keys such as `RunAtLoad`, `KeepAlive`, or `ProgramArguments` for policy alignment", "field": "PlistKeyMonitor"}, {"description": "Patterns used to detect execution from non-standard or suspicious locations like `/tmp`, `/var`, or `/Users/Shared`", "field": "ExecutablePathPattern"}, {"description": "Raise alerts if the binary referenced in the Launch Agent is unsigned or unverified", "field": "UnsignedBinaryAlert"}, {"description": "List of users whose LaunchAgents are considered high-sensitivity (e.g., admins)", "field": "UserContextScope"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2711', 0, 193, '09-mitre-attack', 'retrieved', 'E3D77FFF2A1FF44D5B06F76E5EFBEA37665DADE135FEBD8899D449D5892FAA57', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
