VALUES ('doc-09-mitre-attack-p0-2714', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for execution of hypervisor management commands such as `esxcli vm process list` or `vim-cmd vmsvc/getallvms` that enumerate virtual machines. Defenders observe unexpected users issuing VM listing commands outside normal administrative workflows.", "external_references": [{"external_id": "AN0572", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0199#AN0572"}], "id": "x-mitre-analytic--44bb0cf8-12ee-4a8f-8701-6c787a008bd8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0572", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command IN (\"esxcli vm process list\", \"vim-cmd vmsvc/getallvms\")", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of known administrators authorized to run ESXi enumeration commands.", "field": "ExpectedAdminUsers"}, {"description": "Defines restricted paths or contexts where VM enumeration should not occur.", "field": "UnexpectedCommandPaths"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2714', 0, 111, '09-mitre-attack', 'retrieved', '945C6055A59EEFED89D0C51ECFF4565758E2C5E34E0C557E9F9E9DD73BFCF50C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
