VALUES ('doc-09-mitre-attack-p0-2715', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Command-line initiated UDP traffic bursts to external reflection amplification ports using built-in scripting or binaries with network anomalies", "external_references": [{"external_id": "AN1142", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0408#AN1142"}], "id": "x-mitre-analytic--44c2e32e-bd34-4ba9-8105-28c14309207c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1142", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of ping, nping, or crafted network packets via bash or python to reflection services", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound UDP spikes to external reflector IPs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Ports known for reflection abuse — DNS, NTP, SSDP, Memcached", "field": "ReflectionPorts"}, {"description": "How much deviation in outbound traffic constitutes a suspicious spike", "field": "TrafficSpikeThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2715', 0, 115, '09-mitre-attack', 'retrieved', '1B521D1A7C28BCF0F26524E406E9536A8730E0BAA453E65214115C8F3DF66A99', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
