VALUES ('doc-09-mitre-attack-p0-2716', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation of IaaS cloud security boundaries to evade defense controls. Defender perspective includes anomalous API calls that bypass audit logging, disable monitoring, or manipulate guardrails (e.g., CloudTrail tampering). Correlation highlights when exploitation attempts precede sudden absence of expected telemetry.", "external_references": [{"external_id": "AN1636", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0595#AN1636"}], "id": "x-mitre-analytic--458038e6-60a2-47d2-bd55-675e77f0e279", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1636", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "StopLogging, DeleteTrail, UpdateTrail: API calls that disable or modify logging services", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of sensitive cloud API operations that should be rare and tightly monitored.", "field": "CriticalAPIs"}, {"description": "Duration for correlation of API exploitation with sudden logging gaps.", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2716', 0, 124, '09-mitre-attack', 'retrieved', '3043860D7F6C4004465F2E8F183672F4FC36585045E80B574137B7E0F125C003', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
