VALUES ('doc-09-mitre-attack-p0-2717', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual long-running processes consuming high CPU cycles (e.g., via ''top'' or ''ps'') initiated via cron, shell scripts, or Docker. Connections to known mining pools or DNS over HTTPS usage as evasion.", "external_references": [{"external_id": "AN1490", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0540#AN1490"}], "id": "x-mitre-analytic--45a34d76-16aa-45ac-9419-ffbc5d2e090d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1490", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound connection to mining pool port (3333, 4444, 5555)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Scheduled execution of unknown or unusual script/binary", "name": "linux:cron", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "The miner''s execution path and options may vary by campaign.", "field": "CommandLine"}, {"description": "Environment-specific definition of anomalous CPU usage.", "field": "CPUThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2717', 0, 124, '09-mitre-attack', 'retrieved', '0F233782FF69D914718D4FD4AC1262FB74815301DF360513617B318EA003DAEB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
