VALUES ('doc-09-mitre-attack-p0-2718', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account creation using ''dscl -create'' or via GUI tools. Detection involves command execution and file changes to the local directory services database.", "external_references": [{"external_id": "AN1237", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0447#AN1237"}], "id": "x-mitre-analytic--45e8fdaf-60cc-46db-a9fd-5dc18c8db6bb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1237", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dscl -create", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "modification to /var/db/dslocal/nodes/Default/users/", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Accounts like ''svc*'', ''backup*'' may blend into legit naming patterns", "field": "UsernamePattern"}, {"description": "Identify if dscl was run locally, via ARD, or Terminal.app", "field": "SessionOrigin"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2718', 0, 102, '09-mitre-attack', 'retrieved', '0F7F231E1CE69AF7AABA502BF3B45D9B539ADCFC53415BD56191F67D7E7D1F70', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
