VALUES ('doc-09-mitre-attack-p0-2721', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects binaries or launch daemons in /System/Library or /Applications with mismatched bundle names, unexpected metadata, or improper installation origin.", "external_references": [{"external_id": "AN0985", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0347#AN0985"}], "id": "x-mitre-analytic--466a2102-fcb3-4372-9a8d-ad8fe34e94ec", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0985", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log collect from launchd and process start", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "filesystem monitoring of exec/open", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of known application names and paths to validate against", "field": "expected_bundle_names"}, {"description": "Toggle to enforce checks for Apple-signed binaries in trusted directories", "field": "signed_by_apple_check"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2721', 0, 105, '09-mitre-attack', 'retrieved', '2EDA393574C14143A0CA098A6EED6FA116FC9D9A8E40DDB5E74032F812F43BC4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
