VALUES ('doc-09-mitre-attack-p0-2722', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Phishing via Office documents containing embedded macros or links that spawn processes. Detection relies on correlating Office application logs with suspicious child process execution and outbound network connections.", "external_references": [{"external_id": "AN0191", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0070#AN0191"}], "id": "x-mitre-analytic--46ecb875-0842-4171-bb36-9b361453a89f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0191", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FileAccessed: Access of email attachments by Office applications", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Parent processes expected to execute child processes (e.g., Office apps).", "field": "ParentProcessList"}, {"description": "Threshold for number of macros executed before raising alerts.", "field": "MacroExecutionThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2722', 0, 112, '09-mitre-attack', 'retrieved', 'ADA799D638587AB70126B12FDB04554F483CADB4D93E6F0FD2340E2C46867450', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
