VALUES ('doc-09-mitre-attack-p0-2723', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Instance enters degraded/unhealthy state due to abnormal process load or memory exhaustion, often caused by automation or script-based attacks.", "external_references": [{"external_id": "AN0587", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0208#AN0587"}], "id": "x-mitre-analytic--472f81b1-99ba-406a-b2ef-d70b2af5b527", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0587", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "StatusCheckFailed or StatusCheckFailed_System for burstable instances (t2/t3)", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "StartInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "High volume internal traffic with low entropy indicating looped or malicious DoS script", "name": "VPCFlowLogs:All", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Burstable vs compute-optimized instances impact DoS effect", "field": "InstanceType"}, {"description": "How many consecutive StatusCheckFailed events to consider critical", "field": "FailureThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2723', 0, 115, '09-mitre-attack', 'retrieved', '2AB1EDCBEA48FE2E6C30AA53FD4E83F