VALUES ('doc-09-mitre-attack-p0-2724', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unsigned binaries or interpreted scripts initiating non-standard protocols (ICMP, UDP, SOCKS) outside of baseline network behavior.", "external_references": [{"external_id": "AN1256", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0457#AN1256"}], "id": "x-mitre-analytic--4742e058-a301-47e1-b594-8daa8eabfc79", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1256", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.network", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "ICMP/UDP monitoring (tcpdump, Wireshark, Zeek)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection threshold for unsigned or transient binaries making ICMP/UDP calls.", "field": "UnsignedBinaryNetworkUsage"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2724', 0, 84, '09-mitre-attack', 'retrieved', '61EB9B44F9570CA36286F08245CA619304648674A9E1686A8736B9BA0B9A9DA3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
