VALUES ('doc-09-mitre-attack-p0-2725', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of services via native CLI tools (e.g., `sc query`, `tasklist /svc`, `net start`) or API calls via PowerShell and WMI.", "external_references": [{"external_id": "AN1325", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0483#AN1325"}], "id": "x-mitre-analytic--475313b7-c26f-44f6-a8f3-09b57f03fcd8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1325", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be tuned to specific binaries used for service enumeration (e.g., `sc.exe`, `tasklist.exe`).", "field": "ProcessName"}, {"description": "Filters for variations like `sc query`, `net start`, `Get-Service`.", "field": "CommandLineMatch"}, {"description": "Used to suppress known admin scripts or automation jobs.", "field": "ParentProcess"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2725', 0, 115, '09-mitre-attack', 'retrieved', '6DFD533A5A7F97CF0202DA56730C4F473A3B7EB06B5C44EE6737E2C1D07CE22B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "