VALUES ('doc-09-mitre-attack-p0-2726', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects attempts to modify file timestamps via API usage (e.g., `SetFileTime`), CLI tools (e.g., `w32tm`, PowerShell), or double-timestomp behavior where $SI and $FN timestamps are mismatched or reverted.", "external_references": [{"external_id": "AN1626", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0591#AN1626"}], "id": "x-mitre-analytic--475a8817-1ace-4bef-baaa-0f56979eb85a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1626", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "SetFileTime", "name": "EDR:file", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate timestamp change with preceding file creation or suspicious access", "field": "TimeWindow"}, {"description": "Include SetFileTime, NtSetInformationFile, or other timestamp APIs", "field": "APINamePattern"}, {"description": "Trigger on excessive backdating (e.g., >90 days)", "field": "TimestampDeltaThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2726', 0, 120, '09-mitre-attack', 'retrieved', '0FA00C9F1A78492EBBCE505EFD25087BFD897D94CF9066EE15F17B4441B9CD2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
