VALUES ('doc-09-mitre-attack-p0-2727', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain: (1) third-party app or admin connects via OAuth/marketplace install; (2) high-privilege scopes granted; (3) anomalous actions (mass read/exports, admin changes).", "external_references": [{"external_id": "AN1349", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0488#AN1349"}], "id": "x-mitre-analytic--4766bdc0-047a-4250-93c1-6d907178620e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1349", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "OAuth2 authorization grants / Admin role assignments", "name": "saas:googleworkspace", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "ConnectedApp OAuth policy change / Login as user", "name": "saas:salesforce", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Catalog of sanctioned third-party apps and scopes.", "field": "ApprovedApps"}, {"description": "Data export size/rate baselines to detect abnormal partner activity.", "field": "ExportVolumeThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2727', 0, 108, '09-mitre-attack', 'retrieved', '2378A17B67AE1FCB8F132E3EDCFD18295890DB2D6EAB8EC8C188D5B3ACF5BE28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
