VALUES ('doc-09-mitre-attack-p0-2728', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of malicious certificate installation via monitoring execution of the `security add-trusted-cert` command and modifications to system keychains.", "external_references": [{"external_id": "AN0155", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0056#AN0155"}], "id": "x-mitre-analytic--477fb167-a388-4e85-856b-bdcb36e7fd95", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0155", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of /usr/bin/security add-trusted-cert or keychain modifications to System.keychain", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "query: Enumeration of root certificates showing unexpected additions", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Commands related to certificate management (e.g., security, profiles) that can be tuned per environment.", "field": "MonitoredCommands"}, {"description": "Baseline of expected certificates in System.keychain to reduce false positives from legitimate enterprise certificates.", "field": "KeychainBaseline"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2728', 0, 118, '09-mitre-attack', 'retrieved', 'D27587EDB045050A59749E128697629E94A3D7055FA0E24B9476C5EF29884096', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
