VALUES ('doc-09-mitre-attack-p0-2729', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of `esxcli storage` or `vim-cmd vmsvc/getallvms` by unusual sessions or through interactive shells unrelated to administrative maintenance tasks.", "external_references": [{"external_id": "AN0539", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0188#AN0539"}], "id": "x-mitre-analytic--478e6298-d012-4337-b2ed-0f8d4909ee05", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0539", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of esxcli with args matching ''storage'', ''filesystem'', ''core device list''", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "interactive shell or SSH access preceding storage enumeration", "name": "esxi:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict alerts to unexpected remote sessions accessing host storage commands", "field": "ssh_source_ip"}, {"description": "Tailor detection based on subcommands more likely to be abused", "field": "esxcli_command_scope"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2729', 0, 113, '09-mitre-attack', 'retrieved', '1FF6B67684069F7452FD8DCD9600174C665F2478CE72C5E706DCB224EBD46D1C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
