VALUES ('doc-09-mitre-attack-p0-2730', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of system utilities like ''system_profiler'' and ''ioreg'' to enumerate hardware components or USB devices, particularly if followed by clipboard, file, or network activity.", "external_references": [{"external_id": "AN1355", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0491#AN1355"}], "id": "x-mitre-analytic--479e5749-a746-4b17-9543-ca4b9d41576a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1355", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "usb_devices", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Commands like ''system_profiler SPUSBDataType'', ''ioreg -p IOUSB'' that may indicate enumeration", "field": "BinaryList"}, {"description": "Temporal grouping of enumeration with follow-on activity (e.g., clipboard capture, exfiltration)", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2730', 0, 104, '09-mitre-attack', 'retrieved', 'FCEB57ED586F86075596A03E736C346FF8810E42C2DCD28B90BFE3D883B96007', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
