VALUES ('doc-09-mitre-attack-p0-2732', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for unexpected modifications of plist files in persistence or configuration directories (e.g., ~/Library/LaunchAgents, ~/Library/Preferences, /Library/LaunchDaemons). Detect when modifications are followed by execution of new or unexpected binaries. Track use of utilities such as defaults, plutil, or text editors making changes to Info.plist files. Correlate file modifications with subsequent process launches or service starts that reference the altered plist.", "external_references": [{"external_id": "AN0306", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0109#AN0306"}], "id": "x-mitre-analytic--481966ed-de78-42e4-9c51-c69281a21650", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0306", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write: File modifications to *.plist within LaunchAgents, LaunchDaemons, Application Support, or Preferences directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "exec: Execution of defaults, plutil, or common editors (vim/nano) targeting plist files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "exec: Invocation of /usr/bin/defaults write or /usr/bin/plutil modifying plist keys", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set of directories where plist modifications are considered suspicious (e.g., ~/Library/LaunchAgents, /Library/LaunchDaemons)", "field": "MonitoredDirectories"}, {"description": "List of plist keys associated with evasion or persistence (e.g., LSUIElement, LSEnvironment, ProgramArguments)", "field": "SuspiciousKeys"}, {"description": "Temporal correlation window to link plist file modifications with subsequent suspicious process launches", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2732', 0, 195, '09-mitre-attack', 'retrieved', 'E6BBCBB26DA78B013DA5C075C81E0CEC7967135C5F8675286043AF68DCCFAF66', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
