VALUES ('doc-09-mitre-attack-p0-2733', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Rule manipulation through local email clients (e.g., Evolution, Thunderbird) or server-side filtering scripts (e.g., sieve) creating conditions to move or discard emails with security-related keywords.", "external_references": [{"external_id": "AN0553", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0192#AN0553"}], "id": "x-mitre-analytic--487d9ddf-a790-4adc-9be4-ec5651e790f1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0553", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve calls modifying local mail filter configuration files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Unexpected additions of sieve rules or filtering directives", "name": "ApplicationLog:MailServer", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize based on mail server software (Postfix, Dovecot, Exim).", "field": "MailServerLogs"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2733', 0, 102, '09-mitre-attack', 'retrieved', '5DB382FF7787492735C01BB0DF172050436BFA8EB9E94E03928E0E1785C51902', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
