VALUES ('doc-09-mitre-attack-p0-2735', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain involving suspicious use of GetProcAddress and LoadLibrary following memory allocation and manual mapping, often paired with low entropy strings, abnormal API use without static import tables, or delayed module load behaviors.", "external_references": [{"external_id": "AN0250", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0091#AN0250"}], "id": "x-mitre-analytic--48a818ac-077b-46ff-b615-bb2958536aef", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0250", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "API tracing / stack tracing via ETW or telemetry-based EDR", "name": "etw:Microsoft-Windows-Kernel-Process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable logic to flag suspicious modules used without static IAT entries", "field": "APILoadWithoutImport"}, {"description": "Correlates module load to suspicious memory allocation or API lookup within timeframe", "field": "TimeWindow"}, {"description": "Used to detect obfuscated strings or hashed function names", "field": "EntropyThreshold"}, {"description": "Optional filtering of known safe modules or patterns from telemetry", "field": "StackTraceFilter"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2735', 0, 153, '09-mitre-attack', 'retrieved', 'BFE085B745440A6959D933DBD0669251FE09C9F84AF82EA470160D6BD8B5CBDE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
