VALUES ('doc-09-mitre-attack-p0-2737', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remote knock sequence followed by PF/socketfilterfw rule update or a background process listening on a new port; then a successful TCP session. Also flags WoL magic packets on local segment.", "external_references": [{"external_id": "AN1450", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0524#AN1450"}], "id": "x-mitre-analytic--48d2effa-7fc0-4790-9cc9-bbe573c29301", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1450", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec: Execution of /sbin/pfctl, /usr/libexec/ApplicationFirewall/socketfilterfw, ifconfig, tcpdump, npcap/libpcap consumers", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Firewall rule enable/disable or listen socket changes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Closed-port hits followed by success from same src_ip", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Anchors or conf files monitored for change (/etc/pf.conf, /etc/pf.anchors/*).", "field": "PFAnchorPaths"}, {"description": "Reduce noise on dev endpoints compiling or testing PF rules.", "field": "DeveloperMode"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2737', 0, 133, '09-mitre-attack', 'retrieved', 'C15701F52ACAA85B571C5C4BEAF82AF722B6CF2AD97B22C648750167F5D81E5D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
