VALUES ('doc-09-mitre-attack-p0-2738', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of clipboard access via OS utilities (e.g., clip.exe, Get-Clipboard) by non-interactive or abnormal parent processes, potentially chained with staging or exfiltration commands.", "external_references": [{"external_id": "AN0965", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0341#AN0965"}], "id": "x-mitre-analytic--48e4aceb-38dd-4bf2-8074-9fee8436985b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0965", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how far back to look for parent-child relationships and follow-on network activity.", "field": "TimeWindow"}, {"description": "Filters based on service vs interactive users to reduce noise.", "field": "UserContext"}, {"description": "Tunable list of expected/benign clipboard accessors.", "field": "ParentProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2738', 0, 112, '09-mitre-attack', 'retrieved', '99288B433F9B13E5FC15660EC3581F210E78698F0F4455761C4BB9F30854710C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
