VALUES ('doc-09-mitre-attack-p0-2739', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the creation, modification, or deletion of scheduled tasks through Task Scheduler, WMI, PowerShell, or API-based methods followed by execution from svchost.exe or taskeng.exe. Includes detection of hidden or anomalous scheduled tasks, especially those created under SYSTEM or suspicious user contexts.", "external_references": [{"external_id": "AN1221", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0441#AN1221"}], "id": "x-mitre-analytic--4959f750-78db-4b4c-8d91-23027b386c2b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1221", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4698", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "EventCode=4702", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--faa34cf6-cf32-4dc9-bd6a-8f7a606ff65b"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines threshold for grouping task creation and associated execution within suspicious time proximity.", "field": "TimeWindow"}, {"description": "Filters based on non-standard user accounts or execution under SYSTEM when not typical for the environment.", "field": "UserContext"}, {"description": "Allows defenders to flag obfuscated, randomized, or suspicious task names outside normal conventions.", "field": "TaskNamePattern"}, {"description": "Flags tasks executing heavily obfuscated PowerShell or binary blobs via base64 or encoding.", "field": "CommandLineEntropyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2739', 0, 178, '09-mitre-attack', 'retrieved', '83298FC8EE86ADE02DA2162A1D8CE430EE730BC9DF084462134855C3F4997C31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
