VALUES ('doc-09-mitre-attack-p0-2740', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual access to ~/Library/Keychains, ~/.bash_history, or Terminal command history by unauthorized processes or users.", "external_references": [{"external_id": "AN1155", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0412#AN1155"}], "id": "x-mitre-analytic--49897e8e-8d14-4fcb-b305-328d44e58f35", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1155", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "read access to ~/Library/Keychains or history files by terminal processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execution of ''security'', ''cat'', or ''grep'' commands accessing credential storage", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tool or command used to query credentials (e.g., security, grep)", "field": "ProcessName"}, {"description": "Credential file paths (e.g., ~/Library/Keychains)", "field": "TargetPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2740', 0, 104, '09-mitre-attack', 'retrieved', 'AD7F694EF5D7D87192DCDCBF361D37BFB76E19882A731E6774BD52F3B1B87637', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
