VALUES ('doc-09-mitre-attack-p0-2741', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of network enumeration utilities (e.g., net.exe, ping.exe, tracert.exe) in short succession, often chained with lateral movement tools or system enumeration commands.", "external_references": [{"external_id": "AN1583", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0574#AN1583"}], "id": "x-mitre-analytic--498eb889-4468-4c55-9337-df219d5f142b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1583", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define bursty execution patterns of enumeration commands (e.g., <30s)", "field": "TimeWindow"}, {"description": "Tunable per org’s scripting/IT tools (e.g., exclude SCCM, PsExec)", "field": "CommandLinePattern"}, {"description": "Flag suspicious process ancestry (e.g., Word.exe spawning net.exe)", "field": "ParentProcess"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2741', 0, 109, '09-mitre-attack', 'retrieved', 'A4DBF8DADE017C328E12C6575208A63D14B5484BF8C84F50B8027E83D21079AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1",