VALUES ('doc-09-mitre-attack-p0-2742', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects upload of malicious or unusual file types into cloud-shared folders, followed by user downloads or interactions.", "external_references": [{"external_id": "AN1301", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0471#AN1301"}], "id": "x-mitre-analytic--49e91c60-9b73-4a0a-9510-f94152a8ba5e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1301", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "drive.activity logs", "name": "gcp:workspaceaudit", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "FileUploaded, FileAccessed", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Abnormal upload patterns into shared drives.", "field": "UserUploadRateThreshold"}, {"description": "File hash or known-bad filename pattern matching.", "field": "MaliciousFileIndicator"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2742', 0, 89, '09-mitre-attack', 'retrieved', '0C8E007AEDF465FB92E3CB4EA015C9FF18339DA24F74C7EF93953DDE845697A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
