VALUES ('doc-09-mitre-attack-p0-2743', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects launch of command-line interpreters via Terminal, Automator, or hidden `osascript`, especially when parent process lineage deviates from user-initiated applications.", "external_references": [{"external_id": "AN1430", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0516#AN1430"}], "id": "x-mitre-analytic--4a32d0e6-9486-4bbb-8807-7f913f96f448", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1430", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --info --predicate ''eventMessage CONTAINS \"exec\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor for specific plist agents frequently abused for persistence or payload execution.", "field": "LaunchAgentName"}, {"description": "Path or script name pattern (e.g., hidden files, /tmp locations).", "field": "ScriptName"}, {"description": "Adjust based on whether Terminal.app use is common or restricted in user policy.", "field": "TerminalAppUsage"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2743', 0, 115, '09-mitre-attack', 'retrieved', '5A89556FF00A0B528BFBD6E34540F767B200C736E7B69467687A7263B77DE914', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
