VALUES ('doc-09-mitre-attack-p0-2744', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized shell or script-based access to browser config or SQLite history files, typically in ~/.config/google-chrome/, ~/.mozilla/, or ~/.var/app folders, indicating enumeration of bookmarks or saved credentials.", "external_references": [{"external_id": "AN0038", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0013#AN0038"}], "id": "x-mitre-analytic--4a5abd9c-b4f3-4c29-9406-82aa3401c049", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0038", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read, or stat of browser config files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Suspicious script or command execution targeting browser folders", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "User-specific browser data folders, e.g., ~/.config/chromium/Default/History", "field": "BrowserProfilePath"}, {"description": "Shell pattern detecting suspicious access to .sqlite or .json files", "field": "ShellRegex"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2744', 0, 113, '09-mitre-attack', 'retrieved', '904C458D27C7AC86EEDA928C840C91AEE0D1936E7C9B45ACA9878E38A05DEEF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
