VALUES ('doc-09-mitre-attack-p0-2745', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of automated tools or scripts periodically transmitting data to external destinations using scheduled tasks or background processes.", "external_references": [{"external_id": "AN1113", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0397#AN1113"}], "id": "x-mitre-analytic--4a92d2e9-fc28-4eac-9b3d-113e74d7bf2d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1113", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to detect repeated exfil activity over intervals (e.g., every 5 minutes).", "field": "TimeWindow"}, {"description": "Can be tuned to filter known internal or trusted destinations.", "field": "DestinationIP"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2745', 0, 98, '09-mitre-attack', 'retrieved', 'B47B0DBE16DABF01D6F0D0217E9F9BAD06889A5EF72355EC58A2EE8AEC5A36AA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
