VALUES ('doc-09-mitre-attack-p0-2746', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Router/firewall/syslog logs showing authentication failures with unique usernames and reused credentials from same source IP", "external_references": [{"external_id": "AN1267", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1267"}], "id": "x-mitre-analytic--4a930e8d-75eb-469d-82d8-1e1d5764a6d4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1267", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AAA, RADIUS, or TACACS authentication", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to interactive logins rather than SNMP/RPC", "field": "AuthProtocolFilter"}, {"description": "Detection trigger when failure rate exceeds normal profile", "field": "FailedAuthBurst"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2746', 0, 87, '09-mitre-attack', 'retrieved', '302644E0C90C5328FA76CD326FCB85A9E814687F3B383D8A876584D8BC81354E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
