VALUES ('doc-09-mitre-attack-p0-2747', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain: (1) App crash/abnormal termination in unified logs for Safari/Chrome/Office/Preview, (2) new files/scripts in ~/Library, ~/Downloads, /private/var/folders/*, (3) unexpected child (osascript, zsh, bash, curl) spawned by those apps, (4) new outbound connections.", "external_references": [{"external_id": "AN0799", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0287#AN0799"}], "id": "x-mitre-analytic--4aaf0a98-c6a9-4b30-a9d9-3a014473bd0e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0799", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process crash, abort, code signing violations", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "create/write/rename under user-writable paths", "name": "fs:fsevents", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "exec", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "new connections from exploited lineage", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "10–30m correlation window.", "field": "TimeWindow"}, {"description": "osascript, bash, zsh, curl, python, pbpaste/pbcopy, open -a Terminal.", "field": "HighRiskChildren"}, {"description": "~/Library/LaunchAgents, ~/Library/Containers/*/Data, /private/var/folders/*.", "field": "UserPaths"}, {"description": "Flag files with missing com.apple.quarantine extended attribute when sourced from internet.", "field": "QuarantineBypass"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2747', 0, 146, '09-mitre-attack', 'retrieved', '30DCC18AE5A351044B548BAD6E904E1220AA35C9AD778EF54BD67CB14170378F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
