VALUES ('doc-09-mitre-attack-p0-2748', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User-mode application uses flock() or NSDistributedLock to gain exclusive access to a resource file (e.g., /tmp/guard.lock), conditional logic alters execution if already locked.", "external_references": [{"external_id": "AN0374", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0132#AN0374"}], "id": "x-mitre-analytic--4ab12b3f-5c6a-42a6-8d9c-c10b7e814986", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0374", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "flock|NSDistributedLock|FileHandle.*lockForWriting", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "process.*exit.*code", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to mutex file (e.g., /tmp/*, /private/tmp/*), tune per environment.", "field": "lockfile_path"}, {"description": "Flag non-user processes using these APIs.", "field": "user_context"}, {"description": "Detection correlation across short time intervals between lock attempt and process exit.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2748', 0, 111, '09-mitre-attack', 'retrieved', '683737F0C0E55CC9520E125F2232198F8724DFC27ADECC107E3B4C68073DB29E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
