VALUES ('doc-09-mitre-attack-p0-2750', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor VM-level DNS and network traffic logs for adversary-controlled domains or selective response behavior (e.g., dropped requests from security scanners).", "external_references": [{"external_id": "AN1152", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0411#AN1152"}], "id": "x-mitre-analytic--4b16cb6e-7a81-4f97-a4ad-5e461e1cc154", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1152", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DNS lookups resolving to domains with rapid changes in registration metadata", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--ff9b665a-598b-4bcb-8b2a-a87566aa1256"}, {"channel": "Suspicious traffic filtered or redirected by VM networking stack", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted virtual machines where adversaries may attempt to hide C2 traffic.", "field": "MonitoredVMs"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2750', 0, 103, '09-mitre-attack', 'retrieved', 'B0608210E95EF53C87B5D23CBC91217D739C6576398C29B41E15E829A36771C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
