VALUES ('doc-09-mitre-attack-p0-2751', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abnormal HID device enumeration via I/O Registry (ioreg -p IOUSB) and keystroke injection targeting AppleScript, osascript, or PowerShell equivalents. Defender correlates new USB device connections with rapid script execution.", "external_references": [{"external_id": "AN1569", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0568#AN1569"}], "id": "x-mitre-analytic--4b47697b-ff9b-4af7-a079-d34210cebdab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1569", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New IOUSB keyboard/HID device enumerated with suspicious attributes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "osascript, AppleScript, or Python execution triggered immediately after HID connection", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of AppleScripts expected in the environment, to minimize false positives.", "field": "AllowedAppleScripts"}, {"description": "Timeframe between HID injection and script execution considered suspicious.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2751', 0, 123, '09-mitre-attack', 'retrieved', 'EDEB3F489AD75AEAAEA182F8404F4CA5D5D50B16097104662FF7E7FC77CBC810', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
