VALUES ('doc-09-mitre-attack-p0-2752', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Lua script execution via native or 3rd party interpreters, chained with unsigned binaries or unexpected parent lineage.", "external_references": [{"external_id": "AN0280", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0101#AN0280"}], "id": "x-mitre-analytic--4b53b71f-16b4-483b-b64a-eacf6c9db077", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0280", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjustable based on system activity patterns (e.g., Terminal vs GUI)", "field": "ParentProcessName"}, {"description": "Helps filter unsigned or self-signed Lua payloads.", "field": "SignatureStatus"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2752', 0, 87, '09-mitre-attack', 'retrieved', '18899FA617FC37543B18452AE077DAC05DF91F58D61FEF9EA36C37FC02B734D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
