INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2753', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious SaaS tenant activity involving webhook configurations pointing to external or untrusted domains. Defender perspective: repeated automated exports or suspicious webhook endpoint registrations.", "external_references": [{"external_id": "AN0440", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0153#AN0440"}], "id": "x-mitre-analytic--4b72b349-f810-4e34-9185-b5550147147e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0440", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set-Mailbox, Add-InboxRule, RegisterWebhook", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Webhook registrations or repeated POST activity", "name": "saas:api", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor new webhook creation events in SaaS environments.", "field": "WebhookRegistrations"}, {"description": "Flag webhooks pointing to domains not owned by the enterprise.", "field": "ExternalDomains"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2753', 0, 105, '09-mitre-attack', 'retrieved', '0FCED25886A6C9A67BAAA728703B0625BB49A90F50EA1BAB8B44D441F5E4161D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
