INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2756', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outbound connections from non-network-facing processes repeatedly send similarly sized payloads within uniform time intervals.", "external_references": [{"external_id": "AN0597", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0213#AN0597"}], "id": "x-mitre-analytic--4baad14d-46b1-4e96-9e2a-138ae4e3ec75", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0597", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connect/sendto", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Outbound Network Flow", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of typical binaries expected to generate outbound connections (e.g., wget, curl)", "field": "ProcessNetworkBaseline"}, {"description": "Deviation threshold to consider data ''fixed size'' (e.g., ±5% size delta)", "field": "PayloadLengthVariance"}, {"description": "Number of observed transfers per minute/hour that signals anomalous repetition", "field": "RepeatFrequencyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2756', 0, 109, '09-mitre-attack', 'retrieved', 'BEEB766D82B96082066DBCCB794430D99A00BB6E926186C51969EFFCD3E15444', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
