VALUES ('doc-09-mitre-attack-p0-2757', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Domain account enumeration using ldapsearch, samba tools (e.g., ''wbinfo -u''), or winbindd lookups.", "external_references": [{"external_id": "AN0364", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0129#AN0364"}], "id": "x-mitre-analytic--4bad86cf-6cab-46f4-8748-28dc8c8ec81b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0364", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "nslcd or winbind logs", "name": "linuxsyslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "LDAP Query", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect suspicious use of ldapsearch, wbinfo, getent passwd, or samba enumeration tools.", "field": "ProcessName"}, {"description": "Tune for high-volume or broad-scope LDAP queries.", "field": "LDAPSearchFilter"}, {"description": "Apply filters for unexpected users or service accounts executing the behavior.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2757', 0, 113, '09-mitre-attack', 'retrieved', 'E462D8DBEF7B572566ACA9D0C2CE5C6AD20CBCB6456202DD92BBDE04C3CD781B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
