INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2758', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of `.plist` files in /Library/LaunchDaemons/, especially those with suspicious Program or ProgramArguments paths, combined with execution activity under launchd with elevated privileges. Detectable through correlated Unified Logs, file monitoring, and process telemetry.", "external_references": [{"external_id": "AN1126", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0401#AN1126"}], "id": "x-mitre-analytic--4bb5b68e-1a01-498e-ae39-94f951e01cd9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1126", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchd spawning processes tied to new or modified LaunchDaemon .plist entries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_create", "name": "fs:launchdaemons", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "file_modify", "name": "fs:launchdaemons", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "launchd loading new LaunchDaemon or changes to existing daemon configuration", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex patterns to match anomalous executable paths or names in .plist files", "field": "ProgramPathRegex"}, {"description": "Correlation window between file modification and launchd process execution", "field": "TimeWindow"}, {"description": "Admin or root context used during daemon installation", "field": "UserContext"}, {"description": "Whether the binary associated with the LaunchDaemon is signed or trusted", "field": "UnsignedBinaryFlag"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2758', 0, 169, '09-mitre-attack', 'retrieved', '544B3F868B0F94D5529E5943FE7B341D7D3D8498271F2EC4D96032B7A09CD3E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
