INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2760', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CONTAINERS (Docker/K8s/containerd): A user pulls an untrusted image from a public/unknown registry and then creates/starts a container from that image. Shortly after start, the container spawns unexpected utilities (e.g., curl/wget/bash/python), or makes outbound network connections atypical for the namespace/workload. The analytic correlates Image Creation/Download → Container Creation → Container Start → Command Execution/Network activity within a short window and with a consistent image digest.", "external_references": [{"external_id": "AN0691", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0248#AN0691"}], "id": "x-mitre-analytic--4c16cebd-ac7e-472a-ae12-62966cbd19e2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0691", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Image pull from untrusted registry (name NOT IN allowlist) or new digest never seen before", "name": "containerd:events", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"channel": "create: Pod/Container created with image tag ''latest'' or mutable tag; imagePullPolicy=Always; noDigest=true", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"channel": "start: ContainerStarted or Pulling image → Started container", "name": "kubernetes:events", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"channel": "execve: Process in container namespace executes curl|wget|bash|sh|python|nc with outbound args", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "New egress from container IP/namespace to Internet or non-approved CIDRs/ASNs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved registries/namespaces (e.g., ECR/GCR/ACR org repos).", "field": "ImageRegistryAllowList"}, {"description": "Correlation window from image pull to container activity (e.g., ≤15m).", "field": "TimeWindow"}, {"description": "Executables treated as high-risk when run in app containers (bash, sh, curl, wget, nc, powershell for Windows containers).", "field": "SuspiciousBinaries"}, {"description": "K8s namespaces that should never pull from Internet or run mutable tags.", "field": "NamespaceScope"}, {"description": "Destination networks/domains that should not be contacted by containers.", "field": "OutboundCIDRBlockList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2760', 0, 253, '09-mitre-attack', 'retrieved', 'C98DBF2E249B69EBE20E20D477B8164CBF2608289ECEBCC68128353F88641666', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
