INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2761', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation of traffic mirroring sessions (e.g., AWS VPC Traffic Mirroring, Azure vTAP) that redirect traffic from critical assets to other virtual instances, often followed by file creation or session establishment.", "external_references": [{"external_id": "AN0878", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0314#AN0878"}], "id": "x-mitre-analytic--4c4941eb-b087-4710-8c88-ff537c2309ff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0878", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateTrafficMirrorSession / ModifyTrafficMirrorTarget", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify VMs or containers where mirror sessions are abnormal or unexpected.", "field": "MirrorSourceList"}, {"description": "Monitor whether mirror target roles match administrative expectations.", "field": "TargetIAMRole"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2761', 0, 103, '09-mitre-attack', 'retrieved', '147CB0B6BE6EF71098E6AACF130A9A19DB1691466285153B515FD22720EF3D9F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
