INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2762', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders observe command-line executions or API-based registry reads targeting sensitive paths like HKLM or HKCU with keyword filters such as ''password'', ''cred'', or ''logon''. Typically performed by Reg.exe, PowerShell, custom binaries, or offensive tools such as Cobalt Strike. Correlation with process ancestry and command-line arguments indicates suspicious credential discovery activity.", "external_references": [{"external_id": "AN0694", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0250#AN0694"}], "id": "x-mitre-analytic--4c744ac0-ba25-4b42-8397-9b398ba55eb8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0694", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "Behavioral rule for registry enumeration under credential-related paths", "name": "EDR:hunting", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of strings searched in registry queries (e.g., password, credential, login). May need to expand for localized OS or app-specific terms.", "field": "KeywordMatch"}, {"description": "Parent process used for registry access. Can tune for suspicious ancestry (e.g., cmd.exe > reg.exe vs. services.exe > reg.exe).", "field": "ParentProcessFilter"}, {"description": "Time-based correlation window for detecting chained activity between registry reads and subsequent credential use or exfiltration.", "field": "TimeWindow"}, {"description": "HKLM vs. HKCU vs. others. May limit scope to user or system context depending on risk appetite.", "field": "RegistryHiveScope"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2762', 0, 200, '09-mitre-attack', 'retrieved', 'A091B912F22AE720329E4DBC683F6137465166C78F515F58D501ED1F024C63DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
