INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2763', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outbound traffic with anomalous payload sizes and patterns from non-networking processes, often observed via packet inspection or connection logs.", "external_references": [{"external_id": "AN0031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0011#AN0031"}], "id": "x-mitre-analytic--4c7d92bb-4b46-44e4-b070-43c46d3193c4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0031", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve network tools", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "TCP session tracking", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust based on expected entropy of typical outbound data.", "field": "EntropyScore"}, {"description": "Exclude known good binaries that generate high network output.", "field": "ProcessWhitelist"}, {"description": "Minimum ratio of bytes_sent to bytes_received.", "field": "DataRatioThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2763', 0, 107, '09-mitre-attack', 'retrieved', '5BA35A3791D9A2522338BBB91BE874018F8EFA3F376DC8486691F7141B59ADC8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
