VALUES ('doc-09-mitre-attack-p0-2766', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of command-line like `ip ssh pubkey-chain` to bind SSH keys to privileged accounts on routers or switches.", "external_references": [{"external_id": "AN0354", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0126#AN0354"}], "id": "x-mitre-analytic--4d8e89c0-fbde-43fc-adc4-d2f50bec3193", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0354", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ip ssh pubkey-chain", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Was the role allowed to push persistent config changes?", "field": "CLIUserRole"}, {"description": "Variations in syntax or log behavior across device OS", "field": "DeviceModel"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2766', 0, 90, '09-mitre-attack', 'retrieved', '38EEC1C542082EDF6DE25AEA73F25874B848BFAC18C92DBA041DD34DDEEAB276', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
