INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2767', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the creation or modification of `.service` unit files in system/user-level directories, combined with execution of `systemctl`, `service`, or dynamically created drop-ins via systemd generators. Detects persistence by analyzing the `ExecStart` path, file entropy, and symlink usage, especially when paired with execution from `/tmp`, `/dev/shm`, or unmounted volumes.", "external_references": [{"external_id": "AN0701", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0253#AN0701"}], "id": "x-mitre-analytic--4da5660a-3b1c-4b4d-ad79-991bef456b20", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0701", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write, open, or rename to /etc/systemd/system/*.service", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "modification of existing .service file", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execution of systemctl or service with enable/start parameters", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "fork/exec of service via PID 1 (systemd)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "newly registered unit file with ExecStart pointing to unknown binary", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex filters for systemd unit locations (e.g., `/etc/systemd/system/*.service`, `/lib/systemd/system/`)", "field": "ServicePathRegex"}, {"description": "Allowlist of trusted `ExecStart` binary paths (e.g., `/usr/bin/`, `/bin/`)", "field": "ExecStartPathAllowlist"}, {"description": "List of usernames that are authorized to define user-level services", "field": "UserContextFilter"}, {"description": "Entropy level of binaries referenced in `ExecStart` to detect packed or obfuscated payloads", "field": "FileEntropyThreshold"}, {"description": "Flags suspicious combinations such as `systemctl enable` + `systemctl start` within short interval", "field": "SystemctlOperationSet"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2767', 0, 217, '09-mitre-attack', 'retrieved', '5F7AB16D64E3BA1528AD429AC865260361ECB94B7C409F2C05D285A8DF51568B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
