VALUES ('doc-09-mitre-attack-p0-2768', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Phishing delivered via SaaS services (chat, collaboration platforms) where messages contain malicious URLs or attachments. Detect anomalous link clicks, suspicious file uploads, or token misuse after SaaS-based phishing attempts.", "external_references": [{"external_id": "AN0193", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0070#AN0193"}], "id": "x-mitre-analytic--4da63d13-d9bb-41c6-88c8-31bc9f2579fb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0193", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "MessagePosted: Suspicious links or attachment delivery via collaboration tools (Slack, Teams, Zoom)", "name": "saas:collaboration", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope of SaaS platforms under phishing monitoring.", "field": "MonitoredSaaSApps"}, {"description": "Threshold for auto-expansion and detonation of URLs sent in SaaS messages.", "field": "LinkInspectionPolicy"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2768', 0, 109, '09-mitre-attack', 'retrieved', 'A911E57E9981B250550BB7C13BDE155695B7D4963E7541CC1FF805AE342335DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
