VALUES ('doc-09-mitre-attack-p0-2769', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary tool/script issuing mass SYN/ACK floods that degrade OS responsiveness and interrupt service response on macOS endpoints.", "external_references": [{"external_id": "AN1014", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0356#AN1014"}], "id": "x-mitre-analytic--4db0f97c-a0c4-4c96-af56-86c6b227ea42", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1014", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "network stack resource exhaustion, tcp_accept queue overflow, repeated resets", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Execution of flooding tools or compiled packet generators", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Anomalous TCP SYN or ACK spikes from specific source or interface", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Observed CPU/network degradation level that triggers response", "field": "SystemLoadThreshold"}, {"description": "Where DoS tools are commonly dropped or compiled", "field": "ToolExecutionPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2769', 0, 120, '09-mitre-attack', 'retrieved', '0A5C8F3837F561EF212E86D4DFDF47F0F2291986B1753B27D4EDAD979F7B8956', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
