VALUES ('doc-09-mitre-attack-p0-2772', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects mounted external devices (via /media or /mnt) followed by large file read or copy operations by shell scripts, unauthorized users, or staging tools (e.g., tar, rsync).", "external_references": [{"external_id": "AN0343", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0123#AN0343"}], "id": "x-mitre-analytic--4e288214-93b3-48a7-b51e-2b0136db8540", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0343", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "device event logs", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor mount points like /media, /mnt, or /run/media.", "field": "MountPointPattern"}, {"description": "Restrict detection to non-root or unexpected users.", "field": "UserGroupScope"}, {"description": "Alert on large file access or copy events.", "field": "AccessVolumeThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2772', 0, 112, '09-mitre-attack', 'retrieved', 'F51F3D6F32B2CFCAE1B0BA5A704307D660A6127A10391C991238D2B76DF4DAD1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
