VALUES ('doc-09-mitre-attack-p0-2773', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "VM services or management daemons communicating on ports not defined by VMware defaults, such as vpxa or hostd processes initiating traffic over high-numbered or unexpected ports.", "external_references": [{"external_id": "AN0636", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0227#AN0636"}], "id": "x-mitre-analytic--4e3afe58-e384-4b9e-9137-adaa0bac72af", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0636", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ESXi service connections on unexpected ports", "name": "esxi:vpxd", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "listening sockets bound to non-standard ports", "name": "esxcli:network", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Default VMware service ports that should not be flagged.", "field": "ESXiAllowedPorts"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2773', 0, 99, '09-mitre-attack', 'retrieved', 'AE43F3FC5E51D36BA9C9E63F9F751BC575229CC84FA83F93F419F11A184D364B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
