VALUES ('doc-09-mitre-attack-p0-2775', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses built-in tools like ''net user /add'', PowerShell, or WMI to create a local user. Sequence: Account creation event (4720) follows process creation of a suspicious executable (e.g., powershell.exe or net.exe).", "external_references": [{"external_id": "AN1235", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0447#AN1235"}], "id": "x-mitre-analytic--4e4c318b-5da0-46f7-aed2-d37828e4831b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1235", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4720", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Attackers may use cmd.exe, wscript.exe, or renamed binaries to evade detection", "field": "ParentProcessName"}, {"description": "Define time threshold between process start and user creation event (e.g., 5s–2m)", "field": "TimeWindow"}, {"description": "Correlate if process runs under SYSTEM, Administrator, or untrusted account", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2775', 0, 125, '09-mitre-attack', 'retrieved', '61D1B9A645D1D7512277FC257FD9E08F029CBB32527DD1F1FD221CDC03A9FF13', 'v1', '{