VALUES ('doc-09-mitre-attack-p0-2776', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the execution of non-browser processes establishing outbound encrypted network connections using uncommon symmetric encryption protocols (e.g., AES via PowerShell or custom scripts) to alternate external destinations.", "external_references": [{"external_id": "AN1389", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0503#AN1389"}], "id": "x-mitre-analytic--4e5ffb58-75de-4305-a439-98ca3499f45e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1389", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag high-entropy payloads sent over unexpected protocols.", "field": "PayloadEntropyThreshold"}, {"description": "Define allowable transfer window (e.g., abnormal traffic outside business hours).", "field": "TimeWindow"}, {"description": "List of known-good binaries for encrypted traffic (e.g., Chrome, Outlook).", "field": "ExecutableAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2776', 0, 115, '09-mitre-attack', 'retrieved', '159C346A4C1F0B5E422EA0CC75B847198B021CAB01B1EC4B7AC22460C7B6548B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
