VALUES ('doc-09-mitre-attack-p0-2778', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious use of attrib.exe or PowerShell commands to set hidden attributes on files/directories. Defender view: processes modifying file attributes to ''hidden'' or creating files with ADS (alternate data streams).", "external_references": [{"external_id": "AN0091", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0032#AN0091"}], "id": "x-mitre-analytic--4ea80ec4-bfcc-4bd6-b986-aa2c9fe2d8d6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0091", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter hidden file detection by sensitive file extensions (.exe, .dll, .bat).", "field": "MonitoredExtensions"}, {"description": "Enable detection of alternate data streams depending on organizational usage.", "field": "ADSMonitoring"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2778', 0, 107, '09-mitre-attack', 'retrieved', 'EAB55A6F9F5483C20575DB9F5350B9082B0FA3EF3FD4F97752EB56E5C3F61C31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
