VALUES ('doc-09-mitre-attack-p0-2780', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Internal user account accesses shared links outside org followed by mass file download", "external_references": [{"external_id": "AN1330", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0484#AN1330"}], "id": "x-mitre-analytic--4eca5ae6-797c-41cb-bacd-dc7a6da58fb0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1330", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AnonymousLinkCreated, FileDownloaded", "name": "m365:sharepoint", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "SigninSuccess", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether links allow anonymous/external access", "field": "LinkVisibilityScope"}, {"description": "# of files downloaded within 50 files)", "field": "DownloadBurstThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2780', 0, 84, '09-mitre-attack', 'retrieved', '91ECEF78D4C48DB1B2B66DB87BA8771437A99937DD6EBCE1FA8717ED456FEE00', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
