INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2781', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects malicious archiving via system or third-party libraries (libz, libarchive) invoked by Python, Swift, or Objective-C binaries. Correlates unified logs of library loads with creation of compressed or encrypted archives (.zip, .gz, .bz2, .dmg).", "external_references": [{"external_id": "AN0749", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0268#AN0749"}], "id": "x-mitre-analytic--4ecd8727-bcf3-4fce-8c04-e8d0bad1267e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0749", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of Python, Swift, or other binaries invoking archiving libraries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Loading of libz.dylib, libarchive.dylib by non-standard applications", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Creation of .zip, .gz, .dmg archives in /Users, /tmp, or application directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Applications allowed to load compression libraries (e.g., backup agents).", "field": "AllowedProcesses"}, {"description": "Flag archiving under privileged or system accounts as suspicious.", "field": "UserContext"}, {"description": "Targeted monitoring of sensitive file formats or compressed containers.", "field": "FileExtensionFilter"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2781', 0, 153, '09-mitre-attack', 'retrieved', '6E8CF0C195E38E52A4E5678C62BC559B1E489101319617F39AD8DB9562B7CACD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
