VALUES ('doc-09-mitre-attack-p0-2784', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates creation of email forwarding rules or header anomalies (e.g., X-MS-Exchange-Organization-AutoForwarded) with suspicious process execution, file access of .pst/.ost files, and network connections to external SMTP servers.", "external_references": [{"external_id": "AN1309", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0476#AN1309"}], "id": "x-mitre-analytic--4f15b707-9b44-4716-bfcd-e3f28659077b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1309", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5145", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Exchange logs or header artifacts", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines correlation window across email rule creation and outbound SMTP.", "field": "TimeWindow"}, {"description": "Filters for admin or service accounts to reduce false positives.", "field": "UserContext"}, {"description": "Allows tuning based on expected external email domains.", "field": "SMTPDomainList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2784', 0, 135, '09-mitre-attack', 'retrieved', 'C6F1E79DA4620293AAD9DCE43B956C5BD14294EDBCA652E755244ECB5C3D6A72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
