VALUES ('doc-09-mitre-attack-p0-2785', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects DHCP spoofing by monitoring unified logs for unexpected DHCP ACK/OFFER parameters and correlating with packet captures for multiple DHCP servers. Behavioral emphasis is on inconsistent DNS and gateway assignments that redirect traffic.", "external_references": [{"external_id": "AN1292", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0468#AN1292"}], "id": "x-mitre-analytic--4f2bc468-a57d-44e9-b9cd-d491df6b0daf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1292", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "new DHCP configuration with anomalous DNS or router values", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Multiple DHCP OFFER responses for a single DISCOVER", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected DNS server list; deviations may indicate spoofing.", "field": "BaselineDNS"}, {"description": "Threshold for number of anomalous DHCP responses before alerting.", "field": "AlertSensitivity"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2785', 0, 122, '09-mitre-attack', 'retrieved', '8EFF029278ACB1F706E85A8A372D91F4360AB4EF9F429248261907AF2FE61D6A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
