VALUES ('doc-09-mitre-attack-p0-2786', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects tampering of IIS-based login pages (e.g., default.aspx, login.aspx) tied to VPN, OWA, or SharePoint via script injection or unexpected editor processes modifying web roots.", "external_references": [{"external_id": "AN1321", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0480#AN1321"}], "id": "x-mitre-analytic--4f33b538-1370-4df1-934f-fe3a609453fb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1321", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "IIS Logs", "name": "WinEventLog:iis", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define path to monitored IIS web root (e.g., C:\\inetpub\\wwwroot\\login.aspx)", "field": "FilePath"}, {"description": "Exclude legitimate updates (e.g., msdeploy.exe) and alert on suspicious editors (e.g., notepad.exe, certutil.exe)", "field": "ProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2786', 0, 105, '09-mitre-attack', 'retrieved', '5E71CA6D2563E0E148D2BC5663BE4A8356C6E6DF7E768961EAF6CF484B15FF35', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
