VALUES ('doc-09-mitre-attack-p0-2787', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abuse of fileless storage mechanisms such as Registry keys, WMI classes, and Event Logs used to stage payloads, scripts, or encoded content outside traditional files.", "external_references": [{"external_id": "AN0973", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0344#AN0973"}], "id": "x-mitre-analytic--4f5f4b26-0bf0-4f3d-b8ac-1af660923bd2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0973", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "WMI Object Creation Events", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scoped to suspicious or abused paths like HKCU\\Software\\Classes\\ or HKLM\\SYSTEM\\CurrentControlSet\\Services\\", "field": "RegistryPathFilter"}, {"description": "Minimum entropy level to flag suspicious registry or WMI content as encoded payloads", "field": "PayloadEntropyThreshold"}, {"description": "Temporal window for correlating WMI/registry modifications with process creation or network usage", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2787', 0, 124, '09-mitre-attack', 'retrieved', 'F5CCA15144484ABBEE94524B4BB482