VALUES ('doc-09-mitre-attack-p0-2788', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries using bash scripts or tools to recursively enumerate user home directories, config files, or SSH keys.", "external_references": [{"external_id": "AN1071", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0380#AN1071"}], "id": "x-mitre-analytic--4f5f64b3-bc1b-4573-b790-42b8adfdd609", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1071", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time span to correlate multiple file access events indicative of scripted or bulk access.", "field": "TimeWindow"}, {"description": "List of tools (e.g., `find`, `grep`, `tar`, `scp`) that may be benign but are context-sensitive.", "field": "ScriptToolName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2788', 0, 103, '09-mitre-attack', 'retrieved', '7747D7DD445EAB928F7992B34CDCDBDE4A6E5390B56564474C9F844781F48898', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
