VALUES ('doc-09-mitre-attack-p0-2789', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) execution of `pwpolicy` or MDM/DirectoryService reads of account policies; (2) optional read of `/Library/Preferences/com.apple.loginwindow` or config profiles; (3) follow-on credential probing or lateral movement by same user/session. Use unified logs and process telemetry.", "external_references": [{"external_id": "AN0457", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0161#AN0457"}], "id": "x-mitre-analytic--4f71c7bd-dd25-43c7-ac5c-7a85c7588759", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0457", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "pwpolicy|PasswordPolicy", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "exec /usr/bin/pwpolicy", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "profiles -P|getaccountpolicies", "name": "macos:MDM", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved profiles reading/updating auth policies.", "field": "MDMProfileIDs"}, {"description": "Jamf or management hosts where queries are expected.", "field": "AdminConsoleHosts"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2789', 0, 113, '09-mitre-attack', 'retrieved', '79E03B09DAA009E3F2013B6943DA4163B3D3F83C4FD8780D27B1C4E8288B35AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
