VALUES ('doc-09-mitre-attack-p0-2790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of processes that load or decode encrypted/encoded files in memory and subsequently execute or inject them, indicating payload unpacking or memory-resident malware.", "external_references": [{"external_id": "AN0237", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0087#AN0237"}], "id": "x-mitre-analytic--4f985435-9144-4a8f-aca0-598f788855b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0237", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path of decoder utilities (e.g., certutil.exe, powershell.exe) can vary across environments.", "field": "Image"}, {"description": "Base64/hex strings used may change per encoded payload.", "field": "CommandLine"}, {"description": "The duration between file decode and execution may differ across implementations.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2790', 0, 119, '09-mitre-attack', 'retrieved', '1541D08ACEE871CB9B7C884A07D71CAC5382B7FDFDA479A191CAD0C378160DC5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
