VALUES ('doc-09-mitre-attack-p0-2791', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect alterations of transmitted data via monitoring syscalls (`send`, `recv`, `write`) or middleware interception. Identify mismatched file hashes when compared at origin vs. destination. Watch for anomalous activity from processes interacting with secure transmission services (e.g., OpenSSL, scp).", "external_references": [{"external_id": "AN0703", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0254#AN0703"}], "id": "x-mitre-analytic--500ae9f9-c6c2-4160-ac03-072d963eba63", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0703", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "send, recv, write: Abnormal interception or alteration of transmitted data", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "Integrity mismatch warnings or malformed packets detected", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of processes authorized to handle transmitted data (e.g., sshd, nginx).", "field": "WatchedProcesses"}, {"description": "Frequency of out-of-band integrity verification checks.", "field": "HashCheckInterval"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2791', 0, 127, '09-mitre-attack', 'retrieved', '01FED632CCE28F7C0D192365354A6A8C4BC6F89F3BB8F0BAEF9432FF55351E06', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
