VALUES ('doc-09-mitre-attack-p0-2792', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi daemons (hostd, vpxa) unexpectedly using symmetric encryption routines for external connections. Defender identifies logs of service traffic with encrypted payloads inconsistent with VMware management baselines.", "external_references": [{"external_id": "AN0403", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0143#AN0403"}], "id": "x-mitre-analytic--50102ced-9c8f-47e6-b438-63b2a7fe983d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0403", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Symmetric crypto routines triggered for external session", "name": "esxi:vpxd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Socket sessions with randomized payloads inconsistent with TLS", "name": "esxcli:network", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline list of approved vCenter and update endpoints.", "field": "AllowedMgmtHosts"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2792', 0, 101, '09-mitre-attack', 'retrieved', 'F9F52E2786FC18FCCB14262414BDCEF7AF41E552B8CCA993CA7CBCF4DE3F2393', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
