VALUES ('doc-09-mitre-attack-p0-2794', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized creation or modification of DLLs loaded by LSASS, abnormal registry values under LSA extensions, and anomalous DLL load activity into the lsass.exe process context—correlated during boot or logon events.", "external_references": [{"external_id": "AN0629", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0225#AN0629"}], "id": "x-mitre-analytic--5028303d-22d6-490c-b053-015e877d5829", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0629", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3033", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate DLL file creation/modification with LSASS execution within a configurable timeframe (e.g., 5 min)", "field": "TimeWindow"}, {"description": "Tune based on known legitimate LSASS plugin DLL paths", "field": "ImagePathPattern"}, {"description": "Flag unsigned DLLs loaded into lsass.exe or those signed by unexpected publishers", "field": "SignatureValidation"}, {"description": "Scope to specific registry keys: HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Authentication Packages", "field": "RegistryKeyScope"}, {"description": "Exclude known-good LSASS plugin DLLs based on cryptographic hash", "field": "FileHashAllowList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2794', 0, 172, '09-mitre-attack', 'retrieved', '5B654E4DA743F61E154F738DD09CFE572A3C02E6B4989671DD788875608AF027', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
