INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2795', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection focuses on identifying anomalous regsvr32.exe executions that deviate from normal administrative or system use. Defenders may observe regsvr32.exe loading scriptlets or DLLs from unusual paths (especially temporary directories or remote URLs), command-line arguments invoking /i or /u with suspicious file references, network connections initiated by regsvr32.exe, and unsigned or untrusted DLLs being loaded shortly after regsvr32.exe invocation. Correlated sequences include regsvr32.exe process creation, module load of DLL/scriptlet, and optional outbound network traffic.", "external_references": [{"external_id": "AN0785", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0282#AN0785"}], "id": "x-mitre-analytic--50658b7e-57c5-4e31-b156-1b294574a9f2", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0785", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directories where DLL loading via regsvr32.exe is expected (e.g., C:\\Windows\\System32).", "field": "AllowedDLLPaths"}, {"description": "File extensions considered suspicious when executed by regsvr32.exe (e.g., .sct, .ocx).", "field": "ScriptletExtensions"}, {"description": "Timeframe to correlate regsvr32.exe process creation with subsequent module loads and network connections.", "field": "TimeWindow"}, {"description": "Parent processes from which regsvr32.exe is expected (e.g., explorer.exe during legitimate COM object registration).", "field": "ParentProcessWhitelist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2795', 0, 191, '09-mitre-attack', 'retrieved', '45DC57F892F0333C455D5C96C1517E9472F58D029C15B739116DB63C9F9C9F9A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
