INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2797', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of Windows services or scheduled tasks with names or descriptions mimicking legitimate entries, followed by anomalous execution of untrusted binaries or LOLBAS.", "external_references": [{"external_id": "AN0324", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0117#AN0324"}], "id": "x-mitre-analytic--51a23f35-4a11-4119-935a-1ffebcda2839", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0324", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=4698", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Similarity threshold for comparing new task/service names to known legitimate names (e.g., Levenshtein distance)", "field": "TaskNameSimilarityThreshold"}, {"description": "Confidence level required for allowing a binary, often from unsigned or untrusted source", "field": "BinaryReputationScore"}, {"description": "Whether the execution came from SYSTEM, service accounts, or user contexts", "field": "ExecutionContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2797', 0, 129, '09-mitre-attack', 'retrieved', '3F1BCB286729A302FC597FFEB2B8E47A5F4DD67E85A1B8931F18A8A0860470CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
