VALUES ('doc-09-mitre-attack-p0-2800', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process loads a non-system .dylib/.so via dyld (dlopen/dlsym) from user-writable locations (~/Library, /tmp) or after the library was recently created/downloaded, often followed by network egress or persistence.", "external_references": [{"external_id": "AN0054", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0018#AN0054"}], "id": "x-mitre-analytic--52a5dffb-f3a3-45fc-97b3-2c09fed8e0b4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0054", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dyld/unified log entries indicating image load from non-system paths", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "exec: Process execution context for loaders calling dlopen/dlsym", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ES_EVENT_TYPE_NOTIFY_OPEN: Open of .dylib/.so in user-writable locations", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "~/Library, /tmp, /Users/*/.* (hidden dirs) – tune to enterprise layout.", "field": "SuspiciousDirs"}, {"description": "Alert only when code-signing is invalid or absent.", "field": "UnsignedOnly"}, {"description": "Correlate write/open to module load within N minutes.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2800', 0, 141, '09-mitre-attack', 'retrieved', '7F49DE348049005B4364B7099C10B073A7B7649AE0E6BCA905E03121E25C04EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
