VALUES ('doc-09-mitre-attack-p0-2801', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate process execution of shutdown/reboot commands (e.g., shutdown.exe, restart-computer) with host status change logs (Event IDs 1074, 6006) and absence of related administrative context (e.g., user not in Helpdesk group).", "external_references": [{"external_id": "AN1538", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0559#AN1538"}], "id": "x-mitre-analytic--52b9bf67-304e-403f-9b81-4d4b9d974ad6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1538", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1074", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines if user has appropriate privileges to initiate shutdown/reboot.", "field": "UserContext"}, {"description": "Unexpected shutdowns during business hours may warrant increased scrutiny.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2801', 0, 105, '09-mitre-attack', 'retrieved', '4B76894E6AE859A562851E8C5A29168230003F3D0CC69AA2267C6EC7A342A39C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
