VALUES ('doc-09-mitre-attack-p0-2802', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Executable or binary files created without symbol tables or with stripped sections, especially by non-user shell processes or compilers invoked outside standard dev paths.", "external_references": [{"external_id": "AN0056", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0019#AN0056"}], "id": "x-mitre-analytic--52d150da-36f4-43b4-96c4-b4fe33b012a2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0056", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EXECVE", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "hash, elf_info, file_metadata", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag combinations in compiled binaries indicating symbol table removal", "field": "StripFlags"}, {"description": "Whitelist compiler output directories to reduce false positives", "field": "DirectoryScope"}, {"description": "Heuristic boundaries for abnormal small or overly large stripped binaries", "field": "FileSizeRange"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2802', 0, 120, '09-mitre-attack', 'retrieved', '4EFEB0F443CE