VALUES ('doc-09-mitre-attack-p0-2803', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Series of authentication failures (Event ID 4625) targeting the same or similar user accounts over time from one or more remote IPs", "external_references": [{"external_id": "AN1521", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0551#AN1521"}], "id": "x-mitre-analytic--52dfd8de-910a-4caa-98a7-6dcf44ef903e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1521", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4625", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the period in which multiple failed attempts are aggregated (e.g., 10 minutes)", "field": "TimeWindow"}, {"description": "Filter for common account naming conventions, e.g., service accounts or administrator variants", "field": "UsernamePattern"}, {"description": "Limit on unique IPs trying to authenticate against a single account", "field": "SourceIPThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2803', 0, 112, '09-mitre-attack', 'retrieved', 'AE7D896840264298A976F357BBE795B34098B99662846391D75D8DDA1800DC48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
