VALUES ('doc-09-mitre-attack-p0-2804', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation of new container system processes via `docker run --restart`, `kubectl exec` to init containers, or modification of container init specs. Flags container images that override entrypoints to embed persistence behaviors.", "external_references": [{"external_id": "AN1578", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0571#AN1578"}], "id": "x-mitre-analytic--52ee5593-7db2-4ad0-b5f4-630ebcf2ce0f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1578", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "docker run with restart=always or modifying init", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"channel": "modification of entrypoint scripts or init containers", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns used to detect modified container start scripts", "field": "EntrypointOverridePattern"}, {"description": "Policy values triggering alert (e.g., always, on-failure)", "field": "RestartPolicyMatch"}, {"description": "Path filters for `/etc/init.d/`-like behaviors inside containers", "field": "KubeInitModPath"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2804', 0, 126, '09-mitre-attack', 'retrieved', '283BAB6AD2CE225C84E5FDD1C7F61D4832E4AA77EAE189850FC6253ABFD5469F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
