VALUES ('doc-09-mitre-attack-p0-2805', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects BusyBox or Ash shell execution from unauthorized logins or remote connections. Focus is on rare shell invocations from DCUI, SSH sessions, or remote management paths. Also watches for payload droppers or persistence artifacts using shell.", "external_references": [{"external_id": "AN1083", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0384#AN1083"}], "id": "x-mitre-analytic--52f4a572-0d43-4684-9598-6bc8cf2bffb1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1083", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DCUI shell start, BusyBox activity", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Shell login or escalation", "name": "esxi:auth", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-root use of shell (or root outside maintenance window).", "field": "UserContext"}, {"description": "Use of ‘nc’, ‘wget’, or dropper-like behavior in shell.", "field": "CommandPattern"}, {"description": "Unexpected invocation of BusyBox/ash from mounted ISO or datastore.", "field": "ShellPath"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2805', 0, 130, '09-mitre-attack', 'retrieved', 'C4D794217D128A3D33FFE3A790A48304577E50D17B65B525E9A4AB42C045D438', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
