VALUES ('doc-09-mitre-attack-p0-2806', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary mounts external drive to /media or /mnt then accesses or copies targeted data via shell, cp, or tar.", "external_references": [{"external_id": "AN1411", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0511#AN1411"}], "id": "x-mitre-analytic--5312ddd0-dd58-4bcb-afc0-7a05a6b2df42", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1411", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read, mount", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "udisks2 or udevd logs", "name": "journald:systemd", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for unexpected or user-defined mount locations (e.g., /media/usb*)", "field": "MountPathRegex"}, {"description": "Tune based on read/write access types seen during collection", "field": "AccessMask"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2806', 0, 105, '09-mitre-attack', 'retrieved', '839935EA9F39840BF1D8B3969EF80125914822D9CA663A4075ABE1FB0372F1E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
