VALUES ('doc-09-mitre-attack-p0-2807', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Launchd jobs or user processes invoking symmetric crypto APIs from the Security framework and generating outbound connections carrying randomized payloads inconsistent with normal TLS patterns.", "external_references": [{"external_id": "AN0402", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0143#AN0402"}], "id": "x-mitre-analytic--531ba452-e3b8-4064-be28-31ddd13b3478", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0402", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process using AES/RC4 routines unexpectedly", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Encrypted connection with anomalous payload entropy", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate DNS-over-HTTPS endpoints to avoid FP.", "field": "DoHResolvers"}, {"description": "Define entropy level at which traffic should be flagged.", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2807', 0, 106, '09-mitre-attack', 'retrieved', '1D275E7729D5581B63AA007182362EE6AC58A8BB3F66BD9FAFEB44FB8FECCA92', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
