VALUES ('doc-09-mitre-attack-p0-2808', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Series of failed logins from loginwindow or sshd with repeated usernames or password prompts", "external_references": [{"external_id": "AN1523", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0551#AN1523"}], "id": "x-mitre-analytic--53336c8f-a218-462a-b97c-aac07cf96077", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1523", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authd", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Local console vs. SSH vs. remote Apple Admin tools", "field": "AuthMechanism"}, {"description": "Use regex to isolate brute force messages among other log noise", "field": "FailurePattern"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2808', 0, 85, '09-mitre-attack', 'retrieved', 'ED05043CB27B508443BC5228AE082591D7CEF9ED864CE31EAE8BF5EAFA323A19', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
