VALUES ('doc-09-mitre-attack-p0-2809', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of ''esxcli system'' or direct interpreter commands (e.g., busybox shell) invoked from SSH or host terminal unexpectedly.", "external_references": [{"external_id": "AN1431", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0516#AN1431"}], "id": "x-mitre-analytic--533d13df-5317-45dd-a544-c26d0192d6b2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1431", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "shell session start", "name": "esxi:vobd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Control alerting based on whether ESXi shell access is typically disabled.", "field": "ShellEnabledFlag"}, {"description": "Scope detection to SSH session origins or internal vs. remote access.", "field": "SSHContext"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2809', 0, 94, '09-mitre-attack', 'retrieved', '5ACD6CAB8A82439F59FECCCEF1C8AC96095FF99D63CCD6FD0304BD0CE49CB940', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
