VALUES ('doc-09-mitre-attack-p0-2810', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications or scripts invoking cloud storage APIs (Dropbox sync, iCloud, Google Drive client) in unexpected contexts. Defender perspective: detect sensitive file reads by non-standard applications followed by unusual encrypted uploads to external cloud storage domains.", "external_references": [{"external_id": "AN1573", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0570#AN1573"}], "id": "x-mitre-analytic--535e9bc8-b033-4aee-88e1-bd48699b7856", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1573", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of curl, rclone, or Office apps invoking network sessions", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file read of sensitive directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "outbound HTTPS connections to cloud storage APIs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track processes that normally should not upload data (e.g., Preview, Calculator).", "field": "WatchedApps"}, {"description": "High-entropy file uploads may indicate encrypted payloads designed for exfiltration.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2810', 0, 138, '09-mitre-attack', 'retrieved', '5751F00B459550F6371D589FCD561096740964CD5E06A09926BB7B1D4F752384', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
