VALUES ('doc-09-mitre-attack-p0-2811', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of utilities (dd, hdparm, sgdisk) or custom binaries attempting to overwrite disk boot structures (/dev/sda MBR sector or partition tables). Detection correlates shell execution with syscalls writing to sector 0 or disk metadata blocks.", "external_references": [{"external_id": "AN0828", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0297#AN0828"}], "id": "x-mitre-analytic--538707d4-df45-489b-97f5-0115802a701f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0828", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write syscalls to /dev/sd* targeting offset 0", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"channel": "Execution of dd/sgdisk with arguments writing to sector 0 or partition table", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define specific device paths to monitor (e.g., /dev/sda, /dev/nvme0n1).", "field": "TargetDevices"}, {"description": "Focus on suspicious writes at disk offsets corresponding to MBR/partition structures.", "field": "OffsetThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2811', 0, 129, '09-mitre-attack', 'retrieved', 'D2CD28D0D75C5473049685F7F3EED6C5716A1964575793ACEFC2DC6E0430A1F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
