INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2812', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries leverage M365 or Google Workspace APIs to create users, service accounts, or guest accounts. Follow-on behaviors include login activity, role escalation, or service principal token generation.", "external_references": [{"external_id": "AN0902", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0319#AN0902"}], "id": "x-mitre-analytic--53872bd3-7e5e-4573-ae07-6304bf7e49af", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0902", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add user", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "Add member to group", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--05d5b5b4-ef93-4807-b05f-33d8c5a35bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Only alert on additions to high-value groups (e.g., Domain Admins)", "field": "GroupSensitivity"}, {"description": "Tune alerts based on guest vs internal user creation", "field": "GuestFlag"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2812', 0, 108, '09-mitre-attack', 'retrieved', 'AE22434E41D82FA873B3E2EB93375FB891E959D35C80A30E0CC60BF2A6C90469', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
