VALUES ('doc-09-mitre-attack-p0-2814', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Initial process using NSURLSession or similar APIs reaches out to known staging domains, followed by creation of a reverse shell or RAT connecting to a second unrelated server.", "external_references": [{"external_id": "AN0639", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0228#AN0639"}], "id": "x-mitre-analytic--53ba6028-13cd-449e-aab4-d2f9fea458a4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0639", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "tcp/udp", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect activity outside normal user behavior (e.g., automation or daemon context)", "field": "UserContext"}, {"description": "Optional for detecting encoded payloads delivered via stage 1", "field": "EntropyScore"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2814', 0, 105, '09-mitre-attack', 'retrieved', '30BC2F5D2F4DA61CD6AB91F19E461CF6BDF995EAB7CABD1BDA75327DF90AE84D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
