INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2815', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates Group Policy updates that configure network logon scripts with subsequent remote file execution behaviors triggered by user logons to identify potential persistence or execution chains tied to adversarial manipulation of logon scripts.", "external_references": [{"external_id": "AN1034", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0367#AN1034"}], "id": "x-mitre-analytic--53dd199d-4f38-4f12-83dd-f2d471d58a1b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1034", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5145", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4016, 5312", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to network-based script execution; tuning required for environment-specific network shares.", "field": "TargetObject"}, {"description": "Initial execution process that launches the script; may vary depending on script language or user context.", "field": "ParentProcessName"}, {"description": "Acceptable time window to correlate Group Policy update with script execution (e.g., 2–10 minutes).", "field": "TimeWindow"}, {"description": "Account initiating execution; useful for filtering known administrative activity.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2815', 0, 153, '09-mitre-attack', 'retrieved', 'F2C8323A6D0E065387EC4DBCB4146E38087DE8C66D0F4902C7A3C135BE9FE776', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
