VALUES ('doc-09-mitre-attack-p0-2816', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects memory-based injection by monitoring `task_for_pid`, `mach_vm_write`, and dylib injection patterns through `DYLD_INSERT_LIBRARIES` or manual memory mapping.", "external_references": [{"external_id": "AN1401", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0508#AN1401"}], "id": "x-mitre-analytic--5439d083-91d6-4369-9406-8cfb2cf5cbde", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1401", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.security, library=libsystem_kernel.dylib", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC, ES_EVENT_TYPE_NOTIFY_MMAP", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "DYLD_INSERT_LIBRARIES anomalies", "name": "macos:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected signing identity or origin of process being injected", "field": "TargetProcessSignature"}, {"description": "Observed syscall combinations (e.g., task_for_pid followed by vm_write)", "field": "MachSyscallContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2816', 0, 100, '09-mitre-attack', 'retrieved', '07ED513CC74AE568B