VALUES ('doc-09-mitre-attack-p0-2817', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual or excessive database/table exports from SaaS database platforms (e.g., Snowflake, Firebase, BigQuery, Airtable) by users or apps not in known analytics or dev groups. Defender observes access patterns outside baseline working hours or with new query templates, and correlates those with audit logs or file downloads.", "external_references": [{"external_id": "AN0680", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0242#AN0680"}], "id": "x-mitre-analytic--544c832f-4849-4fb7-a851-5f69ec0692a9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0680", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "QUERY: Large or repeated SELECT * queries to sensitive tables", "name": "saas:Snowflake", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Bulk downloads or API extractions from Microsoft-hosted data repositories (e.g., Dynamics 365)", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Query hash or shape for common BI/ETL jobs to reduce false positives", "field": "BaselineQueryTemplates"}, {"description": "Window to define after-hours activity thresholds for DB access", "field": "OffHoursAccessWindow"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2817', 0, 145, '09-mitre-attack', 'retrieved', 'B312E231A315DB57F11E68AE25F8E3C5BC6B75B1EE0E476C326B11A5B5D129DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
