VALUES ('doc-09-mitre-attack-p0-2818', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors API calls and service-specific logs for enumeration of organizational roles, permissions, and group structure, particularly outside of normal admin behavior baselines.", "external_references": [{"external_id": "AN0697", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0251#AN0697"}], "id": "x-mitre-analytic--54ae99be-c089-4e96-97f5-52af2892ae25", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0697", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GET /services/data/vXX.X/groups", "name": "saas:salesforce", "x_mitre_data_component_ref": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope to cross-team access or unfamiliar org enumeration.", "field": "OrgScope"}, {"description": "Tuning for excessive group-list API calls.", "field": "RequestRate"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2818', 0, 88, '09-mitre-attack', 'retrieved', 'A1AD186270FD322569E5474423F00F120427719015F39E512597DA03826DCE82', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
