VALUES ('doc-09-mitre-attack-p0-2819', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T16:43:32.659Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects users executing commands copied from chats, tickets, or emails, including curl|bash patterns, shell script launches from temp directories, credential changes, or SSH key additions shortly after communication events.", "external_references": [{"external_id": "AN2037", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0899#AN2037"}], "id": "x-mitre-analytic--54bb8256-cbe8-4088-9cff-b03711bd7841", "modified": "2026-05-12T16:30:18.378Z", "name": "Analytic 2037", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Outbound connection after script or installer launch", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "execve of curl,wget,bash,sh,python with piped or remote content", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "odification of ~/.ssh/authorized_keys or credential files", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organization-specific admin automation patterns to exclude", "field": "RemoteScriptExecutionPatterns"}, {"description": "Time from help desk/chat event to command execution", "field": "TicketToExecutionWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2819', 0, 126, '09-mitre-attack', 'retrieved', 'C20C55A1D7741A0A04B1285DAC890CC69C92E050E13720D6D58685A763B1C6D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
