VALUES ('doc-09-mitre-attack-p0-2823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects sequential command-line compression utilities (e.g., gzip, tar, zip, 7z) followed by execution of unpacked files, especially in temp directories or under non-standard locations like /dev/shm or /tmp with ELF binaries.", "external_references": [{"external_id": "AN0783", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0281#AN0783"}], "id": "x-mitre-analytic--55083ce8-b00e-4501-97db-829082bdbb48", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0783", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "openat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "chmod", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag compressed archives extracted to /tmp, /dev/shm, or user’s home dir", "field": "PathRegex"}, {"description": "gzip, tar, bzip2, xz, 7z – tune to suppress admin packaging workflows", "field": "CompressionToolPatterns"}, {"description": "How soon a new file is executed after it’s unpacked", "field": "ExecutionAfterUnpackWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2823', 0, 136, '09-mitre-attack', 'retrieved', '248BAF1C8F6A4CDCDB35BA7F6F4149E690EF40CD978C84B991EB804765CCD820', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
