VALUES ('doc-09-mitre-attack-p0-2824', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abnormal creation of binary files with significant size that are subsequently executed or accessed by non-standard users.", "external_references": [{"external_id": "AN1529", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0553#AN1529"}], "id": "x-mitre-analytic--5523b4ab-42b1-480a-854b-819879905f8d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1529", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how large a file must be to consider it padded", "field": "FileSizeThresholdMB"}, {"description": "Target abnormal user behavior outside of expected automation", "field": "UserContext"}, {"description": "Time window for correlating file creation and execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2824', 0, 111, '09-mitre-attack', 'retrieved', '7D072225A22D2ECA6D34414097FF64FFA3B3FBD05C734D0E784D5F26C2C857B7', 'v1', '{"source_id": "09-mitre-attack", "vers