VALUES ('doc-09-mitre-attack-p0-2825', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Userland processes invoking syscall-heavy libraries (libc, glibc) followed by fork, mmap, or ptrace behavior commonly associated with code injection or memory manipulation.", "external_references": [{"external_id": "AN1466", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0529#AN1466"}], "id": "x-mitre-analytic--552ff82d-467b-4aeb-a4c3-084ca24dbd3e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1466", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve, fork, mmap, ptrace", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "module load or memory map path", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for fork, mmap, ptrace based on context", "field": "SyscallType"}, {"description": "Whitelist known daemon and scheduled task patterns", "field": "ProcessName"}, {"description": "Tune suspicious memory map regions (e.g., /tmp/.evilshmem)", "field": "MAPS Path"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2825', 0, 113, '09-mitre-attack', 'retrieved', '6D53405687EEE7B268776F2E7979124780EB269AA0F384519D1F62D583DF3F18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DA