VALUES ('doc-09-mitre-attack-p0-2826', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Scripted or binary usage of X11 utilities (e.g., xdotool, wmctrl) or direct /proc/*/window mappings to discover open GUI windows and active desktops.", "external_references": [{"external_id": "AN0272", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0097#AN0272"}], "id": "x-mitre-analytic--557d1a5d-31ae-4600-b4ed-a456d9964a83", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0272", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "None", "name": "linus:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common window management utilities can be tuned to reduce noise (e.g., xprop, xwininfo).", "field": "ExecutableName"}, {"description": "Restrict detection to processes executing under graphical sessions (e.g., DISPLAY=:0).", "field": "DisplayContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2826', 0, 102, '09-mitre-attack', 'retrieved', 'D5E973C2518D24DC7B535FDD89E02A9ECDA05C2B3E11EC89704E18B7417F16ED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
