VALUES ('doc-09-mitre-attack-p0-2827', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects behavior where files with non-executable or misleading extensions (e.g., .jpg, .txt) are created or modified but subsequently executed as binaries based on internal file headers or abnormal parent process lineage. This includes identifying polyglot files or malformed magic bytes indicative of masquerading attempts.", "external_references": [{"external_id": "AN0630", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0226#AN0630"}], "id": "x-mitre-analytic--557e1f6e-5eeb-46ea-bcd2-5d858eea314c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0630", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of non-executable file types commonly used to mask payloads (.jpg, .txt, .gif)", "field": "benign_extensions"}, {"description": "Targeted directories for initial access and downloads (e.g., %TEMP%, Downloads, AppData)", "field": "monitored_directories"}, {"description": "Detection tolerance for mismatches between extension and file signature (magic bytes)", "field": "MagicByteMismatchThreshold"}, {"description": "Time range between file creation and first execution", "field": "TimeWindow"}, {"description": "Anomaly score threshold for suspicious parent-child process combinations", "field": "ParentProcessAnomalyScore"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2827', 0, 161, '09-mitre-attack', 'retrieved', '58F0288CD0820FF79A1BDC48268153D0F9F7D3B78CB21999375C238E33FF5E7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
