VALUES ('doc-09-mitre-attack-p0-2828', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of discovery commands or API calls for virtualization artifacts (e.g., registry keys, device drivers, services), sleep/skipped execution behavior, or sandbox evasion DLLs before payload deployment.", "external_references": [{"external_id": "AN0127", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0046#AN0127"}], "id": "x-mitre-analytic--55808d73-7aa9-4f2c-8122-8e60bf14f4c6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0127", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time range in which multiple discovery processes or sleep/delay operations are executed to avoid sandbox detonation.", "field": "TimeWindow"}, {"description": "Registry paths, DLLs, services or device names indicative of sandbox/VM environments.", "field": "KnownVMArtifactList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2828', 0, 110, '09-mitre-attack', 'retrieved', 'B74A3A8F9932D55878AD1D1D26756C3223BE9D718FDC450E9567DC95FE54C425', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
