VALUES ('doc-09-mitre-attack-p0-2829', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of `erase`, `format`, and `reload` in immediate sequence from a privileged AAA session", "external_references": [{"external_id": "AN0936", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0329#AN0936"}], "id": "x-mitre-analytic--55a0743e-cdc1-44d1-94c7-cf3837e3ef2f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0936", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command sequence: erase → format → reload", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time between erase and reload command to establish causality", "field": "CommandSequenceWindow"}, {"description": "Filter for high-privilege user sessions", "field": "UserPrivilegeLevel"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2829', 0, 86, '09-mitre-attack', 'retrieved', '06D9AFAE93DBDC16001290EAE6CEE1FE90702BCE6E970E08C5DEAF5E9F81349D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
