VALUES ('doc-09-mitre-attack-p0-2830', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of ESXi web interface plugins or vSphere extensions to embed persistent malicious scripts or services.", "external_references": [{"external_id": "AN1510", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0547#AN1510"}], "id": "x-mitre-analytic--55b8622a-795b-41d8-9b11-5576a0fb8f0f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1510", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New extension/module install with unknown vendor ID", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unexpected restarts of management agents or shell access", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist known vendor plug-in names for extension correlation", "field": "PluginVendorName"}, {"description": "Limit exposure of plugin installation via HTTPS or SSH", "field": "AccessVector"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2830', 0, 103, '09-mitre-attack', 'retrieved', '492BCF698A146F2957CCBC7FCBAF8F6691137C7D8087CD3F44356DDC25D51143', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
