VALUES ('doc-09-mitre-attack-p0-2831', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).", "external_references": [{"external_id": "AN0158", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0058#AN0158"}], "id": "x-mitre-analytic--55ec66de-8146-4fd0-a423-0954d6ba33ef", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0158", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "TLS Handshake/Network Flow", "name": "etw:Microsoft-Windows-NDIS-PacketCapture", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "FQDN or IP for the hosting site of the dead drop (e.g., pastebin.com, twitter.com)", "field": "TargetDomain"}, {"description": "Defines how close in time the suspicious network and process behavior must occur", "field": "TimeWindow"}, {"description": "Filter by user or system accounts to reduce noise", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2831', 0, 126, '09-mitre-attack', 'retrieved', 'F2F53B3C92386784EBC33B5EF90F39BBB231FC040E524ED43E6C88E8695957F7', 'v1', '{"source_id": "09-mitre-attack", "versio