VALUES ('doc-09-mitre-attack-p0-2832', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Manual or script-based installation of extension-like modules into browser config directories or IDE plugin paths, followed by suspicious network activity", "external_references": [{"external_id": "AN0253", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0092#AN0253"}], "id": "x-mitre-analytic--560f859b-2174-4655-b927-b274ad0bda3f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0253", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "creat", "name": "fs:fileevents", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Abnormal browser traffic volume or destination", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common plugin or extension directories may vary by distro or browser (e.g., ~/.config/google-chrome/Default/Extensions)", "field": "DirectoryPath"}, {"description": "Path to scripting tools used in installation (e.g., bash, curl, unzip)", "field": "ExecPath"}, {"description": "Tunable interval between install and first network beacon", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2832', 0, 123, '09-mitre-attack', 'retrieved', '1E9341911EDCF62ED48E3C75A3BA0920F432E00A8E97A198FBCCD0551C1CE129', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
