VALUES ('doc-09-mitre-attack-p0-2833', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects file reads across locations followed by writes to temp or staging directories, often compressed or encrypted, indicating local staging behavior.", "external_references": [{"external_id": "AN0724", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0261#AN0724"}], "id": "x-mitre-analytic--561fb700-686a-4583-96a9-77a55358d357", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0724", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths such as C:\\Temp, C:\\Windows\\Tasks, etc.", "field": "StagingDirList"}, {"description": "Matches to 7z.exe, rar.exe, zip.exe, or custom scripts.", "field": "ArchivingToolPatterns"}, {"description": "How long to correlate file reads followed by compression.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2833', 0, 112, '09-mitre-attack', 'retrieved', '055FB2CF390B0DE443741594DED6913D136176D879E40405