VALUES ('doc-09-mitre-attack-p0-2834', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized changes to locally hosted login pages on macOS (common in developer VPN environments) and links file edits to cron jobs, background scripts, or SUID binaries.", "external_references": [{"external_id": "AN1322", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0480#AN1322"}], "id": "x-mitre-analytic--564071d9-44b1-44b8-92c0-348e22e544b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1322", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Filesystem Access Logging", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "subsystem=com.apple.WebKit", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify custom web service directories (e.g., /Library/WebServer/Documents/)", "field": "WebRootPath"}, {"description": "Alert on web root changes from non-web processes or scripts", "field": "AnomalousProcess"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2834', 0, 103, '09-mitre-attack', 'retrieved', 'B7056A3E31081724C827895C52F11245EEF20F22F9CFC922A7FA5BA370FAE8AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
