VALUES ('doc-09-mitre-attack-p0-2835', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process execution of curl or wget followed by a network connection and a file created in temporary or user-specific directories.", "external_references": [{"external_id": "AN0167", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0060#AN0167"}], "id": "x-mitre-analytic--56552a3e-9934-4809-97a4-67d62f29478c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0167", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file write/create", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "connection open", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict to high-risk directories like /Users/Shared, /tmp/", "field": "DirectoryTargeted"}, {"description": "May tune based on custom tooling or MDM activity", "field": "ProcessPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2835', 0, 101, '09-mitre-attack', 'retrieved', '9FCE2A540A2D32DBADC5EB950B56911A02311A9CCC12577B6177D8D62A56A7FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
