VALUES ('doc-09-mitre-attack-p0-2836', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for suspicious network traffic that could be indicative of scanning, such as large quantities originating from a single source (especially if the source is known to be associated with an adversary/botnet).", "external_references": [{"external_id": "AN2000", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0868#AN2000"}], "id": "x-mitre-analytic--56622fce-489a-4ed9-b1fb-e525939667d4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 2000", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "Network Traffic", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2836', 0, 77, '09-mitre-attack', 'retrieved', 'CFA2CCBD31F5453F97DB391F5D130FE5F630F9B2EC4F183D77B206222728A30F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
