INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2838', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of group enumeration using commands like ''id'', ''groups'', or ''getent group'', often followed by privilege escalation or SSH lateral movement.", "external_references": [{"external_id": "AN0508", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0179#AN0508"}], "id": "x-mitre-analytic--56a17328-c6b0-4e3d-9404-d4b8ba967a14", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0508", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Variations of enumeration commands tailored to different Linux distros (e.g., ''getent group'', ''cut -d'' in /etc/group parsing).", "field": "CommandLine"}, {"description": "TTY context or source terminal (remote shell vs local login) to reduce noise.", "field": "TTYSession"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2838', 0, 102, '09-mitre-attack', 'retrieved', 'CE7DD7E71BAC2AF73E4E0ABB779A78D89C66C013F6E2ED5BBAD2D6207BA302F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
