VALUES ('doc-09-mitre-attack-p0-2839', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects non-standard compilation activity via Xcode CLI tools or bundled GCC/MONO packages writing new executable files and executing them outside dev environments (e.g., user Downloads folder).", "external_references": [{"external_id": "AN1383", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0501#AN1383"}], "id": "x-mitre-analytic--56a814a9-2b6b-4fcc-a530-e9ca62faaa17", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1383", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process activity, exec events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "networkd or socket", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect calls to `xcodebuild`, `clang`, or `/Applications/Mono.app/...` from non-admin users", "field": "CompilerInvocationPattern"}, {"description": "Monitor for output files in user-writable paths (e.g., `~/Library/Caches`, `~/Downloads`)", "field": "OutputBinaryPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2839', 0, 114, '09-mitre-attack', 'retrieved', 'E4A4E446F6A0914B41AED9A0A766AFFCC0494CB856B3E8EF9DCB635385F35C7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
