VALUES ('doc-09-mitre-attack-p0-2840', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects access to known password store files (e.g., /etc/shadow, GNOME Keyring, KWallet, browser credential databases). Monitors anomalous process read attempts and suspicious API calls that attempt to extract stored credentials.", "external_references": [{"external_id": "AN1199", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0430#AN1199"}], "id": "x-mitre-analytic--571b10ce-fb7d-492e-b05a-23649ae14148", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1199", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths to password storage files (e.g., /etc/shadow, ~/.local/share/keyrings/)", "field": "MonitoredFiles"}, {"description": "Process or command-line keywords that indicate password extraction attempts", "field": "SuspiciousCommands"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2840', 0, 104, '09-mitre-attack', 'retrieved', '9FC9540771BEE5BFB2111AC487AC42DF81D235591CF5B6699E9ACCEABDF60E2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
