VALUES ('doc-09-mitre-attack-p0-2842', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal invocation of diskutil or asr that modifies partition tables or initializes raw devices. Monitor for IOKit system calls targeting disk headers or EFI boot sectors, correlated with elevated privileges.", "external_references": [{"external_id": "AN0829", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0297#AN0829"}], "id": "x-mitre-analytic--575a9c01-6dac-4513-86ca-e80b6e485212", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0829", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "diskutil partitionDisk or eraseVolume with partition scheme modifications", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "IOKit raw disk write to EFI/boot partition sectors", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "System provisioning workflows may legitimately re-partition disks; whitelist by context.", "field": "AdminToolWhitelist"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2842', 0, 108, '09-mitre-attack', 'retrieved', 'E7ED281DF1D385095A4189C4CB6469DB28B64663A78EB717249A1445F3DFB519', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
