VALUES ('doc-09-mitre-attack-p0-2843', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes executing binaries named after legitimate system utilities (e.g., net.exe, findstr.exe, python.exe) from non-standard or application-specific directories, combined with file creation or modification events for such binaries. Defender correlates file writes in vulnerable directories, process execution paths inconsistent with baseline system paths, and abnormal parent-child relationships in process lineage.", "external_references": [{"external_id": "AN1560", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0564#AN1560"}], "id": "x-mitre-analytic--578c821c-f8e3-45e7-a9b4-9aed6c84309a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1560", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common system utilities often hijacked (e.g., net.exe, cmd.exe, powershell.exe, python.exe).", "field": "SuspiciousBinaryList"}, {"description": "Directories where executables should not normally be written (e.g., application folders, user profile subdirs).", "field": "MonitoredDirectories"}, {"description": "Correlation window between file creation and subsequent process execution.", "field": "TimeWindow"}, {"description": "Expected parent processes for critical system binaries, deviations may indicate hijacking.", "field": "ParentProcessBaseline"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2843', 0, 162, '09-mitre-attack', 'retrieved', '3073FBFFA023541115012888D01B7E6DA259E77E22F6D723FC76865F82FAC8E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
