VALUES ('doc-09-mitre-attack-p0-2844', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CLI-based export of private key material (e.g., ''crypto pki export'') with anomalous user session or AAA role escalation.", "external_references": [{"external_id": "AN1519", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0549#AN1519"}], "id": "x-mitre-analytic--57a547e1-1086-427c-9ea8-59059dec1938", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1519", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Detected CLI command to export key material", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for export commands (e.g., crypto pki export, export ssh-key)", "field": "CLICommandMatch"}, {"description": "Source username or role performing export — may tune for known admins", "field": "AAAUserContext"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2844', 0, 98, '09-mitre-attack', 'retrieved', '015826E2F36DA1949A0BDEC87F22C19C2F7E2B58A7BE285CEEDF8A462136E2DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
