INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2845', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Encryption of cloud storage objects (e.g., S3 buckets) via Server-Side Encryption (SSE-C) or by replacing objects with encrypted variants. May include API patterns like PutObject with SSE-C headers.", "external_references": [{"external_id": "AN0606", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0215#AN0606"}], "id": "x-mitre-analytic--57d8fd27-9af5-4d01-9d1a-fdde8ec0c902", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0606", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PutObject (with SSE-C), UploadPart (SSE-C)", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "SSE-C headers indicate attacker-controlled encryption keys.", "field": "SSEHeader"}, {"description": "Prioritize logs, backups, or shared document storage buckets.", "field": "AffectedBucket"}, {"description": "Detect scripted automation vs console-based API behavior.", "field": "UserAgent"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2845', 0, 107, '09-mitre-attack', 'retrieved', '77388B846346C6079365CF3943AC4F3DE09ECB4139DB74F74B27206BDB4B6320', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
