INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2847', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary activity that removes persistence artifacts such as services, registry keys, scheduled tasks, user accounts, and binaries through commands like `sc delete`, `schtasks /delete`, or `reg delete`.", "external_references": [{"external_id": "AN0113", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0040#AN0113"}], "id": "x-mitre-analytic--5882d2ff-289e-454d-9146-81306c154be3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0113", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4726, 4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d6257b8e-869c-41c0-8731-fdca40858a91"}, {"channel": "EventCode=106", "name": "WinEventLog:TaskScheduler", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filters known persistence keys like Run/RunOnce, Image File Execution Options", "field": "TargetRegistryPathRegex"}, {"description": "Monitors known or suspicious task names deleted post-persistence", "field": "DeletedScheduledTaskName"}, {"description": "Focuses on highly privileged or recently created accounts", "field": "DeletedAccountGroupScope"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2847', 0, 127, '09-mitre-attack', 'retrieved', '29F1AA4035DABD709281A16A3821DC1B307E3BAA988637B6DA1053FC9D1EE111', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
