VALUES ('doc-09-mitre-attack-p0-2848', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi services (vmx, hostd) generating outbound HTTPS POST requests to text storage sites. Defender perspective: anomalous datastore or log reads chained with traffic to pastebin-like destinations.", "external_references": [{"external_id": "AN0790", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0284#AN0790"}], "id": "x-mitre-analytic--58a609cb-b266-4a1a-a40f-9e4cd5d591ce", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0790", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "datastore/log file access", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "HTTPS POST connections to pastebin-like domains", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold of bytes exfiltrated from ESXi datastore files.", "field": "DatastoreExfilThreshold"}, {"description": "Whitelist of domains approved for API communication to prevent false positives.", "field": "ApprovedDestinations"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2848', 0, 109, '09-mitre-attack', 'retrieved', '658E30753591501D5F40B2D488EB1859907F09A7763EED9E62A9169A5F2D3E70', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
