VALUES ('doc-09-mitre-attack-p0-2849', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized additions of users or machine accounts to privileged local or domain groups (e.g., Administrators, Remote Desktop Users).", "external_references": [{"external_id": "AN0865", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0310#AN0865"}], "id": "x-mitre-analytic--58bed5f5-6ef5-4558-9ac9-b58f8aa9888c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0865", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4728, 4729, 4732, 4733, 4756, 4757", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set to detect high-privileged groups like ''Administrators'', ''Domain Admins'', or ''Remote Desktop Users''", "field": "TargetGroup"}, {"description": "Restrict detections to business hours or approved maintenance windows", "field": "TimeWindow"}, {"description": "Filter out known automated processes or provisioning systems", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2849', 0, 108, '09-mitre-attack', 'retrieved', 'F1D89B19E19BB0B23448C7895C764B44B61341755B3E037C71DD41397546DC0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
