INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2850', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe adversary attempts to collect or export full device configurations by detecting unusual SNMP queries, Smart Install (SMI) activity, or CLI/API commands that request running or startup configuration dumps. Correlated behaviors include high-volume read requests for sensitive OIDs, repeated use of ''show running-config'' or equivalent commands from untrusted IPs, or unexpected TFTP/SCP/FTP transfers containing configuration files. These behaviors often appear in sequence: anomalous authentication or privilege escalation, followed by bulk configuration retrieval and outbound transfer.", "external_references": [{"external_id": "AN0647", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0233#AN0647"}], "id": "x-mitre-analytic--58e73108-657e-42ce-8dad-4edc968a2b20", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0647", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Failed and successful logins to network devices outside approved admin IP ranges", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "Execution of commands like ''show running-config'', ''copy running-config'', or ''export config''", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Outbound SCP, TFTP, or FTP sessions carrying configuration file content", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "GETBULK/GETNEXT requests for OIDs associated with configuration parameters", "name": "snmp:access", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known trusted IP addresses permitted to execute configuration dump commands.", "field": "AuthorizedAdminIPs"}, {"description": "Baseline frequency of legitimate configuration exports; anomalies above threshold may indicate malicious activity.", "field": "NormalConfigExportRate"}, {"description": "Expected transfer methods (e.g., SCP vs. TFTP). Unexpected use of weak protocols may indicate exfiltration.", "field": "AllowedTransferProtocols"}, {"description": "Normal maintenance windows for authorized configuration exports; activity outside these windows may be suspicious.", "field": "TimeWindow"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2850', 0, 242, '09-mitre-attack', 'retrieved', '29E86EB0A86895151C2856DBF4E6C68FB470E54B8DCB0F48EABB08E803E75E4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
