INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2851', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection centers on DYLD_INSERT_LIBRARIES and DYLD_LIBRARY_PATH abuse. Defender perspective: monitor for modification of these environment variables in shell or plist files, file creation of dylibs in user-controlled paths, and correlation of environment variable usage with unexpected module loads by user applications. Suspicious indicators include processes with DYLD_INSERT_LIBRARIES set, execution of applications loading untrusted dylibs, and anomalies in module load history.", "external_references": [{"external_id": "AN1210", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0435#AN1210"}], "id": "x-mitre-analytic--5907bfc2-a5d6-4ff1-bba8-8b94c9835ed6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1210", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of process with DYLD_INSERT_LIBRARIES set", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "create/modify dylib in monitored directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "loading of unexpected dylibs compared to historical baselines", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "macOS linker variables like DYLD_INSERT_LIBRARIES. Tunable to development environments where use may be expected.", "field": "WatchedEnvVars"}, {"description": "Known dylibs typically loaded by apps. Deviations highlight potential hijacking.", "field": "BaselineDylibs"}, {"description": "Locations where dylibs are monitored for tampering (e.g., /Applications, /System/Library, /tmp).", "field": "MonitoredDirectories"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2851', 0, 177, '09-mitre-attack', 'retrieved', 'CC1158361F112FBECFA8B9B3905ACDEBB06DB3F71D4B20FD3C086823B6F6AD1F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
