INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2852', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Python execution from non-standard user contexts or cron jobs that invoke outbound traffic, access sensitive files, or perform process injection (e.g., ptrace or /proc memory maps).", "external_references": [{"external_id": "AN0174", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0063#AN0174"}], "id": "x-mitre-analytic--59354e08-ed82-4b95-99c5-aed3996473e1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0174", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/syslog", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Script invoked from /tmp, /var/tmp, or .hidden/ folders.", "field": "ScriptDir"}, {"description": "Execution from user cron or systemd timers outside of approved scripts.", "field": "ScheduledContext"}, {"description": "Python performing HTTP/HTTPS without package updates.", "field": "NetworkActivity"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2852', 0, 112, '09-mitre-attack', 'retrieved', 'F826472514810E1B6BD7A0466B8701E01C7ACDA9D1F94414C31767C23FCAB11D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
