VALUES ('doc-09-mitre-attack-p0-2853', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Scripting engines (e.g., osascript, Python) initiating HTTPS requests to social media or content-sharing platforms, paired with automated response handling indicative of two-way communication.", "external_references": [{"external_id": "AN0102", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0035#AN0102"}], "id": "x-mitre-analytic--5935bda3-8d4d-44b4-aca4-8b40cf45f686", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0102", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --info --predicate ''subsystem == \"com.apple.cfprefsd\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "web domain alerts", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scripting interpreters to monitor for unusual HTTP traffic (e.g., osascript, ruby, bash)", "field": "ScriptEngineList"}, {"description": "Patterns or domains used for C2 dead drops and responses (e.g., pastebin.com, twitter.com)", "field": "SocialMediaDomainPatterns"}, {"description": "Threshold for number of short-lived HTTPS connections in a short window", "field": "BurstConnectionRate"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2853', 0, 127, '09-mitre-attack', 'retrieved', '7F70E3D302933BB7E60AA19882502E7A1383FEBBE5492A2B5149D4B794C6B903', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
