VALUES ('doc-09-mitre-attack-p0-2854', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution of common process enumeration utilities (e.g., ps, top, htop) or access to /proc with suspicious ancestry. Correlates command usage with interactive shell context and user role.", "external_references": [{"external_id": "AN0096", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0034#AN0096"}], "id": "x-mitre-analytic--59aedd87-8373-45d3-93e3-5697e4cc7a48", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0096", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "openat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Process State", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter based on suspicious /proc directory enumeration or high-volume ls/readlink usage", "field": "AccessedPath"}, {"description": "Helps tune for root vs. low-priv users during interactive vs. scripted activity", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2854', 0, 115, '09-mitre-attack', 'retrieved', '91DDF289E402144F4F1446C7B260B21EE30091FDD1E87764FC7940E6584CACB9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
