VALUES ('doc-09-mitre-attack-p0-2855', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Startup-based persistence mechanisms within Microsoft Office Suite like template macros and home page redirects being configured through internal automation or client-side settings.", "external_references": [{"external_id": "AN1117", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0398#AN1117"}], "id": "x-mitre-analytic--59bfb473-611f-4443-9d11-f44e7ace93fb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1117", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set-Mailbox, Set-InboxRule, Set-MailboxFolderPermission", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "Outlook rule creation or custom form deployment", "name": "m365:mailboxaudit", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify rule actions that execute scripts, forward emails externally, or start external content", "field": "RuleAction"}, {"description": "Focus on users with sensitive roles or shared mailboxes", "field": "MailboxTarget"}, {"description": "Detect persistence artifacts created shortly after credential access or login from an unusual location", "field": "TimeWindow"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2855', 0, 127, '09-mitre-attack', 'retrieved', '099CDC48D33CD3A6A3A8C4FF02CBAAADB871F8C3102DB3DCD6508BFF0C97ECC8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
