VALUES ('doc-09-mitre-attack-p0-2856', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected write operations to BIOS/UEFI firmware regions or EFI boot partitions that do not correlate with legitimate vendor firmware updates. API calls or utilities such as fwupdate.exe or vendor flash tools executed from non-administrative or non-IT management accounts. Suspicious raw disk writes targeting System Firmware GUID partitions followed by abnormal reboot sequences.", "external_references": [{"external_id": "AN0275", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0099#AN0275"}], "id": "x-mitre-analytic--59d44906-a35e-4b0f-ab84-df3bfa6df8f9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0275", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=9", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate vendor tools permitted to perform firmware flashing or BIOS updates.", "field": "AllowedFirmwareUpdateTools"}, {"description": "Expected time periods for approved firmware updates, used for correlating suspicious activity outside patch cycles.", "field": "TimeWindow"}, {"description": "Baseline hashes of vendor BIOS/UEFI firmware for integrity comparison.", "field": "KnownGoodFirmwareHashes"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2856', 0, 153, '09-mitre-attack', 'retrieved', 'AC6ADE7878CBA068D76146D1169140298E60FAF379F263C8206F7E5AFBE9718E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
