VALUES ('doc-09-mitre-attack-p0-2857', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Command-line tools (e.g., curl, rsync, wget, or custom Python scripts) used to scrape documentation systems or internal REST APIs. Unusual access patterns to knowledge base folders or shared team drives.", "external_references": [{"external_id": "AN1161", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0413#AN1161"}], "id": "x-mitre-analytic--59faf79f-831d-436b-9ce3-e5c1d338da6c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1161", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of curl, rsync, wget with internal knowledge base or IPs", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=3, 22", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex matching internal doc servers, knowledge base paths, or IP patterns.", "field": "CommandRegex"}, {"description": "Burst access of repositories over a short time window.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2857', 0, 118, '09-mitre-attack', 'retrieved', '7D5E2DD352D985CF61878B727928D9FBD41663DDCF7697C423DDFE30BC4E5353', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
