VALUES ('doc-09-mitre-attack-p0-2858', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "AppleScript or system calls to activate WiFi/Bluetooth interfaces (`networksetup`, `blueutil`), followed by exfiltration via AirDrop, cloud sync, or network socket.", "external_references": [{"external_id": "AN0214", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0077#AN0214"}], "id": "x-mitre-analytic--5a05483c-fb3b-4240-bf90-c1873b6bd392", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0214", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "interface_details ", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Protocol used for exfil (e.g., AirDrop, mDNS, Apple File Service).", "field": "Protocol"}, {"description": "Time period between interface activation and transfer.", "field": "InterfaceActivityWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2858', 0, 101, '09-mitre-attack', 'retrieved', 'E97CA69F57C62AD1A261B7C411A4A25B6BE30A10DFEB3060B2B10D7DEF2C4D09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1"