VALUES ('doc-09-mitre-attack-p0-2859', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unusual outbound connections to web services from uncommon processes using SSL/TLS, particularly those exhibiting high outbound data volume or persistence.", "external_references": [{"external_id": "AN1189", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0425#AN1189"}], "id": "x-mitre-analytic--5a10a19a-035e-469e-8ec5-fafb1f0f0fe6", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1189", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "SSL/TLS Inspection or PCAP", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "To tune for unexpected or uncommon executables initiating network connections", "field": "ProcessName"}, {"description": "Volume of outbound data in short time window (e.g., >1MB in <5 min)", "field": "DataTransferThreshold"}, {"description": "Look for connections persisting outside of normal business hours", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2859', 0, 117, '09-mitre-attack', 'retrieved', 'D6FB060E30D1FE69FAD9522588AFA092529DDBBB4654B8704740D27F9BD61A46', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1"