VALUES ('doc-09-mitre-attack-p0-2860', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes accessing LSASS memory or SAM registry hives outside of trusted security tools, often followed by file creation or lateral movement. Detects unauthorized access to sensitive OS subsystems for credential extraction.", "external_references": [{"external_id": "AN0648", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0234#AN0648"}], "id": "x-mitre-analytic--5a5d5ff5-e2bb-4ba9-9f95-504c86b1a1cf", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0648", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=4662", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set to detect full access rights (0x1F0FFF) or modify based on tool behavior.", "field": "AccessMask"}, {"description": "Define how soon access to LSASS is followed by suspicious file or registry activity.", "field": "TimeWindow"}, {"description": "Allowlist known security tools or system processes accessing LSASS.", "field": "ParentProcessFilter"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2860', 0, 141, '09-mitre-attack', 'retrieved', 'AD0C09A3CDCB42994F396EA1EC14C44EF13C64A1D8204AB5A8F0D8CF212D219C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
