INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2861', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use ESXi syslogs to track abnormal DNS query patterns from management agents or VMs. Identify high-frequency, low-TTL, or unresolvable domains as suspicious. Correlate with unusual management plane process activity.", "external_references": [{"external_id": "AN1181", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0419#AN1181"}], "id": "x-mitre-analytic--5a652a8f-a8e1-4010-bc2b-2ffaa2838333", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1181", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Frequent DNS queries with high entropy names or NXDOMAIN results", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected resolver settings for ESXi hosts", "field": "ResolverConfigPaths"}, {"description": "Trusted external domains for hypervisor operations", "field": "DomainWhitelist"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2861', 0, 101, '09-mitre-attack', 'retrieved', 'C446F9AB71CF9477AA0E3615EBB4C73F7715AB83E9813AE3EFA2B89E8485A279', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
