INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2862', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of native/mac tools (sharing -l, smbutil view, mount_smbfs) or scripts to enumerate SMB shares across many hosts, followed by outbound SMB connections observed in PF/Zeek logs.", "external_references": [{"external_id": "AN0515", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0182#AN0515"}], "id": "x-mitre-analytic--5a9238a9-acd0-44f0-bd41-f86ef433775b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0515", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC: Process execution of \"sharing -l\", \"smbutil view\", \"mount_smbfs\"", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Command line contains smbutil view //, mount_smbfs //", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Outbound connections to 139/445 to multiple destinations", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "connection: SMB connections to multiple internal hosts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum unique SMB destinations (e.g., ≥3–5 in smaller mac fleets).", "field": "BurstHostThreshold"}, {"description": "Correlation window between exec and SMB connections (default 10m).", "field": "TimeWindow"}, {"description": "Jamf/IT scripts legitimately running smbutil/mount_smbfs.", "field": "AllowedMgmtTools"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2862', 0, 150, '09-mitre-attack', 'retrieved', 'C855EF442E67D58E61CE0F188B4DAF5780880D32C034CBC9325EB197389201C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
