VALUES ('doc-09-mitre-attack-p0-2863', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Bash, Swift, or Objective-C programs enumerate system profile, I/O registry, or inspect kernel extensions to identify VM artifacts", "external_references": [{"external_id": "AN0480", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0168#AN0480"}], "id": "x-mitre-analytic--5a92bf3c-1832-453b-8ac9-24f8688d6faf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0480", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec or spawn of ''system_profiler'', ''ioreg'', ''kextstat'', ''sysctl'', or calls to sysctl API", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold of sequential system checks or tools used in a short time", "field": "ExecutionBurst"}, {"description": "Specific tools used for querying device and system metadata", "field": "ToolName"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2863', 0, 102, '09-mitre-attack', 'retrieved', 'A0F1186E48BF56715C7A5CA88F6A8557625DBAAA218E1379AA7B03CBE9F5FA48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
