VALUES ('doc-09-mitre-attack-p0-2864', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of `systemd` service units or cron jobs using deceptive naming and untrusted command paths, often followed by lateral network activity or privilege escalation.", "external_references": [{"external_id": "AN0325", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0117#AN0325"}], "id": "x-mitre-analytic--5a9c1860-23ae-455e-bcab-0e0f91af5548", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0325", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/audit/audit.log", "name": "auditd:CONFIG_CHANGE", "x_mitre_data_component_ref": "x-mitre-data-component--faa34cf6-cf32-4dc9-bd6a-8f7a606ff65b"}, {"channel": "scheduled/real-time", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "cron activity", "name": "linux:cron", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unusual or user-space paths for systemd unit files", "field": "UnitFilePath"}, {"description": "Detect units with names similar to legitimate ones (e.g., `networks.service` instead of `network.service`)", "field": "ServiceNameDeviation"}, {"description": "Track uncommon or suspicious binaries in `ExecStart=` directives", "field": "ExecStartPath"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2864', 0, 122, '09-mitre-attack', 'retrieved', '1E0DA8D688132E1BC254163A8585508A4AC5D53B4F9815E47A13E288A7B86DC4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
