VALUES ('doc-09-mitre-attack-p0-2865', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual or unauthorized processes accessing microphone APIs (e.g., winmm.dll, avrt.dll) followed by audio file writes to user-accessible or temp directories.", "external_references": [{"external_id": "AN0619", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0221#AN0619"}], "id": "x-mitre-analytic--5aaad268-48fb-4826-9f68-b666e1b4a3bf", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0619", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time span in which the process accesses audio APIs and writes files, to reduce false positives.", "field": "TimeWindow"}, {"description": "Set of approved processes known to legitimately use microphone (e.g., Zoom, Teams).", "field": "TargetProcess"}, {"description": "Allowlist of paths where legitimate apps store audio (e.g., user media folders).", "field": "WriteDirectory"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2865', 0, 12