VALUES ('doc-09-mitre-attack-p0-2866', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "sshd, socat, or custom binaries initiating port forwarding or encapsulating traffic (e.g., RDP, SMB) through SSH or HTTP. Defender sees abnormal connect/bind syscalls, encrypted traffic on ports typically used for non-encrypted services, and outlier traffic volume patterns.", "external_references": [{"external_id": "AN1484", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0538#AN1484"}], "id": "x-mitre-analytic--5acd81f3-466a-472d-bb1f-9bda231ac4c0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1484", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket/connect calls showing SSH processes forwarding arbitrary ports", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "sshd sessions with unusual port forwarding parameters", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "socat, ssh, or nc processes opening unexpected ports", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific sshd config flags indicating port forwarding.", "field": "ForwardingFlags"}, {"description": "Define expected application protocols by port to catch tunneling mismatches.", "field": "ProtocolBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2866', 0, 137, '09-mitre-attack', 'retrieved', 'D7E34CEB443C1B0E00394C97DF7C0D4915F67761457FD8D79AE2919A4CCF2EF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
