VALUES ('doc-09-mitre-attack-p0-2867', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Direct write access to /dev/mem or /sys/firmware combined with usage of firmware flashing utilities (e.g., flashrom).", "external_references": [{"external_id": "AN0475", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0167#AN0475"}], "id": "x-mitre-analytic--5b1514b3-e35b-4ea8-bcc1-b8e492d6d3cd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0475", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write access to /dev/mem or /sys/firmware/efi/efivars", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"channel": "execution of known flash tools (e.g., flashrom, fwupd)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom or renamed firmware tools may require pattern matching", "field": "ToolName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2867', 0, 91, '09-mitre-attack', 'retrieved', '8C749463797A1261E083325B3CF80F8E449D93054F6901AFCC2D014BA2185579', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
