VALUES ('doc-09-mitre-attack-p0-2868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of queries to instance metadata services (e.g., AWS IMDS, Azure Metadata Service) for availability zone, region, or network geolocation details. Correlation with non-management accounts or non-standard workloads may indicate adversary reconnaissance.", "external_references": [{"external_id": "AN0122", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0043#AN0122"}], "id": "x-mitre-analytic--5b41efa6-7410-403b-ac07-89e262fa17ca", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0122", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetMetadata, DescribeInstanceIdentity", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "HTTP requests to 169.254.169.254 or Azure Metadata endpoints", "name": "azure:vpcflow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected services that query cloud metadata APIs. Any additional sources may be malicious.", "field": "MetadataQueryAllowList"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2868', 0, 107, '09-mitre-attack', 'retrieved', '0B00FB0781DF25711058941BEE79E3348F5CCEF5F7654BF434C671B7BBCFF974', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
