VALUES ('doc-09-mitre-attack-p0-2870', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of `rfkill`, `nmcli`, or low-level tools (e.g., `iw`, `hcitool`, `pppd`) to enable alternate interfaces followed by data transfer via non-primary NICs.", "external_references": [{"external_id": "AN0213", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0077#AN0213"}], "id": "x-mitre-analytic--5b9f2d26-e84c-49a3-8586-a7367580b802", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0213", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "None", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match known interface manipulation utilities or driver invocations.", "field": "CommandPattern"}, {"description": "Tunable to non-default or rarely used interfaces (e.g., wlan1, hci0).", "field": "NetworkDevice"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2870', 0, 97, '09-mitre-attack', 'retrieved', 'F8AB2E88C5AF1AF5EFE3224BE4753642DD719FB8DF8DDCABB2D7B7B254C1C02C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
