VALUES ('doc-09-mitre-attack-p0-2871', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) unified logs report IOUSBHost/IOThunderbolt device arrival; (2) diskarbitrationd attaches a new volume; (3) optional: config profile manipulation or new network interface MAC obtains a lease. Correlate unifiedlogs (subsystems: IOUSBHost, IOKit, diskarbitrationd), FSEvents, and DHCP/Zeek.", "external_references": [{"external_id": "AN0187", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0069#AN0187"}], "id": "x-mitre-analytic--5bbe0089-4927-4415-bff7-14a3ba5543c0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0187", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Device attached|enumerated VID/PID", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "mounted|appeared|DA: disk* attached", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "MAC not in allow-list acquiring IP (DHCP)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "MDM profile expectations for external media and Thunderbolt mode; deviations alert.", "field": "ManagedUSBPolicy"}, {"description": "VID/PID for corporate-issued docks/keyboards.", "field": "KnownAppleAccessories"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2871', 0, 124, '09-mitre-attack', 'retrieved', 'A13949A3A5DB792F26655ABB1364C4F1208095DAEE486D67BF4565B82CADBED5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
