INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2873', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Automated and repetitive triggering of SMS messages through OTP/account verification fields on SaaS platforms, leveraging background messaging APIs such as Twilio, AWS SNS, or Amazon Cognito to generate traffic toward attacker-controlled numbers.", "external_references": [{"external_id": "AN0443", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0156#AN0443"}], "id": "x-mitre-analytic--5beb62fd-7dac-485f-828c-72cf151124a8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0443", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "High-frequency invocation of SMS-related API endpoints from publicly accessible OTP or verification forms (e.g., Twilio: SendMessage, Cognito: AdminCreateUser) with irregular destination patterns.", "name": "saas:application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Repeated requests to SMS-generating endpoints using anomalous or new user agents, IP ranges, or geographies.", "name": "saas:audit", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the rolling window over which SMS API invocation frequency is measured. Tunable based on average platform traffic.", "field": "TimeWindow"}, {"description": "Number of SMS requests per endpoint or per user that should trigger investigation. Should align with business logic and user behavior.", "field": "SMSFrequencyThreshold"}, {"description": "Monitors if requests target known high-risk, revenue-sharing regions. Tunable to reflect SMS tariff rates or abuse history.", "field": "DestinationCountryCodeFilter"}, {"description": "Defines outlier score or list of unknown/automated user agents submitting forms.", "field": "UserAgentAnomalyThreshold"}, {"description": "Tracks abnormal geographic spread of traffic sourcing OTP triggers.", "field": "IPGeoVarianceScore"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2873', 0, 209, '09-mitre-attack', 'retrieved', '9219C4AB1D57DAA8393D51E8219095ED9D56734885FB68E789809ACB1218B4FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
