VALUES ('doc-09-mitre-attack-p0-2876', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Modifications to SSO/SAML user attributes (e.g., `isAdmin`, `role`, MFA bypass, App assignments) often through CLI, API, or rogue IdP apps.", "external_references": [{"external_id": "AN0268", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0096#AN0268"}], "id": "x-mitre-analytic--5c69f3b9-8f73-455e-8eb1-5281cd6ce6d5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0268", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "User Attribute Modified / Role Assignment Changed", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected user-role pairings per app or org unit.", "field": "RoleAssignmentBaseline"}, {"description": "Caller identity or IP address ranges for identity admin actions.", "field": "APIUsageContext"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2876', 0, 96, '09-mitre-attack', 'retrieved', '3AD2BB6883D1B124DCEBC4FEE78DD32BDC5D4DE4C5FC7DA39FE0023117264ED8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
