INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2877', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged SAML tokens in IaaS environments often manifest as cross-cloud or cross-account authentication without matching STS events. Defenders may see AssumeRole or GetFederationToken API usage without a corresponding SAML assertion log from the trusted IdP.", "external_references": [{"external_id": "AN0419", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0148#AN0419"}], "id": "x-mitre-analytic--5c6e9102-b3ef-4eaa-85c1-bb5702df0f45", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0419", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AssumeRoleWithSAML", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "SAML login without corresponding IdP authentication log", "name": "CloudTrail:Signin", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag SAML tokens used across unexpected accounts or cloud tenants.", "field": "CrossAccountUsage"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2877', 0, 105, '09-mitre-attack', 'retrieved', '0EC41502BBA3E2A9A2D6F000BD0B39F520B3B10D47919797C9013B48D121F4BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
