VALUES ('doc-09-mitre-attack-p0-2878', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor mail server logs (Postfix, Sendmail, Exim) for anomalous From headers mismatching authenticated SMTP identities. Detect abnormal relay attempts, spoofed envelope-from values, or large-scale outbound campaigns targeting internal users.", "external_references": [{"external_id": "AN0793", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0286#AN0793"}], "id": "x-mitre-analytic--5c7a8194-f0cb-498a-98c6-5928859bf79f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0793", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Processes executing sendmail/postfix with forged headers", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Mismatch between authenticated username and From header in email", "name": "Application:Mail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter trusted relays or automated notification systems from impersonation alerts.", "field": "KnownRelayHosts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2878', 0, 107, '09-mitre-attack', 'retrieved', '2B91D47402E2B9D627A1736CF2EFBEF3B2148352A662C04BC9617AD8AE5C3235', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
