INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2879', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection focuses on monitoring registry modifications under HKLM\\SOFTWARE\\Microsoft\\Netsh that indicate the addition of helper DLLs, followed by anomalous child process activity or module load behavior initiated by netsh.exe. These behaviors are rarely legitimate and may represent an adversary establishing persistence.", "external_references": [{"external_id": "AN1588", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0575#AN1588"}], "id": "x-mitre-analytic--5ca1b37f-31c9-414b-9a31-9f80f553c44a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1588", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the time window in which correlated registry and execution events are considered suspicious (e.g., within 10 minutes)", "field": "TimeWindow"}, {"description": "List of expected or approved child processes spawned by netsh.exe in the enterprise environment", "field": "NetshChildProcessWhitelist"}, {"description": "Directory or filename heuristics to distinguish benign DLLs from malicious helper DLLs", "field": "DLLLoadPath"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2879', 0, 150, '09-mitre-attack', 'retrieved', '321EEDD7D940F310E20FB8B8C89AA736A9D9BEA414453670D6E65927D8951D30', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
