VALUES ('doc-09-mitre-attack-p0-2880', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses a tool like Ruler to configure a malicious Outlook folder Home Page that loads a remote or embedded HTML payload upon folder interaction. Execution chain begins with Outlook launching, a specific folder being accessed, and a suspicious child process being spawned or COM-based execution invoked.", "external_references": [{"external_id": "AN0502", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0177#AN0502"}], "id": "x-mitre-analytic--5ce49e4b-a67f-46ea-b48d-f08f7b942fb4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0502", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Outlook logs indicating failure to load or render HTML page in Home Page view", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Execution of PowerShell script to enumerate or remove malicious Home Page folder config", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Home Page can be configured on any folder like Calendar, Inbox, or custom folders", "field": "TargetFolder"}, {"description": "The Home Page URL may point to internal or external content, hosted on trusted or unknown domains", "field": "HTMLPayloadLocation"}, {"description": "Execution may result in launch of scripting hosts (e.g., mshta.exe, wscript.exe) from outlook.exe", "field": "ChildProcessName"}, {"description": "Execution may occur only when the specific folder is accessed after launch, not immediately at startup", "field": "TimeWindow"}, {"description": "Behavior may vary if the folder''s form view is customized or suppressed via GPO", "field": "FormViewBehavior"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2880', 0, 224, '09-mitre-attack', 'retrieved', '5366CA73A3C4B906DBF8C09880A0E0B0A5B060A38F9D6E7E0B731981763EE59D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
