VALUES ('doc-09-mitre-attack-p0-2881', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell or scheduled tasks initiating outbound HTTPS to known public services without inbound return or loggable response, used to fetch instructions.", "external_references": [{"external_id": "AN1602", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0581#AN1602"}], "id": "x-mitre-analytic--5ce50294-f89c-4158-b5f2-7ca257a88837", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1602", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI network calls", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can tune for task names used to execute curl-based outbound requests", "field": "ScheduledTaskName"}, {"description": "Scoped by environment to exclude known legitimate CDNs", "field": "DestinationIP"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2881', 0, 94, '09-mitre-attack', 'retrieved', '831CB64C7FCDE6A8168F1F26D3F301BF54099543115D70E1BD0740E5D94D4298', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
