VALUES ('doc-09-mitre-attack-p0-2882', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary launches built-in system tools (e.g., whoami, query user, net user) or scripts that enumerate user account information via local execution or remote API queries (e.g., WMI, PowerShell).", "external_references": [{"external_id": "AN0254", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0093#AN0254"}], "id": "x-mitre-analytic--5d024a50-97d8-4b81-8cc6-3db4fff2712c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0254", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify if enumeration originates from non-interactive shell or system service", "field": "ParentProcessContext"}, {"description": "Tune temporal grouping of enumeration + lateral movement attempts", "field": "TimeWindow"}, {"description": "Flag unexpected users issuing enumeration commands (e.g., service accounts)", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2882', 0, 119, '09-mitre-attack', 'retrieved', '15D56078ED43825F1099969E26BBCFD43D8FB1831EEA24559E29E48183E75AAA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
