VALUES ('doc-09-mitre-attack-p0-2883', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged SAML tokens may be used on Windows systems to authenticate to federated apps without normal Kerberos activity. Defenders may detect anomalous event correlation, where access to SaaS/O365 via SAML occurs without prior TGT requests or user logons.", "external_references": [{"external_id": "AN0420", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0148#AN0420"}], "id": "x-mitre-analytic--5d2820b1-af59-4ca2-9f9e-b5bc76f55395", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0420", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Token issuance events showing anomalous claims or issuers", "name": "WinEventLog:ADFS", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of unusual claims in a SAML token (e.g., excessive privileges).", "field": "ClaimAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2883', 0, 111, '09-mitre-attack', 'retrieved', 'C1B7C6D209A9A2E4EF676C98452125BC63FDFBAA9CFC03DD71C73B3B511353A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
