VALUES ('doc-09-mitre-attack-p0-2884', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates control-plane API actions disabling cloud-native monitoring or sensor agents (CloudTrail, GuardDuty, Security Hub, Defender, monitoring agents), role abuse preceding disablement, or instance agent uninstall events", "external_references": [{"external_id": "AN1372", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0497#AN1372"}], "id": "x-mitre-analytic--5d329e39-a38b-47cd-8d3d-fa7515280fd7", "modified": "2026-05-12T16:30:18.378Z", "name": "Analytic 1372", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Delete* / Stop*: DeleteAlarms, StopLogging, or DisableMonitoring API calls", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customizable list of cloud provider API calls related to monitoring/alerting disablement.", "field": "APIActions"}, {"description": "Distinguishes adversary actions from authorized DevOps/CloudOps activities.", "field": "UserContext"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-2884', 0, 105, '09-mitre-attack', 'retrieved', 'E456044381A88F5CF06A428AC76B271EC85A5CF11888598203CD53E069FA2087', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
