VALUES ('doc-09-mitre-attack-p0-2885', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation of cloud instances, services, or resources in normally unused or unsupported regions, especially following initial account access or credential use from known regions. Correlates resource provisioning across regions with absence of historical usage and alerting from standard logging services (e.g., GuardDuty not enabled in that region).", "external_references": [{"external_id": "AN0690", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0247#AN0690"}], "id": "x-mitre-analytic--5d4419cc-6925-4f7d-a247-e0a4634fea90", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0690", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RunInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "CreateBucket", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--59ec10d9-546b-4b8e-bccb-fa85f71e5055"}, {"channel": "GetCallerIdentity", "name": "CloudTrail:GetCallerIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"channel": "High outbound traffic from new region resource", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of regions historically unused by the organization (can vary per tenant/project)", "field": "UnusedRegionList"}, {"description": "Time interval for correlating activity following account access", "field": "TimeWindow"}, {"description": "Whitelist of services allowed in secondary/DR regions", "field": "AllowedServiceList"}, {"description": "Volume threshold to flag suspicious outbound activity", "field": "OutboundTrafficThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2885', 0, 163, '09-mitre-attack', 'retrieved', '83C7327C8BA3583F57C7E10E6E25B7F3D3F9EFD798E0D367DE0C8845CDA4FC19', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
