INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects network share disconnection attempts using command-line tools like `net use /delete`, PowerShell `Remove-SmbMapping`, and correlation with process lineage and SMB session teardown activity.", "external_references": [{"external_id": "AN0286", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0103#AN0286"}], "id": "x-mitre-analytic--5d47e6b2-04fb-45ab-be98-7de1baabf508", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0286", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "SMB2_LOGOFF/SMB_TREE_DISCONNECT", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjustable window to correlate CLI disconnection command with SMB session teardown (e.g., 5 mins)", "field": "TimeWindow"}, {"description": "Used to filter on non-interactive users or highly privileged accounts", "field": "UserContext"}, {"description": "Patterns to match `net use \\\\host\\share /delete`, `Remove-SmbMapping`, or suspicious batched disconnections", "field": "ProcessCommandLineRegex"}, {"description": "Tunable list of shares likely targeted (e.g., ADMIN$, C$, IPC$)", "field": "NetworkShareNamePattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2886', 0, 149, '09-mitre-attack', 'retrieved', 'B938D68310A489E4D0DBD9E8535BC74D11C8FA68B5F129CB4ED42AB29CDA9B98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
