VALUES ('doc-09-mitre-attack-p0-2887', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of enumeration of identity entities through cloud provider APIs where principals retrieve account metadata such as IAM users or roles in rapid succession.", "external_references": [{"external_id": "AN1615", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1615"}], "id": "x-mitre-analytic--5d7158ce-17f5-4643-bde2-c0a4f2ba0b73", "modified": "2026-05-12T16:30:18.378Z", "name": "Analytic 1615", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DescribeUsers / ListUsers / GetUser", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on which IAM APIs are used and their frequency.", "field": "API_Method"}, {"description": "Differentiate user-initiated from automated/scripted enumeration.", "field": "CallerType"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2887', 0, 97, '09-mitre-attack', 'retrieved', '40E7EDF475F186C5E2706459F833E2B373C0AFFA6EF14341C233B3D53CB5AA81', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
