VALUES ('doc-09-mitre-attack-p0-2888', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects lateral discovery or container breakout attempts using netcat, curl, or custom binaries probing other services within the same namespace or VPC subnet.", "external_references": [{"external_id": "AN1060", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0376#AN1060"}], "id": "x-mitre-analytic--5d7b1be3-1c8a-40bf-a4d2-85e26dd82d76", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1060", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket connect", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "execve", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "container-level outbound traffic events", "name": "containerd:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom or renamed versions of tools may use different paths", "field": "ExecutablePath"}, {"description": "Aggregation interval for identifying anomalous traffic", "field": "TimeWindow"}, {"description": "Tunable count of unique destinations to classify discovery", "field": "NetworkDestinationCount"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2888', 0, 117, '09-mitre-attack', 'retrieved', 'CB2F73761F63E74F7B4B5C29E66