VALUES ('doc-09-mitre-attack-p0-2890', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of processes that link to CoreServices or Foundation APIs followed by creation of memory regions, code execution, or abnormal library injection.", "external_references": [{"external_id": "AN1467", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0529#AN1467"}], "id": "x-mitre-analytic--5e02fe2a-7659-4871-b79e-7ea57373aa37", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1467", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launch and dylib load", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter on CoreServices, Cocoa, Foundation framework usage", "field": "API Framework Name"}, {"description": "Tune to exclude known developer tools or test environments", "field": "Execution Context"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2890', 0, 101, '09-mitre-attack', 'retrieved', '3D023D2B9E52E95239BF5215E9B192E783C1D46D702FCEC459243A97CD72C15E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
