VALUES ('doc-09-mitre-attack-p0-2891', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Destruction via `rm -rf`, overwrite with `dd` or `srm`, often executed by script in /tmp or /private/tmp, may also involve file overwrite to political or decoy image data.", "external_references": [{"external_id": "AN0413", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0146#AN0413"}], "id": "x-mitre-analytic--5e1b310a-ce3d-4271-83e0-87cd2862f959", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0413", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec rm -rf|dd if=/dev|srm|file unlink", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "process.*exit.*code", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on high-risk patterns in temporary directories or key system paths.", "field": "CommandPattern"}, {"description": "Optional anomaly detection on overwritten files with high-entropy payloads.", "field": "EntropyChangeRate"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2891', 0, 109, '09-mitre-attack', 'retrieved', '91F62DF19284020054AE66D88A536240B9D2B3AF81B457E755FCB196DEBD339F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
