VALUES ('doc-09-mitre-attack-p0-2892', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of session cookies or authentication tokens from unusual user agents or locations. Identifies token reuse without reauthentication or attempts to bypass MFA using previously stolen cookies.", "external_references": [{"external_id": "AN1406", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0509#AN1406"}], "id": "x-mitre-analytic--5e1d71ce-5653-4580-a609-9832c88e2c87", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1406", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "login with reused session token and mismatched user agent or IP", "name": "saas:googleworkspace", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "session.token.reuse", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Max allowed delta between token issuance and second use", "field": "TokenReuseTimeWindow"}, {"description": "Deviation score from normal browser/device fingerprint", "field": "UserAgentAnomalyScore"}, {"description": "Deviation in IP region or ASN per user profile", "field": "GeoLocationAnomalyScore"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2892', 0, 122, '09-mitre-attack', 'retrieved', '02B614A9B3C136A8519D5BAA44F9071CC773FE1BC4577B463305199E5835F850', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
