VALUES ('doc-09-mitre-attack-p0-2893', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Inspect unified logs for anomalous DNS resolutions triggered by non-network applications. Flag repeated connections to newly registered or algorithmically generated domains. Correlate with endpoint process telemetry.", "external_references": [{"external_id": "AN0111", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0039#AN0111"}], "id": "x-mitre-analytic--5e225927-bf50-4261-b1ae-d65e803da0b8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0111", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DNS query with pseudo-random subdomain patterns", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Unexpected applications generating outbound DNS queries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Age of domain registration considered suspicious (e.g., < 30 days)", "field": "NewDomainThreshold"}, {"description": "Number of queries per process per time window", "field": "DNSQueryVolume"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2893', 0, 111, '09-mitre-attack', 'retrieved', 'C9C220F89FD2D1C36EABFC8446487F1115BEF00FE44B81C7F259DE67EB8A4473', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
