INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2894', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outlook or Word used to forward suspicious internal attachments with macro content. Defender observes attachment forwarding, auto-opening behaviors, or macro prompt interactions.", "external_references": [{"external_id": "AN0151", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0054#AN0151"}], "id": "x-mitre-analytic--5e3f407f-192b-4e6f-aab0-e0682da3a4a9", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0151", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SendOnBehalf, MessageSend, AttachmentPreviewed", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Timing between mail open and macro invocation", "field": "MacroExecutionWindow"}, {"description": "Patterns of known internal spearphishing lures (e.g., invoice, HR_policy)", "field": "AttachmentNameHeuristics"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2894', 0, 101, '09-mitre-attack', 'retrieved', '205217382707F8A411E69D891CC09957C278D43A4CCAF1249B4116DB5B2F6BCE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
