VALUES ('doc-09-mitre-attack-p0-2896', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outbound traffic from host management services or guest-to-host interactions over unusual interfaces (e.g., backdoor API endpoints or external VPN tunnels).", "external_references": [{"external_id": "AN1379", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0499#AN1379"}], "id": "x-mitre-analytic--5e7eea18-14f5-4d76-b5cc-bc63a0e5ce65", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1379", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "None", "name": "esxi:vpxd", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May vary based on ESXi build and should be filtered to suppress known interfaces.", "field": "InterfaceName"}, {"description": "Environment-specific ranges to ignore (e.g., DR tunnels or out-of-band mgmt).", "field": "FallbackIPRanges"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2896', 0, 101, '09-mitre-attack', 'retrieved', 'BB80FCB296106B691C678E38561770509339EB698369FEC3BC3DAFBE8A012FED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
