VALUES ('doc-09-mitre-attack-p0-2897', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect curl/wget commands saving executable/script payloads to /tmp or /var/tmp followed by execution. Monitor packet captures or IDS/IPS alerts for injected responses or mismatched content types.", "external_references": [{"external_id": "AN0993", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0349#AN0993"}], "id": "x-mitre-analytic--5e8af32c-5246-43e1-a7d9-c4d263c7b135", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0993", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of curl or wget writing files to /tmp/* followed by chmod or execution", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "File creation of suspicious scripts/binaries in temporary directories", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Injected content responses with unexpected script/malware signatures", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directories such as /tmp and /var/tmp where injected files are often written.", "field": "TempDirectories"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2897', 0, 125, '09-mitre-attack', 'retrieved', 'BB9376BACD59BE9FD20FA1D4DD0