VALUES ('doc-09-mitre-attack-p0-2899', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious gratuitous ARP responses or inconsistent IP-to-MAC mappings using auditd and packet capture. Behavioral focus is on unsolicited replies overriding legitimate ARP ownership.", "external_references": [{"external_id": "AN1092", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0387#AN1092"}], "id": "x-mitre-analytic--5ee16525-5e86-4634-aa75-37468c4034c4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1092", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "setsockopt, ioctl modifying ARP entries", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Gratuitous ARP replies with mismatched IP-MAC binding", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected legitimate IP-to-MAC updates for servers or virtual routers.", "field": "AllowedARPUpdates"}, {"description": "Number of anomalous ARP packets per second before triggering detection.", "field": "AlertThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2899', 0, 110, '09-mitre-attack', 'retrieved', 'EF0E1A92B58913A1935DED88593C8C3EB00CD9BC354CF4C4A8608D8FF39F47F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
