VALUES ('doc-09-mitre-attack-p0-2900', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes use base64/xxd/openssl/python Objective‑C APIs to encode data (seen in EndpointSecurity exec events or Unified Logs) → quick outbound connections with large bytes_out or HTTP POSTs carrying Base64/MIME bodies.", "external_references": [{"external_id": "AN0347", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0124#AN0347"}], "id": "x-mitre-analytic--5eefb166-8f2b-45e0-b5c8-bf71984dec08", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0347", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process command line contains base64, -enc, openssl enc -base64", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "outbound flows with bytes_out >> bytes_in", "name": "PF:Logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "http: HTTP body contains long Base64 sections", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Signed/allowed developer binaries routinely using encoding.", "field": "AllowedDeveloperIDs"}, {"description": "Payload entropy cutoff.", "field": "EntropyThreshold"}, {"description": "Exec → egress window.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2900', 0, 127, '09-mitre-attack', 'retrieved', '3338504B257642AF9F1F5F021A15917A331841D1E60C4BC629CF61A3EAA7089D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
