VALUES ('doc-09-mitre-attack-p0-2901', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A high volume of authentication failures using a single password (or small set) across many different user accounts within a defined time window", "external_references": [{"external_id": "AN1336", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1336"}], "id": "x-mitre-analytic--5ef73ed0-313e-4b9b-b616-8c2d02f4151a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1336", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4625, 4771, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of distinct accounts a password is used against before alerting", "field": "PasswordReuseThreshold"}, {"description": "Window over which the correlation is measured (e.g., 10 mins)", "field": "TimeWindow"}, {"description": "Limit detection to sensitive or monitored user groups (e.g., Admins)", "field": "TargetGroupFilter"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2901', 0, 110, '09-mitre-attack', 'retrieved', 'CC0BB890FE0170580F430D5E4BFEC83E73C1C072570D1063C45A134C252DE3F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
