VALUES ('doc-09-mitre-attack-p0-2902', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Invocation of built-in commands like screencapture or use of undocumented APIs from suspicious parent processes.", "external_references": [{"external_id": "AN0981", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0346#AN0981"}], "id": "x-mitre-analytic--5f1a4795-74e5-49b9-85bb-e186ca699648", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0981", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process: exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize regex for flag detection (e.g., `screencapture -x`) based on usage patterns", "field": "CommandLineRegex"}, {"description": "May vary depending on expected screencapture behavior (Terminal vs remote agent)", "field": "ParentProcessName"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2902', 0, 90, '09-mitre-attack', 'retrieved', '74891E443F513B4D08E32F9B1F87062EAC1B7EC5471FFDE121D6F314B4C846D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
