VALUES ('doc-09-mitre-attack-p0-2903', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects login and usage patterns deviating from typical Microsoft 365 or Google Workspace user profiles.", "external_references": [{"external_id": "AN1506", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0546#AN1506"}], "id": "x-mitre-analytic--5f1ffd26-01f7-47fc-b544-130fc14c0bd2", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1506", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "UserLogin", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "login.event", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to identify logins outside of expected work times.", "field": "BusinessHours"}, {"description": "Defines expected application usage per department or role.", "field": "OfficeProductivityToolBaseline"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2903', 0, 90, '09-mitre-attack', 'retrieved', 'DF437F97105D8048B4D49F6AE86C5E719D2279B0B922E16F5E699957F80260F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
