VALUES ('doc-09-mitre-attack-p0-2904', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary launches high-entropy process or malformed app bundle causing repeated application crashes and system slowdowns.", "external_references": [{"external_id": "AN0586", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0208#AN0586"}], "id": "x-mitre-analytic--5f2cc434-5edc-4f36-927a-eb48ee72aa6e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0586", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Repeated process crashes logged by CrashReporter or system instability logs in com.apple.console", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Spike in CPU or memory use from non-user-initiated processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of app crashes within monitoring window", "field": "CrashCountThreshold"}, {"description": "Used for high-entropy binaries often observed in DoS malware samples", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2904', 0, 108, '09-mitre-attack', 'retrieved', 'BD7C57C4DD700559F92D11811F168CEA7EAA1EB94E0AE15ABE2F74549418CB77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
