VALUES ('doc-09-mitre-attack-p0-2905', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or renaming of accounts with names that closely match known service, root, or admin accounts. Behavior often follows account discovery or deletion, attempting to blend into system activity logs using trusted name conventions.", "external_references": [{"external_id": "AN1078", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0383#AN1078"}], "id": "x-mitre-analytic--5f584d00-63b5-44c5-b629-ff238f5b9931", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1078", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "adduser", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "usermod, or account rename system calls", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "Listing of /etc/passwd and /etc/shadow metadata", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist of legitimate service accounts used for validation.", "field": "AllowedSystemAccounts"}, {"description": "Edit distance sensitivity between created account and existing account names.", "field": "LevenshteinThreshold"}, {"description": "Whether to flag account creation events triggered from suspicious scripts or shell histories.", "field": "ScriptInitiatorDetection"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2905', 0, 142, '09-mitre-attack', 'retrieved', '8DF9D36D6EC86BCF8B45A8D64DFC87522D25A4A7EDFBF2FCD4F29FD7D9CB884C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
