VALUES ('doc-09-mitre-attack-p0-2906', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of HTML-based downloads via Safari/Chrome that create obfuscated files (e.g., .zip, .app, .js) in user directories and are followed by suspicious executions from preview or launch services.", "external_references": [{"external_id": "AN0874", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0313#AN0874"}], "id": "x-mitre-analytic--5f8b5ef5-8b4a-4713-a694-dc0746669a73", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0874", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "File Events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "LaunchServices quarantine", "name": "gatekeeper/quarantine database", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether downloaded file has a quarantine flag and is bypassed via Gatekeeper", "field": "QuarantineFlagCheck"}, {"description": "JavaScript strings that may indicate smuggling: msSaveBlob, download.href, createObjectURL", "field": "BlobKeywordAlertList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2906', 0, 115, '09-mitre-attack', 'retrieved', '39ECDF029B9A70C53C5EF446B2C43391D