VALUES ('doc-09-mitre-attack-p0-2907', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection correlates file creation or modification of `.lnk` (shortcut) files in autostart locations with anomalous parent-child process lineage or unsigned binaries. Defenders should watch for LNK creation/modification events outside of known software installations, patch events, or OS updates. Flag shortcut targets pointing to suspicious locations or unknown binaries, particularly those written by script interpreters or spawned from phishing delivery chains.", "external_references": [{"external_id": "AN0510", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0180#AN0510"}], "id": "x-mitre-analytic--5f9fdff8-55ed-4b1e-8889-46b376ce7149", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0510", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable regex to flag suspicious shortcut target paths (e.g., temp folder, base64 in target, unusual executable names)", "field": "TargetPathRegex"}, {"description": "Time window used to correlate shortcut creation with process execution (e.g., 5-minute window)", "field": "TimeWindow"}, {"description": "Filter for expected administrative installs versus end-user initiated shortcut creation", "field": "UserContextScope"}, {"description": "Configurable value to filter LNK files tagged with external source markers (e.g., ZoneId=3 for Internet)", "field": "ZoneIdentifierThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2907', 0, 190, '09-mitre-attack', 'retrieved', 'F5D36456BA0F087B560C213A8C194D48A137B11AEF6DD46FF74DB12F97280125', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
