VALUES ('doc-09-mitre-attack-p0-2908', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects applications such as Automator, AppleScript, or LaunchDaemons invoking HTTP/S traffic to non-standard domains or using suspicious headers (e.g., Base64 in URIs or cookie fields).", "external_references": [{"external_id": "AN0077", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0027#AN0077"}], "id": "x-mitre-analytic--5ff3ae40-d326-4eae-9bc5-c77ddcb6cb6e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0077", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "log stream --predicate", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-browser parent of web traffic (e.g., AppleScript, bash)", "field": "SuspiciousParentProcess"}, {"description": "Unusually encoded data in GET/POST URIs", "field": "URIEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2908', 0, 98, '09-mitre-attack', 'retrieved', '0B2298BFB120C8DE1B72BDFE01FF036D98346687006FD0A7F8F1CFBF584153DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
