INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2909', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders can detect suspicious cloud instance deletions by correlating events across authentication, instance lifecycle, and account activity. From a defender’s perspective, behaviors of interest include instances deleted shortly after creation, deletions initiated by new or rarely used accounts, deletions following snapshot creation, and deletions originating from anomalous geolocations or access keys. These may indicate adversarial attempts to destroy forensic evidence or evade detection.", "external_references": [{"external_id": "AN0234", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0084#AN0234"}], "id": "x-mitre-analytic--602def5b-49e4-4c64-afe6-1476eac13e67", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0234", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TerminateInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--1361e324-b594-4c0e-a517-20cee32b8d7f"}, {"channel": "DescribeInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--45fd904d-6eb0-4b50-8478-a961f09f898b"}, {"channel": "MICROSOFT.COMPUTE/VIRTUALMACHINES/DELETE", "name": "azure:activity", "x_mitre_data_component_ref": "x-mitre-data-component--7561ed50-16cb-4826-82c7-c1ddca61785e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identity of the user/service account performing deletions; tuned to exclude automation or known administrative workflows.", "field": "UserContext"}, {"description": "Threshold for detecting rapid instance lifecycle events (e.g., creation and deletion within minutes).", "field": "TimeWindow"}, {"description": "Region or source IP where the delete request originated; can be tuned to align with enterprise cloud geography.", "field": "GeoLocation"}, {"description": "Number of deletions per user/account in a defined window; tuned for organizations with high elasticity.", "field": "RateThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2909', 0, 193, '09-mitre-attack', 'retrieved', 'F359DF75CAF201B56A48C692615DF66155C7BE217E12F6E79424796AF88FF728', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
