VALUES ('doc-09-mitre-attack-p0-2910', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Registry modifications to HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon\\SpecialAccounts\\UserList setting user visibility to 0, or creation of user accounts not shown on login screen. Defender view: correlation of account creation with registry edits that mark users hidden.", "external_references": [{"external_id": "AN1001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0353#AN1001"}], "id": "x-mitre-analytic--6039c777-6a85-4df4-86b9-40d95796046e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1001", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4720", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict monitoring to privileged or unexpected accounts.", "field": "AccountScope"}, {"description": "Whitelist accounts that are intentionally hidden by administrators.", "field": "BaselineHiddenUsers"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2910', 0, 106, '09-mitre-attack', 'retrieved', '2808FD07DF3E89322D7139DE56F826A0CD1ECE9C0AE36F40A01D43B7B8AE542F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
