VALUES ('doc-09-mitre-attack-p0-2911', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects user activity that shares or syncs files with external domains via link generation, OneDrive external sharing, or file transfer actions involving non-whitelisted partner tenants.", "external_references": [{"external_id": "AN1581", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0573#AN1581"}], "id": "x-mitre-analytic--60b2d6f4-1bf0-4c52-8923-ac8e3b8088d4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1581", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SharingSet", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}, {"channel": "AnonymousLinkCreated", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--e214eb6d-de8f-4154-9015-6d47915fbed1"}, {"channel": "FileAccessed", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known partner or adversarial cloud identities/domains", "field": "ExternalDomainList"}, {"description": "Duration between file access and external sharing", "field": "TimeWindow"}, {"description": "Type of link (anonymous, internal, organization-wide) to alert on", "field": "SharingMethod"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2911', 0, 114, '09-mitre-attack', 'retrieved', 'CB2C1BCEB5F55767D82194F4FC27A30ADA89F813DCA3219ED69B59538F8B2B49', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
