VALUES ('doc-09-mitre-attack-p0-2912', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects interactive or scripted abuse of cmd.exe, batch files, or shell invocation chains. Focuses on parent-child relationships (e.g., cmd.exe launched from unusual parents), anomalous command-line parameters, and chaining with discovery, credential access, or lateral movement behaviors.", "external_references": [{"external_id": "AN0578", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0202#AN0578"}], "id": "x-mitre-analytic--60d70569-0d28-4d98-957c-4676b2411685", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0578", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Process Tree + Script Block Logging", "name": "EDR:scriptblock", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Cmd.exe launched from uncommon parents (e.g., msedge.exe, winword.exe) may indicate abuse.", "field": "ParentProcessName"}, {"description": "Cmd or .bat execution during non-working hours may indicate automation or C2 activity.", "field": "TimeWindow"}, {"description": "Flags suspicious switches (e.g., /c ping, /k whoami) or command chaining (&&, ^).", "field": "CommandLinePattern"}, {"description": "Batch file execution from %TEMP%, C:\\Users\\Public, or external drives.", "field": "ScriptStoragePath"}, {"description": "Flags admin-level users executing cmd outside expected baselines.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2912', 0, 167, '09-mitre-attack', 'retrieved', '6732AA0488CB0F0AF8DEA99220918CD3B5ADED899B243913022ABDBA4804A6C4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
