VALUES ('doc-09-mitre-attack-p0-2913', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of unencrypted protocols (e.g., TFTP, FTP, HTTP) to transfer configuration files, routing tables, or logs to untrusted IP addresses, especially using administrative commands like `copy run ftp:`.", "external_references": [{"external_id": "AN0427", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0149#AN0427"}], "id": "x-mitre-analytic--611778c2-9de4-4066-b7d1-78752891c32e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0427", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI command logs", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "flow records", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "PCAP inspection", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag commands like `copy`, `archive tar`, or `upload` directed at external hosts.", "field": "ProtocolCommandWatchlist"}, {"description": "Define external IP ranges unauthorized to receive router/switch configs.", "field": "DestinationIPBlocklist"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2913', 0, 118, '09-mitre-attack', 'retrieved', '039C6DDF4D9C1A05E739877F4E4BC3B708581CCF0A