VALUES ('doc-09-mitre-attack-p0-2914', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects processes or binaries executed from trusted directories (e.g., System32) or using trusted names (e.g., svchost.exe) where the metadata, hash, or parent process does not align with legitimate activity patterns.", "external_references": [{"external_id": "AN0983", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0347#AN0983"}], "id": "x-mitre-analytic--61256fb2-d490-4e1d-b308-665a2d68ec64", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0983", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths such as C:\\Windows\\System32 that adversaries may abuse", "field": "trusted_directory_list"}, {"description": "Time window to determine process novelty (e.g., 30 days)", "field": "process_baseline_age"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2914', 0, 104, '09-mitre-attack', 'retrieved', '92E61D6B5D24C83CFFC0A562189F5F0DD81076CF21458047AD5983D8B8DC9A3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
