VALUES ('doc-09-mitre-attack-p0-2916', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account created via CLI using ''username'' command or REST API. Detectable through AAA logging or CLI history telemetry.", "external_references": [{"external_id": "AN1240", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0447#AN1240"}], "id": "x-mitre-analytic--614594ba-9590-4fa9-871c-3e092882c74c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1240", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "username privilege ", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Some devices allow unprivileged user creation—adjust based on role risk", "field": "PrivilegeLevel"}, {"description": "Creation via Telnet, SSH, or serial console affects detection priority", "field": "RemoteSessionFlag"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2916', 0, 92, '09-mitre-attack', 'retrieved', '9064A9D4E4412CCF970DBC68D75201A11275F4797E5B30535233AFCCEAB3A4C4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
