VALUES ('doc-09-mitre-attack-p0-2917', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious HTML or script is rendered as a Home Page for a specific Outlook folder. Outlook accesses that folder, loads remote content, and executes embedded JavaScript or ActiveX/COM logic resulting in unauthorized actions or local execution.", "external_references": [{"external_id": "AN0503", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0177#AN0503"}], "id": "x-mitre-analytic--616755c6-e83d-46ce-ad76-ac706074a575", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0503", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Folder configuration updated with external or HTML-formatted Home Page via Set-MailboxFolder", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Inbound email triggering Outlook to auto-access folder tied to malicious Home Page", "name": "m365:messagetrace", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Home Page customization may not be audited unless detailed message or folder auditing is enabled", "field": "AuditPolicyScope"}, {"description": "Anomalous access to folders not usually interacted with can signal triggering of malicious view", "field": "FolderAccessRate"}, {"description": "Mail clients may restrict remote Home Page content unless domain is explicitly allowed", "field": "ExternalURLAllowlist"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2917', 0, 160, '09-mitre-attack', 'retrieved', 'EDD311A34982D1C3D8B5EE5AB0D85262E92FB1462EAAEF9D98A6665DC2834F5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
