VALUES ('doc-09-mitre-attack-p0-2918', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous high-volume access to customer records in CRM software by a non-CRM admin user account, especially following initial authentication from a rare location or device. Behavior includes abnormal access to PII fields or data exports within a short time window.", "external_references": [{"external_id": "AN1520", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0550#AN1520"}], "id": "x-mitre-analytic--616bc2d5-5c4d-4efa-9490-c77213be1de1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1520", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DataExport, RestAPI, Login, ReportExport", "name": "saas:salesforce", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "UserLoggedIn", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Duration over which bulk CRM queries occur (e.g., 1 minute, 5 minutes); varies by organization usage pattern", "field": "TimeWindow"}, {"description": "User''s CRM role, department, or job function (e.g., non-sales user accessing customer PII)", "field": "UserContext"}, {"description": "Number of CRM objects (contacts, deals, logs) accessed or exported above normal", "field": "AnomalousExportThreshold"}, {"description": "Rare or impossible geolocation/IP address for legitimate CRM user access", "field": "SourceLocation"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2918', 0, 158, '09-mitre-attack', 'retrieved', '88940CC940408F7DB18D765203F52B2C2C38B70DB4DA3E6AF9B8A997DDC4083B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
