VALUES ('doc-09-mitre-attack-p0-2919', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Modifications to user accounts via `dscl`, `pwpolicy`, or System Preferences CLI (`sysadminctl`) that alter user groups, enable root, or bypass MDM restrictions.", "external_references": [{"external_id": "AN0267", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0096#AN0267"}], "id": "x-mitre-analytic--616ccbf4-08f2-4b54-8e41-a8e362e31827", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0267", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.accountsd, com.apple.opendirectoryd", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track known non-system user UIDs or service accounts.", "field": "ModifiedUserList"}, {"description": "List of sensitive groups (admin, _developer, _analyticsd).", "field": "GroupMembershipChanges"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2919', 0, 89, '09-mitre-attack', 'retrieved', 'C327A333BA4E9290CE3A131D9EA177A5C5BD3DF255ACD0791E776495983AC538', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
