VALUES ('doc-09-mitre-attack-p0-2920', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious registry modifications under `HKLM\\SYSTEM\\CurrentControlSet\\Control\\Print\\Monitors\\*\\Driver`, DLL loads by `spoolsv.exe` of non-standard or unsigned modules, and abnormal usage of the `AddMonitor` API by non-installation processes. This pattern often indicates an attempt to persist a malicious DLL via the print monitor mechanism, particularly when correlated with creation of files in `C:\\Windows\\System32` not tied to known patches or installations.", "external_references": [{"external_id": "AN0580", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0204#AN0580"}], "id": "x-mitre-analytic--61729716-59f3-433e-a678-101c18040851", "modified": "2025-11-12T17:13:52.357Z", "name": "Analytic 0580", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=13", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "API call to AddMonitor invoked by non-installer process", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected directory path for legitimate monitor DLLs (e.g., C:\\Windows\\System32)", "field": "TargetDLLDirectory"}, {"description": "Enable/disable signature validation on DLLs loaded by spoolsv.exe", "field": "SignedImageValidation"}, {"description": "Define whether only SYSTEM/user installs are expected to make changes to the port monitor registry keys", "field": "UserContextScope"}, {"description": "Timeframe between registry modification and subsequent spoolsv.exe DLL load", "field": "TimeWindow"}, {"description": "Filter on calling process of AddMonitor API to detect anomalies outside installer/updater", "field": "AddMonitorCallContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2920', 0, 204, '09-mitre-attack', 'retrieved', '0F0028A6FAFB04526C2A0C728044A5CB6C0966ECB31535FD6BC0D3977318F5B7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
