INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2921', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-23T18:32:05.919Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection identifies execution of scripts or applications containing invisible Unicode payloads reconstructed at runtime, correlated with abnormal AppleScript, JavaScript for Automation, or shell execution and subsequent process or network behavior inconsistent with visible file content. ", "external_references": [{"external_id": "AN2065", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0920#AN2065"}], "id": "x-mitre-analytic--6195e912-ed73-4ec7-a03b-097631ec0b26", "modified": "2026-04-24T20:31:59.381Z", "name": "Analytic 2065", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log entries indicating network connection initiation on macOS", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Execution of osascript, sh, bash, zsh, installer, open", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "looking for file access to scripts with abnormal encoding patterns", "name": "macOS:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Use of abnormal AppleScript or JavaScript functions (such as eval()) not typically expected", "field": "ExecutionContext"}, {"description": "Specific unicode ranges monitored (zero-width, PUA, bidi) ", "field": "UnicodeCharacterSet"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2921', 0, 145, '09-mitre-attack', 'retrieved', '18C558B33F4B70B46570420384953AFDB8BE360AADD3F91660225B674EDED5CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
