INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected creation or modification of files with `com.apple.ResourceFork` extended attributes containing unusually large or non-standard data. Defender perspective: detection of resource forks in contexts where they are uncommon, especially when paired with process execution or network activity.", "external_references": [{"external_id": "AN1609", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0584#AN1609"}], "id": "x-mitre-analytic--619804e7-5ae7-4c6e-b1bb-e1d10a22cc87", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1609", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "File creation or modification with com.apple.ResourceFork extended attribute", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Execution of commands like `ls -l@`, `xattr -l`, or custom tools interacting with resource forks", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Process creation involving binaries interacting with resource fork data", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust thresholds for ''unusually large'' resource fork data based on baseline usage in the environment.", "field": "ResourceForkSizeThreshold"}, {"description": "Scope monitoring to sensitive directories such as /Users, /Applications, or temporary paths.", "field": "MonitoredDirectories"}, {"description": "Time window for correlating resource fork activity with subsequent execution or network activity.", "field": "CorrelatedActivityWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2922', 0, 172, '09-mitre-attack', 'retrieved', 'E54EC1343C3C8B6F5A94C123AE559A1938FF88E0AC5CFF4645AD031CDB4EC83D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
