VALUES ('doc-09-mitre-attack-p0-2924', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects file movement or outbound TFTP/FTP transfers from ESXi host initiated via shell commands or injected scripts, particularly from scratch partitions or /tmp.", "external_references": [{"external_id": "AN1172", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0416#AN1172"}], "id": "x-mitre-analytic--61e3802a-c95c-43c2-8749-139e0f750169", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1172", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/root/.ash_history", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "mirror/SPAN port", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Public IPs or domains not belonging to known ESXi mgmt infra", "field": "TransferTargetDomainOrIP"}, {"description": "Monitor transfers from /tmp/, /etc/, /vmfs/volumes/", "field": "SourceDirectoryFilter"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2924', 0, 98, '09-mitre-attack', 'retrieved', 'F546CD5FECD54A30EEF7E0343004454B0479B65FF42729F8A3F27E92F47B8C91', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
