VALUES ('doc-09-mitre-attack-p0-2925', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of files in directories known to be excluded from AV scanning (e.g., C:\\Windows\\Temp, Exchange server directories, or default AV exclusions). Defender perspective: correlate file creation with execution behavior or anomalous parent processes writing to excluded paths.", "external_references": [{"external_id": "AN0139", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0051#AN0139"}], "id": "x-mitre-analytic--620cae28-1874-462d-a2e4-47ddd75098ea", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0139", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of directories excluded from scanning in the environment (customizable per organization).", "field": "ExcludedPaths"}, {"description": "Legitimate processes typically writing to excluded paths to minimize false positives.", "field": "ProcessAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2925', 0, 121, '09-mitre-attack', 'retrieved', 'D161EB68C53BACEB928F3C7676A290C91A02B8A1D4CD1A4D9D252789655CB483', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
