VALUES ('doc-09-mitre-attack-p0-2926', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for security commands and API calls interacting with the Keychain, as well as file access attempts to stored certificates and private keys in ~/Library/Keychains or /Library/Keychains.", "external_references": [{"external_id": "AN0673", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0240#AN0673"}], "id": "x-mitre-analytic--62285936-d8a3-4b18-b3b4-a521fbef10ec", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0673", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process calling security find-certificate, export, or import", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "~/Library/Keychains, /Library/Keychains", "name": "macos:keychain", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist legitimate apps that interact with Keychain to reduce false positives.", "field": "ApplicationAllowList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2926', 0, 99, '09-mitre-attack', 'retrieved', 'EB53327E6B461B0B35EBE87AFE82A311F1C6CD64551F4B198C07EBAF4628A9BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
