VALUES ('doc-09-mitre-attack-p0-2927', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies adversary behavior that launches commands or invokes APIs to enumerate active processes (e.g., tasklist.exe, Get-Process, or CreateToolhelp32Snapshot). Detects execution combined with parent process lineage, network session context, or remote origin.", "external_references": [{"external_id": "AN0095", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0034#AN0095"}], "id": "x-mitre-analytic--625983e7-9736-44f4-98ba-f372b3a3d236", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0095", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to scope suspicious discovery from non-interactive or non-standard parent processes like Office macros, WMI, or script engines", "field": "ParentProcessName"}, {"description": "Adversaries may obfuscate or vary process discovery commands (e.g., aliases, PowerShell variants)", "field": "CommandLinePattern"}, {"description": "Helps detect bursty discovery behavior within a short timeframe", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2927', 0, 130, '09-mitre-attack', 'retrieved', '0E05BA80163ACE69E56D869FA0F39B691BF3F60AAEC71E3892404CDE53F9D138', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
