VALUES ('doc-09-mitre-attack-p0-2928', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies archive utilities (e.g., ditto, unzip, xar, pkgutil) used to extract payloads to non-standard paths, then correlates with execution or file permission changes (e.g., `chmod +x`) and process spawns from decompressed location.", "external_references": [{"external_id": "AN0784", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0281#AN0784"}], "id": "x-mitre-analytic--62afd8a1-550d-43a6-a56a-7d5ae5abbcf6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0784", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process launch", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "filesystem events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "file open/write", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Target unusual extraction paths (~/Library/, /tmp/, /private/tmp/)", "field": "DecompressionPathMatch"}, {"description": "List of decompression utilities used in the environment", "field": "ToolBinaryNames"}, {"description": "Time between decompression and first binary execution", "field": "FollowOnExecutionDelta"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2928', 0, 123, '09-mitre-attack', 'retrieved', 'DF44C8895BD4E8FF2C51EC51F144998951ED5217F3FF7468763D61D0658B4087', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
