VALUES ('doc-09-mitre-attack-p0-2929', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal loading of kernel modules, direct tampering with /dev, /proc, or LD_PRELOAD behaviors hiding processes or files.", "external_references": [{"external_id": "AN1062", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0377#AN1062"}], "id": "x-mitre-analytic--62cf396f-01d6-4ab0-a3f5-bf75d90c2c40", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1062", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "kmod", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Directories where kernel modules or tampering could be staged (e.g., /lib/modules/).", "field": "MonitoredDirectories"}, {"description": "Regex or heuristic match to anomalous module names (e.g., suspicious entropy or gibberish).", "field": "ModuleNamePattern"}, {"description": "Monitor presence of suspicious preload values that mask processes or files.", "field": "LD_PRELOAD"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2929', 0, 118, '09-mitre-attack', 'retrieved', 'C3C765C96A79121886D4377A1E3FED97B500EE961EDB5B775B59B4E901A7BF26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
