VALUES ('doc-09-mitre-attack-p0-2930', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell-based tools (curl, wget, scp) initiate connections to external domains followed by creation of executable files on disk.", "external_references": [{"external_id": "AN0166", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0060#AN0166"}], "id": "x-mitre-analytic--62d55c57-54a3-4c6f-8d0d-2684fa26c347", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0166", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connect, execve, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file creation/modification", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "TCP connections", "name": "iptables:LOG", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match on curl, wget, rsync, etc. based on environment", "field": "ToolName"}, {"description": "Tunable filter to limit to suspicious file types (.sh, .bin, .elf)", "field": "DownloadExtension"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2930', 0, 105, '09-mitre-attack', 'retrieved', '2FB3822BEA3E36D05D9F6A8EAF1AE377A7F9350527E07F9A35C7E4AF523A490C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
