VALUES ('doc-09-mitre-attack-p0-2931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of excessive or programmatic access to Confluence spaces or pages, particularly by privileged users, through a combination of access logs, API usage, and identity context. Correlates logon sessions, user roles, and abnormal document viewing or export behavior. Identifies burst access patterns and tools/scripts abusing the Confluence API for mass enumeration or data scraping.", "external_references": [{"external_id": "AN1019", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0358#AN1019"}], "id": "x-mitre-analytic--62f43db8-4701-49b9-bb0e-a8fde37e5d07", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1019", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "access.content", "name": "saas:confluence", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "logon", "name": "saas:confluence", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "REST API access from non-browser agents", "name": "saas:confluence", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the time span (e.g., 5m, 1h) in which excessive access behavior becomes suspicious.", "field": "TimeWindow"}, {"description": "Privileged user roles (e.g., domain admins) should be excluded or flagged if found accessing documentation repositories.", "field": "UserContext"}, {"description": "The number of pages viewed or exported by a single user before triggering detection logic.", "field": "AccessThreshold"}, {"description": "User agent strings that may indicate scripted, automated, or non-interactive access methods.", "field": "AgentFilter"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2931', 0, 185, '09-mitre-attack', 'retrieved', '49D432FDA93A1A0FD7F43D323C5FA06E72D423B3AB7DF52003A91558C47E36AA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
