VALUES ('doc-09-mitre-attack-p0-2932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection correlates message events in email and collaboration tools (e.g., Outlook, Teams) that contain regex-like patterns resembling credentials, API keys, or tokens. Anomalous forwarding or bulk copy activity of chat/email content containing secrets is flagged. Suspicious behavior includes users pasting secrets into direct messages or attaching config files with passwords.", "external_references": [{"external_id": "AN0309", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0111#AN0309"}], "id": "x-mitre-analytic--631da3e4-5ecd-4dc9-966a-1c2633f8f24c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0309", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "MessageSend, MessageRead, or FileAttached events containing credential-like patterns", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customizable credential-detection regex (e.g., API_KEY=, bearer token formats) depending on enterprise apps in use", "field": "RegexPatterns"}, {"description": "Exclude known trusted domains or automated system-to-system messages", "field": "AllowedDomains"}, {"description": "Adjust correlation period for bulk credential sharing events", "field": "TimeWindow"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2932', 0, 142, '09-mitre-attack', 'retrieved', '8597D18E2C348266EF831D16155ADC4A501AAE8708A09A34ABE416EFF67203D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
