INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2933', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of timestamp-altering commands like `touch -a -m -t` or `touch -r`, particularly when executed by unusual users or in suspicious directories.", "external_references": [{"external_id": "AN1627", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0591#AN1627"}], "id": "x-mitre-analytic--632f7aef-f848-4147-95fa-2052bd373576", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1627", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Commands like `touch -r`, `debugfs`, `stat` used in sequence", "field": "MonitoredCommandList"}, {"description": "Suspicious paths like `/tmp/`, `/var/lib/`, `/mnt/esxi/`", "field": "FilePathRegex"}, {"description": "Mismatch between timestamp and file activity time", "field": "DeltaThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2933', 0, 105, '09-mitre-attack', 'retrieved', '7E0050D4D1CBF84117016C3F447D76DCEDA32930E7745E0A5BADD70C5B479300', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
