VALUES ('doc-09-mitre-attack-p0-2934', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual or unauthorized external remote access attempts (e.g., RDP, VPN, Citrix) → repeated failed logins followed by a successful session from uncommon geolocations or outside business hours → subsequent internal lateral movement or data exfiltration activities.", "external_references": [{"external_id": "AN1004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0354#AN1004"}], "id": "x-mitre-analytic--63583dcb-dbdc-4b9d-a261-3129de12327e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1004", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4776, 4625", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "VPN, Citrix, or remote access gateway logs showing external IP addresses", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Normal business hours for logon activity.", "field": "BusinessHours"}, {"description": "List of approved external IPs or VPN endpoints.", "field": "KnownRemoteIPs"}, {"description": "Number of failed logons before raising suspicion (e.g., >5).", "field": "FailedLogonThreshold"}, {"description": "Geographic regions allowed for remote access.", "field": "GeoIPWhitelist"}, {"description": "Time window to correlate failed attempts and success (e.g., 15m).", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2934', 0, 159, '09-mitre-attack', 'retrieved', '11C3F329FA993CD33F94BD500154C52A79B32DB8EEEDCE22F538D57120273AD8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
