VALUES ('doc-09-mitre-attack-p0-2940', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor unified DNS logs for abnormal domain queries with low lexical similarity to known domains, repeated failed lookups, and random string structures. Cross-check with process logs to confirm unusual origins (non-browser apps).", "external_references": [{"external_id": "AN1180", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0419#AN1180"}], "id": "x-mitre-analytic--63de336c-105c-4e8f-aefc-420a3eac32e9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1180", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "High entropy domain queries with multiple NXDOMAINs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Unexpected apps performing repeated DNS lookups", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude trusted CDN and cloud provider domains", "field": "ReputationFeedWhitelist"}, {"description": "Adjust score for word-based vs. letter-based DGAs", "field": "LexicalScoreThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2940', 0, 114, '09-mitre-attack', 'retrieved', 'D9B4FC055FAC4B686A45644462D0B59EA2B857D6720B10D6125C99C049C8C332', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_obje