VALUES ('doc-09-mitre-attack-p0-2941', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects disabling or reconfiguration of syslog or rsyslog services. Monitors sudden stops in logging daemons and suspicious execution of kill or service stop commands targeting syslog processes.", "external_references": [{"external_id": "AN0668", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0239#AN0668"}], "id": "x-mitre-analytic--63e17792-17f5-48ae-8002-da6b62b4bcaa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0668", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: service stop syslog, systemctl stop rsyslog, kill -9 syslog", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "unexpected termination of syslog or rsyslog processes", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Service name for syslog daemon, which can differ across distributions.", "field": "SyslogServiceName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2941', 0, 106, '09-mitre-attack', 'retrieved', 'B42F72594F637C66227D02AB192D42337D52DEA0212EAA112F73CA5F63F07A3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
