VALUES ('doc-09-mitre-attack-p0-2943', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects behavioral sequence where an adversary gains elevated privileges and clears event logs using native binaries (e.g., wevtutil), PowerShell, or direct file deletion of .evtx files.", "external_references": [{"external_id": "AN1472", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0532#AN1472"}], "id": "x-mitre-analytic--6482fa33-322b-47e4-a9f7-c2bcc92d132a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1472", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1102", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=23", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time range between log-clearing command and 1102 event; tunable to reduce false positives", "field": "TimeWindow"}, {"description": "Filter by admin/elevated users; allow tuning to detect abuse of high-privilege accounts", "field": "UserContext"}, {"description": "Match common variations of log-clearing commands like `Remove-EventLog`, `wevtutil cl`", "field": "CommandLinePattern"}, {"description": "Scope detection to Security, System, Application, or custom logs based on environment", "field": "TargetLogName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2943', 0, 142, '09-mitre-attack', 'retrieved', 'E47C92B917A6409E6EEF291DD0C79E03E8C6F99E3D0DC21238A42B8AEE265BAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
