VALUES ('doc-09-mitre-attack-p0-2947', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect unusual invocations of systemctl, service, or init scripts creating or modifying daemons. Monitor audit logs for execution of binaries from unexpected paths linked to service start/stop activity.", "external_references": [{"external_id": "AN0779", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0279#AN0779"}], "id": "x-mitre-analytic--65691cb3-a2b3-4c48-91d2-7088a047ebef", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0779", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "systemctl start/enable with uncommon binary paths", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Valid directories for service binaries to filter out benign changes", "field": "ServiceBinaryPaths"}, {"description": "Expected accounts performing service management (e.g., root/admin)", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2947', 0, 113, '09-mitre-attack', 'retrieved', 'F66148E7F9F14BCB974A1CEF0A469E9BB1EFB366E43C8852127F26B224E59BBE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
