VALUES ('doc-09-mitre-attack-p0-2948', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies tenant policy through changes to federation configuration, trust settings, or identity provider additions in Microsoft 365/AzureAD via Portal, PowerShell, or Graph API. Includes setting authentication to federated or updating federated domains.", "external_references": [{"external_id": "AN0756", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0270#AN0756"}], "id": "x-mitre-analytic--65a1926d-e504-4153-b19f-555e8a06e5a5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0756", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set federation settings on domain|Set domain authentication|Add federated identity provider", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "OperationName=SetDomainAuthentication OR Set-FederatedDomain", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify rare modification operations that are not part of standard admin lifecycle.", "field": "OperationName"}, {"description": "Filter by known administrators or service principals. Flag unknown initiators.", "field": "InitiatedBy"}, {"description": "Detect scripted modifications (e.g., PowerShell/Graph API vs Azure Portal).", "field": "UserAgent"}, {"description": "Correlate tenant policy changes with new sign-ins or token forgery attempts.", "field": "TimeWindow"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2948', 0, 150, '09-mitre-attack', 'retrieved', 'CE540486E21A5EBCFF4287C7550A4352EB970136AE7DAF7DA9BF0CFEC9A757D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
