VALUES ('doc-09-mitre-attack-p0-2949', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "macOS environmental validation behavioral chain: (1) System profiling through system_profiler, sysctl, and hardware discovery commands, (2) Network interface and configuration enumeration for geolocation and network environment validation, (3) Application installation and version discovery for software environment fingerprinting, (4) Security feature detection (SIP, Gatekeeper, XProtect status), (5) Conditional payload execution based on macOS-specific environmental criteria and System Integrity Protection bypass validation", "external_references": [{"external_id": "AN1553", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0562#AN1553"}], "id": "x-mitre-analytic--65abf5f4-ddb9-4eac-a926-1bef5d6b5c63", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1553", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process execution events for system discovery utilities (system_profiler, sysctl, networksetup, ioreg) with parameter analysis", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "File system access events with kFSEventStreamEventFlagItemRemoved, kFSEventStreamEventFlagItemRenamed flags for environmental artifact collection (/System/Library, /usr/sbin, plist files)", "name": "fs:fileevents", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "macOS-specific system discovery utilities commonly used for environmental validation", "field": "MacOSDiscoveryTools"}, {"description": "Security features and configurations typically validated by macOS execution guardrails", "field": "SecurityFeatureEnumeration"}, {"description": "Normal hardware discovery patterns to distinguish from environmental validation attempts", "field": "HardwareFingerprintBaseline"}, {"description": "Patterns indicating attempts to validate or bypass System Integrity Protection", "field": "SIPBypassIndicators"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2949', 0, 190, '09-mitre-attack', 'retrieved', 'AB0E6FF9D7403DD73F331BB2038DE33BD85A59A17BC20BF8E3E2E6ADBCA7112E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
