VALUES ('doc-09-mitre-attack-p0-2950', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of extensible server modules (e.g., Apache, Nginx, Tomcat) to load rogue plugins that initiate bash, connect to C2, or spawn reverse shells.", "external_references": [{"external_id": "AN1508", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0547#AN1508"}], "id": "x-mitre-analytic--65f89c21-d42a-4028-9865-122ea1079a77", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1508", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Module registration or stacktrace logs indicating segmentation faults or unknown module errors", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Outbound connections from web server binaries (apache2, nginx, php-fpm) to unknown external IPs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alternate install paths like /opt/httpd or user-compiled binaries", "field": "ServerBinaryPath"}, {"description": "Tunable to match expected versus suspicious outbound traffic patterns", "field": "OutboundPortRange"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2950', 0, 126, '09-mitre-attack', 'retrieved', '699F811B2015FF573DB2B6445FF9CD35ECD22AA1217C57B861708F76F087E4B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
