VALUES ('doc-09-mitre-attack-p0-2951', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain: (1) unified logs show application open/click or crash for Safari/Chrome/Office/Preview/archiver, (2) file write/extraction into ~/Downloads, /private/var/folders/* or ~/Library, (3) parent app spawns osascript/bash/zsh/curl/python or opens a quarantined app with Gatekeeper prompts, (4) network egress from child.", "external_references": [{"external_id": "AN1316", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0478#AN1316"}], "id": "x-mitre-analytic--66107cd1-c123-4ad5-bb0b-62d8a9a451a6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1316", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "opened document|clicked link|EXC_BAD_ACCESS|abort|LSQuarantine", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "create/write/rename in user-writable paths", "name": "fs:fileevents", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "exec", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "new outbound connection from exploited lineage", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "10–30 minute correlation window.", "field": "TimeWindow"}, {"description": "osascript, bash, zsh, curl, python, open -a Terminal, installer, tccutil misuse.", "field": "HighRiskChildren"}, {"description": "Flag new apps lacking com.apple.quarantine or with quarantine=''0081'' (downloaded then auto-opened).", "field": "QuarantineSignals"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2951', 0, 146, '09-mitre-attack', 'retrieved', '03C0CF07A89472118AA240301E3421AA55F45601EEB02ACA6A8616AFD37D1C47', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
