VALUES ('doc-09-mitre-attack-p0-2953', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of files with reversed filename extensions using Unicode RTLO character. Frequently used to deceive Gatekeeper and users in Safari or Mail-based phishing.", "external_references": [{"external_id": "AN1462", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0527#AN1462"}], "id": "x-mitre-analytic--667326a7-1f31-4ef1-92c1-6cb5241dadcf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1462", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.lsd", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/quarantine.log", "name": "fs:quarantine", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether user-facing tools display the spoofed name or the true extension", "field": "FilenameDisplay"}, {"description": "Whether the execution bypassed translocation or quarantine checks", "field": "GatekeeperBypassFlag"}, {"description": "Scope detection to untrusted or non-admin users", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2953', 0, 115, '09-mitre-attack', 'retrieved', 'E4DCE2DF696BB0E103CC33432EA275D132004768358CEF1075371AB098C0A5C2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
