INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2957', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of dscl or id/group commands to enumerate local system groups, often by post-exploitation tools or persistence checks.", "external_references": [{"external_id": "AN0319", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0114#AN0319"}], "id": "x-mitre-analytic--66923fbc-1d4d-4945-89dd-102a8e2c6122", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0319", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process:exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match on specific dscl paths like ''/Groups'' or known enumeration options.", "field": "CommandLineContains"}, {"description": "Used to scope out enumeration from user terminals versus background utilities.", "field": "InteractiveSession"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2957', 0, 92, '09-mitre-attack', 'retrieved', '3B6E92BF48F816818A734E33E2BC379E19CBD58938D0D152430A4037C00B7236', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
