VALUES ('doc-09-mitre-attack-p0-2958', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of anti-malware quarantining or flagging a tool, followed by a new binary written to disk with a similar function or name and a resumed process chain.", "external_references": [{"external_id": "AN0541", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0189#AN0541"}], "id": "x-mitre-analytic--66bab948-9baa-4f5c-b259-333eb2ac08ad", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0541", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open, rename", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "file_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "ThreatDetected, QuarantineLog", "name": "EDR:detection", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable list of directories often abused for dropped binaries (e.g., /tmp, ~/.cache, /opt/soft/).", "field": "PathWatchlist"}, {"description": "Limit how far up the tree to trace tool modification behavior for detection.", "field": "ProcessAncestryDepth"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2958', 0, 124, '09-mitre-attack', 'retrieved', 'C36A3DE647028C7AE7050FE975D51CA81E76391C50AD66F1CF857EFEF7563CE9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
