VALUES ('doc-09-mitre-attack-p0-2960', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects rogue Wi-Fi access points broadcasting the same SSID as legitimate APs with stronger signal strength, unexpected MAC/BSSID values, or inconsistent encryption settings. Correlates authentication attempts, captive portal redirections, and anomalous traffic flows through unauthorized APs.", "external_references": [{"external_id": "AN1069", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0379#AN1069"}], "id": "x-mitre-analytic--670462e3-6c3e-4779-af75-2a0424a5d221", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1069", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Multiple APs advertising the same SSID but with different BSSID/MAC or encryption type", "name": "WLANLogs:Association", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Probe responses from unauthorized APs responding to client probe requests", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Failed authentication requests redirected to non-standard portals", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline of authorized SSIDs; deviations may indicate rogue AP.", "field": "KnownSSIDs"}, {"description": "Whitelist of BSSID/MAC addresses mapped to corporate SSIDs.", "field": "AllowedBSSIDs"}, {"description": "Used to flag unusually strong signals from unexpected APs.", "field": "SignalStrengthThreshold"}, {"description": "Trusted login domains; unrecognized portals may be malicious.", "field": "CaptivePortalDomains"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2960', 0, 167, '09-mitre-attack', 'retrieved', 'E2A34E580EF8403F5A83E5325DA1FF9B0B755858210D3065ADCDA0265B033DB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
