VALUES ('doc-09-mitre-attack-p0-2961', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).", "external_references": [{"external_id": "AN0160", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0058#AN0160"}], "id": "x-mitre-analytic--671050c7-7e86-4be7-9ab4-aa9c763fad44", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0160", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem: com.apple.network", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process_events/socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known services abused for D2 (e.g., iCloud, Dropbox)", "field": "TargetService"}, {"description": "Useful to isolate rare users accessing web services for C2", "field": "UserContext"}, {"description": "Max time gap between dead drop resolver fetch and follow-on traffic", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2961', 0, 117, '09-mitre-attack', 'retrieved', '017FF3DCE69AC430D7B0030179D7312C6387DBD15DE74250A4AA44AB9D60EA4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowled