VALUES ('doc-09-mitre-attack-p0-2962', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of file access from mounted SMB shares followed by copy or exfil commands from Terminal or script interpreter processes.", "external_references": [{"external_id": "AN1147", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0410#AN1147"}], "id": "x-mitre-analytic--67ca77c9-074f-4c93-9592-cabe9ba8a831", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1147", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "filesystem and process events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "open/read/mount operations", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Script interpreters may vary (e.g., zsh, bash, python, osascript).", "field": "ProcessPath"}, {"description": "Network drive mount points may differ across enterprises.", "field": "SharePath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2962', 0, 98, '09-mitre-attack', 'retrieved', 'B087E13624EB75FD79B9F74E51417EC251ED944B67A569F3A7C3877BA3885E2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
