VALUES ('doc-09-mitre-attack-p0-2964', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies externally-facing web content by accessing and overwriting hosted HTML/JS/CSS files, typically following web shell deployment, credential abuse, or exploitation of web application vulnerabilities.", "external_references": [{"external_id": "AN1622", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0590#AN1622"}], "id": "x-mitre-analytic--67febd8b-36fe-4f72-8647-95fe449ecb5d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1622", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Unusual POST requests to admin or upload endpoints", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Web root folder varies by environment, e.g., C:\\inetpub\\wwwroot", "field": "target_directory"}, {"description": "May vary based on which service account hosts the website", "field": "UserContext"}, {"description": "Time between webshell upload and file overwrite may vary", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitr