VALUES ('doc-09-mitre-attack-p0-2966', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitoring modification and execution of user or system logon scripts such as in registry Run keys or startup folders.", "external_references": [{"external_id": "AN0311", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0112#AN0311"}], "id": "x-mitre-analytic--682bd971-c540-4c16-a25a-b928201a320d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0311", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=106", "name": "WinEventLog:TaskScheduler", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Registry path that may vary by user or policy configuration.", "field": "TargetObject"}, {"description": "Can be tuned to known parent processes to reduce false positives.", "field": "ParentProcessName"}, {"description": "Logon activity clustered during specific user shifts.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2966', 0, 113, '09-mitre-attack', 'retrieved', 'B2A91885CB0C1698A3BB68E53FCC2C6959182DE4D8969DCE3CE4B2224E3963C4', 'v