VALUES ('doc-09-mitre-attack-p0-2967', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual ESXi processes (vmx, hostd) reading datastore files and generating outbound HTTPS traffic toward external cloud storage endpoints. Defender perspective: anomalous datastore activity followed by network transfers to Dropbox, AWS S3, or other storage services.", "external_references": [{"external_id": "AN1574", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0570#AN1574"}], "id": "x-mitre-analytic--682f84f1-5571-4d41-b071-53c8f72a88f1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1574", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "datastore file access", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "network flows to external cloud services", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for outbound data exfiltration from ESXi datastore files.", "field": "DatastoreTransferThreshold"}, {"description": "Whitelist of sanctioned storage providers used by admins for backup operations.", "field": "ApprovedStorageServices"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2967', 0, 119, '09-mitre-attack', 'retrieved', '9B1EC196C0C4AA8F05DDC632ABFCAF5082A53C516983350EC9508839B9B82401', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
