VALUES ('doc-09-mitre-attack-p0-2968', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous Kerberos activity such as forged or stolen tickets by correlating malformed fields in logon events, RC4-encrypted TGTs, or TGS requests without corresponding TGT requests. Also detects suspicious processes accessing LSASS memory for ticket extraction.", "external_references": [{"external_id": "AN1443", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0522#AN1443"}], "id": "x-mitre-analytic--685b05a6-92a3-417d-a917-8e7689e43237", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1443", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4672, 4634", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for Kerberos TGT lifetimes deviating from domain defaults.", "field": "TicketLifetimeThreshold"}, {"description": "Monitor for downgraded encryption types (e.g., RC4) in Kerberos tickets.", "field": "EncryptionTypes"}, {"description": "List of expected processes accessing LSASS; deviations may be suspicious.", "field": "ProcessAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2968', 0, 126, '09-mitre-attack', 'retrieved', 'EB9F5D0320981E8D633A4BD9147