VALUES ('doc-09-mitre-attack-p0-2969', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects non-browser processes that establish encrypted outbound connections (e.g., TLS/SSL) to unfamiliar or atypical destinations for the host/user, following a data staging or compression event.", "external_references": [{"external_id": "AN1413", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0512#AN1413"}], "id": "x-mitre-analytic--6869578d-d3e8-4a3c-9717-0a188dc0bafe", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1413", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "ssl.log - Certificate Analysis", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlates file access, encryption, and network transmission within a timeframe (e.g., 5 minutes).", "field": "TimeWindow"}, {"description": "Blocks or flags untrusted certificate authorities in SSL/TLS handshakes.", "field": "CertificateIssuerDenylist"}, {"description": "Whitelist for known-good applications allowed to use encrypted outbound traffic.", "field": "BinaryAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2969', 0, 135, '09-mitre-attack', 'retrieved', 'ADAF133680294C4EE34F27F3757DDD095490B68B78B1E5BDC40D0B6CF95BA7A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
