VALUES ('doc-09-mitre-attack-p0-2970', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Non-standard port/protocol pairings or low-entropy ICMP traffic resembling tunneling patterns (e.g., fixed-size pings with delays).", "external_references": [{"external_id": "AN1258", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0457#AN1258"}], "id": "x-mitre-analytic--688ed638-d3ba-47dc-baa7-16b16a9fe9c8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1258", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ICMP/UDP protocol anomaly", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "conn.log, icmp.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "ICMP/UDP packet content entropy filter to identify encoded payloads.", "field": "ProtocolEntropyThreshold"}, {"description": "Long ICMP/UDP sessions beyond expected limits (e.g., >5min).", "field": "SessionDurationThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2970', 0, 93, '09-mitre-attack', 'retrieved', 'A0E7B54BDA5BE6531EC90DC19877094986BCDD3FC89278843F1EDC973292A556', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
