VALUES ('doc-09-mitre-attack-p0-2972', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors for processes reading sensitive files then immediately initiating unusual outbound connections or bulk transfer sessions over persistent sockets, particularly with encrypted or binary payloads.", "external_references": [{"external_id": "AN0989", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0348#AN0989"}], "id": "x-mitre-analytic--6914dd62-46a6-4de4-9c0b-afe1cb5b075d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0989", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "conn.log + files.log + ssl.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "session stats with bytes_out > bytes_in", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for high-entropy payloads indicative of encoded or encrypted exfil data.", "field": "OutboundEntropyScore"}, {"description": "Defines length of time over which transfer size must be aggregated to trigger detection.", "field": "ConnectionDuration"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2972', 0, 128, '09-mitre-attack', 'retrieved', '1EE9A3BDC5C0B0AAEF9CDE28C228328137EA2D98939A6B709531D66E2E7C1C2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
