VALUES ('doc-09-mitre-attack-p0-2974', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of changes to /etc/rc.local.d/local.sh or rc.local during post-boot script execution with abnormal commands or additions.", "external_references": [{"external_id": "AN0660", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0237#AN0660"}], "id": "x-mitre-analytic--69562961-14e6-42a7-9f8a-24ac00f6404e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0660", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "boot logs", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "admin command usage", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable script section edited by adversary (beginning, end, inline)", "field": "script_section"}, {"description": "Nature of embedded command or payload affects detection scope", "field": "command_type"}, {"description": "Boot vs. manual script re-invocation", "field": "execution_trigger"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2974', 0, 102, '09-mitre-attack', 'retrieved', 'F165EBEDFA7B587906D2D4D2C084AE3B689C6B5119811735D0EFDB50ECAD999B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
