VALUES ('doc-09-mitre-attack-p0-2975', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects remote write activity across cloud VMs or object storage buckets within the same region/account that correlate with data aggregation across hosts.", "external_references": [{"external_id": "AN0198", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0071#AN0198"}], "id": "x-mitre-analytic--696b98e8-10fd-4c7a-bb80-302baca34e60", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0198", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetObject, CopyObject", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "Traffic between instances", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "process execution across cloud VM", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Destination naming convention used for staging (e.g., temp-store)", "field": "BucketNamePatterns"}, {"description": "IAM role or user performing multi-host write ops", "field": "IAMContext"}, {"description": "Burst of high-volume inter-VM transfers indicating staging", "field": "TransferWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2975', 0, 118, '09-mitre-attack', 'retrieved', 'C6C2E3DC97E96860A43509556253