VALUES ('doc-09-mitre-attack-p0-2976', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of file enumeration commands (e.g., ''dir'', ''tree'') from non-standard processes or unusual user contexts, followed by recursive directory traversal or access to sensitive locations.", "external_references": [{"external_id": "AN1040", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0370#AN1040"}], "id": "x-mitre-analytic--69d9d158-aa43-4b73-b9a4-f1a2dc6c13c1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1040", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allows tuning based on tools/scripts used for enumeration (e.g., tree, dir /s /b)", "field": "CommandLineRegex"}, {"description": "Scoping for standard vs elevated or service accounts", "field": "UserContext"}, {"description": "Defines burst activity over short periods (e.g., >50 directory queries in 30s)", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2976', 0, 118, '09-mitre-attack', 'retrieved', '2D064F362C2FE0474C9D2C78B1D4BFA4CED7E7428F7857F2E72F3D4172AFAB4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
