VALUES ('doc-09-mitre-attack-p0-2977', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of `ifconfig`, `ip a`, or access to `/proc/net/` indicating collection of local interface and route configuration.", "external_references": [{"external_id": "AN0560", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0195#AN0560"}], "id": "x-mitre-analytic--6a57daad-9d2c-4851-a46e-b6ebac607a4c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0560", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match regex for variations in enumeration syntax (e.g., `ip -4 addr show`)", "field": "CommandLinePattern"}, {"description": "Differentiate scripted versus interactive sessions", "field": "InteractiveShellIndicator"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2977', 0, 85, '09-mitre-attack', 'retrieved', 'E343719A3B206B53EF398284CED03A5E4D17D414D5149392E5819ED64B156AE6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
