VALUES ('doc-09-mitre-attack-p0-2978', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates zsh shell configuration file changes (e.g., ~/.zshrc, ~/.zlogin, /etc/zprofile) with execution of unauthorized binaries or unexpected network activity triggered on Terminal.app launch.", "external_references": [{"external_id": "AN0060", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0020#AN0060"}], "id": "x-mitre-analytic--6acf01f9-723e-499b-8774-3fa689a36ded", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0060", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launch of Terminal.app or shell with non-standard environment setup", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ES_EVENT_TYPE_NOTIFY_WRITE, targeting .zshrc, .zlogin, .zprofile", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customizable list of shell config files considered sensitive for detection.", "field": "FileTargetList"}, {"description": "Used to distinguish benign from potentially obfuscated commands written to config files.", "field": "PayloadEntropyThreshold"}, {"description": "Scoping based on user login class, e.g., administrative vs standard users.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2978', 0, 128, '09-mitre-attack', 'retrieved', '92E57828E76B06F76AE968AAF745D8C8D885AA87A00EF632DA9758208E3CDF5C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
