VALUES ('doc-09-mitre-attack-p0-2979', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized wireless associations by monitoring wpa_supplicant logs, NetworkManager events, and system calls related to interface state changes. Anomalies include repeated association failures, new SSIDs outside baselined values, and rogue AP connections.", "external_references": [{"external_id": "AN1477", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0536#AN1477"}], "id": "x-mitre-analytic--6ad3d8bb-fc6f-45fb-b44e-871c263230d8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1477", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New Wi-Fi connection established or repeated association failures", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "ioctl: Changes to wireless network interfaces (up, down, reassociate)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex-based whitelist of corporate SSIDs; anomalous matches indicate suspicious activity.", "field": "AllowedSSIDRegex"}, {"description": "Number of failed association attempts allowed before triggering detection.", "field": "RetryThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2979', 0, 123, '09-mitre-attack', 'retrieved', '6557970BA1063070F4D5937A8612638095C19140A4B14E430C2A3E11F77D8BF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
