INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2980', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identify use of ''shutdown'', ''reboot'', or ''osascript'' system shutdown invocations within unified logs and track unexpected shutdown sequences initiated by GUI or script. Cross-reference with user activity or absence thereof.", "external_references": [{"external_id": "AN1540", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0559#AN1540"}], "id": "x-mitre-analytic--6b11c208-4dbf-4d52-9254-524e622c6250", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1540", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "shutdown -h now or reboot", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "System shutdown or reboot requested", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scripted vs interactive shutdowns.", "field": "LaunchMechanism"}, {"description": "May vary depending on macOS version and unified log verbosity.", "field": "LogGranularity"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2980', 0, 109, '09-mitre-attack', 'retrieved', 'A92B32DDAF695082D44287F094AD0E0BFBF6EA4784AEEFB566BB3031EFBD4784', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
