VALUES ('doc-09-mitre-attack-p0-2982', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications or launchd services invoking RSA or public-key routines from the Security framework, followed by outbound SSL/TLS sessions with unrecognized certs or anomalous handshakes. Defender observes unified logs of API calls and suspicious network entropy.", "external_references": [{"external_id": "AN1498", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0543#AN1498"}], "id": "x-mitre-analytic--6b63caad-5d8d-4f23-be77-4e81d8904da6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1498", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process invoking SecKeyCreateRandomKey or asymmetric crypto APIs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "TLS connections with abnormal handshake sequence or self-signed cert", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known legitimate DoH/SSL endpoints.", "field": "TrustedDoHEndpoints"}, {"description": "Entropy scoring for outbound payloads.", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2982', 0, 115, '09-mitre-attack', 'retrieved', 'ADE6EBD2E7E08F8E98EE5235E42D9473AF891DC43E8AA317D3E38A81F4AF77DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved",