VALUES ('doc-09-mitre-attack-p0-2983', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects firmware or script relocation attempts (e.g., CLI-based `copy`, `move`, or `rename`) between temporary partitions and config startup folders on routers or switches.", "external_references": [{"external_id": "AN1219", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0439#AN1219"}], "id": "x-mitre-analytic--6b8a97fe-4e51-4409-9eab-f2795eb2ec74", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1219", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command audit", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted config folders like flash:/startup-config or nvram:", "field": "StartupConfigPath"}, {"description": "e.g., `copy tftp flash`, `rename`, `move flash:/old.bin flash:/new.bin`", "field": "CommandPatternMatch"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2983', 0, 91, '09-mitre-attack', 'retrieved', 'E365F8AE356EF1C7511918D398C4CC98357E0E62CACC0E00E18E7AC85C1297A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
