VALUES ('doc-09-mitre-attack-p0-2990', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of cloud messaging platforms to send mass spam or consume quota-based resources.", "external_references": [{"external_id": "AN0746", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0267#AN0746"}], "id": "x-mitre-analytic--6e5bfc6b-3f07-426b-ac9f-6a8cc6b591c3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0746", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SendMessage", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "High-volume API calls or traffic via messaging or webhook service", "name": "saas:application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Max allowable outbound message rate per user/account", "field": "MessageRateThreshold"}, {"description": "Known authorized API clients for messaging usage", "field": "APIKeyList"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2990', 0, 93, '09-mitre-attack', 'retrieved', 'A3967CDD9825244191394BCC33DB40CCBCC9E243062D39902D79F00D9BE5A55D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
