INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2991', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary behavior where a file with a benign-looking first extension (e.g., .txt, .jpg) ends with a dangerous second extension (e.g., .exe, .scr), and is subsequently executed. The behavior chain includes file creation with misleading naming and user or system-initiated process execution from the disguised file.", "external_references": [{"external_id": "AN1033", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0366#AN1033"}], "id": "x-mitre-analytic--6eab694d-ea06-4487-99c4-0e21279530e8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1033", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of extensions typically used to masquerade malicious files (.txt, .jpg, .doc, .pdf)", "field": "benign_extensions"}, {"description": "List of true executable extensions that may be abused (.exe, .scr, .hta, .lnk)", "field": "dangerous_extensions"}, {"description": "Specific directories to focus on (e.g., Downloads folder, %TEMP%, Desktop)", "field": "monitored_paths"}, {"description": "Duration between file creation and process execution to correlate activity", "field": "TimeWindow"}, {"description": "Whether the behavior occurs in a standard user session or elevated context", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2991', 0, 170, '09-mitre-attack', 'retrieved', '50A034B0FC7DA29AF522D0955438E223B2A4969D35992BE57FAB9692D7D51F0B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
