INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2993', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary manipulation of Extra Window Memory (EWM) in a GUI process, where the attacker uses SetWindowLong or SetClassLong to redirect function pointers to injected shellcode stored in shared memory, then triggers execution via a window message like SendNotifyMessage.", "external_references": [{"external_id": "AN0608", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0217#AN0608"}], "id": "x-mitre-analytic--6ec034ac-289d-48d1-b310-021dfbf7087b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0608", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "SetWindowLong, SetClassLong, NtUserMessageCall, SendNotifyMessage, PostMessage", "name": "etw:Microsoft-Windows-Win32k", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex to scope suspicious or uncommon GUI class names registered by user-created processes", "field": "TargetWindowClassRegex"}, {"description": "API calls like SendNotifyMessage or PostMessage that deliver execution to the shellcode location", "field": "ExecutionTriggerWindowMessage"}, {"description": "Set byte count thresholds on suspicious memory writes to known shared sections", "field": "SharedSectionWriteThreshold"}, {"description": "Define max time (e.g., <10s) between API call to set window memory and the message call to trigger it", "field": "TimeWindowSetWindowLongToMessageTrigger"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2993', 0, 169, '09-mitre-attack', 'retrieved', '99B5D6AA4801C36084C1656F26F17E0D62816BCA62DC4A7D850624B1D31234F5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
