INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2994', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects files or processes where execution results in frequent re-creation or modification of ELF binaries or interpreter scripts, often using chmod + execve with abnormal entropy.", "external_references": [{"external_id": "AN0920", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0324#AN0920"}], "id": "x-mitre-analytic--6ed3efbf-c060-4c7f-8d8b-0e93f65a0790", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0920", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "mmap", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "chmod", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to alert on write followed by chmod + exec in quick succession.", "field": "WriteExecThreshold"}, {"description": "Detect high deviation from average entropy score of baseline ELF/script files.", "field": "FileEntropyDeviation"}, {"description": "Abnormal burst executions of file with identical functionality but varying hash.", "field": "ExecutionFrequency"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2994', 0, 127, '09-mitre-attack', 'retrieved', 'A443FB44B7806A137FD644A571F9425D8D37209E6DA6B7BC33BB7B62A232946E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
