INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2995', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of anomalous driver and firmware interactions, including unsigned or unexpected firmware updates, driver loads linked to hardware components, and suspicious use of privileged APIs to read/write firmware or controller memory.", "external_references": [{"external_id": "AN0916", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0323#AN0916"}], "id": "x-mitre-analytic--6f2fdf37-f603-4264-aed1-24fe2d1aa094", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0916", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"channel": "Firmware integrity verification failures or mismatches against expected UEFI/firmware image baselines", "name": "firmware:integrity ", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment-specific list of baseline firmware images for integrity comparison", "field": "KnownGoodFirmwareHashes"}, {"description": "Drivers approved for loading in production environments", "field": "DriverAllowList"}, {"description": "Correlation period between firmware modification attempt and abnormal driver or process behavior", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2995', 0, 130, '09-mitre-attack', 'retrieved', '4141EF484E70DD039D6E90499A9A05A7E8E6B869282C0A3537650D0C93F4CC65', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
