INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2997', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of file write-access to USB-mount directories (e.g., /media/, /run/media/) followed by same-file access or execution on another host.", "external_references": [{"external_id": "AN0248", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0090#AN0248"}], "id": "x-mitre-analytic--6f8fdb88-56d1-454e-9a35-3b7170011ca2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0248", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write/open, FIM audit", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Removable media mount notification", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Typical mount paths to monitor (e.g., /media/usb*, /run/media/username/*).", "field": "MountPathPattern"}, {"description": "Tunable detection window to correlate read/write between different hosts within a short interval (e.g., <15m).", "field": "TimeWindowBetweenHosts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2997', 0, 104, '09-mitre-attack', 'retrieved', '474B48FEF7590733379053C484E542DE8D70C93B7B8648785EDB72E85A7F62DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
