INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2999', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious OAuth application integrations within Office 365 or Google Workspace environments, such as new app registrations, unexpected consent grants, or privilege assignments. Defenders should correlate between application creation/modification events and associated user or service principal activity to identify persistence via app integrations.", "external_references": [{"external_id": "AN1487", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0539#AN1487"}], "id": "x-mitre-analytic--6feb9746-7b2c-4f6f-92c9-bfdb14eddddc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1487", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add app role assignment grant to user: Consent to application by privileged or unexpected accounts", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "Consent to application: OAuth application consent granted to service principal", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines which accounts are authorized to consent or register applications; deviations indicate possible adversary persistence.", "field": "PrivilegedUserList"}, {"description": "Defines which OAuth scopes are considered risky (e.g., Mail.ReadWrite, Files.ReadWrite.All).", "field": "ApplicationScopeThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2999', 0, 149, '09-mitre-attack', 'retrieved', 'AC9D2B261E65E5D61708325CD81CFB8050A30C38A4D1E66968570AE07EBAAB4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
