VALUES ('doc-09-mitre-attack-p0-3000', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects log-clearing behavior by correlating suspicious command execution targeting log files under /var/log/, anomalous deletions or truncations of system logs, and unusual child processes (e.g., shell pipelines or redirections).", "external_references": [{"external_id": "AN1438", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0520#AN1438"}], "id": "x-mitre-analytic--6ffa0db8-a088-4e7a-b8e5-50a204762cca", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1438", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "PATH", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "The time window used to correlate log file interaction and suspicious command execution.", "field": "TimeWindow"}, {"description": "Regex pattern used to match monitored log file paths (e.g., /var/log/auth.log).", "field": "LogFilePathPattern"}, {"description": "User or group (e.g., root) that should trigger higher severity detection.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3000', 0, 124, '09-mitre-attack', 'retrieved', 'E2C5261EAA7555BAC395D5BF2653233714BDA1B1424A66A6DD3AB9B73EC16813', 'v1', '{"source_id": 