VALUES ('doc-09-mitre-attack-p0-3001', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary enumeration of local user accounts using Net.exe, WMI, or PowerShell.", "external_references": [{"external_id": "AN0846", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0303#AN0846"}], "id": "x-mitre-analytic--6ffbdad6-3d60-452b-9e04-a8292d0125e9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0846", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects variations of ''net user'', ''net localgroup'', ''Get-LocalUser''.", "field": "CommandLinePattern"}, {"description": "Restrict monitoring to low-privileged or unexpected users executing enumeration.", "field": "UserContext"}, {"description": "Tune for bursts of enumeration commands in short succession.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3001', 0, 91, '09-mitre-attack', 'retrieved', 'C197D3F692D96E94B5B4302EF27E2C96DDFD93F5BB1D6E42BD40E6985568E697', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
