INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Container orchestrator logs show crashlooping pods, repeated resource exhaustion, or malicious binaries with infinite loops consuming systemd/cgroup limits.", "external_references": [{"external_id": "AN0588", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0208#AN0588"}], "id": "x-mitre-analytic--7027622a-7a33-4189-a500-c54eef3467b6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0588", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CrashLoopBackOff, OOMKilled, container restart count exceeds threshold", "name": "kubernetes:events", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Container exited with non-zero code repeatedly in short period", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of container restarts within a time window", "field": "RestartCountThreshold"}, {"description": "Payload entropy of container image as an anomaly factor", "field": "ContainerImageEntropy"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3002', 0, 106, '09-mitre-attack', 'retrieved', 'C786E6FE361ACEEFCD390C0665DC68DCDCBBC561F7E87BDB429CDA1C09ECF652', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
