VALUES ('doc-09-mitre-attack-p0-3003', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T17:34:13.876Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects processes or users modifying Windows Defender Firewall profiles, policies, or rules followed by measurable network exposure changes. Correlates firewall management execution, registry/policy mutation, service state changes, and subsequent inbound or outbound connectivity inconsistent with baseline administration.", "external_references": [{"external_id": "AN2043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0901#AN2043"}], "id": "x-mitre-analytic--702db8b6-641f-4526-a0d0-a5a62c499508", "modified": "2026-05-12T16:30:18.378Z", "name": "Analytic 2043", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"channel": "EventCode=7036", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=5156, 5157", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known administrators allowed to manage host firewall settings", "field": "AuthorizedAdminAccounts"}, {"description": "Approved change windows where firewall modifications are expected", "field": "MaintenanceWindow"}, {"description": "Time window to correlate firewall change with new connections/listeners", "field": "ExposureCorrelationWindow"}, {"description": "Ports of concern such as RDP, SMB, WinRM, SSH, custom admin ports", "field": "SensitivePorts"}, {"description": "Expected parent processes such as SCCM, Intune agent, GPO client", "field": "AllowedManagementParents"}, {"description": "Detect widening from subnet/local scope to Any/0.0.0.0/0", "field": "RuleScopeThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3003', 0, 195, '09-mitre-attack', 'retrieved', '9E52204F8A2C0802AC4F769F168DA6CEA0226BC8F6A084ACBB53B5474C466990', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
