VALUES ('doc-09-mitre-attack-p0-3004', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes that typically do not perform cryptographic operations loading symmetric encryption libraries (e.g., bcryptprimitives.dll, aes.dll), then initiating outbound connections with high-entropy payloads. Defender correlates process creation, DLL load, and anomalous encrypted traffic patterns.", "external_references": [{"external_id": "AN0400", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0143#AN0400"}], "id": "x-mitre-analytic--704bd588-a82b-4139-92ef-6dc6a48581c8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0400", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Processes normally expected to use symmetric crypto (e.g., disk encryption, secure messaging).", "field": "AllowedCryptoProcesses"}, {"description": "Minimum payload entropy score for flagging unusual encrypted sessions.", "field": "EntropyThreshold"}, {"description": "Correlation window between module load and encrypted connection creation.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3004', 0, 124, '09-mitre-attack', 'retrieved', '143F8EA4C7D17708EBFB3430A4FDC81262CBE9547065377F63AFED7DF21CA326', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
