VALUES ('doc-09-mitre-attack-p0-3005', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Repeated failed authentication attempts to container APIs, control planes, or login shells across many user names using same password", "external_references": [{"external_id": "AN1341", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1341"}], "id": "x-mitre-analytic--70500794-7d3d-4538-8e88-ed6d5e998a8a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1341", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Failed login", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect spray attempts scoped to single pod vs full cluster", "field": "OrchestrationScope"}, {"description": "Limit detection to non-service accounts to reduce noise", "field": "ServiceAccountFilter"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3005', 0, 89, '09-mitre-attack', 'retrieved', 'B8E9CDD65761FA8019659C23325E35B2670A55B5B9600A4EFE042FF786FAB575', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
