VALUES ('doc-09-mitre-attack-p0-3006', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of attempts to disable or tamper with Windows Event Logging. This includes stopping or disabling the EventLog service, modifying registry keys related to EventLog and Autologger, using `auditpol` or `wevtutil` to disable categories or clear audit policies, and detecting suspicious gaps or resets in event logs. Defenders observe registry changes, service state changes, process execution of disabling commands, and anomalies in event record sequences.", "external_references": [{"external_id": "AN0535", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0187#AN0535"}], "id": "x-mitre-analytic--705168ad-1701-453c-9aea-c75029492b89", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0535", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7035", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "EventCode=1102", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of accounts authorized to legitimately modify audit policies or disable services.", "field": "AuthorizedAdminAccounts"}, {"description": "Correlation window between registry modification, service stop, and audit policy commands.", "field": "TimeWindow"}, {"description": "Customizable set of monitored services such as EventLog, Sysmon, or custom loggers.", "field": "ServiceNames"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3006', 0, 173, '09-mitre-attack', 'retrieved', '15E95D7ED66932C99F61D78AE494C6FDFD6A7D684CBBC0585FABCB4D77D8D7CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
