INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3010', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects usage of `at` command to schedule jobs, followed by job execution and modification of job files under /var/spool/cron/atjobs.", "external_references": [{"external_id": "AN0944", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0333#AN0944"}], "id": "x-mitre-analytic--70e28077-c8a6-425f-94c7-a74a7140c7ce", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0944", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitoring additional paths (e.g., tmp-mounted spool dirs) for modified at jobs.", "field": "AtJobPath"}, {"description": "Expected delay between at job creation and execution.", "field": "ScheduleLatency"}, {"description": "High entropy or obfuscation in at job payloads.", "field": "JobScriptEntropy"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3010', 0, 106, '09-mitre-attack', 'retrieved', 'C4C02E1ADB73AE5F8F812DDFAB3604C5AA8DFEBF68DDD50AD9621D985197847F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
