INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3011', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Links inbound network access to SSHD/SMB/NFS/Databases or custom daemons with subsequent daemon crash/restart, core dump, or spawning of shells/reverse shells from the service context, indicating remote exploitation.", "external_references": [{"external_id": "AN0328", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0118#AN0328"}], "id": "x-mitre-analytic--70e3066e-6ba3-444b-8e88-dfc3575f2706", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0328", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "kernel|systemd messages indicating ''segmentation fault''|''core dumped''|''service terminated unexpectedly'' for sshd, smbd, vsftpd, mysqld, httpd, etc.", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve of /bin/sh,/bin/bash,/usr/bin/curl,/usr/bin/python by service accounts (e.g., apache, mysql, nobody) immediately after inbound network activity.", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Inbound connections to monitored service ports from external or unusual internal sources; rapid follow-on lateral connections from the same host.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Linux daemons to watch (sshd, smbd, nfsd, httpd/nginx, mysqld, postgres, redis).", "field": "ServiceNames"}, {"description": "Paths indicating crash artifacts (/var/crash, /var/lib/systemd/coredump).", "field": "CoreDumpPaths"}, {"description": "Paths/users allowed to spawn shells from services (default: empty).", "field": "ShellSpawnAllowlist"}, {"description": "Correlation window (default 10m).", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3011', 0, 173, '09-mitre-attack', 'retrieved', 'CD84A56EF5D621EAE9312A6CB82F73E11E1056C45795C00701F40369B29AD2E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
