INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3012', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Token retrieval from instance metadata endpoints such as AWS IMDS or Azure IMDS, followed by API usage using the obtained token from non-standard applications.", "external_references": [{"external_id": "AN1424", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0515#AN1424"}], "id": "x-mitre-analytic--70f6482e-e93b-45a5-9b8c-ba7fd0c8220a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1424", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetInstanceIdentityDocument or IMDSv2 token requests", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "Use of temporary credentials issued from IMDS access", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May need tuning for known automation tools versus unexpected curl usage", "field": "UserAgent"}, {"description": "Correlate retrieval and use of token within expected timeout window", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3012', 0, 113, '09-mitre-attack', 'retrieved', '9B90CD35538FDB54D5CB72E47BFB4968B6EF04FDFC075645B8A1A707B157DA9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
