VALUES ('doc-09-mitre-attack-p0-3014', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of email forwarding/redirect rules in Exchange Online via New-InboxRule or transport rule cmdlets, including auto-forwarding address field usage.", "external_references": [{"external_id": "AN1591", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0576#AN1591"}], "id": "x-mitre-analytic--710aa303-3e9f-4170-95a4-b2caf5f827fd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1591", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New-InboxRule, Set-InboxRule", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"channel": "X-MS-Exchange-Organization-AutoForwarded", "name": "m365:messagetrace", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Destination domain may vary; commonly tuned per org policies.", "field": "ForwardingSMTPAddress"}, {"description": "Differentiate service/admin users vs standard user population.", "field": "ActorId"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3014', 0, 94, '09-mitre-attack', 'retrieved', '85C1E2D42C44E36033F5EB34B1313B2E0DFA475CEA74521CDD1978824E8B0AED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
