INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3015', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe unauthorized or anomalous changes to NAT configurations, including the addition of new translation rules or modifications to existing ones. Suspicious behaviors include sudden introduction of NAT mappings bridging segmented networks, new port address translation rules that obscure true source IPs, or traffic flows inconsistent with expected network design. Multi-event correlation includes detecting configuration changes on routers/firewalls, followed by traffic traversing unexpected internal/external address pairs.", "external_references": [{"external_id": "AN0465", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0163#AN0465"}], "id": "x-mitre-analytic--72033f2d-a943-40be-862c-051317ec541c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0465", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "NAT table modification (add/update/delete rule)", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Source/destination IP translation inconsistent with intended policy", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time correlation window between NAT rule change and unexpected traffic; adjustable to align with change management practices.", "field": "TimeWindow"}, {"description": "Whitelist of approved NAT policies and rules; prevents false positives from legitimate operations.", "field": "AuthorizedNATRules"}, {"description": "Threshold for abnormal traffic across NAT; tuned to differentiate testing from large-scale exfiltration or bridging.", "field": "TrafficVolumeThreshold"}, {"description": "Specific interfaces or zones monitored for NAT translation; allows tuning for internal vs. external-facing boundaries.", "field": "InterfaceScope"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3015', 0, 201, '09-mitre-attack', 'retrieved', 'F2F171D235560F44825F08236A83636F3FCCF1993BCE633404B09A74BDF56FAD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
