VALUES ('doc-09-mitre-attack-p0-3016', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary exploits public admin services on routers/firewalls/switches. Chain: anomalous HTTP/SNMP/SmartInstall inputs → device syslog errors/restarts → config changes/CLI spawn → egress to attacker C2.", "external_references": [{"external_id": "AN0225", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0080#AN0225"}], "id": "x-mitre-analytic--72298803-0644-477f-be89-01b173202577", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0225", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Syslog from edge devices with HTTP 500s on mgmt portal, SmartInstall events, unexpected CLI commands", "name": "networkdevice:controlplane", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "NetFlow/sFlow for odd egress to Internet from mgmt plane", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of admin services to watch (8443, 443, 161/udp, 4786, 22).", "field": "MgmtPorts"}, {"description": "Admin source ranges to allow.", "field": "TrustedAdmins"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3016', 0, 120, '09-mitre-attack', 'retrieved', 'F33338336225A8A2E50A1DFEDEEA2C5414655AD07E7997DEBAEDFDCF81B17DF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
