VALUES ('doc-09-mitre-attack-p0-3017', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects movement of binaries to `~/Library/`, `/System/`, or app bundle locations, especially after initial execution or download from Safari or Mail.", "external_references": [{"external_id": "AN1218", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0439#AN1218"}], "id": "x-mitre-analytic--72540cd1-3ba6-4a4a-8866-a3113094196a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1218", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor relocation to .app/Contents/MacOS/ or ~/Library/Launch*", "field": "TargetBundlePathPattern"}, {"description": "Check for disappearance of com.apple.quarantine attribute post-move", "field": "QuarantineFlagCheck"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3017', 0, 92, '09-mitre-attack', 'retrieved', '6F6C5A07D190DC3F8B5A708B3DFFB1D9491A48B2D01778939FFFD7BE5FD80824', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
