VALUES ('doc-09-mitre-attack-p0-3018', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary writes or drops a malicious Office Add-in (e.g., WLL, XLL, COM) to a trusted directory or modifies registry keys to load malicious add-ins on Office application launch. Upon user opening Word or Excel, the add-in is automatically loaded, triggering execution of the payload, often spawning scripting engines or anomalous child processes.", "external_references": [{"external_id": "AN0137", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0050#AN0137"}], "id": "x-mitre-analytic--7263a8a8-a06f-4bdc-a021-3529ad683f9d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0137", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Malicious add-ins may have varying extensions (.wll, .xll, .dll, .vsto)", "field": "AddInExtension"}, {"description": "Office trusted add-in paths may differ across enterprise configurations", "field": "TrustedPath"}, {"description": "Registry keys used to load add-ins may be version- and app-specific", "field": "RegistryPath"}, {"description": "Office processes spawning mshta.exe, powershell.exe, or rundll32.exe are abnormal", "field": "ChildProcessName"}, {"description": "Add-in loading may occur only during Office launch windows", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3018', 0, 180, '09-mitre-attack', 'retrieved', 'A9AEF0996B576D4F124ACA8332B96C66408E0FCDC8DBFB5870BD5A4CE9C0FDA9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
