VALUES ('doc-09-mitre-attack-p0-3019', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitoring of file access to network shares (e.g., C$, Admin$) followed by unusual read or copy operations by processes not typically associated with such activity (e.g., PowerShell, certutil).", "external_references": [{"external_id": "AN1145", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0410#AN1145"}], "id": "x-mitre-analytic--72ba4979-f786-4205-a5da-90874e12813f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1145", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5145", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organizations may use custom share paths outside of default C$, Admin$, etc.", "field": "ShareName"}, {"description": "Common toolsets vary; defenders should tailor to unusual processes for their environment.", "field": "ProcessName"}, {"description": "Time of day and access duration may need to be tuned to reduce false positives.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3019', 0, 127, '09-mitre-attack', 'retrieved', 'AAE62662AB390BE6B6DC2B2AB0073360031E987485CD58484AD8C06A7C9E0E3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
