VALUES ('doc-09-mitre-attack-p0-3020', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Password spraying or brute force attempts across user pool within short time intervals", "external_references": [{"external_id": "AN1277", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0463#AN1277"}], "id": "x-mitre-analytic--72bf9819-b0b5-43ab-9c2d-195abe8165b8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1277", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Sign-in logs", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Max number of accounts targeted from a single IP", "field": "UsernameSprayThreshold"}, {"description": "Mismatch between user location and request location", "field": "GeoAnomaly"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3020', 0, 82, '09-mitre-attack', 'retrieved', '7A363CBBF34B9EF2B571EF38CF9311DB431658A1367180618B3F879D8CE003EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
