VALUES ('doc-09-mitre-attack-p0-3021', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary attempts to gain persistence by modifying ~/.ssh/authorized_keys via shell, text editor, echo or redirected output.", "external_references": [{"external_id": "AN0350", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0126#AN0350"}], "id": "x-mitre-analytic--72dd4fd9-b6cb-4704-b845-0632fe224995", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0350", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write | PATH=/home/*/.ssh/authorized_keys", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Temporal window to correlate file writes and suspicious process launches (e.g., <60s)", "field": "TimeWindow"}, {"description": "Expected user-to-process correlation (e.g., root writing to non-root authorized_keys)", "field": "UserContext"}, {"description": "Custom SSH path or user home variation (e.g., /etc/skel/.ssh/)", "field": "TargetPath"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3021', 0, 108, '09-mitre-attack', 'retrieved', '3FB8FF0AF7521EB525569B4657A945BA6C235811D470985D8F194183F06B105B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
