VALUES ('doc-09-mitre-attack-p0-3022', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of chflags hidden or SetFile -a V commands to hide files, or creation of hidden files with leading ''.''. Defender view: monitoring process execution and file metadata changes setting UF_HIDDEN attribute.", "external_references": [{"external_id": "AN0093", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0032#AN0093"}], "id": "x-mitre-analytic--73931643-7fae-409c-98b3-00bd88e246e0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0093", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of chflags hidden or SetFile -a V", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "File metadata updated with UF_HIDDEN flag", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict detection to non-standard directories where hidden flags are unexpected.", "field": "HiddenAttributeScope"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3022', 0, 108, '09-mitre-attack', 'retrieved', '8FD77BC16B1A446B38D4035E521EE514842B3487B78AA7CE236EE275607459B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
