VALUES ('doc-09-mitre-attack-p0-3023', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary runs commands like `whoami`, `id`, `w`, or `cat /etc/passwd` from non-interactive or scripting contexts to enumerate system user details.", "external_references": [{"external_id": "AN0255", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0093#AN0255"}], "id": "x-mitre-analytic--73b31f73-bc47-45c1-9c02-fd8eaacb2f9b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0255", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune detection based on argument presence (e.g., `cat /etc/passwd` vs. `cat` alone)", "field": "CommandLineRegex"}, {"description": "Identify if command issued via cron, systemd, or reverse shell", "field": "ShellContext"}, {"description": "Define how often user/account commands are expected on endpoint", "field": "AccessFrequency"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3023', 0, 105, '09-mitre-attack', 'retrieved', 'A88A3B9FFB75F2AE9365139CB13235B0C416ED1649340F5A2373117EB11B6949', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
