VALUES ('doc-09-mitre-attack-p0-3024', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outlook form execution upon message receipt or client launch results in automated code execution within user session. Form definitions deviate from standard templates and include script logic or COM object calls embedded in form fields.", "external_references": [{"external_id": "AN0086", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0029#AN0086"}], "id": "x-mitre-analytic--73ec21b3-5679-44a9-bac3-943060bed786", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0086", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unusual form activity within Outlook client, including load of non-default forms", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Inbound email triggers execution of mailbox-stored custom form", "name": "m365:messagetrace", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Not all tenants may enable audit logs of custom form activity or COM component usage in Office", "field": "AuditPolicyScope"}, {"description": "Ruler-style delivery may come from external accounts with forged headers or low reputation", "field": "MessageSenderAnomalyThreshold"}, {"description": "Frequency of form triggers may be anomalously high compared to baseline Outlook usage", "field": "FormExecutionRate"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3024', 0, 156, '09-mitre-attack', 'retrieved', '752BE7123A123A772CCF50D21D66D2FA2D172DE8D6D01EC7C741635951A94188', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
