VALUES ('doc-09-mitre-attack-p0-3025', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects file exfiltration using tools like curl, scp, or custom binaries over protocols such as FTP, HTTP/S, or DNS tunneling, especially outside baseline user behavior.", "external_references": [{"external_id": "AN0368", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0131#AN0368"}], "id": "x-mitre-analytic--7402eb3b-9349-478a-a8e9-7ee72c4b67c5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0368", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "NetFlow/Zeek conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag unexpected protocols (e.g., HTTP on port 53 or FTP traffic from non-standard tools).", "field": "ProtocolType"}, {"description": "Scope for privilege escalation or service account behavior.", "field": "UserContext"}, {"description": "Track movement of file types of interest (e.g., `.csv`, `.sql`, `.key`).", "field": "FileExtensionSensitivity"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3025', 0, 137, '09-mitre-attack', 'retrieved', '39932F1024F0E18914DDD64050EFFF62E7C9094A5E51AC652EBD5CFB613F3DA1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
