VALUES ('doc-09-mitre-attack-p0-3026', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Addition of new users or changes to role permissions (e.g., ReadOnly -> Admin) via API or vSphere Client, particularly from non-jumpbox IPs.", "external_references": [{"external_id": "AN0269", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0096#AN0269"}], "id": "x-mitre-analytic--74565d24-df58-49b6-86e0-01a03d6dc2a7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0269", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "vim.SessionManager.login / vim.AccountManager.createUser", "name": "esxi:vpxa", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected account name patterns for ESXi/vCenter admins.", "field": "VMAdminAccountName"}, {"description": "Expected IPs/subnets for legitimate ESXi access.", "field": "NetworkAccessLocation"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3026', 0, 88, '09-mitre-attack', 'retrieved', '638BD97595FFADBBE5ECE2F98D452268914405D1410A41CA3C499324BB2DE9E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
