VALUES ('doc-09-mitre-attack-p0-3028', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious rule creation within Outlook or Exchange clients, including auto-move or delete conditions tied to incident or security alert keywords. Defender perspective: correlation between missing inbound emails and newly added mailbox rules.", "external_references": [{"external_id": "AN0554", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0192#AN0554"}], "id": "x-mitre-analytic--747a2974-0c77-4c47-9c02-2775025327c6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0554", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Transport rule or inbox rule creation events", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Decide whether to monitor individual mailbox rules, org-wide transport rules, or both.", "field": "RuleScope"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3028', 0, 99, '09-mitre-attack', 'retrieved', 'CEEF920B3B43BAD046AE4A67DCA9B9DA5C61AE900210A9DF9777354DE1109C27', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
