VALUES ('doc-09-mitre-attack-p0-3029', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects pub/sub traffic over unusual ports, high-frequency topic publications, and connections to known-bad or dynamic broker endpoints outside allowlisted infrastructure.", "external_references": [{"external_id": "AN0005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0002#AN0005"}], "id": "x-mitre-analytic--748f457a-5dfa-431b-b5a0-3d5e1d56ebbb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0005", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "mqtt.log, xmpp.log, amqp.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Dynamic blocklist or threat intel feed for C2 brokers", "field": "BrokerReputationList"}, {"description": "Exfil-style long topic messages vs telemetry-style short messages", "field": "PayloadLengthThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3029', 0, 91, '09-mitre-attack', 'retrieved', 'C29DB2D2441F90158E67E54034F0DD7AA9780487AB66639550A25E8501F3FD3A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
