VALUES ('doc-09-mitre-attack-p0-3030', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of domain accounts via sssd or winbind for logon activity outside of typical patterns, especially on sensitive systems or with lateral movement tools.", "external_references": [{"external_id": "AN0591", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0210#AN0591"}], "id": "x-mitre-analytic--74aade7b-b61a-46d0-a68b-33fba4f09f6e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0591", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "pam_authenticate, sshd", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "sssd / sudo logs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter to high-value systems (e.g., domain-joined servers).", "field": "HostnameScope"}, {"description": "Identify trusted domains versus external or misconfigured domains.", "field": "AccountDomain"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3030', 0, 100, '09-mitre-attack', 'retrieved', 'B4EE714F3E3FAE90A8BFB86AE1BA5BC5FCC3955AC0854B1A4482BA31420AC731', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
