VALUES ('doc-09-mitre-attack-p0-3031', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects script or binary modification within shared NFS/SMB directories followed by process execution from those paths.", "external_references": [{"external_id": "AN1299", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0471#AN1299"}], "id": "x-mitre-analytic--7518f788-43dd-440a-955c-870cdb7dea26", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1299", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "smb_files.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Mount path of monitored shared volumes (e.g., /mnt/shared).", "field": "MountPath"}, {"description": "Pattern matching of abnormal or disguised filenames.", "field": "FilenamePattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3031', 0, 88, '09-mitre-attack', 'retrieved', '982E86A1C3848B72847D944A719EF26E4D7003DEB2FBBFBD03AD1A28A7458B5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
