VALUES ('doc-09-mitre-attack-p0-3032', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized edits to system configuration profiles, unexpected certificate trust changes, or abnormal ARP/DNS patterns indicative of interception.", "external_references": [{"external_id": "AN0825", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0296#AN0825"}], "id": "x-mitre-analytic--7535f2e7-d7bb-4e92-8a63-36cd9ccc01be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0825", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Configuration profile modified or new profile installed", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "TLS downgrade or inconsistent DNS answers", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known good vs suspicious configuration profiles per enterprise baseline.", "field": "ProfileIdentifiers"}, {"description": "Minimum TLS version accepted in network traffic inspection.", "field": "TLSVersionThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3032', 0, 103, '09-mitre-attack', 'retrieved', 'E47590841AFE20AE39FA493B29B93D06AFD99FC83767BEA8CC712401389EE348', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
