VALUES ('doc-09-mitre-attack-p0-3033', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects attempts to enumerate VMs via hypervisor tools like `virsh`, `VBoxManage`, or `qemu-img`. Defender correlates suspicious command invocations with parent process lineage and unexpected users.", "external_references": [{"external_id": "AN0573", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0199#AN0573"}], "id": "x-mitre-analytic--753ec5a6-9327-452e-ab9c-62b7206c24aa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0573", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: process_name IN (\"virsh\", \"VBoxManage\", \"qemu-img\") AND command IN (\"list\", \"info\")", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor non-root users invoking hypervisor management utilities.", "field": "NonRootAccounts"}, {"description": "Whitelist of scripts expected to run VM enumeration as part of routine operations.", "field": "KnownAdminScripts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3033', 0, 106, '09-mitre-attack', 'retrieved', 'B0259F7BF0B0BC42F9AD8E38BDB6BD45DB6FDBEF7E35E9CB87F796FAE2DBF3BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
