VALUES ('doc-09-mitre-attack-p0-3034', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects embedded Lua interpreter execution or script injection on devices supporting Lua scripting (e.g., routers, firewalls), often seen in modified firmware or abused APIs.", "external_references": [{"external_id": "AN0281", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0101#AN0281"}], "id": "x-mitre-analytic--755fb4b5-903f-4694-b591-04078afa27aa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0281", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "runtime", "name": "networkdevice:runtime", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to baseline known good versions versus injected scripts.", "field": "FirmwareBuildHash"}, {"description": "Path to where scripts are allowed or denied based on config.", "field": "ScriptInjectionPath"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3034', 0, 96, '09-mitre-attack', 'retrieved', 'EFA22ED5713EDB8FCE91575A7FD3391A42F1A8799964A6468C65F4EA76F06A24', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
