VALUES ('doc-09-mitre-attack-p0-3035', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor Facetime, iMessage, or SIP client logs for anomalous voice call attempts. Link to subsequent user execution events (downloads, RMM installs) triggered post-call.", "external_references": [{"external_id": "AN0685", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0245#AN0685"}], "id": "x-mitre-analytic--756214e0-660d-4f32-a4f1-f8ff24a7852f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0685", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Outgoing or incoming calls with non-standard caller IDs or unusual metadata", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns of spoofed caller IDs that must be tuned based on region and telecom provider", "field": "CallerIDPatterns"}, {"description": "Define what follow-on events (browser downloads, execution) to correlate with call logs", "field": "PayloadCorrelation"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3035', 0, 111, '09-mitre-attack', 'retrieved', '76A9163A994EA49E7B590E2903EBB6986C5B3299551E537E01D8B164EDE0D8B0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
