INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3037', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of unexpected additions or modifications to system-wide certificate stores or execution of commands adding certificates to trusted stores.", "external_references": [{"external_id": "AN0154", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0056#AN0154"}], "id": "x-mitre-analytic--759c073c-2c40-484b-af47-8426ec5d5a3e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0154", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write: File modifications under /etc/ssl/certs, /usr/local/share/ca-certificates, or /etc/pki/ca-trust/source/anchors", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve: Execution of update-ca-certificates or trust anchor modification commands", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths monitored for certificate modifications; can be tuned depending on Linux distribution.", "field": "CertificatePaths"}, {"description": "Expected user accounts with privileges to install root certificates; anomalies outside this context are suspicious.", "field": "AdminAccounts"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3037', 0, 119, '09-mitre-attack', 'retrieved', '3C09145138A3F53F99985024E0F746B223D486DC45D0202A9CB1FE966A305C54', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
