INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3038', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "SaaS platforms may show forged credentials as unusual API keys, tokens, or session cookies being used without corresponding authentication. Correlated patterns include simultaneous valid sessions from multiple geographies, unusual API calls with new tokens, or bypass of expected MFA enforcement.", "external_references": [{"external_id": "AN0722", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0260#AN0722"}], "id": "x-mitre-analytic--75d43d9f-7b54-4cd4-a6d9-523f8f9a60ff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0722", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Session creation without MFA or login event", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"channel": "API requests made with tokens not associated with expected user logins", "name": "saas:auth", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Trigger on logins from unusual or high-risk geographies.", "field": "GeoLocationAlerts"}, {"description": "Detect multiple simultaneous uses of the same forged credential.", "field": "TokenReplayThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3038', 0, 130, '09-mitre-attack', 'retrieved', 'E03537D514DB0C662AC48B7F5956880C8F67728087B5F97C86CFE0346DBBF260', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
