INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3039', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary leverages built-in tools such as certutil.exe, powershell.exe, or copy.exe to decode, reassemble, or extract hidden malicious content from obfuscated containers or encoded formats. The decoding utility often spawns shortly after file staging or download and may be chained with script interpreters or further payload execution.", "external_references": [{"external_id": "AN0767", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0275#AN0767"}], "id": "x-mitre-analytic--75f05a04-103c-432a-afd6-8a8987b4370e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0767", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May vary across environments (e.g., certutil, powershell, copy, expand, 7zip)", "field": "ToolName"}, {"description": "Targets may use .txt, .cer, .enc, .b64, .zip, etc. to disguise payloads", "field": "FileExtensionFilter"}, {"description": "Command syntax varies between base64 decoding, copy /b, and expand switches", "field": "CommandLineRegex"}, {"description": "Deobfuscation typically follows staging/download within a short timeframe", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3039', 0, 157, '09-mitre-attack', 'retrieved', '44FA00034EB2CD728F44F1EEFB45222E124C856E484089972157A1493E8BBE4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
