INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3041', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.\n\nDetection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access.", "external_references": [{"external_id": "AN2022", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0890#AN2022"}], "id": "x-mitre-analytic--7726e542-666b-4eeb-8998-cddb45a41605", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 2022", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3041', 0, 86, '09-mitre-attack', 'retrieved', '4B7FD5738F78BB016E82D8D58A257BEA5F80CDABF6D9F70A2211DD1DC3EEB43C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
