INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3042', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of renamed or dropped files with a trailing space to deceive users or analysts, especially in LaunchAgents or LaunchDaemons.", "external_references": [{"external_id": "AN0813", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0292#AN0813"}], "id": "x-mitre-analytic--773188c7-6191-4ba4-ad39-b67ed8578dd9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0813", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "filesystem activity", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable regex or path rule to match common masquerade attempts (e.g., ''Terminal .app'').", "field": "FilenamePattern"}, {"description": "Analytic can be scoped to key directories (e.g., /Users/Library/LaunchAgents/).", "field": "TargetPath"}, {"description": "Focus detection on suspicious user sessions or service creation under non-admin users.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3042', 0, 116, '09-mitre-attack', 'retrieved', '9478E3968FFED520B07A3DD3943C094754D130BDF4026BBBC47191B2EFED5A5B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
