INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3043', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Container process executes destructive file operations inside volume mounts or host paths. Includes `rm -rf /mnt/volumes/`, container breakout followed by host deletion attempts.", "external_references": [{"external_id": "AN0416", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0146#AN0416"}], "id": "x-mitre-analytic--7735a0b1-f3bc-44fc-a909-75738e77bded", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0416", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unlink, unlinkat, rmdir", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "container exec rm|container stop --force", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify when deletions occur inside persistent or shared volume paths.", "field": "MountPoint"}, {"description": "Correlate destructive behavior with unknown or untrusted container sources.", "field": "ContainerImage"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3043', 0, 105, '09-mitre-attack', 'retrieved', 'B6A892F44EFB0387545C98804EEA988AE0103034D22526377D3DAE237797D738', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
