INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3044', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of CLI commands that disable history logging such as ''no logging''. Anomalous lack of new commands in session logs while activity persists is a strong signal.", "external_references": [{"external_id": "AN1559", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0563#AN1559"}], "id": "x-mitre-analytic--77450309-6789-4025-9817-d908c4ac9e5b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1559", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Commands like ''no logging'' or equivalents that disable session history", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Command syntax differs across Cisco, Juniper, Fortinet, etc., requiring vendor-aware tuning.", "field": "DeviceVendors"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3044', 0, 96, '09-mitre-attack', 'retrieved', 'A1A0FB6DAAE2BF374DEC6D7CF20A09A667BD74907C7CC11D927B2385B72C34CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
