INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3047', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of known or custom VNC/remote desktop daemons or tunneling agents that initiate external communication after launch", "external_references": [{"external_id": "AN0715", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0259#AN0715"}], "id": "x-mitre-analytic--77769a6d-f3f4-42f1-a9a7-0d1096563115", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0715", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "outbound connections to RMM services or to unusual destination ports", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom-compiled or renamed VNC servers (e.g., x11vnc, tightvncserver) may require local tuning", "field": "binary_name"}, {"description": "Destination IP or ASN may shift depending on geolocation of cloud-hosted RMM backends", "field": "OutboundIPRange"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3047', 0, 108, '09-mitre-attack', 'retrieved', 'EE746E32D83412079F7CE5DD26C74B100494A32D28C93B8D2928715468E1DF34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
