VALUES ('doc-09-mitre-attack-p0-3048', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of file execution where the file name contains a trailing space to masquerade as a known executable. Adversaries may exploit the way command line interpreters handle file names with trailing whitespace.", "external_references": [{"external_id": "AN0812", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0292#AN0812"}], "id": "x-mitre-analytic--778e2c18-2b26-4dd4-b4b2-3f8310d57a07", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0812", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "application or system execution logs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "This detection may vary based on how different shells and file systems treat trailing spaces. Normalize or regex-match file names with trailing space.", "field": "ExecutableNameTrailingSpace"}, {"description": "Monitor for untrusted or lower-privileged users executing suspicious scripts with disguised names.", "field": "UserContext"}, {"description": "Tune for execution patterns during off-hours to reduce false positives.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3048', 0, 141, '09-mitre-attack', 'retrieved', '6471B4B2E7B522E8393CF778EA4B4955A008FCC6F03F061B9191B4F47DDE9A4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
