VALUES ('doc-09-mitre-attack-p0-3050', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary abuse of SaaS platform vulnerabilities to bypass logging, monitoring, or consent boundaries. Defender perspective focuses on abnormal application integration events, missing audit logs, or API calls from unauthorized service principals that align with exploitation attempts.", "external_references": [{"external_id": "AN1637", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0595#AN1637"}], "id": "x-mitre-analytic--77c3b78a-fb34-4040-9dda-057e8eca3362", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1637", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ApplicationModified, ConsentGranted: Unexpected app consent or modification events linked to security evasion", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Applications and integrations expected in the environment; deviations may be suspect.", "field": "MonitoredApps"}, {"description": "Threshold for anomalous OAuth or app consent events before flagging exploitation.", "field": "ConsentAnomalyThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3050', 0, 121, '09-mitre-attack', 'retrieved', '7F2BBEA7386402D6F522A728B02924D2F69025FF4541AE89CAAE72ACC960F879', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
