VALUES ('doc-09-mitre-attack-p0-3051', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary adds IDE extensions or plugins (VS Code, JetBrains Toolbox/EAP, Eclipse) via GUI or CLI, possibly via managed profiles. Chain: process start with install/update flags → plist/extension folder changes under ~/Library/Application Support/Code or ~/Library/Application Support/JetBrains → outbound connections to marketplaces/tunnel services → optional helper (ssh/node) spawned.", "external_references": [{"external_id": "AN1550", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0561#AN1550"}], "id": "x-mitre-analytic--77d3146f-2066-40a9-872e-ec05d7a4d6d1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1550", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of Code.app, idea, JetBrainsToolbox, eclipse with install/extension flags", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Writes under ~/Library/Application Support/Code*/extensions or JetBrains plugins", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Outbound connections from IDE processes to marketplace/tunnel domains", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Per-app preference domains and plugin directories vary by version.", "field": "PlistLocations"}, {"description": "If MDM installs extensions, allowlist those events to avoid FPs.", "field": "MDMProfiles"}, {"description": "Correlation range between install and first beacon.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3051', 0, 159, '09-mitre-attack', 'retrieved', '5BAB134184D5A6F7F8FA02723B73049DC2CDE7851462336FB86102C4DE67B0A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
