VALUES ('doc-09-mitre-attack-p0-3052', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects rogue DHCP server activity and anomalous DHCP OFFER/ACK messages assigning unexpected DNS or gateway values. Detection correlates DHCP server role changes, DHCP exhaustion warnings, and sudden network configuration changes across endpoints.", "external_references": [{"external_id": "AN1290", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0468#AN1290"}], "id": "x-mitre-analytic--780021a3-d3e6-4c5b-a976-1c3715b990e2", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1290", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1341, 1342, 1020, 1063", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "DHCP OFFER or ACK with unauthorized DNS/gateway parameters", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of known DHCP servers; unexpected sources are suspicious.", "field": "AuthorizedDHCPServers"}, {"description": "Interval to correlate DHCP OFFER/ACK anomalies with subsequent misconfigurations.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3052', 0, 117, '09-mitre-attack', 'retrieved', '56EA7C609A5524728C036A8C192667B722518C61B984C901B612E5E433B73097', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
