VALUES ('doc-09-mitre-attack-p0-3053', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of cloud virtual machine images (AMIs, custom images) with persistence mechanisms, followed by infrastructure provisioning that uses these implanted images.", "external_references": [{"external_id": "AN0947", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0334#AN0947"}], "id": "x-mitre-analytic--7845facb-50f2-4d32-ae00-6766b9410681", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0947", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RegisterImage", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"channel": "ModifyImageAttribute", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--071a09b1-8945-46fd-8bb7-6bcc89400963"}, {"channel": "RunInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Roles that are allowed to register and modify images should be scoped narrowly.", "field": "IAMRole"}, {"description": "Expected tags or naming patterns for images (e.g., ''golden-image'', ''base-image'').", "field": "ImageTagRegex"}, {"description": "Time interval between image creation and instance launch.", "field": "LaunchWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3053', 0, 120, '09-mitre-attack', 'retrieved', 'D234BF014F7F64D1FB90674BB7687A18AD0D4A147F527FE2F8C3B5BB52B617DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
