VALUES ('doc-09-mitre-attack-p0-3054', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects hosts transmitting large volumes of SMTP, IMAP, or POP3 traffic to external IPs or relays that aren''t associated with the enterprise mail infrastructure.", "external_references": [{"external_id": "AN0382", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0135#AN0382"}], "id": "x-mitre-analytic--784b7a50-cdc5-4161-8b52-2be5e5de19ac", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0382", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "smtp.log, conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Dest IPs not matching sanctioned SMTP/IMAP relays", "field": "ExternalMailRelayFilter"}, {"description": "Outbound email bytes vastly exceed response", "field": "OutflowToInflowRatio"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3054', 0, 90, '09-mitre-attack', 'retrieved', '6FC114351E57E160556E466F6C96215801466800882D5FC752F5C60F39E9F9A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
