VALUES ('doc-09-mitre-attack-p0-3055', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modification of System Integrity Protection (SIP) or code signing enforcement policies through csrutil or kernel variable tampering. Correlates execution of csrutil disable commands with subsequent policy state changes and anomalous unsigned process executions.", "external_references": [{"external_id": "AN1447", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0523#AN1447"}], "id": "x-mitre-analytic--7853421f-8eb4-49c3-9943-077430b97037", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1447", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "csrutil disable", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "g_CiOptions modification or SIP state change", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "Unsigned binary execution following SIP change", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track configuration files and kernel extensions tied to SIP enforcement", "field": "PolicyPaths"}, {"description": "Restrict or expand which privileged accounts are monitored for SIP/CSRUTIL changes", "field": "AllowedUsers"}, {"description": "Define correlation between csrutil execution and unsigned process activity", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3055', 0, 141, '09-mitre-attack', 'retrieved', '182721349AE002BE66F3C8637C75B7F6987B6602B23D14C5FCA9BE361F66AB8B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
