VALUES ('doc-09-mitre-attack-p0-3056', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications making outbound connections on non-standard ports or launchd services bound to ports inconsistent with system baselines.", "external_references": [{"external_id": "AN0635", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0227#AN0635"}], "id": "x-mitre-analytic--785c44d0-7e5b-4d3e-a3cd-0c5e96b8891b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0635", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "outbound TCP/UDP traffic over unexpected port", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "launchd services binding to non-standard ports", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define expected macOS service port usage (e.g., AirDrop, Bonjour).", "field": "BaselinePortProfiles"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3056', 0, 90, '09-mitre-attack', 'retrieved', 'C7B7727ED54D1CF729B66AF7609886000D55DF5D85D0A1041E586491079036D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
