VALUES ('doc-09-mitre-attack-p0-3057', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies self-modifying executables that exhibit changes in binary hash, entropy, or memory sections during or between executions—often tied to dynamic unpacking or decryption behaviors.", "external_references": [{"external_id": "AN0919", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0324#AN0919"}], "id": "x-mitre-analytic--786c54fa-8a9f-41bc-aa22-c4a4f6a93bd7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0919", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on expected baseline entropy for executables; higher values may indicate polymorphic packing.", "field": "EntropyThreshold"}, {"description": "Correlate rapid process spawn + image load activity suggesting mutation engine usage.", "field": "TimeWindow"}, {"description": "Define expected or suspicious parent-child chains (e.g., script runner -> encoded PE)", "field": "ParentProcessPatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3057', 0, 128, '09-mitre-attack', 'retrieved', 'A039C8A99C6D6BECBB224603BB408833F95C4C393B5CC04F061C1ACC0CCD1CBB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
