VALUES ('doc-09-mitre-attack-p0-3058', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of `clear history` or `clear logging` commands on network device CLI to remove past activity logs.", "external_references": [{"external_id": "AN0471", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0165#AN0471"}], "id": "x-mitre-analytic--7879313f-abf1-487a-b4d3-813f385ddce3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0471", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CLI command audit", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Support detection of known variants: ''clear history'', ''clear logging'', etc.", "field": "CommandPattern"}, {"description": "Router, switch, firewall—may have different CLI behaviors.", "field": "DeviceType"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3058', 0, 89, '09-mitre-attack', 'retrieved', '8AA2B962EF133A070ED3F047B26757DC035F9A2E7242430594CC7F8C85E65E8B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
