VALUES ('doc-09-mitre-attack-p0-3059', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access and retrieval of container service account tokens followed by unauthorized API requests using those tokens to interact with the Kubernetes API server or internal services.", "external_references": [{"external_id": "AN1423", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0515#AN1423"}], "id": "x-mitre-analytic--78821450-c84f-498f-abf2-b43211fa4218", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1423", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GET or LIST requests to /var/run/secrets/kubernetes.io/serviceaccount/ followed by access to the Kubernetes API server", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust based on how quickly tokens are expected to be used post-access", "field": "TimeWindow"}, {"description": "Tuning for known service accounts that legitimately access the API", "field": "UserContext"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3059', 0, 112, '09-mitre-attack', 'retrieved', '0B08F3169EEE5B0CB2EF64845FB445C014A0CD91A618A48631917490382392F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
