VALUES ('doc-09-mitre-attack-p0-3063', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects attempts to enumerate local groups via Net.exe, PowerShell, or native API calls that precede lateral movement or privilege abuse.", "external_references": [{"external_id": "AN0317", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0114#AN0317"}], "id": "x-mitre-analytic--78f4f0fe-55ef-4598-85ac-865cba1920d3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0317", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time window between group enumeration and lateral movement or privilege escalation activity.", "field": "TimeWindow"}, {"description": "Whether the process was executed by a privileged or low-privilege account.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3063', 0, 94, '09-mitre-attack', 'retrieved', '438959A1AD37F8225A8E49381CA57E56EC05DD2AA211A2E9AFC94628FEDE37E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
