VALUES ('doc-09-mitre-attack-p0-3064', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary spawns command-line tools (e.g., del, cipher /w, SDelete) or scripts to recursively delete or overwrite user/system files. This may be correlated with abnormal file IO activity, registry writes, or tampering in critical system directories.", "external_references": [{"external_id": "AN0411", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0146#AN0411"}], "id": "x-mitre-analytic--791dfdd4-b04d-498a-accc-ee9e2acc7b14", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0411", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=23", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter file deletion activity to sensitive locations (e.g., %System32%, Documents, DB paths).", "field": "TargetFilename"}, {"description": "Tune for aggressive overwrite flags (e.g., /w, /q, /s) or temp file overwrites.", "field": "ProcessCommandLine"}, {"description": "Threshold of unique file deletions or modifications within time window.", "field": "VolumeThreshold"}, {"description": "Correlate rapid file delete/overwrite behavior from same process/user.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3064', 0, 147, '09-mitre-attack', 'retrieved', 'BC1EBA989E5E01FFDECA9F735B6B074C2E963273516EAD8116DCFBD33AFB0333', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
