VALUES ('doc-09-mitre-attack-p0-3067', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary creates users via IAM/IdP API or portal (e.g., Azure AD, Okta). Detection involves monitoring API calls, admin action logs, and correlation with role assignments.", "external_references": [{"external_id": "AN1607", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0583#AN1607"}], "id": "x-mitre-analytic--7947aae5-fd76-403c-8c73-1300dff7d30f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1607", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add user", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Trigger alert only when account is assigned privileged roles", "field": "AdminThreshold"}, {"description": "Exclude accounts from known automation processes or provisioning pipelines", "field": "AutomationExemptions"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3067', 0, 96, '09-mitre-attack', 'retrieved', '8FFC0F4166D321B43FEF3B168089D63CE94FE9AFFA4FA6B84EF5548067E48179', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
