VALUES ('doc-09-mitre-attack-p0-3068', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Recurring network exfiltration initiated by scheduled or script-based processes exhibiting time-based regularity and consistent external destinations.", "external_references": [{"external_id": "AN1118", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0399#AN1118"}], "id": "x-mitre-analytic--79600919-afe8-4ac9-946c-147d85af6cfe", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1118", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=106, 200", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Duration threshold to consider a connection repetitive (e.g., same hour daily)", "field": "TimeWindow"}, {"description": "Known external destinations to exclude (e.g., approved SFTP/backup servers)", "field": "DestIPAllowlist"}, {"description": "Allowlisted job runners or scripts known to schedule legitimate transfers", "field": "ParentProcessBaseline"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3068', 0, 114, '09-mitre-attack', 'retrieved', '9BFDABCD5FFDAC5CD22744DB8E944674D9CBFF1874C7F522BA7732F60EF7DE73', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
