VALUES ('doc-09-mitre-attack-p0-3069', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution of AutoHotKey or AutoIT interpreters or compiled scripts used for unauthorized automation, command execution, or payload delivery, correlated with anomalous process lineage, command-line arguments, or script creation events.", "external_references": [{"external_id": "AN0942", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0332#AN0942"}], "id": "x-mitre-analytic--7975ae39-8c6b-45cc-9280-98e94b666c85", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0942", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tuning this helps identify automation behavior outside expected user work hours.", "field": "TimeWindow"}, {"description": "Used to isolate cases where AHK or AutoIT scripts are spawned by suspicious or unusual processes.", "field": "ParentProcessName"}, {"description": "Extensions such as .ahk, .au3, or unknown .exe names compiled from these.", "field": "ScriptExtension"}, {"description": "Threshold for number of spawned children to detect automation or modular malware behavior.", "field": "ChildProcessCount"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3069', 0, 151, '09-mitre-attack', 'retrieved', '9DD77691AC6145896D618E8CC676071765E2A2E6427782CF3295B7238F9AEB51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
