VALUES ('doc-09-mitre-attack-p0-3070', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of QEMU, KVM, or VirtualBox processes with unusual flags (e.g., ''-nographic'', ''-snapshot''). File creation of VM images in atypical directories. Defender view: monitoring audit logs for process executions and file modifications linked to hidden virtualization.", "external_references": [{"external_id": "AN0910", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0321#AN0910"}], "id": "x-mitre-analytic--79ba9430-eeb0-4fce-9757-bb81fc2a43d5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0910", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve calls for qemu-system*, kvm, or VBoxHeadless", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "File creations of *.qcow2, *.vdi, *.vmdk outside standard VM directories", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate VM image storage paths to reduce false positives.", "field": "ImageDirectoryWhitelist"}, {"description": "Correlate suspicious VM execution with non-admin or service accounts.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3070', 0, 126, '09-mitre-attack', 'retrieved', 'C0ABB2AFF49C866D34D113088938930C0AA9310EF02D99BBC310294A35D61582', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
