VALUES ('doc-09-mitre-attack-p0-3071', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of `ifconfig`, `networksetup`, or `system_profiler` to query IP/MAC/interface configuration and status.", "external_references": [{"external_id": "AN0561", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0195#AN0561"}], "id": "x-mitre-analytic--79c196d7-abb8-4766-a875-4acafc6f059d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0561", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scripted tools (e.g., bash calling `ifconfig`) vs GUI-initiated inspection", "field": "ScriptedContext"}, {"description": "Enumerations executed frequently or across multiple interfaces may indicate enumeration loops", "field": "ExecutionFrequency"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3071', 0, 83, '09-mitre-attack', 'retrieved', '96D772E06EDF1CC0AEAA02BA99285D1589BA904425C447672F55AA923B357E33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
