VALUES ('doc-09-mitre-attack-p0-3072', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects excessive outbound traffic to remote host over HTTP(S) from uncommon or previously unseen processes.", "external_references": [{"external_id": "AN0144", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0053#AN0144"}], "id": "x-mitre-analytic--79c7d394-e772-479c-acf9-ddd05b8a68b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0144", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "HTTP ", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines threshold ratio of outbound to inbound bytes that signals possible obfuscation", "field": "OutboundByteThreshold"}, {"description": "List of known legitimate network clients to exclude from anomaly checks", "field": "ProcessAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3072', 0, 90, '09-mitre-attack', 'retrieved', 'EB393288281C8B01DA40834291B4C5E42AAD428ADD0C33394FAE39ABE3D99FED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
