VALUES ('doc-09-mitre-attack-p0-3073', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries collecting local files via PowerShell, WMI, or direct file API calls often include recursive file listings, targeted file reads, and temporary file staging.", "external_references": [{"external_id": "AN1070", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0380#AN1070"}], "id": "x-mitre-analytic--79ecfad5-3439-4a04-919a-236d47652ba0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1070", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allows tuning for file extensions or paths of sensitive data (e.g., *.xls, *.db, *.pdf).", "field": "TargetFilePathRegex"}, {"description": "Used to scope monitoring to suspicious parent/child process trees like PowerShell or WMI spawning file reads.", "field": "ParentProcessFilter"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3073', 0, 111, '09-mitre-attack', 'retrieved', '20EEDF6F63A6FB8D35FDD373CA2405DFF5E528D1F26FA9AED0AB93185E4BE295', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
