VALUES ('doc-09-mitre-attack-p0-3074', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of tools/scripts accessing input devices like /dev/input/* or evdev via suspicious processes lacking GUI context.", "external_references": [{"external_id": "AN0283", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0102#AN0283"}], "id": "x-mitre-analytic--79f3bf7a-cf35-442c-b707-ba4dabd6ed62", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0283", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "ptrace, ioctl", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unusual process accessing device files", "field": "ProcessName"}, {"description": "Typically /dev/input/*, but tunable to exact endpoint config", "field": "DevicePath"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3074', 0, 95, '09-mitre-attack', 'retrieved', '9616121F3280F6AC59E408D01FB112328DBD19613DF802D5E49B65C6ECD98BF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
