VALUES ('doc-09-mitre-attack-p0-3075', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of default account usage such as Guest or Administrator performing interactive or remote logons on systems outside of installation or maintenance windows.", "external_references": [{"external_id": "AN1283", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0465#AN1283"}], "id": "x-mitre-analytic--7a3dd710-39a7-4327-8d3b-150c50b2c680", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1283", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Default usernames like ''Administrator'' or ''Guest'' may be renamed or disabled by the organization. Detection logic should account for name changes.", "field": "UserContext"}, {"description": "Restrict detection to unusual hours or outside of expected maintenance windows.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3075', 0, 107, '09-mitre-attack', 'retrieved', 'D8998C6AAFB0910BF5544F4051F49ECD4183225B50F2427907D1FB1EC97F8776', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
