VALUES ('doc-09-mitre-attack-p0-3076', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of persistent login hooks configured via defaults or plist modifications that result in execution of scripts or binaries at user login, breaking expected parent-child process lineage.", "external_references": [{"external_id": "AN0682", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0244#AN0682"}], "id": "x-mitre-analytic--7a424183-94ca-4dc1-a03b-610d174aa973", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0682", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "loginwindow or tccd-related entries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/root/Library/Preferences/com.apple.loginwindow.plist", "name": "fs:plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path of script or binary assigned to login hook; may vary by environment", "field": "login_hook_path"}, {"description": "Login hook may be applied to specific user accounts; tune by privilege level", "field": "user_context"}, {"description": "Correlate plist file modification to execution within a short timeframe", "field": "time_window"}, {"description": "Expected parent process (e.g., loginwindow); anomalies can indicate masquerading", "field": "parent_process_name"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3076', 0, 138, '09-mitre-attack', 'retrieved', 'B5394A96FFDE3F475A119962960CEE3423654244E69437684D5159F9EF30C28B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
