VALUES ('doc-09-mitre-attack-p0-3077', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized instance creation in unmonitored or unused regions. Burst of compute-intensive jobs in spot instances or sudden spike in resource usage in legitimate VMs.", "external_references": [{"external_id": "AN1493", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0540#AN1493"}], "id": "x-mitre-analytic--7a5e5aff-8395-4b4e-9072-dd765dae7d19", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1493", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RunInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "Unusual CPU burst or metric anomalies", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adversaries may deploy resources in rarely used or misconfigured regions.", "field": "Region"}, {"description": "Used to evade detection with benign-looking tags or names.", "field": "TagKey"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3077', 0, 105, '09-mitre-attack', 'retrieved', 'DBEC0F9AAEBA46E6D51A3DD198FAAEA13F9A270A12F54DF5DE04D4D4FF0D4D0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
