VALUES ('doc-09-mitre-attack-p0-3078', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Phishing attachment detection on macOS through correlation of Mail app logs, file creation in user directories, and abnormal process execution (e.g., Preview.app or Mail.app spawning Terminal or scripting binaries). Network traffic after attachment interaction is also monitored.", "external_references": [{"external_id": "AN0657", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0236#AN0657"}], "id": "x-mitre-analytic--7a6192b4-997a-4526-bb3d-76664bc31274", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0657", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inbound messages with attachments from suspicious domains", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Execution of Terminal, osascript, or other interpreters originating from Mail or Preview", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Attachment files written to ~/Downloads or temporary folders", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time delay between attachment download and execution considered suspicious.", "field": "ExecutionDelayThreshold"}, {"description": "Parent processes expected to rarely spawn child processes (e.g., Mail.app, Preview.app).", "field": "SuspiciousParentApps"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3078', 0, 144, '09-mitre-attack', 'retrieved', 'AF6FFDB2A1DE99201AAC42A2D9114C05603D71150F9A8475B7E7ECCC0BBE7D3A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
