VALUES ('doc-09-mitre-attack-p0-3079', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of user-downloaded or created scripts with hidden extensions due to RTLO character insertion in filename, often present in desktop environments or phishing campaigns.", "external_references": [{"external_id": "AN1463", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0527#AN1463"}], "id": "x-mitre-analytic--7a72f91d-9c16-4724-b87d-3e5448f81b51", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1463", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "event-based", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "nautilus, dolphin, or gvfs logs", "name": "desktop:file_manager", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter based on mismatched visible extension vs. magic bytes or mime-type", "field": "ExtensionMismatch"}, {"description": "Correlation between file open and subsequent script interpreter invocation", "field": "ProcessLineage"}, {"description": "Suspicious Unicode sequences or byte entropy in filenames", "field": "FilenameEntropy"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3079', 0, 122, '09-mitre-attack', 'retrieved', 'EDDF7EEC3894460E02BD902A68CC19059D4FE596002BB0D3042BC9421D062DC5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
