VALUES ('doc-09-mitre-attack-p0-3080', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Credential-related configuration changes in productivity apps, such as API key creation in Google Workspace, app tokens in Slack, or user-level OAuth credentials in M365.", "external_references": [{"external_id": "AN1471", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0531#AN1471"}], "id": "x-mitre-analytic--7a9088cb-cfe8-4a4a-979c-1ef7678179f2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1471", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "API Key Created, OAuth Client Registered", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "Set-Mailbox, Set-AppPassword, Add-MailboxPermission", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect suspicious redirect URI mismatches in new clients.", "field": "OAuthClientRedirectURIBaseline"}, {"description": "Highlight credentials granting excessive read/write org-wide.", "field": "TokenScopeSensitivity"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3080', 0, 102, '09-mitre-attack', 'retrieved', 'F48EC9A446445C9E01728F18B788FC18A2C38BF36A19387850D11D25ACDE9C96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
