INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3081', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection focuses on unauthorized modification of Mach-O binaries to include LC_LOAD_DYLIB headers pointing to malicious dylibs. Behavior is identified via a chain of file metadata changes, removal of code signatures, and subsequent anomalous dylib loads at runtime. Correlation of file changes with lack of authorized updates and process memory mapping of unrecognized or unsigned libraries is crucial.", "external_references": [{"external_id": "AN0607", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0216#AN0607"}], "id": "x-mitre-analytic--7aaf568b-bc31-4fb0-8543-12ee281a0b85", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0607", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process memory maps new dylib (dylib_load event)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Mach-O binary modified or LC_LOAD_DYLIB segment inserted", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Code signature validation fails or is absent post-binary modification", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlates binary modification and dylib load within a defined time interval (e.g., 1 hour)", "field": "TimeWindow"}, {"description": "Regular expression to match known malicious or uncommon library paths", "field": "DylibPathRegex"}, {"description": "Number of unsigned or unrecognized dylibs mapped into memory per process", "field": "UnsignedDylibThreshold"}, {"description": "Scope monitoring to non-admin users or sensitive system directories", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3081', 0, 190, '09-mitre-attack', 'retrieved', '0A6DB990930CB0DA9819234CF543CDBB5C955E9C594421CBC74988E6E49735A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
