VALUES ('doc-09-mitre-attack-p0-3083', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of users and groups through suspicious shell commands or unauthorized access to /etc/passwd or /etc/shadow.", "external_references": [{"external_id": "AN1613", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1613"}], "id": "x-mitre-analytic--7b0d80c0-807e-46b1-b3f7-fd3e4f3aceba", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1613", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PATH", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=1", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on file paths such as ''/etc/passwd'', ''/etc/group'', ''/etc/shadow''.", "field": "AccessedFile"}, {"description": "Filter known admin processes to reduce false positives.", "field": "ParentProcessName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3083', 0, 91, '09-mitre-attack', 'retrieved', '5FF6B0B84ADB123F924F0A12544FDB307F0D310381ABCCB0692865A78BB83BC6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
