VALUES ('doc-09-mitre-attack-p0-3084', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell script or binary uses multiple system commands (e.g., dmidecode, lscpu, lspci) in quick succession to detect virtualization environment", "external_references": [{"external_id": "AN0479", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0168#AN0479"}], "id": "x-mitre-analytic--7b4b3b54-d992-4f03-922a-6eec96c9342e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0479", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of system tools like dmidecode, lspci, lscpu, dmesg, systemd-detect-virt", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Burst of system info commands within X seconds", "field": "TimeWindow"}, {"description": "Regex or substring matching virtualization artifact checks", "field": "CommandPattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3084', 0, 94, '09-mitre-attack', 'retrieved', '329E171D9021ABA808EE01815A4D165B2A4564E0716AA690050A6527EC82B0C9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
