VALUES ('doc-09-mitre-attack-p0-3086', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of local users or groups via file access (/etc/passwd) or commands like id, groups.", "external_references": [{"external_id": "AN0847", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0303#AN0847"}], "id": "x-mitre-analytic--7b87b63c-0936-48b5-8017-47bf5561e6f9", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0847", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PATH", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=1", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitors sensitive file access such as ''/etc/passwd'', ''/etc/group''.", "field": "AccessedFile"}, {"description": "Restrict detection to user-initiated sessions or specific parent processes.", "field": "ExecutionScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3086', 0, 89, '09-mitre-attack', 'retrieved', '80B6BFFAB431CDC793C223A8378131917B0136DD44B416073388711AEC8E1A47', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
