VALUES ('doc-09-mitre-attack-p0-3087', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary gains shell access or uploads a malicious script to deface hosted web content in Nginx, Apache, or other services.", "external_references": [{"external_id": "AN0663", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0238#AN0663"}], "id": "x-mitre-analytic--7b95ffd7-165d-4435-97b6-4508b9328d89", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0663", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Unusual HTTP POST or PUT requests to paths such as ''/uploads/'', ''/admin/'', or CMS plugin folders", "name": "apache:access_log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Unauthorized sudo or shell access, especially leading to file changes in /var/www or /srv/http", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for CMS-specific upload directories subject to defacement (e.g., wp-content/uploads).", "field": "UploadPathRegex"}, {"description": "Types of files to monitor for defacement (e.g., .html, .php, .jsp).", "field": "FileExtensionScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3087', 0, 132, '09-mitre-attack', 're