INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3089', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of file creation/modification of `.desktop` files within XDG autostart directories, followed by execution of processes at user login initiated by the desktop environment. Malicious entries typically include suspicious Exec paths or anomalous names and are not associated with installed packages.", "external_references": [{"external_id": "AN1096", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0390#AN1096"}], "id": "x-mitre-analytic--7bd7f602-0f85-4e96-bd40-ae4a6f490b32", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1096", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "creat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Process execution via .desktop Exec path from /etc/xdg/autostart or ~/.config/autostart", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Write or modify .desktop file in XDG autostart path", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "User login event followed by unexpected process tree", "name": "linux:auth", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex or allowlist of expected Exec paths within .desktop files. Deviations may be suspicious.", "field": "ExecCommandPattern"}, {"description": "May vary by user config (e.g., $XDG_CONFIG_HOME). Must enumerate actual values per system.", "field": "AutostartDirectory"}, {"description": "Correlate file creation/mod + exec within login window (e.g., 0–5 min of user logon).", "field": "TimeWindow"}, {"description": "Should filter to non-system users, as XDG persistence typically targets interactive sessions.", "field": "UserContext"}, {"description": "Compare .desktop entries to known package sources (e.g., `dpkg -S`). Unexpected origins may be suspicious.", "field": "PackageOriginBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3089', 0, 217, '09-mitre-attack', 'retrieved', '317FB928C67BC58A407516579F3BE13CB7C311216A26CB6AB939055556EACB76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
