INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3090', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configuration changes to virtual TAP/mirror policies that forward traffic to unapproved destinations. Detection correlates management plane API calls with mirrored traffic observation.", "external_references": [{"external_id": "AN1131", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0403#AN1131"}], "id": "x-mitre-analytic--7becb616-f907-4533-a425-08ca42440e3f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1131", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateTrafficMirrorSession or ModifyTrafficMirrorTarget", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Traffic observed on mirror destination instance", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect mirror session creation followed by mirrored traffic within X seconds (e.g., 60s)", "field": "TimeWindow"}, {"description": "Define suspicious or external mirror targets (e.g., non-enterprise ranges)", "field": "MirrorDestinationCIDR"}, {"description": "Flag traffic mirror activity by non-privileged or unexpected IAM roles", "field": "UserIdentity"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3090', 0, 121, '09-mitre-attack', 'retrieved', '84C2B19D226A7B170CA47B7F3EECE2DBEAAD1AACC70A151CB4B9CEC9C5510E64', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
