INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3092', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "File lock acquired via open() + flock() or lockf() on predictable path (e.g., /tmp/.lock123) followed by conditional early exit or divergent process behavior.", "external_references": [{"external_id": "AN0373", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0132#AN0373"}], "id": "x-mitre-analytic--7c0e4ffa-7f95-41de-9e3b-de2ad4a7a9ae", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0373", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, flock, fcntl, unlink", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "exit_group", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect patterns like /tmp/.lock*, /var/run/*lock used by malware.", "field": "lockfile_path_regex"}, {"description": "Track specific exit codes (e.g., 1, 2) that signal lock acquisition failure.", "field": "exit_code"}, {"description": "Correlate lockfile access + early process termination within N seconds.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3092', 0, 116, '09-mitre-attack', 'retrieved', '5FF70EF55DBEDE88C4B057893FE07837DC401F7DC4FD5BED5140FEA61CA1FD32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
