VALUES ('doc-09-mitre-attack-p0-3095', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of VNC service or executable starting unexpectedly, followed by user session creation and interactive desktop activity (mouse/keyboard simulation).", "external_references": [{"external_id": "AN0504", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0178#AN0504"}], "id": "x-mitre-analytic--7c91d6c7-4591-41b1-9c08-0c0660b07d24", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0504", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "port 5900 inbound", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate VNC process with user logon activity within defined time span", "field": "TimeWindow"}, {"description": "Trackable VNC executable names (e.g., vncserver.exe, winvnc.exe)", "field": "VNCBinaryList"}, {"description": "Limit detection to interactive logons (type 10)", "field": "LogonType"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3095', 0, 113, '09-mitre-attack', 'retrieved', 'F3BC48FBB964489676FCA3AC56F1E473B47F9C1A64725BC75938E0C8283A11EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
