VALUES ('doc-09-mitre-attack-p0-3096', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects staging of sensitive files into temporary or public directories, compression with 7zip/WinRAR, or batch copy prior to exfiltration.", "external_references": [{"external_id": "AN0040", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0014#AN0040"}], "id": "x-mitre-analytic--7cb2010a-e502-4117-94f3-fa3bd8d64a34", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0040", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Temp folders or user profile staging directories", "field": "StagingDirectoryList"}, {"description": "7z.exe, rar.exe, zip.exe paths", "field": "CompressionToolList"}, {"description": "Temporal bounds for detecting batch staging activities", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3096', 0, 105, '09-mitre-attack', 'retrieved', '4C3B81195A42D64F8EDBEAE76E993B60703B24E17A6924618F32DC6AD1F1E0C2', 'v1', '{"source_id