VALUES ('doc-09-mitre-attack-p0-3098', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlated user account modification (reset, disable, deletion) events with anomalous process lineage (e.g., PowerShell or net.exe from an interactive session), especially outside of IT admin change windows or by non-admin users.", "external_references": [{"external_id": "AN0334", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0120#AN0334"}], "id": "x-mitre-analytic--7d0595b9-eca7-488d-bbc2-ed02ff4ced9b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0334", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4723, 4724, 4740", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Account performing the operation (e.g., Domain Admins vs. local users)", "field": "UserContext"}, {"description": "Alert only on actions outside of maintenance windows", "field": "TimeWindow"}, {"description": "Detect suspicious process lineage (e.g., powershell.exe launching net.exe)", "field": "ParentProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3098', 0, 119, '09-mitre-attack', 'retrieved', 'E1A43640EC562D8A5CC3CF39FB52EFC4F08C7764208714B03A846F1828F115C2', 'v1', '{"source_id": "09-mit