VALUES ('doc-09-mitre-attack-p0-3099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal CPU/memory usage by unauthorized processes with outbound connections to known mining pools or using cron jobs/scripts to maintain persistence.", "external_references": [{"external_id": "AN0742", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0267#AN0742"}], "id": "x-mitre-analytic--7d099bc4-1a19-4aa3-b12b-a9390e98408a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0742", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Sustained high /proc/[pid]/stat usage", "name": "linux:procfs", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Outbound traffic to mining pools or proxies", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Location of resource-heavy binaries (e.g., /tmp/.xmr)", "field": "ProcessPath"}, {"description": "Acceptable baseline for CPU overuse", "field": "CPUThreshold"}, {"description": "List of domains/IPs for known cryptomining services", "field": "KnownMiningDomains"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3099', 0, 113, '09-mitre-attack', 'retrieved', 'DF0A8E2A2943D863A70E616EF8B93F1C50F3F7E8E8053DE7066C234245E2B