VALUES ('doc-09-mitre-attack-p0-3100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ICMP or raw socket traffic generated by user-mode processes like bash, Python, or nc, typically using `ping`, `hping3`, or crafted packets via libpcap or scapy.", "external_references": [{"external_id": "AN1255", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0457#AN1255"}], "id": "x-mitre-analytic--7d0a3871-8cee-47bd-8829-637e132c98f7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1255", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "sendto/connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "icmp.log, weird.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Uncommon programs using raw sockets (e.g., netcat, Python, nmap).", "field": "RawSocketExecutionPath"}, {"description": "Tunable window for correlating execution with network events (e.g., 2m).", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3100', 0, 102, '09-mitre-attack', 'retrieved', 'FA025449CE14B86F334ABB7C6A937BBE560FD12AC2300FF034BF53A8EA58A292', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
