VALUES ('doc-09-mitre-attack-p0-3102', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes accessing TCC-protected input APIs or polling HID services without user interaction, or dynamically loaded keylogging frameworks using accessibility privileges", "external_references": [{"external_id": "AN0689", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0246#AN0689"}], "id": "x-mitre-analytic--7d5eb9bd-5e53-4cf8-b86d-7136bbf8f673", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0689", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "com.apple.securityd, com.apple.tccd", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "query: process_events, launchd, and tcc.db access", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection of programs requesting access to input monitoring (e.g., CGEventTap)", "field": "AccessibilityAPIUsage"}, {"description": "Alert if TCC settings are altered or bypassed", "field": "TCCBypassAttempt"}, {"description": "Tunable based on developer signing status (legitimate software vs unsigned)", "field": "SignedBinaryCheck"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3102', 0, 114, '09-mitre-attack', 'retrieved', '6D4AB461BEE81007B48B70F820D05CB643B08420515CDEE29C3C0E96412E3A73', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
