VALUES ('doc-09-mitre-attack-p0-3104', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Programmatic or excessive access to file shares, SharePoint, or database repositories by users not typically interacting with them. This includes abnormal access by privileged accounts, enumeration of large numbers of files, or downloads of sensitive content in bursts.", "external_references": [{"external_id": "AN1160", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0413#AN1160"}], "id": "x-mitre-analytic--7dce56f3-43db-4787-ae13-bd2ce6851088", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1160", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5145", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "Accessed SharePoint files or pages", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Privileged users may be excluded if they routinely perform admin actions on SharePoint or file shares.", "field": "UserContext"}, {"description": "The number of files accessed or pages retrieved in a short window to flag as abnormal.", "field": "AccessVolumeThreshold"}, {"description": "The time range (e.g., 5 minutes, 1 hour) in which burst access patterns are considered anomalous.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3104', 0, 150, '09-mitre-attack', 'retrieved', '3C43EBCBE37600F57C0EB73F0E257A3EA9140B76E7C855C12052DC66049F3FFD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
