VALUES ('doc-09-mitre-attack-p0-3107', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of LaunchAgents or LaunchDaemons with names resembling known system services but executing non-Apple signed code or scripts.", "external_references": [{"external_id": "AN0326", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0117#AN0326"}], "id": "x-mitre-analytic--7e3c05c9-5e49-416c-a0c9-eb7631ea5e7e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0326", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/Library/LaunchDaemons/*.plist, ~/Library/LaunchAgents/*.plist", "name": "fs:fileevents", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "subsystem=com.apple.launchservices", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect plists with labels that closely resemble legitimate ones (e.g., `com.apple.updates.plist`)", "field": "PlistLabelSimilarity"}, {"description": "Toggle sensitivity for unsigned binaries or scripts launched by daemons", "field": "UnsignedBinaryExecution"}, {"description": "Scope detection based on whether LaunchAgent ran in user or system context", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3107', 0, 118, '09-mitre-attack', 'retrieved', '47520AF0D620F75514DA49B530CC2B15C3CF9041A72431A4D57F02B221F6D5C9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
