INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary creates disguised launch daemons or apps with misleading names and bundle metadata (e.g., Info.plist values inconsistent with binary path or icon). Launch is correlated with user logon or persistence setup.", "external_references": [{"external_id": "AN0357", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0127#AN0357"}], "id": "x-mitre-analytic--7ebea786-db9c-439d-9caf-d0dd740047f3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0357", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/install.log", "name": "fs:fileevents", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Mismatch between bundle metadata and file system path/name", "field": "InfoPlistDiscrepancy"}, {"description": "Unusual LaunchDaemon/LaunchAgent paths can be tuned per org", "field": "LaunchAgentPath"}, {"description": "Window between install and first execution (e.g., at user login)", "field": "ExecutionTrigger"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3111', 0, 123, '09-mitre-attack', 'retrieved', '1A85133967BBF3C258772B0F09E20A500DFF362D543F589EB8B02FE9B33649D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
