VALUES ('doc-09-mitre-attack-p0-3112', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T16:54:55.315Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious interactions with security products followed by service crashes, unexpected restarts, driver unloads, telemetry gaps, or tamper-state changes. Correlates exploit precursor behavior with immediate degradation of defensive services and follow-on process execution.", "external_references": [{"external_id": "AN2038", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0900#AN2038"}], "id": "x-mitre-analytic--7ec436a3-dd31-4d23-a51b-0e03d3c474bd", "modified": "2026-05-12T16:30:18.379Z", "name": "Analytic 2038", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7035", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time between suspicious interaction and security service failure", "field": "CrashCorrelationWindow"}, {"description": "Security agents/services expected to remain stable", "field": "ProtectedServiceList"}, {"description": "Acceptable heartbeat silence duration", "field": "TelemetryGapThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3112', 0, 125, '09-mitre-attack', 'retrieved', 'E50B7F0CB01D55D61B68998D5557514C83D2F2584FA786484AD407F747FCB0E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
