VALUES ('doc-09-mitre-attack-p0-3113', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of raw access to physical drives, modification of boot records (MBR/VBR), and suspicious file creation or alteration within the EFI System Partition (ESP). Correlates privileged process execution with low-level disk modification and unexpected driver or firmware interactions.", "external_references": [{"external_id": "AN0428", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0150#AN0428"}], "id": "x-mitre-analytic--7edc8ff6-0616-4fab-a7b7-1bd3d08cc0b1", "modified": "2025-11-12T17:35:05.178Z", "name": "Analytic 0428", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=9", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline hashes of clean MBR/VBR sectors for comparison", "field": "KnownGoodMBRHashes"}, {"description": "Approved EFI executables within ESP directories", "field": "ESPFileWhitelist"}, {"description": "Correlation window between privileged access, raw disk modification, and EFI file creation", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3113', 0, 126, '09-mitre-attack', 'retrieved', '0B5D0D65C3C2389FBCCBA14FB77D504E30419BB21EE6BFB9A46C2D49DD402308', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
