VALUES ('doc-09-mitre-attack-p0-3114', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious invocation of GUI utilities or scripts with suppressed or redirected windowing options. Defender view: detection of X11 or Wayland calls to spawn windows that do not appear on active displays, or use of nohup/screen/tmux to mask interactive shells.", "external_references": [{"external_id": "AN0361", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0128#AN0361"}], "id": "x-mitre-analytic--7ef0d746-f233-4b41-b999-43a6b1484574", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0361", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of GUI-related binaries with suppressed window/display flags", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Use of fork/exec with DISPLAY unset or redirected", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict monitoring to interactive GUI contexts rather than server/headless processes.", "field": "DisplayScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3114', 0, 117, '09-mitre-attack', 'retrieved', '0EEFCAE884D2A07EEC2DD524993C3976A8209D2A4A75DBC44986D42C7A276FF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
