VALUES ('doc-09-mitre-attack-p0-3115', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects file transfers or mounting operations from remote hosts followed by write actions into a local staging directory, often using SMB or remote shell activity.", "external_references": [{"external_id": "AN0194", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0071#AN0194"}], "id": "x-mitre-analytic--7efd6a7b-d7c0-4922-a1df-c492c0a2d3f8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0194", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=31001", "name": "WinEventLog:Microsoft-Windows-SMBClient/Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"channel": "CommandLine=copy-item or robocopy from UNC path", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common directories such as C:\\Temp, Downloads, or hidden folders used for remote staging", "field": "StagingDirectory"}, {"description": "UNC paths like \\\\10.* or \\\\domain\\share indicating lateral data staging", "field": "RemotePathPatterns"}, {"description": "Usage of robocopy, xcopy, copy-item, or scheduled tasks performing cross-host copies", "field": "CopyToolPatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3115', 0, 130, '09-mitre-attack', 'retrieved', 'D83CA90D27931FF3EEA819B311D38E0658A65E47C5BB8C712DC8BC671662F14F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
