VALUES ('doc-09-mitre-attack-p0-3116', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of hash cracking binaries or scripts (e.g., john, hashcat) following access to shadow file or dumped hashes", "external_references": [{"external_id": "AN0293", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0105#AN0293"}], "id": "x-mitre-analytic--7efdc4e3-8a2e-4d0d-8ced-03155f2c55ac", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0293", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "auth.log or custom tool logs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Access to /etc/shadow or known dumped hash files", "field": "ShadowAccessPattern"}, {"description": "Tool path or name associated with hash cracking", "field": "CrackingBinaryPath"}, {"description": "Sustained CPU load post-credential dump can be an indicator", "field": "CPUUsageThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3116', 0, 107, '09-mitre-attack', 'retrieved', '6DF97FD692981B1E557F871FCB6E0FC7AC45791390A5BE1F934FEA086DF2354E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
