INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3118', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "`socat`, `ssh`, `iptables`, or `ncat` invoked from user space or cron jobs to create port forwarding, reverse shells, or inter-host tunnels between compromised Linux systems. Behavior is typically paired with socket activity and high entropy traffic.", "external_references": [{"external_id": "AN0205", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0075#AN0205"}], "id": "x-mitre-analytic--7f269271-6800-4d20-b9f7-6c38cecac6f0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0205", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Internal connection logging", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alert on unexpected users executing inter-host relay tools (e.g., `www-data`, `backup`).", "field": "UserContext"}, {"description": "Adjust to watch for commonly misused internal TCP/UDP ports.", "field": "PortRange"}, {"description": "Shell pipelines or wrapped invocations like `bash -c ''socat ...''`", "field": "ProcessPattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3118', 0, 134, '09-mitre-attack', 'retrieved', 'CE8E2F3469008EAE7FEDA68C5401533E20DFC61D44C9B8CB308AB3C085D7D556', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
