VALUES ('doc-09-mitre-attack-p0-3119', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of adversary behavior that disables or modifies security tools, including killing AV/EDR processes, stopping services, altering Sysmon registry keys, or tampering with exclusion lists. Defenders observe process/service termination, registry modification, and abnormal absence of expected telemetry.", "external_references": [{"external_id": "AN1369", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0497#AN1369"}], "id": "x-mitre-analytic--7faf6f37-f074-4b9d-be19-618c3516486d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1369", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=5", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of expected administrative tools/processes to prevent false positives.", "field": "ProcessNameExclusions"}, {"description": "Defines correlation window linking process termination, registry edits, and service stoppage.", "field": "TimeWindow"}, {"description": "Customizable list of security service names per enterprise deployment.", "field": "ServiceNames"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3119', 0, 133, '09-mitre-attack', 'retrieved', 'BE7F1120A8D14C6CA645D720515EEDDEBE4A24D050EABD7280AB37322D495F1E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
