VALUES ('doc-09-mitre-attack-p0-3120', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual reuse of OAuth access tokens from different geographic regions, without full login events.", "external_references": [{"external_id": "AN0957", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0957"}], "id": "x-mitre-analytic--7fb5fe4f-ecd1-45a1-8a0f-dc913587e650", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0957", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "access_token issued", "name": "saas:googleworkspace", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "API access without user login", "name": "saas:googleworkspace", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum distance between token reuse events to trigger detection", "field": "GeoIPDistanceThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3120', 0, 82, '09-mitre-attack', 'retrieved', '8CFEA04EADD325CC694F461804005633E4AE8B8EEB4C31261118618975F37A1B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
