VALUES ('doc-09-mitre-attack-p0-3121', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "File reads or process executions involving insecurely stored credential files (e.g., config files with password fields) by non-root or anomalous users followed by ssh authentication attempts.", "external_references": [{"external_id": "AN0857", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0307#AN0857"}], "id": "x-mitre-analytic--7ff5d08a-5d4d-4260-85ee-fdb6a244f258", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0857", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read of sensitive config or secret files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "grep/cat/awk on files with password fields", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "authentication success after file access", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns like password, secret, token can be expanded or customized", "field": "RegexPatterns"}, {"description": "Scope of users monitored (e.g., root vs all users)", "field": "UserContextScope"}, {"description": "Time between suspicious file access and credential use", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3121', 0, 134, '09-mitre-attack', 'retrieved', '5C5F4ACE008BE2864C4F11E0CA4FC16C8F7F99A005711DC250DB73D5A35A27D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
