VALUES ('doc-09-mitre-attack-p0-3122', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversarial archiving activity through invocation of utilities like tar, gzip, bzip2, or openssl used in non-administrative or unusual contexts. Correlates command execution patterns with file creation of compressed/encrypted outputs in staging directories (e.g., /tmp, /var/tmp).", "external_references": [{"external_id": "AN1459", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0526#AN1459"}], "id": "x-mitre-analytic--8018e3a6-ab64-4fe2-9771-ca129091bc17", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1459", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of tar, gzip, bzip2, or openssl with output redirection", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "create: Creation of files ending in .tar, .gz, .bz2, .zip in /tmp or /var/tmp", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of archiving/encryption utilities considered sensitive in the monitored environment.", "field": "ArchiveCommands"}, {"description": "Paths where archive creation is suspicious (e.g., /tmp, user home directories).", "field": "SuspiciousDirectories"}, {"description": "Temporal window to correlate command execution with file creation events.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3122', 0, 150, '09-mitre-attack', 'retrieved', '8CBF80630601718323347885F6FD946048B8FD4576819407CB52A6EAE7C1CD9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
