VALUES ('doc-09-mitre-attack-p0-3123', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect user account logon attempts that trigger multiple MFA challenges through enterprise identity integrations, especially if MFA push requests are generated without successful interactive login.", "external_references": [{"external_id": "AN0454", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0160#AN0454"}], "id": "x-mitre-analytic--801a3652-8772-4b69-8a13-d870be653ef0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0454", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authd generating multiple MFA token requests", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude unmanaged macOS devices that use different MFA providers", "field": "DeviceEnrollmentStatus"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3123', 0, 87, '09-mitre-attack', 'retrieved', '932265464D5139F72A8B2FA9219F0E12D256884D94AC7E08226281ECB341BC13', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
