VALUES ('doc-09-mitre-attack-p0-3124', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes like git, curl, or python scripts executing commands that package files (tar, gzip) followed by HTTPS uploads to code repository endpoints. Defender view: detect unusual git push activity or scripted HTTPS requests outside normal developer work hours.", "external_references": [{"external_id": "AN0896", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0318#AN0896"}], "id": "x-mitre-analytic--8049e0b4-961b-499f-9204-45fa9b7117be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0896", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "git push, curl -X POST", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "open/read of sensitive directories", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "large outbound HTTPS uploads to repo domains", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline normal developer activity periods to reduce false positives.", "field": "WorkHours"}, {"description": "Known allowed internal or external repository domains.", "field": "RepoDomainList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3124', 0, 130, '09-mitre-attack', 'retrieved', 'CE44D2EFF171312EEC5767E6000F2901CF8672D4A95B175149FCE8F1339DB867', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
