VALUES ('doc-09-mitre-attack-p0-3126', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors execution of ps, top, or launchctl with unusual parent processes or from terminal scripts. Also detects AppleScript-based process listing or `system_profiler SPApplicationsDataType` misuse.", "external_references": [{"external_id": "AN0097", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0034#AN0097"}], "id": "x-mitre-analytic--80939714-6d17-4cc0-accd-3e1d634846bc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0097", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process launch", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Process Context", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable to detect discovery from non-UI tools or script-based execution (osascript, zsh, cron)", "field": "ParentApp"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3126', 0, 93, '09-mitre-attack', 'retrieved', '066DEEB88D79785567F6F29224809FA2259E57E22D32C695AE4934F56D3D1968', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
