INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3127', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries create the ''Office Test\\Special\\Perf'' registry key and specify a malicious DLL path that is auto-loaded when an Office application starts. This DLL is injected into the Office process memory space and can provide persistent execution without requiring macro enablement.", "external_references": [{"external_id": "AN0880", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0315#AN0880"}], "id": "x-mitre-analytic--80be1bd7-b4e8-4d1b-b294-56b1c073bbe0", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0880", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Unexpected DLL or component loaded at Office startup", "name": "WinEventLog:Microsoft-Office-Alerts", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to ''Office test\\Special\\Perf'' may vary by Office version, 32/64-bit, or architecture (HKCU vs HKLM)", "field": "RegistryPath"}, {"description": "Injected DLL may reside in different user-writable locations (e.g., %APPDATA%, %TEMP%, or network shares)", "field": "DLLPath"}, {"description": "Process name (e.g., winword.exe, excel.exe) may vary by Office deployment and usage", "field": "OfficeProcessName"}, {"description": "Time between DLL registry creation and first Office execution may vary depending on user activity", "field": "TimeWindow"}, {"description": "Malicious DLL may target only specific users, necessitating correlation with interactive logon sessions", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3127', 0, 201, '09-mitre-attack', 'retrieved', '1CEA4F2CD38BF927108C363BDABD7A8306A7E740056533ED54C77DB17218BA32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
