VALUES ('doc-09-mitre-attack-p0-3129', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of built-in or AppleScript-based system enumeration via `arp`, `netstat`, `ping`, and discovery of `/etc/hosts` contents.", "external_references": [{"external_id": "AN1585", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0574#AN1585"}], "id": "x-mitre-analytic--80c7f835-116d-4fa1-817a-08965efef16c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1585", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to suspicious users or automation contexts", "field": "ExecutionUser"}, {"description": "Adapt for expected enumeration tooling used in IT", "field": "CommandSignature"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3129', 0, 89, '09-mitre-attack', 'retrieved', 'FA4718EF8A092CD9047C6BBFC0F9CEA35DF48245F3D96A566F3A34B8B2BE5E5D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
