VALUES ('doc-09-mitre-attack-p0-3130', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious modification of file artifacts (e.g., logs, ISO templates) on ESXi datastores, followed by beaconing or POST operations to external IPs potentially hiding payloads in file-like traffic.", "external_references": [{"external_id": "AN0654", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0235#AN0654"}], "id": "x-mitre-analytic--80caf81c-0714-4fa5-8b77-8e2144e316b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0654", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Storage access and file ops", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Service initiated connections", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Transferred file observations", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for likely stego file names (e.g., wallpaper.jpg, template.iso).", "field": "FilenamePattern"}, {"description": "Destination outside vCenter management subnet.", "field": "UnusualDestinationIP"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3130', 0, 112, '09-mitre-attack', 'retrieved', '2190E0F19476525BAF64178BB7753E58B89BADE30ADB499594610DF8397E3659', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
