VALUES ('doc-09-mitre-attack-p0-3132', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects API calls registering or updating hybrid identity connectors, modification of cloud-to-on-premises federation trust, and unusual token issuance logs.", "external_references": [{"external_id": "AN0816", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0293#AN0816"}], "id": "x-mitre-analytic--80e4f847-a149-423b-a179-cbcf4afd06b9", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0816", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "UpdateFederationSettings or RegisterHybridConnector", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Federation trusts and connectors relevant to hybrid identity setup.", "field": "MonitoredFederations"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3132', 0, 78, '09-mitre-attack', 'retrieved', '9DB53292C8351FFF5E5A9A35064A554EAF68723924A2554F551053189230810B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
