VALUES ('doc-09-mitre-attack-p0-3135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of Linux Electron binaries by modifying app.asar or config JS files and spawning unexpected child processes (bash, curl, python).", "external_references": [{"external_id": "AN0072", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0025#AN0072"}], "id": "x-mitre-analytic--8129e7b8-eaa1-4459-ba70-ebf6d68ca16c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0072", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Electron-based binary spawning shell or script interpreter", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline of expected asar package signatures per app.", "field": "AsarIntegrityCheck"}, {"description": "Flag shells/python spawned from Electron parent.", "field": "SuspiciousChildProcesses"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3135', 0, 98, '09-mitre-attack', 'retrieved', '8C92A04369DD1658928B980A11B8412911B5242202C622324FB427451B8E408F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
