VALUES ('doc-09-mitre-attack-p0-3137', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavior chain involving unexpected API calls to capture keyboard input, driver loads for keyloggers, or remote use of smart card authentication via logon sessions not initiated by local user interaction", "external_references": [{"external_id": "AN0687", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0246#AN0687"}], "id": "x-mitre-analytic--8180320e-ab62-44e5-afae-eba6ba23d769", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0687", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable based on what memory-level access the keylogger uses (e.g., 0x10 for read)", "field": "AccessMask"}, {"description": "Legitimate accessibility tools may use similar API calls (e.g., Magnifier.exe)", "field": "ProcessNameExclusions"}, {"description": "Define how quickly access + registry mod + smart card use must co-occur", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3137', 0, 134, '09-mitre-attack', 'retrieved', '3FFAF8A61BC1DBD7EA351516F7EA1D50191257608B42A7DA1E1FC0810100CB9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
