VALUES ('doc-09-mitre-attack-p0-3140', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes that normally do not initiate network communications suddenly making outbound HTTPS connections with high outbound-to-inbound data ratios. Defender view: correlation between process creation logs (e.g., Word, Excel, PowerShell) and subsequent anomalous network traffic volumes toward common web services (Dropbox, Google Drive, OneDrive).", "external_references": [{"external_id": "AN1511", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0548#AN1511"}], "id": "x-mitre-analytic--81b1e9a7-b6f4-4cca-b07a-3498ab4abd4a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1511", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of legitimate web services to baseline (Dropbox, OneDrive, Google Drive).", "field": "MonitoredServices"}, {"description": "Outbound data threshold for flagging unusual activity, tunable by environment.", "field": "ExfilVolumeThreshold"}, {"description": "Aggregation period to calculate anomalies in outbound data volume.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3140', 0, 140, '09-mitre-attack', 'retrieved', '88C4BB27F9F13DA19D61CE3AC4C0206D6EAD6F331CB3CF1B92FAC55FDA246539', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
