VALUES ('doc-09-mitre-attack-p0-3141', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious MFA method changes, such as registration of weaker factors (e.g., SMS), or removal of MFA requirements for specific accounts or groups.", "external_references": [{"external_id": "AN0548", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0190#AN0548"}], "id": "x-mitre-analytic--81c940cd-633b-4f88-9f8f-f6837a7026bc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0548", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DisableMFA or RegisterNewFactor", "name": "saas:zoom", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Configured MFA factors allowed in SaaS environment; tuned to organizational policies.", "field": "AcceptedFactors"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3141', 0, 84, '09-mitre-attack', 'retrieved', '16E8296808F38F96E90C686A791256E9641E32413D28D3E1541DDFA9753B7536', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
