VALUES ('doc-09-mitre-attack-p0-3142', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) udev / kernel logs show hot-plug (USB/Thunderbolt/PCIe); (2) block device created by udisks/diskarbitration; (3) optional: new network interface or DHCP lease observed. Correlate /var/log/messages|syslog, auditd SYSCALL open/creat on /dev, and DHCP/Zeek.", "external_references": [{"external_id": "AN0186", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0069#AN0186"}], "id": "x-mitre-analytic--81cd2610-bc6c-46bf-8d3c-d6e30c7f51c8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0186", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "mknod,open,openat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "usb * new|thunderbolt|pci .* added|block.*: new .* device", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "LEASE_GRANTED", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Indicators such as ''RubberDucky'', ''BadUSB'', unfamiliar USB-NIC chipsets.", "field": "BlocklistDeviceStrings"}, {"description": "Hosts where any USB attach should alert (DCs, hypervisors).", "field": "ServerClassesNoUSB"}, {"description": "Scopes allowed to issue leases for corp endpoints vs. guest/IoT.", "field": "DHCPVlanScopes"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3142', 0, 133, '09-mitre-attack', 'retrieved', '3F778351FAC1BCF82658DE79ABC281E3521284CFF0D5BB13819D1E82B594223E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
