VALUES ('doc-09-mitre-attack-p0-3143', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects deletion of launch agents (~/Library/LaunchAgents/) and launch daemons (/Library/LaunchDaemons/), especially after suspicious process execution or when tied to known persistence methods.", "external_references": [{"external_id": "AN0115", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0040#AN0115"}], "id": "x-mitre-analytic--81d64cae-ddd2-4512-9c8a-9a574b968c52", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0115", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common plist file paths for persistence: ~/Library/LaunchAgents/*.plist", "field": "LaunchDaemonPath"}, {"description": "Ties deletion to parent process (e.g., suspicious AppleScript runner)", "field": "CorrelatedProcessImage"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3143', 0, 96, '09-mitre-attack', 'retrieved', '3B7959095E47AE9F13E49664EEC8875B378354D9D20B1A666C10630CB691E221', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
