VALUES ('doc-09-mitre-attack-p0-3146', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "OAuth token granted to external app followed by download of high-volume files in OneDrive/Google Drive", "external_references": [{"external_id": "AN1329", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0484#AN1329"}], "id": "x-mitre-analytic--8226ce94-1f5b-4ab0-b0bc-92f1d225eaa4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1329", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FileAccessed, FileDownloaded, ConsentGranted", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Pattern of suspicious OAuth app names (e.g., `rclone`, `mega`, `backup*`)", "field": "AppRegistrationNamePattern"}, {"description": "Flag file downloads over X MB (e.g., >100MB) within short intervals", "field": "DownloadThresholdMB"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3146', 0, 89, '09-mitre-attack', 'retrieved', '0ECA59C2969E559F8E04C55F329A756AD3F096824251729E32A50CAC85CBDE3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
