VALUES ('doc-09-mitre-attack-p0-3147', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect abnormal MFA activity within cloud service provider logs, such as repeated generation of MFA challenges for the same user session or mismatched MFA device and login origin.", "external_references": [{"external_id": "AN0450", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0160#AN0450"}], "id": "x-mitre-analytic--824db63f-2a2c-4e3e-8e7d-49110cc63173", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0450", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AssumeRole or ConsoleLogin with repeated MFA failures followed by repeated MFA requests", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of failed logins before raising detection", "field": "FailedLoginThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3147', 0, 94, '09-mitre-attack', 'retrieved', '13D07FA97A4701EC722073DCA9295EDC50235B81CECD7D45D29F9AEFC5EA14DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
