VALUES ('doc-09-mitre-attack-p0-3148', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Hidden file system use through APFS containers or custom plist configuration. Defender view: anomalous use of hdiutil or diskutil to attach hidden partitions, modification of plist entries tied to system volumes, or suspicious raw disk access.", "external_references": [{"external_id": "AN1273", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0461#AN1273"}], "id": "x-mitre-analytic--82908b5f-fa84-4420-bb1c-cc77e12e9d3c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1273", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of diskutil or hdiutil attaching hidden partitions", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Hidden volume attachment or modification events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust to target only relevant plist files linked to volume mounting.", "field": "MonitoredPlistPaths"}, {"description": "Restrict monitoring to sensitive processes like diskutil and hdiutil.", "field": "ProcessScope"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3148', 0, 125, '09-mitre-attack', 'retrieved', 'B194D6F4F6868B4E7056D47FAAA616EBA81FA1A1541964341D97A41112511287', 'v1', '{"source_id": "09-mitre-attack", "version": 