VALUES ('doc-09-mitre-attack-p0-3149', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects central router or switch config management tools (e.g., FortiManager, Cisco Prime) triggering device reboots or config pushes using abnormal accounts or IPs.", "external_references": [{"external_id": "AN0627", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0223#AN0627"}], "id": "x-mitre-analytic--82acd5d4-70e1-4f3e-b059-15bdc55cf4bf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0627", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "config push events", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Device-to-Device Deployment Flows", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Devices or IPs allowed to push firmware or scripts", "field": "PushSourceAllowList"}, {"description": "Expected CLI or API user performing configuration", "field": "AuthUserPattern"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3149', 0, 101, '09-mitre-attack', 'retrieved', '24BC5EB55DBBECA7F23689DDF43F8AEBB392CB9F01CBF9706EBABFC399465BD5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
