VALUES ('doc-09-mitre-attack-p0-3150', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes opening /proc/*/mem or /proc/*/maps targeting credential-storing services like sshd or login. Behavior often includes high privilege escalation and memory inspection tools such as gcore or gdb.", "external_references": [{"external_id": "AN0649", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0234#AN0649"}], "id": "x-mitre-analytic--82cdec5a-52af-4489-b002-b0256e5ba60e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0649", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "ptrace", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define sensitive targets (e.g., sshd, login) being memory-read.", "field": "TargetProcessName"}, {"description": "Flag use of memory dump tools like gcore, gdb, pmap.", "field": "ToolProcessName"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3150', 0, 108, '09-mitre-attack', 'retrieved', '142C5BC9D9065BADD6146F6C2B30E7804B050608E8DE0F926ED525964F97D561', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
