VALUES ('doc-09-mitre-attack-p0-3152', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors execution of administrative utilities (e.g., bcdedit.exe) or registry modifications that disable Driver Signature Enforcement (DSE) or enable Test Signing. Correlates command-line activity, registry changes, and subsequent process executions that bypass signing enforcement.", "external_references": [{"external_id": "AN1446", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0523#AN1446"}], "id": "x-mitre-analytic--83067587-4426-44cb-89de-f2b948c91104", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1446", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expand or restrict monitored utilities (e.g., bcdedit.exe, reg.exe) based on enterprise usage", "field": "MonitoredExecutables"}, {"description": "Customize registry paths tied to Driver Signing enforcement depending on OS version", "field": "RegistryPaths"}, {"description": "Correlation window between registry modification and subsequent unsigned binary execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3152', 0, 127, '09-mitre-attack', 'retrieved', 'B22E49ED893D4EECAA93F9038583F1C1EF0EECCB7A9DECFE2AE66A8F20755E70', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
