VALUES ('doc-09-mitre-attack-p0-3153', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi hosts initiating connections from non-standard daemons mimicking HTTP/HTTPS or SNMP traffic, but with irregular payload formats or expired/unsigned TLS certificates.", "external_references": [{"external_id": "AN1297", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0470#AN1297"}], "id": "x-mitre-analytic--8307d1d4-4f50-481b-9126-3b145fd68a73", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1297", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Service-Based Network Connection", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "TLS Fingerprint and Certificate Analysis", "name": "NSM:Content", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allows matching against known-good or known-bad JA3/JA3S hashes.", "field": "TLSFingerprintMatch"}, {"description": "Tune for expected network ports per ESXi role.", "field": "AllowedServicePorts"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3153', 0, 100, '09-mitre-attack', 'retrieved', 'EF68672544F2E5466DAA973F8380B564429AFADA3CDE24E05C24AB2F3B36A755', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
