VALUES ('doc-09-mitre-attack-p0-3154', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged SAML tokens may be leveraged to access O365 apps such as Outlook or SharePoint. Defenders should monitor for token replay across multiple clients or access attempts to privileged mailboxes without prior interactive login.", "external_references": [{"external_id": "AN0422", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0148#AN0422"}], "id": "x-mitre-analytic--8359e4ed-c4a1-4734-a3dd-e2d3eb33bc90", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0422", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Mailbox access using SAML token without corresponding MFA event", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "File access with forged or anomalous SAML claims", "name": "m365:sharepoint", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of times a token is reused within short timeframe.", "field": "ReplayDetectionThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3154', 0, 114, '09-mitre-attack', 'retrieved', '76C9878B125F305D4E02BA4CB99494B52188C00434719B1406E216393231FC3A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
