VALUES ('doc-09-mitre-attack-p0-3155', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "LaunchAgent or launchd recurring jobs initiating data transfer to consistent external IPs or domains with repeat timing signatures.", "external_references": [{"external_id": "AN1120", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0399#AN1120"}], "id": "x-mitre-analytic--837bd639-c291-4e42-b737-6a21d6bf8fd5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1120", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "launchd.plist and logs", "name": "macos:launchd", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"channel": "networkd or com.apple.network", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for job locations like ~/Library/LaunchAgents/", "field": "AgentPathPatterns"}, {"description": "Time-based logic to determine schedule (e.g., ~24h ± 5m)", "field": "RepeatIntervalDelta"}, {"description": "Transfers originating from non-admin user context", "field": "UserHomeJobs"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3155', 0, 109, '09-mitre-attack', 'retrieved', 'EAAF0E5D0A5259ED854CE5BDA608D1D0E278D3F4D69DD2CCA