VALUES ('doc-09-mitre-attack-p0-3156', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect suspicious file creations and process executions triggered by browser activity (e.g., injected payloads written to %AppData% or Temp directories, then executed). Correlate network anomalies with subsequent local process creation or script execution.", "external_references": [{"external_id": "AN0992", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0349#AN0992"}], "id": "x-mitre-analytic--8384d942-2f83-4968-9959-fd2f55afb311", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0992", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Unexpected script or binary content returned in HTTP response body", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "File extensions to flag (exe, dll, js, vbs, sh, etc.).", "field": "MonitoredExtensions"}, {"description": "Browser processes (chrome.exe, firefox.exe, edge.exe, etc.) monitored as possible parents for malicious activity.", "field": "SuspiciousParentProcesses"}, {"description": "List of suspicious domains or URLs used for malicious redirects.", "field": "RedirectList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3156', 0, 141, '09-mitre-attack', 'retrieved', '3B11F634D9E57CD01855417DD540B9915CC9DA23BC3B0F317780EA3C7C4E8D28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
