INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3157', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Massive recursive deletions or overwrites via `rm -rf`, `shred`, `dd`, or wiper binaries. May include unlink syscalls, deletion of known config/data paths, or sequential overwrite patterns.", "external_references": [{"external_id": "AN0412", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0146#AN0412"}], "id": "x-mitre-analytic--839d7053-fc62-433a-8eb2-ed87605160f7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0412", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unlink, unlinkat, openat, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on binaries like shred, dd, wipe, custom wipers, or bash execution chains.", "field": "ExecutablePath"}, {"description": "Tune for critical mount points or home/data directories.", "field": "DeletedPathPattern"}, {"description": "Rate of unlink/unlinkat syscalls to indicate mass deletion in a short period.", "field": "SyscallBurstRate"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3157', 0, 122, '09-mitre-attack', 'retrieved', 'F56397A2A61B467EE3865605F7BC40BCEA1FADF50D18A4C15756CD6699BFAC09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
