VALUES ('doc-09-mitre-attack-p0-3158', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects removal of persistence artifacts such as crontab entries, systemd service units, and malicious user accounts through commands like `crontab -r`, `rm /etc/systemd/system/*.service`, or `userdel`.", "external_references": [{"external_id": "AN0114", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0040#AN0114"}], "id": "x-mitre-analytic--83a2f3c2-24c5-466d-8453-aa52802c2991", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0114", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "file deletion", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targets suspicious or orphaned unit files in /etc/systemd/system/", "field": "ServicePathMatch"}, {"description": "Focus on crontab activity from root or uncommon users", "field": "CronUserScope"}, {"description": "Looks for userdel or passwd deletion", "field": "UserDeletionActivity"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3158', 0, 109, '09-mitre-attack', 'retrieved', '768734D6DA106CAA75B79DB78BBC839E074B2B08BD39604CFECB32138F8BD98A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
