VALUES ('doc-09-mitre-attack-p0-3159', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Modification of user desktop backgrounds, login screen messages, or system banners by adversaries using admin privileges or script execution. May coincide with tampering in /Library/Desktop Pictures/ or use of AppleScript.", "external_references": [{"external_id": "AN0231", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0082#AN0231"}], "id": "x-mitre-analytic--83d3222d-6a35-401d-95b5-a09f0eac2201", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0231", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "loginwindow or desktopservices modified settings or files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "osascript or AppleScript invocation modifying UI", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Uncommon scripts like AppleScript variants or osascript for wallpaper changes", "field": "ScriptNames"}, {"description": "Normal users should not alter global visual settings", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3159', 0, 116, '09-mitre-attack', 'retrieved', '5659D4EF3F9A9151AFC7699CB0B7B9790BCB63A851634079A74213A2F50CD7DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
