VALUES ('doc-09-mitre-attack-p0-3160', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects processes performing network enumeration (e.g., port scans, service probing) by correlating process creation, socket connections, and sequential destination IP probing within a time window.", "external_references": [{"external_id": "AN1057", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0376#AN1057"}], "id": "x-mitre-analytic--84299e85-2a7e-4f78-9767-3d29aa58857a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1057", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the number of unique destination IPs or ports accessed within a time window that may indicate a scan.", "field": "ScanRateThreshold"}, {"description": "List of binaries allowed to scan or used by IT (e.g., Nmap, Nessus).", "field": "KnownScannerExeList"}, {"description": "Temporal bounds for correlating sequential connections (e.g., 60 seconds).", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3160', 0, 127, '09-mitre-attack', 'retrieved', '4C72F11050514B03164E3E64B93D2C243F135E1E4DEEA8A13995D151853F8557', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
