VALUES ('doc-09-mitre-attack-p0-3161', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account attribute changes (e.g., password set, group membership, servicePrincipalName, logon hours) correlated with unusual process lineage or timing, indicating privilege escalation or persistence via valid accounts.", "external_references": [{"external_id": "AN0265", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0096#AN0265"}], "id": "x-mitre-analytic--842ba5ee-dcd0-42bd-9ef8-867a4ab1c703", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0265", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4738, 4728, 4670", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time between suspicious process and account change (e.g., 5m).", "field": "TimeWindow"}, {"description": "Customize group list (e.g., Domain Admins, Enterprise Admins) to monitor.", "field": "HighPrivilegeGroupList"}, {"description": "Flag if account modifier != modified user (potential hijack).", "field": "SubjectTargetMismatch"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3161', 0, 116, '09-mitre-attack', 'retrieved', '3B9D047CFC716C1D1914EE1999A0F64F31802F6DAE6AD744C3C9F89BF08F0776', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
