VALUES ('doc-09-mitre-attack-p0-3162', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Inconsistencies between process command-line arguments logged at creation time and subsequent process behavior. Defender perspective: monitoring for processes launched in a suspended state, followed by memory modifications (e.g., WriteProcessMemory targeting the PEB) that overwrite arguments before execution resumes. Detection also includes observing anomalous behaviors from processes whose logged arguments do not align with executed activity (e.g., network connections, file writes, or registry modifications).", "external_references": [{"external_id": "AN0126", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0045#AN0126"}], "id": "x-mitre-analytic--84ad99e5-4e6e-4d07-93ae-9e55e6f99707", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0126", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time window in which a process remains in suspended state before being modified. Tunable based on baseline activity in the environment.", "field": "SuspendedProcessWindow"}, {"description": "List of critical processes (e.g., explorer.exe, lsass.exe) where argument spoofing is highly suspicious. Can be customized per organization.", "field": "SensitiveProcesses"}, {"description": "Time span in which to correlate command-line inconsistencies with anomalous behavior such as network activity or registry modification.", "field": "BehavioralCorrelationWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3162', 0, 180, '09-mitre-attack', 'retrieved', 'E4B6444200CF61890051E6CC1DBD208EC6CB74FC84FA708AD3E0D41097D08EE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
