INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3165', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous wireless connections such as unexpected SSID associations, failed or repeated authentication attempts, and connections outside of known geofenced networks. Defenders should monitor wireless connection logs and event codes for network discovery, authentication, and association events.", "external_references": [{"external_id": "AN1476", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0536#AN1476"}], "id": "x-mitre-analytic--8586fd06-9801-473e-8ea6-d3da0ec82267", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1476", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=8001, 8002, 8003", "name": "WinEventLog:Microsoft-Windows-WLAN-AutoConfig", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4776, 4625", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines approved Wi-Fi SSIDs for the environment; deviations may indicate malicious connection attempts.", "field": "KnownSSIDList"}, {"description": "Correlates expected physical location of systems with observed Wi-Fi connections to detect anomalies.", "field": "GeoLocationContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3165', 0, 123, '09-mitre-attack', 'retrieved', 'CFB517B6A9BEE71FECC2A7B1F7DB7BF6C97587FE057455476B564BA808D62C11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
