INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3167', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries inject VBA macros into Office templates such as Normal.dotm or Personal.xlsb or redirect Office template load path via registry key (GlobalDotName) to gain persistence. Template macros trigger execution of malicious code on application startup.", "external_references": [{"external_id": "AN1436", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0519#AN1436"}], "id": "x-mitre-analytic--85b4c967-56bc-4990-b3e2-7e40f3ef1852", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1436", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "Office application warning or alert on macro execution from template", "name": "WinEventLog:Microsoft-Office-Alerts", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to Normal.dotm, Personal.xlsb, or Excel/Word startup templates may vary by Office version and user", "field": "TemplatePath"}, {"description": "GlobalDotName or equivalent registry keys may differ across Office versions or deployments", "field": "RegistryPath"}, {"description": "Office process creation and macro execution timing after system or user login", "field": "TimeWindow"}, {"description": "May be scoped to high-value users or those with access to sensitive templates", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3167', 0, 178, '09-mitre-attack', 'retrieved', '03C3F232B5AAC851EF1E3B63F2092D514A314B9B43F707ABC0EFC7E7864F7E81', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
