VALUES ('doc-09-mitre-attack-p0-3168', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of new admin or role assignment actions within Microsoft 365/O365 environments to elevate access for persistence or lateral movement.", "external_references": [{"external_id": "AN0773", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0277#AN0773"}], "id": "x-mitre-analytic--8601dbfa-8767-4328-8809-1930b53b5e31", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0773", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add member to role, Set-Mailbox", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Admin role type or application role granted", "field": "OfficeRoleType"}, {"description": "Time between initial login and privilege change", "field": "TimeWindow"}, {"description": "Was the role assignment local or via federated SSO account", "field": "ActionOrigin"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3168', 0, 103, '09-mitre-attack', 'retrieved', '6A548135C1695D68CBA2E443398048BD342C931A1CE6676AD53841B54FC221F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
