VALUES ('doc-09-mitre-attack-p0-3170', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access (ex: [Phishing](https://attack.mitre.org/techniques/T1566)).", "external_references": [{"external_id": "AN1967", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0835#AN1967"}], "id": "x-mitre-analytic--8619af40-05db-49a7-b7b8-476facfd4b2c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1967", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3170', 0, 76, '09-mitre-attack', 'retrieved', 'AE734E6569134B2509D16543FDECDAA2FE4AB4EB60457359720811A7FD9030F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
