VALUES ('doc-09-mitre-attack-p0-3171', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process invokes a standard encoder (e.g., PowerShell -enc, certutil -encode, base64 via .NET/Invoke-Expression) or emits long Base64/hex literals → shortly followed by outbound network egress with high bytes_out:bytes_in ratio or HTTP headers/payloads containing Base64/MIME blocks.", "external_references": [{"external_id": "AN0345", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0124#AN0345"}], "id": "x-mitre-analytic--861ee805-c979-44c9-8b0c-86bd3a6f5872", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0345", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "NetworkConnection: bytes_sent >> bytes_received anomaly", "name": "M365Defender:DeviceNetworkEvents", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Shannon entropy cutoff to consider payload suspicious (e.g., > 4.5–5.0 for HTTP body).", "field": "PayloadEntropyThreshold"}, {"description": "Min continuous Base64 token length in command lines/script blocks to alert (e.g., > 100 chars).", "field": "B64LengthThreshold"}, {"description": "Correlation window between encoding event and egress (default 10m).", "field": "TimeWindow"}, {"description": "Legitimate tools (e.g., backup agents) that routinely encode/compress data.", "field": "KnownAdminTools"}, {"description": "Minimum ratio to treat flow as asymmetric (e.g., ≥ 4:1).", "field": "BytesOutToInRatio"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3171', 0, 177, '09-mitre-attack', 'retrieved', '6042E812F7C8E006BCC6421886CBC211AF06AA1A685B31735AA960E3911CD62D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
