VALUES ('doc-09-mitre-attack-p0-3172', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious process initiating outbound connections to web services without corresponding response or return traffic, indicative of one-way command channels.", "external_references": [{"external_id": "AN1599", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0581#AN1599"}], "id": "x-mitre-analytic--8626f553-efed-4418-bbc6-b9fa83b0b315", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1599", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "WinINet API telemetry", "name": "etw:Microsoft-Windows-WinINet", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can tune for popular web services (e.g., googleapis.com, github.com) based on threat actor tooling", "field": "DestinationDomain"}, {"description": "May adjust temporal window to catch beaconing patterns (e.g., every 10-30 mins)", "field": "TimeWindow"}, {"description": "Environment-specific tuning to exclude expected update or telemetry tools", "field": "ProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3172', 0, 117, '09-mitre-attack', 'retrieved', '8951518363751DEB366181260047942515E44B0C58098C937CACBF520E11FEBE', 'v1', '{"source_id": "09-mitre-attack",