VALUES ('doc-09-mitre-attack-p0-3173', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Alterations to plist configuration files (RulesActiveState.plist, SyncedRules.plist, UnsyncedRules.plist, MessageRules.plist) that define email hiding or filtering rules. Defender perspective: unexpected changes in these files associated with Mail.app processes.", "external_references": [{"external_id": "AN0552", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0192#AN0552"}], "id": "x-mitre-analytic--863a9028-6b2a-46c6-b696-dd310937fbf9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0552", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Modifications to Mail.app plist files controlling message rules", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Mail.app executing with parameters updating rules state", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust to monitor only rule-related plist files relevant to the environment.", "field": "WatchedPlistFiles"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3173', 0, 105, '09-mitre-attack', 'retrieved', 'F321EAB930437CBDB907372068F396EE6FEBF5C6ADDDE31B966D14D17CC687FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
