VALUES ('doc-09-mitre-attack-p0-3174', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of trusted, Microsoft-signed binaries such as `rundll32.exe`, `msiexec.exe`, or `regsvr32.exe` used to execute externally hosted, unsigned, or suspicious payloads through command-line parameters or network retrieval.", "external_references": [{"external_id": "AN0226", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0081#AN0226"}], "id": "x-mitre-analytic--865c00d7-fc01-4ce6-8fc8-d7a84f2ded36", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0226", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Used to profile unexpected parent-child relationships (e.g., regsvr32.exe not launched by explorer.exe)", "field": "ParentProcessName"}, {"description": "List of known signed binaries allowed for execution (e.g., msiexec.exe, regsvr32.exe)", "field": "SignedBinaryList"}, {"description": "Regex to match suspicious arguments, such as URLs, script paths, or DLL entrypoints", "field": "CommandLineRegex"}, {"description": "Filter to suppress activity contacting legitimate enterprise domains", "field": "RemoteDomainAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3174', 0, 140, '09-mitre-attack', 'retrieved', 'B65B7C79ECAC8EE06C9B6FDCDF3A86D86199421C63F25B91251D4DA4C0FDA856', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
