VALUES ('doc-09-mitre-attack-p0-3175', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Automated abuse of cloud-hosted applications (e.g., web apps, REST endpoints, internal APIs) causing compute exhaustion, high 5xx error rates, or frequent autoscaling triggers logged in app insights or cloudwatch.", "external_references": [{"external_id": "AN1168", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0415#AN1168"}], "id": "x-mitre-analytic--867239cd-7939-446c-9efb-b2a7a5bd5403", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1168", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Elevated 5xx response rates in application logs or gateway layer", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "InvokeFunction", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"channel": "Autoscaling, memory/cpu alarms, or instance unhealthiness", "name": "AWS:CloudMetrics", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Ratio of 5xx error codes over requests indicating resource exhaustion.", "field": "HTTP5xxRateThreshold"}, {"description": "Spike in lambda/API gateway executions indicating scripted behavior.", "field": "FunctionInvocationRate"}, {"description": "Triggers linked to app DoS where legitimate scaling is mimicked.", "field": "AutoscaleEventCount"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3175', 0, 137, '09-mitre-attack', 'retrieved', 'E5740C4AB7FBF1AB17D5A001EC2B1ED278DBA8DB8D5199BEF42221945B043F64', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
