VALUES ('doc-09-mitre-attack-p0-3176', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may observe adversary attempts to alter or replace a network device’s operating system image through anomalous CLI commands, unexpected firmware updates, integrity check failures, or mismatches in version and checksum validation. Suspicious behavior includes modification of image files on storage, OS version output inconsistent with baselines, unexpected reloads or reboots after image replacement, and changes to boot configuration that load non-standard system images.", "external_references": [{"external_id": "AN0482", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0170#AN0482"}], "id": "x-mitre-analytic--868abb22-3d6c-4172-bf38-9e3c1aba4dae", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0482", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of commands to load, copy, or replace system images (e.g., ''copy tftp flash'', ''boot system'')", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Configuration changes to boot variables, startup image paths, or checksum verification failures", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines trusted administrator accounts allowed to modify system images; deviations indicate possible malicious modification.", "field": "AuthorizedAdminAccounts"}, {"description": "Whitelist of validated vendor OS images; unexpected versions may suggest adversarial tampering.", "field": "ApprovedFirmwareVersions"}, {"description": "Correlation window for detecting config changes followed by firmware updates or reboots.", "field": "TimeWindow"}, {"description": "Baseline cryptographic hashes of approved system images; deviations may indicate compromise.", "field": "ChecksumBaseline"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3176', 0, 203, '09-mitre-attack', 'retrieved', '6D6619589AA94535BCDB390E3C0CA8DC8B23A73B5A6DD3E7CC59EC38629AE75B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
