INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3180', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual screensaver (.scr) executions correlated with recent registry modifications to HKCU\\Control Panel\\Desktop values such as SCRNSAVE.exe, ScreenSaveTimeout, and ScreenSaveActive. Detection focuses on PE image paths not consistent with known legitimate screensavers and triggered after user inactivity timeout.", "external_references": [{"external_id": "AN0441", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0154#AN0441"}], "id": "x-mitre-analytic--86dbac4c-1cba-4056-84a1-604eefbb11ac", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0441", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust the user inactivity threshold that defines ''screensaver trigger window''; shorter timeouts may increase sensitivity.", "field": "TimeWindow"}, {"description": "Allow tuning based on expected paths for legitimate .scr files vs suspicious locations (e.g., user temp directories).", "field": "SuspiciousPathRegex"}, {"description": "Allowlisting known legitimate initiators of .scr files (e.g., user32.dll context) to reduce false positives.", "field": "ParentProcessAllowList"}, {"description": "Monitor for registry modification performed by unusual processes (e.g., powershell.exe, reg.exe).", "field": "RegistryEditorProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3180', 0, 158, '09-mitre-attack', 'retrieved', '9A4ACC402C4586BB88BD957AAC8145331D3CF153C4879CD56E94E5615232D4E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
