INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3182', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "1) Package manager or curl/wget installs/upgrades from non-approved repos or unsigned packages; 2) new ELF written into PATH directories or replacement of existing binaries/libraries; 3) first run leads to unexpected child processes or outbound connections.", "external_references": [{"external_id": "AN1481", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0537#AN1481"}], "id": "x-mitre-analytic--86f2dfd5-7073-4178-8c83-8628ecf087d4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1481", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve, unlink", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open, rename", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"channel": "dpkg/apt install, remove, upgrade events", "name": "journald:package", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "First-time egress to unknown registries/mirrors immediately after install", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allow-listed APT/YUM repo URLs and GPG key fingerprints.", "field": "ApprovedRepos"}, {"description": "Directories to watch for new ELF writes (e.g., /usr/bin, /usr/local/bin, /lib*/, /opt/*/bin).", "field": "PathScope"}, {"description": "Ignore tiny helper files; default >16KB.", "field": "MinBinarySize"}, {"description": "Install→first-run correlation window (default 2h).", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3182', 0, 154, '09-mitre-attack', 'retrieved', '6F86A4F7A087EAB3DCA3965075151836297DBAD52C129CDDC12FA837CF25CB31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
