INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3183', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Track creation or update of SaaS automation scripts (e.g., Google Workspace Apps Script). Detect when these scripts are bound to user events such as file opens or account modifications, and correlate with subsequent abnormal API calls that exfiltrate or modify user data.", "external_references": [{"external_id": "AN1055", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0374#AN1055"}], "id": "x-mitre-analytic--8708dc0b-8eeb-4a3d-8770-2fab30f46682", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1055", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Create / Update: Deployment of scripts with event-driven triggers", "name": "saas:appsscript", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "FileOpen / FileAccess: Event-driven script triggering on user file actions", "name": "saas:googledrive", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Which SaaS apps or APIs can be legitimately automated in the environment", "field": "ScriptScope"}, {"description": "Event-driven triggers (e.g., on file open, on user creation) considered suspicious", "field": "TriggerTypes"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3183', 0, 139, '09-mitre-attack', 'retrieved', 'AF42C7F3445A24750F7E1DE187E4D747B9238976D3AC30F83D4123EBC8C63E23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
