INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3185', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects deletion of suspicious files (e.g., payloads, temp exes, scripts) via `rm`, `unlink`, or secure deletion tools like `shred`, especially when performed by unexpected users or shortly after execution.", "external_references": [{"external_id": "AN0393", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0140#AN0393"}], "id": "x-mitre-analytic--874f0437-1aab-4cfe-a30a-7586c0602b6f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0393", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PATH", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Pattern matching known attacker staging directories or hidden file paths.", "field": "PathRegex"}, {"description": "Deletion shortly after process execution or privilege escalation.", "field": "TimeWindow"}, {"description": "Uncommon presence or use of `shred`, `wipe`, or `srm`.", "field": "SecureDeletionTool"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3185', 0, 116, '09-mitre-attack', 'retrieved', '57F6E2C9438B30CBAED82A5C4859352CD4C2E9101C23AF732E8D243E90BDAF6E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
