VALUES ('doc-09-mitre-attack-p0-3186', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell or SSH access issuing `esxcli network diag ping` or viewing routing tables to identify connected hosts.", "external_references": [{"external_id": "AN1586", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0574#AN1586"}], "id": "x-mitre-analytic--88041144-900d-4968-9e8a-8f1f63ae8417", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1586", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match specific diag/debug commands abused for recon", "field": "ESXCommandPattern"}, {"description": "Detect unauthorized shell use or user context (e.g., root over SSH)", "field": "RemoteUserShell"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3186', 0, 87, '09-mitre-attack', 'retrieved', '4D7ABFD4D513AFEE19899701E6BF83345A2FF6D8D29692F0DF0D4868DA2DF4D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
