VALUES ('doc-09-mitre-attack-p0-3187', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect sudo activity with NOPASSWD in /etc/sudoers or disabling tty_tickets, followed by immediate privileged commands (e.g., echo ''Defaults !tty_tickets'' >> /etc/sudoers).", "external_references": [{"external_id": "AN0143", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0052#AN0143"}], "id": "x-mitre-analytic--8825b589-3a6a-483a-9fc0-a4d00b1183ab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0143", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "exec or sudo usage with NOPASSWD context or echo modifying sudoers", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Terminal process killed (killall Terminal) immediately after sudoers modification", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define allowed users who may modify sudoers without investigation", "field": "admin_user_context"}, {"description": "Time window after sudoers file change to monitor for Terminal restarts", "field": "terminal_restart_window"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3187', 0, 116, '09-mitre-attack', 'retrieved', '695BBA86668FECC94CE1AA9C828D6913D89E45E239D4A80A68F3F5115101546C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
