INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3189', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation of macOS security and integrity services, such as Gatekeeper, XProtect, or EDR agents. Defender observations include unsigned processes attempting privileged operations, abnormal termination of security daemons, or modification of system integrity logs.", "external_references": [{"external_id": "AN1635", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0595#AN1635"}], "id": "x-mitre-analytic--88d9dbea-cc85-4c94-a368-e5c1a603854b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1635", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Abnormal terminations of com.apple.security.* or 3rd-party security daemons", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve: Unsigned or unnotarized processes launched with high privileges", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored Apple and third-party EDR/AV daemon names.", "field": "SecurityDaemons"}, {"description": "Number of unsigned high-privilege executions before alerting.", "field": "UnsignedProcessThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3189', 0, 120, '09-mitre-attack', 'retrieved', 'B0DF5A1C49DDDA559455CF84D729BF228D73153E15EFBD2E8630943D43EA6365', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
