INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3191', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects forged Kerberos Silver Tickets by identifying anomalous Kerberos service ticket activity such as malformed fields in logon events, TGS requests without interaction with the KDC, and access attempts using service accounts outside expected hosts/resources. Also monitors suspicious processes accessing LSASS memory for credential dumping.", "external_references": [{"external_id": "AN0675", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0241#AN0675"}], "id": "x-mitre-analytic--88ece783-08bc-41e6-a000-a63f540768cc", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0675", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4672, 4634", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "Kerberos TGS-REQ anomalies without KDC validation (Silver Ticket behavior)", "name": "WinEventLog:Kerberos", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected mapping of service accounts to specific resources; deviations may indicate Silver Ticket use.", "field": "ServiceAccountScope"}, {"description": "Expected TGS issuance patterns including KDC validation; anomalies may signal forged tickets.", "field": "TicketValidationBaseline"}, {"description": "Known processes that legitimately interact with LSASS; others may indicate dumping attempts.", "field": "ProcessAllowlist"}, {"description": "Correlate Kerberos requests within a tunable timeframe to reduce false positives.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3191', 0, 172, '09-mitre-attack', 'retrieved', 'C2881303A8901BA806E17D533FBBCF7ED6EE812DD356B6FFB0CCEE8525A06A51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
