INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3192', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CLI or automated utilities accessing raw device volumes or flash storage directly (e.g., via `copy flash:`, `format`, or `partition` commands).", "external_references": [{"external_id": "AN1194", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0426#AN1194"}], "id": "x-mitre-analytic--892f06ae-6a95-438b-8219-49b3384a4d24", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1194", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command logging", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to volume-level commands (e.g., `format`, `copy`, `mount`, `erase`).", "field": "CommandScope"}, {"description": "Filter by internal vs. removable volume interactions (e.g., flash, SD card).", "field": "DeviceTypeFilter"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3192', 0, 94, '09-mitre-attack', 'retrieved', 'D7C4E8C35A70DBC8CDC53D5275DA7FDDBD12E52FE1BD6F213E954F0165708450', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
