VALUES ('doc-09-mitre-attack-p0-3193', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Hidden files via ''chflags hidden'' or Apple-specific attributes, LaunchAgents/LaunchDaemons placed in non-standard hidden directories. Defender view: detect command execution modifying file flags and unusual plist creation in hidden paths.", "external_references": [{"external_id": "AN1386", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0502#AN1386"}], "id": "x-mitre-analytic--8963772e-2ee5-421e-aec0-b952d05d4efc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1386", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of chflags hidden or setfile -a V", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Creation of LaunchAgents/LaunchDaemons in hidden or non-standard directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of directories monitored for hidden plist or agent placement.", "field": "HiddenDirectories"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3193', 0, 107, '09-mitre-attack', 'retrieved', '39330E15E47131DAC9D23F777D9F74D94DC57D65DD08DF7727AB97CE6AEF25FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
