VALUES ('doc-09-mitre-attack-p0-3194', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Registry read access associated with suspicious or non-interactive processes querying system config, installed software, or security settings.", "external_references": [{"external_id": "AN0589", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0209#AN0589"}], "id": "x-mitre-analytic--8986f2ab-2e6d-4c68-99ac-6a1c5f29fb7b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0589", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus detection on registry hives or keys likely to reveal environment info (e.g., HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion).", "field": "TargetRegistryPath"}, {"description": "May tune for suspicious parent processes such as cmd.exe, wscript.exe, or mshta.exe.", "field": "ParentProcess"}, {"description": "Controls how closely registry access must follow process creation for correlation.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3194', 0, 125, '09-mitre-attack', 'retrieved', '2677418E9E24451BEB03EF3F993CAF4C8DAA3032D4066C13D9B6C9F71D159CB1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
