VALUES ('doc-09-mitre-attack-p0-3195', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution of archiving utilities (tar, gzip, bzip2, xz, zip, openssl) followed by suspicious archive file creation. Correlates archive creation in temporary or staging directories with execution of commands involving compression or encryption options.", "external_references": [{"external_id": "AN0832", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0298#AN0832"}], "id": "x-mitre-analytic--89cfa3ac-22c9-462f-a6a5-b142124e22a5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0832", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of tar, gzip, bzip2, xz, zip, or openssl with compression/encryption arguments", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "create: Creation of archive files in /tmp, /var/tmp, or user home directories", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of archiving utilities considered suspicious.", "field": "ArchiveCommands"}, {"description": "Paths where archive creation is flagged as unusual (e.g., /tmp, /var/tmp).", "field": "MonitoredDirectories"}, {"description": "Correlation window for linking utility execution with archive creation.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3195', 0, 143, '09-mitre-attack', 'retrieved', '565723F8B09CBD5D0540E051B6281155484436FF6C90FAC127D25C0BA5738454', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
