INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3196', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation or modification of Login Items using AppleScript or Service Management Framework. Detection focuses on file creation/modification of `backgrounditems.btm`, new executables in `Contents/Library/LoginItems/`, use of `SMLoginItemSetEnabled` API, or suspicious processes triggered post-login without user interaction. Behavioral pivot includes anomalous AppleEvents, suspicious parent-child process pairs, and login-triggered execution chains.", "external_references": [{"external_id": "AN0340", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0121#AN0340"}], "id": "x-mitre-analytic--89e3509c-d732-4826-ac78-baea8fbf0834", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0340", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Post-login execution of unrecognized child process from launchd or loginwindow", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Modification of backgrounditems.btm or creation of LoginItems subdirectory in .app bundle", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Invocation of SMLoginItemSetEnabled by non-system or recently installed application", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "AppleScript creating login item via ''System Events'' dictionary", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate file and process activity within a defined interval post-login (e.g., 0–5 minutes)", "field": "TimeWindow"}, {"description": "Distinguish between system users, interactive users, and daemon contexts", "field": "UserContext"}, {"description": "Define known-good login items to suppress false positives", "field": "ExecutableAllowlist"}, {"description": "Exclude common enterprise paths (e.g., Jamf, MDM-managed apps)", "field": "PathRegexExclusion"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3196', 0, 195, '09-mitre-attack', 'retrieved', 'F8300742CE0B652A8E7BEEF51F0AC7978062FDE6CC41E6AEBC2E745B986E6C39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
