VALUES ('doc-09-mitre-attack-p0-3197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects credential harvesting via userland API hooking (e.g., SetWindowsHookEx, IAT, or inline patching) by correlating memory modifications with hook installation functions and suspicious module loads in credential-sensitive processes like lsass.exe, explorer.exe, or winlogon.exe.", "external_references": [{"external_id": "AN0389", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0139#AN0389"}], "id": "x-mitre-analytic--89e3c3a3-249e-4af3-8885-92c228d88b02", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0389", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=8", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Credential-sensitive targets (e.g., explorer.exe, winlogon.exe) may vary by environment", "field": "TargetProcess"}, {"description": "Tuning for access rights like 0x1FFFFF for full access vs. thread injection", "field": "AccessMask"}, {"description": "Correlate memory access and hook setup in short windows (5–10 seconds)", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3197', 0, 131, '09-mitre-attack', 'retrieved', '9682C9B04C981E97234657169234868EE391D632E728E54A40AE8685BA1CF20B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
