VALUES ('doc-09-mitre-attack-p0-3198', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor resolver logs and auditd events for domains resolving to a rotating set of IPs within very short TTL intervals. Correlate high query rates from non-browser applications (e.g., python, curl).", "external_references": [{"external_id": "AN1332", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0485#AN1332"}], "id": "x-mitre-analytic--8a226737-e2a7-4b70-8964-98c47444a638", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1332", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket/connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum TTL value considered suspicious (e.g., < 60 seconds)", "field": "TTLThreshold"}, {"description": "External TI feed to exclude benign CDN or load balancer behavior", "field": "DomainReputationFeed"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3198', 0, 101, '09-mitre-attack', 'retrieved', '9B274E78FBF2754403F67D4C0CC4BC5AF3C879C618CAB24D59418447A3919A12', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
