VALUES ('doc-09-mitre-attack-p0-3199', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process or script enumerates network shares via CLI (net view/net share, PowerShell Get-SmbShare/WMI) or OS APIs (NetShareEnum/ srvsvc.NetShareEnumAll RPC) → bursts of outbound SMB/RPC connections (445/139, \\\\host\\IPC$ / srvsvc) to many hosts inside a short window → optional follow-on file listing or copy operations.", "external_references": [{"external_id": "AN0513", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0182#AN0513"}], "id": "x-mitre-analytic--8a2537c3-9e9a-482d-81e2-281f88cf8878", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0513", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=17", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "rpc_call: srvsvc.NetShareEnum / NetShareEnumAll from non-admin or unusual processes", "name": "etw:Microsoft-Windows-RPC", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Minimum number of unique destination hosts over SMB within TimeWindow to treat as scanning (e.g., ≥5).", "field": "BurstHostThreshold"}, {"description": "Correlation window between the discovery process start and SMB fan-out (default 10m).", "field": "TimeWindow"}, {"description": "Service/admin accounts legitimately running inventory scripts.", "field": "AllowedDiscoveryAccounts"}, {"description": "Pipes (e.g., \\PIPE\\spoolss) normally accessed by management agents; exclude from alerts.", "field": "PipeNameAllowList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3199', 0, 182, '09-mitre-attack', 'retrieved', 'C67DE3750CEF537CD899649FF623E14A7F900A06F74F0C477698C064CA50B70B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
