VALUES ('doc-09-mitre-attack-p0-3200', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "vSphere API logins (vimService) or SSH to ESXi host followed by unauthorized shell commands or lateral remote logins from the ESXi host.", "external_references": [{"external_id": "AN0754", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0269#AN0754"}], "id": "x-mitre-analytic--8a534291-3b75-45ba-9f7b-b952251a3f03", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0754", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "vim.fault.*, DCUI login, SSH shell", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Command execution trace", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter by DCUI, SSH, vSphere API", "field": "SessionType"}, {"description": "Watch for remote access tool invocations (e.g., netcat, ssh)", "field": "CommandPattern"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3200', 0, 100, '09-mitre-attack', 'retrieved', '64CCAC71B83CBE1F5B3856D6D851250E5465CB3C549E014BD6A222F2D64B14B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
