VALUES ('doc-09-mitre-attack-p0-3201', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes (tar, curl, python scripts) accessing large file sets and initiating outbound HTTPS POST requests with payload sizes inconsistent with baseline activity. Defender perspective: detect abnormal sequence of file archival followed by encrypted uploads to external web services.", "external_references": [{"external_id": "AN1512", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0548#AN1512"}], "id": "x-mitre-analytic--8a5a1b1e-336f-41af-8f30-2fa7e8e10fab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1512", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "curl or wget with POST/PUT options", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "open/read of sensitive directories (/etc, /home/*)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "sustained outbound HTTPS sessions with high data volume", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Suspicious command-line utilities used for exfiltration (curl, wget, python).", "field": "MonitoredTools"}, {"description": "Bytes transferred threshold per session to flag unusual uploads.", "field": "DataVolumeThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3201', 0, 136, '09-mitre-attack', 'retrieved', 'B982ACF54F2BAD6E8A2E682F41CE45264E13F844985772CCD85ED0812D6270AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
