INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects crontab job additions or modifications via `crontab` utility or direct edits, especially those created by interactive users executing hidden or renamed scripts.", "external_references": [{"external_id": "AN0806", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0290#AN0806"}], "id": "x-mitre-analytic--8a764f0e-4bcd-413d-bbf0-1a10cb98b598", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0806", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process: crontab edits, launch of cron job", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "file access to /usr/lib/cron/tabs/ and cron output files", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match scheduled binary path to trusted directory baseline.", "field": "ScriptPath"}, {"description": "Flags excessive frequency or wildcard-heavy cron expressions.", "field": "CronScheduleSyntax"}, {"description": "Limit cron job writes from interactive shells.", "field": "InteractiveUserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3203', 0, 118, '09-mitre-attack', 'retrieved', 'F9346CA84AEF96E1463863641B1DA40ECC7393E651FB82D93E6DA64D0D3020B7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
