VALUES ('doc-09-mitre-attack-p0-3204', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous use of COM objects for execution, such as Office applications spawning scripting engines, enumeration of COM interfaces via registry queries, or processes loading atypical DLLs through COM activation. Correlates process creation, module loads, and registry queries to flag suspicious COM-based code execution or persistence.", "external_references": [{"external_id": "AN0628", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0224#AN0628"}], "id": "x-mitre-analytic--8a7a7e80-c28e-42b2-a222-c1d75932c986", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0628", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate COM CLSIDs and ProgIDs used by enterprise applications, to reduce false positives.", "field": "COMObjectAllowList"}, {"description": "Expected parent-child process relationships (e.g., explorer.exe spawning dllhost.exe).", "field": "ParentProcessExclusions"}, {"description": "Threshold for correlating COM object execution with subsequent process creation or DLL load.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3204', 0, 148, '09-mitre-attack', 'retrieved', 'E2B649A9D7101828F0DCBE460A94C719C6AC1FA25BBEAE0F532DD9CD4B7ECC31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
