INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3208', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "High-frequency, repetitive service requests (e.g., HTTP, TLS renegotiation) originating from a single or small set of source IPs targeting endpoint web services or application ports, leading to exhaustion of CPU or memory on targeted Windows services.", "external_references": [{"external_id": "AN0489", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0173#AN0489"}], "id": "x-mitre-analytic--8c03988c-3387-48e4-8013-7b9d223b8911", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0489", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unexpected spikes in request volume, application-level errors, or thread pool exhaustion in web or API logs", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Sustained CPU/memory exhaustion by service process (e.g., w3wp.exe)", "name": "Windows:perfmon", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines burst threshold (e.g., 1 min, 5 min) for connection spikes", "field": "TimeWindow"}, {"description": "Specific ports/services likely to be abused (e.g., 80, 443, 8080)", "field": "TargetServicePort"}, {"description": "Level of sustained CPU usage considered anomalous for a given service", "field": "CPUThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3208', 0, 157, '09-mitre-attack', 'retrieved', '9599CBEC643A895EC62DB6AEFF9B54AA3730F75A63B4BEB1130DB0499E5E0125', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
