INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3209', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary adds a new Outlook rule with modified or obfuscated PR_RULE_MSG_NAME and PR_RULE_MSG_PROVIDER attributes using MFCMapi or Ruler. Rule is triggered when email arrives, executing embedded or external code. Mailbox audit logs or Unified Audit Log shows automated rule-triggered action without user interaction.", "external_references": [{"external_id": "AN0264", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0095#AN0264"}], "id": "x-mitre-analytic--8c0c52d0-7357-4073-84fc-d262632d268f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0264", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Creation or modification of inbox rule outside of normal user behavior", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Inbound email matches crafted rule trigger pattern tied to persistence logic", "name": "m365:messagetrace", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Mailbox rule changes may not be captured unless advanced audit logging is enabled", "field": "AuditPolicyScope"}, {"description": "Malicious rules may use spoofed or non-standard PR_RULE_MSG_PROVIDER values", "field": "RuleProviderName"}, {"description": "Triggering emails may contain uncommon but benign-looking subjects", "field": "TriggerSubjectKeywords"}, {"description": "Target user account may be inactive or high-value (e.g., VIP, service account)", "field": "UserContext"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3209', 0, 169, '09-mitre-attack', 'retrieved', '95894D5BE14E3A00B4FFAC45E99523716E5164DFE330C5C1146668996E9941B7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
