INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3210', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary behavior where a newly created or renamed user account closely resembles existing service or administrator accounts to blend in and avoid detection. Common patterns include prefix/suffix modifications, homoglyphs, or use of names like ''admin1'', ''adm1n'', or ''backup_help''.", "external_references": [{"external_id": "AN1077", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0383#AN1077"}], "id": "x-mitre-analytic--8c3a43bc-dd07-4e72-a987-a2dc36e162fa", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1077", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4720", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "User enumeration with creation/last modified timestamps", "name": "windows:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how close in Levenshtein or visual distance an account name must be to a legitimate one to raise an alert.", "field": "SimilarityThreshold"}, {"description": "Set of known legitimate accounts to compare new account names against.", "field": "MonitoredAccountList"}, {"description": "Period within which anomalous account creation or renaming is evaluated in relation to discovery or deletion activity.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3210', 0, 153, '09-mitre-attack', 'retrieved', '7913647916592480256623CD60727AEB1826EE60BCC22E437273B9E6B8703F18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
