INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3211', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected processes (e.g., bash, python, custom binaries) dynamically loading libcrypto or performing AES/RC4 encryption operations, then initiating outbound sessions with abnormal byte entropy or asymmetric traffic patterns.", "external_references": [{"external_id": "AN0401", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0143#AN0401"}], "id": "x-mitre-analytic--8c64bf26-bda2-47fc-867d-bcc6a51d57a7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0401", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve or socket/connect system calls from processes using crypto libraries", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "System daemons initiating encrypted sessions with unexpected destinations", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Process linked with libcrypto.so making external connections", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline expected crypto libraries to suppress false positives.", "field": "TrustedCryptoLibs"}, {"description": "Ratio of sent/received bytes indicating possible hidden C2.", "field": "TrafficAsymmetryRatio"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3211', 0, 128, '09-mitre-attack', 'retrieved', '80BEC08AF04F5E2EFC5E2BB8B21EDDCD025E9134CFD07A4532F27420C1B8B46E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
