INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3213', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A user is socially engineered (web page, email, document) to open Run/PowerShell/CMD and paste an obfuscated one-liner. The chain is: (1) user context active in a browser/email/office app → (2) process creation of a command interpreter with suspicious arguments (base64/Invoke-Expression/web download/pipeline to shell) → (3) optional file drop in %TEMP% or %APPDATA% → (4) outbound network connection to an external domain. Events are correlated within a short window and with consistent user/session.", "external_references": [{"external_id": "AN0962", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0340#AN0962"}], "id": "x-mitre-analytic--8cb0a7da-942b-4771-b9d5-cf558755677a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0962", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "HTTP(S) requests with User-Agents typical of PowerShell or curl from desktop; or URIs matching paste-inspired payload hosts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation horizon from parent app (browser/email/office) to interpreter spawn (e.g., 15 minutes).", "field": "TimeWindow"}, {"description": "Legitimate automation that spawns PowerShell/CMD from Office/Email/Browser.", "field": "ParentProcessAllowList"}, {"description": "List of command-line substrings indicating pasted one-liners (e.g., ''-enc'', ''FromBase64String'', ''IEX('', ''DownloadString'', ''Invoke-WebRequest'', ''curl|wget.*\\|\\s*(sh|bash|powershell)'').", "field": "SuspiciousArgPatterns"}, {"description": "Directories treated as risky for first-stage drops (%TEMP%, %APPDATA%, %PUBLIC%).", "field": "WritePaths"}, {"description": "Internet ranges/domains to alert on for first-run egress.", "field": "OutboundCIDRBlockList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3213', 0, 227, '09-mitre-attack', 'retrieved', '16BC326C4BF829AF8D42347D7740A85CE8C09549F81D04ABB1FDF77E6F479203', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
