VALUES ('doc-09-mitre-attack-p0-3214', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or alteration of LaunchAgents or LaunchDaemons with corresponding plist modification followed by execution of associated binaries.", "external_references": [{"external_id": "AN0260", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0094#AN0260"}], "id": "x-mitre-analytic--8cbda989-39e6-4f9e-8e23-213f92b3479d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0260", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process launch", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "disk activity on /Library/LaunchAgents or LaunchDaemons", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "launchd_jobs", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Labels not associated with known applications or vendors.", "field": "PlistLabel"}, {"description": "Executable path outside of standard directories (/usr/bin, /Applications).", "field": "LaunchPath"}, {"description": "Unexpected periodic job intervals (e.g., every minute).", "field": "JobRunInterval"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3214', 0, 113, '09-mitre-attack', 'retrieved', 'BD9A48A74ED79194AA3628A73D292BE61E4E775B6F8943DC007AB019DA3AF3D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
