VALUES ('doc-09-mitre-attack-p0-3215', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Background launch agents/daemons with high CPU use and network access to external mining services.", "external_references": [{"external_id": "AN0743", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0267#AN0743"}], "id": "x-mitre-analytic--8cbeecbb-429f-4f30-9f42-266aaa7b2c0f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0743", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "launchctl activity and process creation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Persistent outbound traffic to mining domains", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Suspicious or unknown launch agents", "field": "launchdLabel"}, {"description": "Outbound bandwidth usage thresholds", "field": "TrafficVolumeThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3215', 0, 89, '09-mitre-attack', 'retrieved', '035075DB2C21E0AA2118B73326B7E8228EA9E0EBF5A9AFC4D0611CB1E6AADAEE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
