VALUES ('doc-09-mitre-attack-p0-3217', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of Mach-O binaries or AppleScripts that contain nested, encoded, or run-only embedded payloads dropped at runtime.", "external_references": [{"external_id": "AN0601", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0214#AN0601"}], "id": "x-mitre-analytic--8cd6ae3d-7f14-42bf-9aff-870209fc333f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0601", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "logd:file write", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "mach_o_info, file_metadata", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Run-only AppleScripts or signed scripting payloads may require scoped detection", "field": "ScriptFormatType"}, {"description": "Threshold on number of binaries created by the parent payload", "field": "DroppedBinaryCount"}, {"description": "Allows focusing on suspicious interpreter or staging tools", "field": "ParentProcessName"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3217', 0, 113, '09-mitre-attack', 'retrieved', 'F19C74AB7F82A6EDD8FA3D