VALUES ('doc-09-mitre-attack-p0-3218', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous access to cloud web applications using session tokens without corresponding MFA/credential validation, often from unusual locations or device fingerprints.", "external_references": [{"external_id": "AN0201", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0074#AN0201"}], "id": "x-mitre-analytic--8d43ac43-de80-4815-b992-6f49519ed340", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0201", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SessionToken used without preceding MFA or login event", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "ConsoleLogin", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "How far back to check for legitimate MFA or login events before token usage", "field": "TimeWindow"}, {"description": "Threshold for flagging geographically impossible logins", "field": "IPGeolocationDistance"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3218', 0, 104, '09-mitre-attack', 'retrieved', 'D1B4A3C582F4F1C2565FB32E0A87AE26DE7E205521CBF357A8F55E0343A44921', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
