VALUES ('doc-09-mitre-attack-p0-3219', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enumeration of saved Wi-Fi profiles and cleartext password retrieval using `netsh wlan` or API-level access to `wlanAPI.dll`.", "external_references": [{"external_id": "AN1280", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0464#AN1280"}], "id": "x-mitre-analytic--8d58973f-7fd7-435e-86b8-58f9b399f89f", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1280", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter by known saved SSID names to reduce benign usage of network diagnostics", "field": "WiFiProfileName"}, {"description": "Anomalous parent-child relationships may be used to spot abuse (e.g., Office → netsh)", "field": "ParentProcess"}, {"description": "Correlate profile enumeration and password dumping within short timeframe (e.g., 60 seconds)", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3219', 0, 118, '09-mitre-attack', 'retrieved', '31C969D1680534056B8C4C71ECD940C458A50BDDA08A231777C36E6198D3BF99', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "