VALUES ('doc-09-mitre-attack-p0-3220', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of processes using nohup or shell redirection to ignore SIGHUP and continue running after session termination. Defender perspective: correlation between commands including nohup, disowned jobs, or `&` suffix with continued process execution after parent terminal exit.", "external_references": [{"external_id": "AN0181", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0067#AN0181"}], "id": "x-mitre-analytic--8d75d4b3-6748-4d1c-936c-129ee56a12a5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0181", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve call including ''nohup'' or trailing ''&''", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "process persists beyond parent shell termination", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific signals to monitor (e.g., SIGHUP, SIGINT) depending on environment baseline.", "field": "IgnoredSignals"}, {"description": "Duration a process continues running after session logout, adjustable to reduce noise from benign long-lived jobs.", "field": "ProcessLifetimeThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3220', 0, 132, '09-mitre-attack', 'retrieved', 'C2667D8BAB911E5E7206064D0AB3BC1634223F1C56C0F6EF00030A3CAA648273', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
