VALUES ('doc-09-mitre-attack-p0-3221', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous creation or mounting of hidden partitions or virtual file systems. Defender view: detection of registry modifications linked to non-standard file systems, suspicious disk I/O patterns, or bootkit-like behavior where hidden volumes are accessed outside normal file system APIs.", "external_references": [{"external_id": "AN1271", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0461#AN1271"}], "id": "x-mitre-analytic--8d7fb300-189d-4654-ba66-3612a8a4cf65", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1271", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "Raw disk I/O operations bypassing NTFS APIs", "name": "etw:Microsoft-Windows-Kernel-Storage", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify registry paths for mount points and hidden partition configs.", "field": "MonitoredRegistryKeys"}, {"description": "Tune thresholds for raw disk access outside expected drivers.", "field": "DiskIOThreshold"}, {"description": "Correlate boot-time anomalies with hidden file system mounting activity.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3221', 0, 142, '09-mitre-attack', 'retrieved', 'D01FC43C7E8A6D7B2E381498431DC48EAC0774DDAD3604BA058101D1D2C10E61', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
