VALUES ('doc-09-mitre-attack-p0-3222', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects access to cloud APIs or CLI tools to move or sync files from sensitive buckets to external endpoints using protocols like HTTPS or S3 APIs.", "external_references": [{"external_id": "AN0370", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0131#AN0370"}], "id": "x-mitre-analytic--8dbd751b-a2cf-418a-b409-daae78a250f8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0370", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetObject, CopyObject", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "Outbound data flows", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect unauthorized use of roles for cloud storage manipulation.", "field": "IAMRoleContext"}, {"description": "Alert on outbound flows to geo-locations not seen in training baseline.", "field": "GeoDestinationThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3222', 0, 106, '09-mitre-attack', 'retrieved', '2860C4B8633FD10551AEEEC17902D6CEF4C5B38204A08D3DE0B55EE1DF915591', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
