VALUES ('doc-09-mitre-attack-p0-3223', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disabling or modifying sign-in or audit log collection for user activities. Defender view: policy or configuration updates removing logging coverage for critical accounts.", "external_references": [{"external_id": "AN0802", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0289#AN0802"}], "id": "x-mitre-analytic--8e0f5333-9fc0-4f03-ae12-cf98903e08ea", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0802", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DisableAuditLogs or ConditionalAccess logging changes", "name": "azure:policy", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to prioritize logging changes that affect administrative or high-value accounts.", "field": "CriticalAccounts"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3223', 0, 87, '09-mitre-attack', 'retrieved', '71ED4DDBD506709CC6100AC2DF77F77EE190DE9A1556BBFDF0302E0079670540', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
