VALUES ('doc-09-mitre-attack-p0-3224', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Sudden spikes in cloud VM CPU usage with outbound traffic to mining pools and unauthorized instance creation.", "external_references": [{"external_id": "AN0744", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0267#AN0744"}], "id": "x-mitre-analytic--8e1872c2-906c-4cf8-b0c7-afd448fe1c0b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0744", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RunInstances", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"channel": "Sustained EC2 CPU usage above normal baseline", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Outbound flow logs to known mining pools", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "CloudWatch alarm trigger for sustained CPU", "field": "CPUUtilizationThreshold"}, {"description": "Instances launched in unexpected regions", "field": "UnusualRegionList"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3224', 0, 103, '09-mitre-attack', 'retrieved', 'CEB9CEF04F5DC1D94C21E8A1FF79B89764E5920369974095C600E77D07337EE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_typ