VALUES ('doc-09-mitre-attack-p0-3225', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects rogue or suspicious wireless access attempts by monitoring firewall, WIDS/WIPS, and controller logs. Focus is on firewall rule changes, rogue AP detection, and anomalous MAC addresses connecting to access points.", "external_references": [{"external_id": "AN1479", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0536#AN1479"}], "id": "x-mitre-analytic--8ea556b8-d6d3-430c-a438-847b00e607a5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1479", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "rule_modification: New or modified firewall rules related to wireless interfaces", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"channel": "Unauthorized AP or anomalous MAC address connection attempts", "name": "WIDS:AssociationLogs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines known access points and MAC addresses; deviations highlight rogue or unauthorized devices.", "field": "AuthorizedAPList"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3225', 0, 115, '09-mitre-attack', 'retrieved', '137D6B2E9772F1113BAF08B6E2553D4AF6A89BE886E82A77780E9E596D66AB93', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
