VALUES ('doc-09-mitre-attack-p0-3226', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of unset HISTFILE or modified history variables in ESXi shell sessions. Correlation of suspicious shell sessions with no recorded commands despite active usage.", "external_references": [{"external_id": "AN1558", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0563#AN1558"}], "id": "x-mitre-analytic--8ed1a27f-3a60-441d-b92d-dc7b086db459", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1558", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unset HISTFILE or HISTFILESIZE modifications", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Differentiate root/admin shell sessions from adversarial misuse of ESXi shell.", "field": "AdminSessions"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3226', 0, 86, '09-mitre-attack', 'retrieved', '4414898927C54DB313E60E39A868D9A26583FE71149B355F98D83F327AFCB33C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
