VALUES ('doc-09-mitre-attack-p0-3227', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary enumeration of domain accounts using net.exe, PowerShell, WMI, or LDAP queries from non-domain controllers or non-admin endpoints.", "external_references": [{"external_id": "AN0363", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0129#AN0363"}], "id": "x-mitre-analytic--8f0ac116-4c8a-4819-b7c0-744e05d672c9", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0363", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "LDAP Bind/Search", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect variations of ''net user /domain'', ''Get-ADUser'', ''Get-ADGroupMember''.", "field": "CommandLinePattern"}, {"description": "Tune detection for bursts of enumeration commands or search queries.", "field": "TimeWindow"}, {"description": "Restrict detection to non-DC or non-admin systems where such commands are unexpected.", "field": "SourceHost"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3227', 0, 118, '09-mitre-attack', 'retrieved', '7C5B2F0A7D2350FE136DC213D72B413B0FE0B16AF869CEC08D5EACF92D20E3D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
