VALUES ('doc-09-mitre-attack-p0-3228', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Discovery via launchctl commands, or process enumeration using `ps aux | grep com.apple.` to identify daemons and services.", "external_references": [{"external_id": "AN1327", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0483#AN1327"}], "id": "x-mitre-analytic--8f654b08-222f-4fc0-83cc-ab871e290d1e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1327", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to recognize `launchctl list`, `launchctl print`, or service grep strings.", "field": "CommandLineContent"}, {"description": "Filter known benign automation or MDM agent invocations.", "field": "ProcessParent"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3228', 0, 94, '09-mitre-attack', 'retrieved', '0DDB205EE1B460090A2B8EB46BAA2D084700962FD69D430748EEF33EE861F0BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
