VALUES ('doc-09-mitre-attack-p0-3229', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of executables or scripts containing hidden embedded resources or secondary payloads, often with anomalies in file size vs. functionality or dropped child binaries.", "external_references": [{"external_id": "AN0599", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0214#AN0599"}], "id": "x-mitre-analytic--8f84fc52-ab74-443b-b618-aa1c0941377a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0599", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "File Metadata Analysis (PE overlays, entropy)", "name": "EDR:file", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold in bytes where appended sections to binaries are considered suspicious", "field": "OverlaySizeThreshold"}, {"description": "Controls how far child process lineage is analyzed for dropped embedded payloads", "field": "ProcessTreeDepth"}, {"description": "Defines correlation interval between file write and process execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-