VALUES ('doc-09-mitre-attack-p0-3230', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect abnormal access to unified logs via log show or fs_usage targeting system log files. Monitor for execution of shell utilities (cat, grep) against /var/log/system.log and for plist modifications enabling verbose logging.", "external_references": [{"external_id": "AN0707", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0255#AN0707"}], "id": "x-mitre-analytic--8f998965-ad70-4ec6-8bc1-85831edc0497", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0707", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of log show, fs_usage, or cat targeting system.log", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "open: Access to /var/log/system.log or related security event logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlist developers or administrators expected to review logs during debugging.", "field": "DebugToolsContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3230', 0, 112, '09-mitre-attack', 'retrieved', '7B848909FE41C7AD6AF1366DEA6D652EDBCD890BA64F2758C461869A436112C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
