VALUES ('doc-09-mitre-attack-p0-3231', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of destructive CLI commands such as ''erase startup-config'', ''erase flash:'' or ''format disk'' on routers/switches. Detect privilege level escalation preceding destructive commands.", "external_references": [{"external_id": "AN0387", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0137#AN0387"}], "id": "x-mitre-analytic--8faa753d-ec3f-4694-9a33-03ce4ccb722f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0387", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "erase flash:, erase startup-config, format disk", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "User privilege escalation to level 15/root prior to destructive commands", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to exclude approved maintenance sessions by known administrators.", "field": "PrivilegedUsers"}, {"description": "Adjust monitored destructive command list depending on device vendor and OS.", "field": "CommandPatterns"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3231', 0, 115, '09-mitre-attack', 'retrieved', 'FDB1EDC036C1C52ECD19F29824AC5D11A9484917231428D840EC50E03CE8F831', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
