VALUES ('doc-09-mitre-attack-p0-3232', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Tracks modification of executables or interpreter payloads (e.g., Mach-O, dylib) that mutate across runs—using scripting engines, JIT compilers, or side-loaded plugins.", "external_references": [{"external_id": "AN0921", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0324#AN0921"}], "id": "x-mitre-analytic--8fba0b53-2aca-4cca-8856-714e0f05665b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0921", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "code signature/memory protection", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "file open/write", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ES_EVENT_TYPE_NOTIFY_MMAP", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection may vary based on whether Python/Swift/AppleScript is used to mutate payloads.", "field": "ScriptEnginePatterns"}, {"description": "Entropy tuning based on expected baseline for system vs user binaries.", "field": "MachOEntropyThreshold"}, {"description": "Helps flag apps that change but maintain signed status across invocations.", "field": "SignedBinaryChangeRate"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3232', 0, 130, '09-mitre-attack', 'retrieved', '10504A3C0739D09735D1018CF55B32DDDB153696A61B126C8E9E09ECAE986595', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
