VALUES ('doc-09-mitre-attack-p0-3233', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlated modification of AppCompat registry keys and execution of sdbinst.exe to install custom shim databases. Followed by DLL injection via shim behavior into target application processes.", "external_references": [{"external_id": "AN0051", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0017#AN0051"}], "id": "x-mitre-analytic--8fcdd234-c8d8-4d95-b381-91c92cb319b6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0051", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter out known-good .sdb paths in AppPatch\\Custom folders", "field": "CustomShimPathAllowlist"}, {"description": "Tunable window for correlating registry modification and sdbinst.exe execution", "field": "TimeWindow"}, {"description": "Expected target applications or binaries for injected DLLs", "field": "DLLInjectionTarget"}, {"description": "Limit alerting to admin or SYSTEM-context initiated shim installations", "field": "UserContext"}, {"description": "Expected or benign sdbinst.exe command-line patterns to exclude", "field": "ShimCommandLinePattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3233', 0, 146, '09-mitre-attack', 'retrieved', '1E36B58A0C8283ECD6C885592A62F2FCF3C54FD9C22923DA84978D0EB9501B2B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
