VALUES ('doc-09-mitre-attack-p0-3234', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects guest VMs or management agents issuing HTTP(S) traffic to external services without a valid patch management or backup justification.", "external_references": [{"external_id": "AN1192", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0425#AN1192"}], "id": "x-mitre-analytic--900bc498-4b81-43b6-bec2-3b55edc5c0ff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1192", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "network activity", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "API communication", "name": "vpxd.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter to detect only external/public destinations", "field": "RemoteIPRange"}, {"description": "Exclude known backup or patch automation services", "field": "VMContext"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3234', 0, 92, '09-mitre-attack', 'retrieved', '7D35A8FED7CA61CF617CA22C1881C742706BF3D7B4B5DB52ECC24756CF6477DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
