VALUES ('doc-09-mitre-attack-p0-3236', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell/utility (base64, xxd -p, od, openssl enc -base64, python/perl base64 libraries) encodes data → subsequent outbound connections (curl/wget/bash TCP, socat, python requests) with high asymmetry or Base64/MIME blobs in HTTP/DNS payloads.", "external_references": [{"external_id": "AN0346", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0124#AN0346"}], "id": "x-mitre-analytic--904100f0-1af9-4ded-89be-dfda7180bcbc", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0346", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of base64|openssl|xxd|python|perl with arguments matching Base64 flags", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "http: HTTP body or headers contain long Base64 sections; gzip/deflate + Base64", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Build/backup jobs that legitimately call base64/openssl.", "field": "EncodingToolsAllowList"}, {"description": "Shannon entropy for payloads (e.g., >4.5).", "field": "EntropyThreshold"}, {"description": "Join window between exec and egress (default 10m).", "field": "TimeWindow"}, {"description": "Bytes_out / bytes_in threshold (default 4).", "field": "OutInRatio"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3236', 0, 145, '09-mitre-attack', 'retrieved', '32EE4CFD514FB33571039350C3CB70592B5BD793C1160479E9412E605335E33C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
