VALUES ('doc-09-mitre-attack-p0-3237', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious usage of common application-layer protocols (e.g., HTTP, HTTPS, DNS, SMB) by abnormal processes, with high outbound byte counts or irregular ports, possibly indicating command and control or data exfiltration.", "external_references": [{"external_id": "AN1225", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0444#AN1225"}], "id": "x-mitre-analytic--908aa2d1-f1c0-456b-9c9f-b984b309e51c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1225", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "http, dns, smb, ssl logs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit detection to app-layer protocols of interest: HTTP, DNS, SSL, SMB, RDP", "field": "ProtocolList"}, {"description": "Detects asymmetric communication volume (e.g., >90% outbound)", "field": "DataVolumeThreshold"}, {"description": "Track processes not normally associated with network activity", "field": "UnusualProcessList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3237', 0, 123, '09-mitre-attack', 'retrieved', '732800B5275CDFA75D4E1153131D0C5272A98E1E1B47AC341F3FBDB11ECB102B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
