VALUES ('doc-09-mitre-attack-p0-3238', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor audit logs for setuid/setgid bit changes, executions where UID ≠ EUID (indicative of sudo or privilege escalation), and high-integrity binaries launched by unprivileged users.", "external_references": [{"external_id": "AN0976", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0345#AN0976"}], "id": "x-mitre-analytic--90a8d89c-f54a-49dd-8734-6f85e5e3a2a5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0976", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "setuid or setgid bit changes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "execve with UID ≠ EUID", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "sudo or pkexec invocation", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths where unauthorized setuid binaries may be dropped", "field": "WatchedDirectories"}, {"description": "Which users are allowed to run sudo/pkexec or modify binaries", "field": "UserContext"}, {"description": "Duration between file permission change and elevated command execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3238', 0, 129, '09-mitre-attack', 'retrieved', 'A3F229ADE7273B3647B60BD959D03648C13626F7DC76172A1E76EF9D2BA504D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
