INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3239', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversarial archiving by scripts or binaries calling compression libraries (libzip, zlib, bzip2). Correlates execution of Python, Perl, or compiled binaries with dynamic linking to archiving libraries and creation of compressed files in /tmp or user directories.", "external_references": [{"external_id": "AN0748", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0268#AN0748"}], "id": "x-mitre-analytic--90e51090-9857-4a28-98b9-f21401ddbe85", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0748", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Execution of python, perl, or custom binaries invoking compression libraries", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "load: Loading of libzip.so, libz.so, or libbz2.so by processes not normally associated with archiving", "name": "auditd:MMAP", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "create: Creation of .zip, .gz, .bz2 files in /tmp, /var/tmp, or /home directories", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of shared objects linked to compression/encryption.", "field": "MonitoredLibraries"}, {"description": "Directories where archive creation is flagged as anomalous.", "field": "ArchivePaths"}, {"description": "Entropy level used to distinguish encryption from normal compression.", "field": "EntropyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3239', 0, 162, '09-mitre-attack', 'retrieved', '40C698F39D5D4AC25B70DD46D2FF42FE548937A0B52393559A30487DF386F071', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
