VALUES ('doc-09-mitre-attack-p0-3240', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious access to cloud-native secret management systems (AWS Secrets Manager, GCP Secret Manager, Azure Key Vault, HashiCorp Vault). Focuses on abnormal secret retrieval activity, such as secrets being accessed by unusual identities, from unexpected regions, outside business hours, or at high volume. Correlates API calls to secret retrieval with surrounding authentication events, role assumptions, and anomalous execution patterns.", "external_references": [{"external_id": "AN0366", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0130#AN0366"}], "id": "x-mitre-analytic--90eca5d7-c330-4b86-bde6-de04019cbba7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0366", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetSecretValue", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set of accounts or roles allowed to retrieve secrets; deviations may indicate misuse.", "field": "PrivilegedRoles"}, {"description": "Temporal window to correlate secret access with authentication and anomalous context.", "field": "TimeWindow"}, {"description": "Expected frequency and volume of secret retrievals per user/service; anomalies may indicate exfiltration.", "field": "AccessPatterns"}, {"description": "Regions in which secret access is expected; access from unusual geographies may indicate compromise.", "field": "RegionConstraints"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3240', 0, 168, '09-mitre-attack', 'retrieved', 'BE5EE94E235C5970A8C00A92E79573BA12F7C860FB8D884468C718F82BC6049F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
