VALUES ('doc-09-mitre-attack-p0-3241', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects enumeration of cloud network interfaces, VPCs, subnets, or peer connections using CLI or SDKs (e.g., AWS CLI, Azure CLI, GCloud CLI).", "external_references": [{"external_id": "AN0908", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0320#AN0908"}], "id": "x-mitre-analytic--914a5b13-5977-4e62-abab-9ee03e72624f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0908", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Describe* or List* API calls", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "networkInsightsLogs", "name": "azure:activity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allow certain automation roles to perform discovery during provisioning.", "field": "ServicePrincipalAllowlist"}, {"description": "Unusual number of Describe* or List* network API calls in a short timeframe.", "field": "BurstQueryThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3241', 0, 105, '09-mitre-attack', 'retrieved', '6B0289BB9E2D600CD9823E74F4517847EE04C0611D4ADD1342D1691D8CD8CF95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
