VALUES ('doc-09-mitre-attack-p0-3242', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of instance metadata tokens across instances or misuse of short-lived tokens issued for different roles.", "external_references": [{"external_id": "AN0960", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0960"}], "id": "x-mitre-analytic--91681b37-7fc7-418c-b4fd-35bebe1d151e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0960", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "GetCallerIdentity", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "AssumeRole", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time window where token reuse is suspicious", "field": "TokenReuseWindow"}, {"description": "Enable if tokens for RoleA are used in resources only RoleB should access", "field": "RoleMismatchAlerting"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3242', 0, 93, '09-mitre-attack', 'retrieved', 'CF9747167C3CD7F88EC037CA2AF7CA450E07694095AA5F9B482EFF2865D3184A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
