VALUES ('doc-09-mitre-attack-p0-3243', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects automation macros or VBA scripts in documents that access browser file paths, read cookie data, or attempt to exfiltrate browser session tokens over HTTP.", "external_references": [{"external_id": "AN1405", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0509#AN1405"}], "id": "x-mitre-analytic--916993bd-600a-43e2-abbf-30c56be84459", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1405", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RunMacro", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Files or directories macros are attempting to access", "field": "MacroTargetPath"}, {"description": "List of IPs or domains that are uncommon for macro-based HTTP POSTs", "field": "HTTPDestinationIPList"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3243', 0, 103, '09-mitre-attack', 'retrieved', 'B4FB7392FC07A4565C7B09D55F65402277F6396E71A759DD4AAD772DE2F562A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
