INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3245', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary clearing shell history using `history -c` or deleting/altering ~/.zsh_history or ~/.bash_history. Focus on sessions with missing or wiped history.", "external_references": [{"external_id": "AN0468", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0165#AN0468"}], "id": "x-mitre-analytic--9199891a-1543-4f51-be59-4fffb03dfd43", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0468", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unlink, write", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Duration after terminal usage where deletion or modification is considered suspicious.", "field": "TimeWindow"}, {"description": "Flag unexpected user activity, especially from users who normally don’t use terminal.", "field": "UserContext"}, {"description": "Zsh or Bash history files under the user''s home directory.", "field": "HistoryFilePath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3245', 0, 115, '09-mitre-attack', 'retrieved', '966E8464B21DBF06F995CF3BAA321C1C81EA9CABA57E9B2E5B746520FB4541A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
