INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3249', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Direct login to cloud-hosted virtual machines via cloud-native access methods (e.g., EC2 Instance Connect, Azure Serial Console, SSM), followed by command execution or privilege escalation on the VM", "external_references": [{"external_id": "AN0594", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0211#AN0594"}], "id": "x-mitre-analytic--926f4550-8c47-4882-afb3-1f0832c8d3b9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0594", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SendSSHPublicKey, StartSession (SSM), EC2InstanceConnect", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlates cloud login to host activity within a reasonable time span (e.g., < 60 seconds)", "field": "TimeWindow"}, {"description": "Filters based on access vector: SSH key, SSM session, or Console connect", "field": "CloudAuthMethod"}, {"description": "Identifies sessions from out-of-region or untrusted networks", "field": "SessionOriginRegion"}, {"description": "Filters sensitive systems or production assets for alert tuning", "field": "TargetInstanceTags"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3249', 0, 137, '09-mitre-attack', 'retrieved', '7659F0F65D1EFA8EDC5FD8F6791C290ECB5FEFB7E673C5C3E4BEB3BE93A08813', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
