INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3251', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects inotify or auditd configuration changes that monitor system files coupled with execution of script interpreters or binaries by cron or systemd timers.", "external_references": [{"external_id": "AN0025", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0010#AN0025"}], "id": "x-mitre-analytic--92d182e9-6723-43e4-9eab-f00aa6d53153", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0025", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inotify watch creation or auditctl changes on /etc/cron* or /lib/systemd/system/", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Execution of non-standard script or binary by cron", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "Execution of script interpreters by systemd timer (ExecStart)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex defining suspicious binary/script paths triggered by cron/systemd", "field": "ExecutablePathRegex"}, {"description": "Paths monitored by auditd/inotify for suspicious event registration", "field": "WatchTargetPaths"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3251', 0, 125, '09-mitre-attack', 'retrieved', '6692FC9E5721DE79AFDE4CC80EAE0F2C081A62515E63CB93D31F78399618A15E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
