INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3253', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor DNS queries, proxy logs, and user-agent strings for anomalous patterns associated with adversary attempts to hide infrastructure. Defenders may observe DNS resolutions to short-lived domains, abnormal WHOIS registration data, or filtering of known defensive/responder IP addresses.", "external_references": [{"external_id": "AN1148", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0411#AN1148"}], "id": "x-mitre-analytic--9311924d-7d8f-489a-8105-058a60f572fc", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1148", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5156, 5157", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "Excessive lookups for domains with suspicious WHOIS or short TTL values", "name": "dns:query", "x_mitre_data_component_ref": "x-mitre-data-component--ff9b665a-598b-4bcb-8b2a-a87566aa1256"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of domains registered with privacy-protected or suspicious WHOIS metadata.", "field": "SuspiciousDomains"}, {"description": "Known incident response or scanning infrastructure IP ranges.", "field": "ResponderIPs"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3253', 0, 123, '09-mitre-attack', 'retrieved', 'E0F0F8831AC67317A403D21913ADA2C9A156D24D0A73B7C0ADA67C8352CC59BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
