VALUES ('doc-09-mitre-attack-p0-3256', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious access to password manager vaults (KeePassXC, gnome-keyring, pass) via memory scraping or unauthorized file reads. Detects unusual command execution involving gdb/strace attached to password manager processes.", "external_references": [{"external_id": "AN1642", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0597#AN1642"}], "id": "x-mitre-analytic--93fd8592-d8ce-4b5e-b095-71cd66062298", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1642", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read on ~/.local/share/keepassxc/* OR ~/.password-store/*", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "ptrace", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Linux paths to monitor for vault database files (KeePassXC, pass, gnome-keyring).", "field": "VaultFilePaths"}, {"description": "Correlation interval to detect multiple suspicious access events.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3256', 0, 107, '09-mitre-attack', 'retrieved', 'CCCF3D7D59EC60E0D2F2BF2ED90554718EF95462005506038EF31DDFB922332E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "ST