VALUES ('doc-09-mitre-attack-p0-3257', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates unexpected modifications to WMI event filters, scheduled task triggers, or registry autorun keys with subsequent execution of non-standard binaries by SYSTEM-level processes.", "external_references": [{"external_id": "AN0024", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0010#AN0024"}], "id": "x-mitre-analytic--9418d7e2-666f-4f73-9ac7-96b32005e9b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0024", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4698", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "Creation or modification of __EventFilter, __FilterToConsumerBinding, or CommandLineEventConsumer", "name": "WinEventLog:WMI", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filters triggering on SYSTEM or LOCAL SERVICE vs. user-initiated triggers", "field": "UserContext"}, {"description": "Correlates trigger definition and execution timing (e.g., within 5 minutes)", "field": "TimeWindow