VALUES ('doc-09-mitre-attack-p0-3258', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection monitors modification of code signing attributes, Gatekeeper/quarantine flags, and insertion of new trust certificates via security add-trusted-cert. Identifies adversary use of xattr to strip quarantine flags from downloaded binaries. Correlates with abnormal module loads bypassing SIP protections.", "external_references": [{"external_id": "AN1248", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0452#AN1248"}], "id": "x-mitre-analytic--94340be7-068e-446a-bca2-d414b66912fc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1248", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New certificate trust settings added by unexpected process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "xattr -d com.apple.quarantine or similar removal commands", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Unsigned or ad-hoc signed process executions in user contexts", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of enterprise apps where quarantine flag removal is expected", "field": "QuarantineBypassAllowList"}, {"description": "Baseline trusted root and intermediate CAs for comparison", "field": "CertificateAuthorityList"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3258', 0, 140, '09-mitre-attack', 'retrieved', '27C5B95EDF7AB189BB5912DC4C5806BA908C4A5BA4220A9A12BDF46D3F88BDFF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
