VALUES ('doc-09-mitre-attack-p0-3259', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates registry modifications to EventLog or WMI Autologger keys, suspicious use of Set-EtwTraceProvider, and Sysmon configuration changes. Defender sees interruption or redirection of ETW and log event collection.", "external_references": [{"external_id": "AN0667", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0239#AN0667"}], "id": "x-mitre-analytic--945f8192-6f4f-4183-b457-40b5c6d9b4ca", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0667", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=16", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of ETW providers to baseline and monitor for unexpected removal.", "field": "MonitoredETWProviders"}, {"description": "Whitelist of expected admin actions modifying Sysmon or ETW configurations.", "field": "AuthorizedConfigChanges"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3259', 0, 106, '09-mitre-attack', 'retrieved', '9B299F1BF6E71BDBEEDFA0136C6C4194B8D98592C6D5938AC2471A49F017E228', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"