VALUES ('doc-09-mitre-attack-p0-3260', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious memory access attempts targeting the `securityd` process. Observes tools invoking process memory read operations (e.g., ptrace, task_for_pid) against `securityd`. Correlates with anomalous parent process lineage, root privilege escalation, or repeated unauthorized attempts.", "external_references": [{"external_id": "AN0156", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0057#AN0156"}], "id": "x-mitre-analytic--94628b16-2443-4e66-9f7b-a61a39012a9c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0156", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ptrace or task_for_pid", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "execution of memory inspection tools (lldb, gdb, osqueryi)", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of authorized debugging tools permitted in dev/test environments", "field": "AllowedDebuggers"}, {"description": "Correlation period between memory inspection and Keychain API access", "field": "TimeWindow"}, {"description": "Expected set of admin accounts with legitimate debugging permissions", "field": "PrivilegedUsers"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3260', 0, 130, '09-mitre-attack', 'retrieved', '818E0D9AE47FE0FF231E8435FBB58BD356B1BFFAFCA2B509B08BAC59A19847CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
