VALUES ('doc-09-mitre-attack-p0-3261', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect sudden privilege escalations such as IAM role changes, user-assigned privilege boundaries, or elevation via assumed roles beyond normal behavior.", "external_references": [{"external_id": "AN0979", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0345#AN0979"}], "id": "x-mitre-analytic--9465ea54-a81a-4d00-a75d-e0b7f3392bb8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0979", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "role privilege expansion detected", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "cross-account or unexpected assume role", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define valid transitions between IAM roles", "field": "PermittedRoleTransitions"}, {"description": "Should flag if assumption crosses trust boundary", "field": "CrossAccountBoundary"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3261', 0, 97, '09-mitre-attack', 'retrieved', '2D07773598F143221D6A1B2F2603A16CF8F7F3ED78CD2EDABB6F14D193BB458A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
