VALUES ('doc-09-mitre-attack-p0-3264', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Flows showing encrypted payloads with high entropy not matching TLS handshake patterns, particularly when occurring on non-standard ports. Defender observes NetFlow/IPFIX byte distribution anomalies or IDS/IPS detecting symmetric encryption patterns without associated key exchange.", "external_references": [{"external_id": "AN0404", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0143#AN0404"}], "id": "x-mitre-analytic--94e5fd96-1fde-41fd-863d-6ef9cb8a3e1a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0404", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Flow records with entropy signatures resembling symmetric encryption", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Symmetric encryption detected without TLS handshake sequence", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline expected encryption by port/protocol.", "field": "PortProfiles"}, {"description": "Volume thresholds for distinguishing benign VPN traffic from hidden C2.", "field": "TrafficVolumeThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3264', 0, 120, '09-mitre-attack', 'retrieved', '80DBE6735F86A091ACC41D9C8BFFDBEA93C6B39145D2E154DCB92720149614E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
