VALUES ('doc-09-mitre-attack-p0-3265', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Rapid login failures across different users from a single IP address, targeting SSH or PAM login with distinct username-password pairs", "external_references": [{"external_id": "AN1263", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1263"}], "id": "x-mitre-analytic--95d381e5-f2d6-4164-9917-57f9b070333b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1263", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SSH failed login", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Ratio of failed logins per unique user attempted", "field": "LoginFailureRatio"}, {"description": "Restrict detection to certain protocols (e.g., sshd, login, su)", "field": "AuthServiceFilter"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3265', 0, 90, '09-mitre-attack', 'retrieved', '90E5141FFD6318629EAEE767635AC17017BDA3F0DFE6ACB2ECB4BAF1252E237A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
