VALUES ('doc-09-mitre-attack-p0-3266', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Domain logins using network accounts or mobile accounts via Open Directory or Active Directory plugins, especially outside business hours or on atypical endpoints.", "external_references": [{"external_id": "AN0592", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0210#AN0592"}], "id": "x-mitre-analytic--96050801-dc36-462f-982e-df2806eaa3ea", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0592", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log show --predicate ''eventMessage contains \"Authentication\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Geo-IP or VPN source context for abnormal remote access.", "field": "UserLocation"}, {"description": "Control for expected services (e.g., GUI login vs. SSH).", "field": "LogonMethod"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3266', 0, 97, '09-mitre-attack', 'retrieved', '2290E98E55086BA9D6221602A6AB2E7516D3105228169F99CDC63A1F91865464', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
