VALUES ('doc-09-mitre-attack-p0-3267', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disabling or altering security and audit logs in SaaS admin panels (e.g., Slack, Zoom, Salesforce). Defender view: API calls or admin console changes that stop event exports or logging integrations.", "external_references": [{"external_id": "AN0804", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0289#AN0804"}], "id": "x-mitre-analytic--967f7636-1547-4db7-921a-1b84f312a2cd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0804", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Log export integration removed or disabled", "name": "saas:audit", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define which SaaS log integrations are required and alert if removed.", "field": "IntegrationScope"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3267', 0, 94, '09-mitre-attack', 'retrieved', '1712BC7A757EB666A6B5C71C0F8BA8B381A4BE1911C5D6C48D5A07ABD6B1B44E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
