VALUES ('doc-09-mitre-attack-p0-3268', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "OAuth token usage for Exchange Online or SharePoint API access without preceding login or from unauthorized clients.", "external_references": [{"external_id": "AN0529", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0185#AN0529"}], "id": "x-mitre-analytic--9680d434-3470-4a35-bf48-1785ab14d831", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0529", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "OAuthTokenIssued, FileAccessed, MailItemsAccessed", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict trusted Office apps authorized to request tokens", "field": "ClientAppIDWhitelist"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3268', 0, 76, '09-mitre-attack', 'retrieved', '8A5DB104CC0C388ABABD300AB7510C6418A41A0E071334E625D52A09FC84A152', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
