INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3269', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious VIB installation for persistence via `esxcli software vib install` using `--force` or `--no-sig-check`, enabling custom startup scripts or firewall rules. Behavior chain: (1) unsigned/suspicious VIB installation → (2) startup script or binary placed in persistent boot path → (3) persistence across reboot via /etc/rc.local.d or other boot hook).", "external_references": [{"external_id": "AN1475", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0535#AN1475"}], "id": "x-mitre-analytic--9696a221-35b9-4576-ae75-714c902c2889", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1475", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/esxupdate.log contains VIB installed with `--force` or `--no-sig-check` and non-standard acceptance levels", "name": "esxi:esxupdate", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "`esxcli software vib install` with `--force` or `--no-sig-check` from shell history or `shell.log`", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Changes to /etc/rc.local.d/local.sh or creation of unexpected startup files in persistent partitions (/etc/init.d, /store, /locker)", "name": "linux:fim", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Some environments may intentionally permit CommunitySupported or unsigned VIBs—filter by known allowed publishers.", "field": "AcceptanceLevel"}, {"description": "Set alerting thresholds for frequency of VIB install attempts per host/user/time window.", "field": "InstallCommandThreshold"}, {"description": "Tune regex for monitoring startup file locations based on ESXi image customization.", "field": "StartupPathRegex"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3269', 0, 189, '09-mitre-attack', 'retrieved', '3526F7311025AE0E6C2749B3763705F6A88B2219DEB777DF9AB1CDB85239C948', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
