VALUES ('doc-09-mitre-attack-p0-3272', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of system-generated or default privileged accounts such as ''root'' or ''vpxuser'' logging into ESXi hosts.", "external_references": [{"external_id": "AN1286", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0465#AN1286"}], "id": "x-mitre-analytic--96fe3582-b1a3-40e4-9e9d-bab764f2af7e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1286", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/auth.log", "name": "esxi:auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "If ''vpxuser'' is replaced or configured differently, detection logic must reflect the change.", "field": "AccountName"}, {"description": "Legitimate vCenter IP ranges may be whitelisted to avoid false positives.", "field": "IPRange"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3272', 0, 91, '09-mitre-attack', 'retrieved', '51B2A84ED2EA7C36FB31314E44D299A9DAF5E636B4DFD0C9B1CB40E75A395E05', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
