INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3273', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Linux permission escalation behavioral chain: (1) Process creation of permission modification utilities (chmod, chown, chgrp, setfacl) with suspicious parameters indicating privilege escalation intent, (2) System call analysis revealing direct file metadata manipulation (chmod, fchmod, chown, fchown syscalls), (3) Extended attribute and ACL modifications targeting critical system paths, (4) Temporal correlation with subsequent file access or process execution from modified locations, (5) Anomalous permission patterns deviating from system baselines", "external_references": [{"external_id": "AN0998", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0351#AN0998"}], "id": "x-mitre-analytic--971ddd36-1ecd-46bf-b94c-22e8f05c1462", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0998", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "syscall in (chmod, fchmod, fchmodat, chown, fchown, fchownat, lchown, setxattr, lsetxattr, fsetxattr, removexattr, lremovexattr, fremovexattr)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "proctitle contains chmod, chown, chgrp, setfacl, or attr with suspicious parameters (777, 755, +x, -R)", "name": "auditd:PROCTITLE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "process execution events for permission modification utilities with command-line analysis", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Octal permission values indicating potential malicious intent - customize based on organizational security policy (default: 777, 755, 4755, 2755, 1755 for sticky/setuid/setgid)", "field": "SuspiciousPermissionValues"}, {"description": "Linux filesystem paths requiring enhanced permission change monitoring - adapt to environment-specific critical directories (/etc, /usr/bin, /usr/sbin, /var, /opt, /root, /boot)", "field": "CriticalSystemPaths"}, {"description": "User accounts and service accounts authorized for system-level permission modifications - maintain current list of legitimate administrators", "field": "AuthorizedSystemAdministrators"}, {"description": "Time window for correlating permission changes with subsequent file access or process execution - adjust based on system performance (default: 300 seconds)", "field": "TemporalCorrelationWindow"}, {"description": "Maximum depth or file count for recursive permission operations before triggering anomaly detection (-R flag monitoring)", "field": "RecursiveOperationThreshold"}, {"description": "Baseline complexity metrics for setfacl operations to detect anomalous extended ACL configurations", "field": "ACLComplexityBaseline"}, {"description": "Statistical baseline for normal file access patterns post-permission modification to detect privilege abuse", "field": "FileAccessFrequencyBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3273', 0, 306, '09-mitre-attack', 'retrieved', '5EEFC0CFB14B5504FDE6EC726394734F3BC95C974A3D763B9018B1F43392D3A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
