VALUES ('doc-09-mitre-attack-p0-3275', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies transfer of base64, uuencoded, or high-entropy files over HTTP, FTP, or custom protocols in lateral movement or exfiltration streams.", "external_references": [{"external_id": "AN1067", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0378#AN1067"}], "id": "x-mitre-analytic--97a188cf-5851-4cb7-9bb5-17702707d52b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1067", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "content inspection / PCAP / HTTP body", "name": "networkdevice:IDS", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust threshold to reduce false positives in compressed but benign data", "field": "EntropyThreshold"}, {"description": "Refine by enabling inspection of specific exfil vectors (e.g., FTP, HTTP POST)", "field": "ProtocolScope"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3275', 0, 101, '09-mitre-attack', 'retrieved', '55D8E34FD0F8C359C36D7F2B558AE97F6088C985006D62B1C1640A22F185032B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
