VALUES ('doc-09-mitre-attack-p0-3277', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects registry and Group Policy modifications that disable or weaken MFA, suspicious PowerShell usage modifying MFA-related attributes, and anomalous login sessions succeeding without expected MFA challenge.", "external_references": [{"external_id": "AN0543", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0190#AN0543"}], "id": "x-mitre-analytic--97cb8df9-f100-4a64-802a-1aa2f45c26eb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0543", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4739", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "Set-ADUser or Set-ADAuthenticationPolicy with MFA attributes disabled", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of AD attributes or policy fields tied to MFA enforcement that may vary by organization.", "field": "WatchedAttributes"}, {"description": "Correlation window between MFA policy changes and anomalous login behavior.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3277', 0, 115, '09-mitre-attack', 'retrieved', '5833C4B0E9D17705FB49A59E2263D2D05674E32FCF79685B0993DF3E6B9B1F98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
