VALUES ('doc-09-mitre-attack-p0-3278', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during exfiltration (ex: [Transfer Data to Cloud Account](https://attack.mitre.org/techniques/T1537)).", "external_references": [{"external_id": "AN1978", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0846#AN1978"}], "id": "x-mitre-analytic--97ec7ade-18b7-43b7-b267-85470862b6ac", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1978", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3278', 0, 79, '09-mitre-attack', 'retrieved', 'CCA41515BBDBC5609981E04B8B3C31D4C2DA9B2E778B21622A3DA11A4C243D90', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
