VALUES ('doc-09-mitre-attack-p0-3279', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Electron/GUI or headless RAT execution followed by LaunchAgent/Daemon persistence and persistent external connections; interactive children (osascript/sh/curl) spawned by parent.", "external_references": [{"external_id": "AN1368", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0496#AN1368"}], "id": "x-mitre-analytic--97f27df6-5041-437b-9aeb-58a9bc33a376", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1368", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process exec of remote-control apps or binaries with headless/connect flags", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "CREATE/MODIFY: Creation of LaunchAgents/Daemons plists in user/system locations", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "CONNECT: Long-lived connections from remote-control parents to external IPs/domains", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate remote-support apps under /Applications.", "field": "AllowedAppBundlePaths"}, {"description": "Known-good LaunchAgents/Daemons identifiers.", "field": "LaunchdAllowlist"}, {"description": "Window for correlating exec→launchd→egress events.", "field": "TimeWindow"}, {"description": "Duration/volume thresholds for persistent sessions.", "field": "EgressHeuristics"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3279', 0, 130, '09-mitre-attack', 'retrieved', 'B0A6FFC7715F6D9DB80CAEEF22C8C4478D3E7E6DCD521B7CBD539E3F18CFC00E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
