VALUES ('doc-09-mitre-attack-p0-3280', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates Power Automate or similar logic app workflows triggered by SaaS file uploads or email rules with data forwarding or anomalous access patterns.", "external_references": [{"external_id": "AN0028", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0010#AN0028"}], "id": "x-mitre-analytic--982100e1-6d38-4d0e-b36d-7e2d2cf5a424", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0028", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Creation of Power Automate flow triggered by OneDrive or Exchange event", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "Automated forwarding or file sync initiated by a logic app", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Event types that initiate SaaS automation (e.g., file add, new email)", "field": "TriggerCondition"}, {"description": "Scopes/permissions granted to automation app accounts", "field": "AppIdentityScope"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3280', 0, 116, '09-mitre-attack', 'retrieved', '46B06CAD9EB16504960EF5F52BD3D8938936FB548C72F253063218F86084BBDC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
