VALUES ('doc-09-mitre-attack-p0-3281', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T16:31:03.795Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects user execution of newly received content or instructions shortly after external communication, including script launches, Office child process spawning, browser-to-script execution chains, or credential prompts followed by new logon sessions.", "external_references": [{"external_id": "AN2035", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0899#AN2035"}], "id": "x-mitre-analytic--983e1849-6af7-491e-9605-46b9bf54bbd1", "modified": "2026-05-12T16:30:18.380Z", "name": "Analytic 2035", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time between message delivery and process launch", "field": "EmailToExecutionWindow"}, {"description": "Approved Office child process patterns", "field": "OfficeChildProcessAllowlist"}, {"description": "Time after credential prompt to monitor new sessions", "field": "NewLogonWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3281', 0, 127, '09-mitre-attack', 'retrieved', 'C5BF5E0774A6F6C6A6AE44B492D9DE601A3041CFBD340571C53D2440B340BFE1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
