VALUES ('doc-09-mitre-attack-p0-3283', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious curl, wget, or custom socket traffic that leverages DNS, HTTPS, or IRC-style protocols with unbalanced traffic or beacon-like intervals.", "external_references": [{"external_id": "AN1226", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0444#AN1226"}], "id": "x-mitre-analytic--989a524f-cf9a-4fcc-a21f-ac5aac46f0ed", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1226", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dns, ssl, conn", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Uncommon ports for HTTPS, IRC, DNS (e.g., 8443, 5353)", "field": "KnownPortsToMonitor"}, {"description": "Detect intervals of outbound traffic within fixed timeframes", "field": "BeaconTimingThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3283', 0, 97, '09-mitre-attack', 'retrieved', '9F9C3948BE879051C6B9E964CC6A2383281FD03A5E8F7F0C472A3E6B31A111D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
