VALUES ('doc-09-mitre-attack-p0-3284', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitoring adversary access to sensitive process memory via the /proc filesystem to extract credential material, often involving multi-step access to /proc/[pid]/mem or /proc/[pid]/maps combined with privilege escalation or credential scraping binaries.", "external_references": [{"external_id": "AN1631", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0593#AN1631"}], "id": "x-mitre-analytic--98b71f96-ae0a-47b4-bec2-156cb6e5bfcb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1631", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "ptrace or process_vm_readv", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored paths such as /proc/[pid]/mem or /proc/[pid]/maps may need to be scoped based on environment", "field": "AccessedFilePath"}, {"description": "Command-line or binary names associated with credential scraping tools may vary", "field": "ProcessName"}, {"description": "Elevated user or unexpected user context accessing other process memory may indicate malicious activity", "field": "UserContext"}, {"description": "Correlating memory access with process creation or ptrace activity within a specific time range", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3284', 0, 163, '09-mitre-attack', 'retrieved', '319D7046B1DEACF54EB7AA6882C67EC4DACED087EAC1CF27821BBDD25F3C1C28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
