VALUES ('doc-09-mitre-attack-p0-3285', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual processes (e.g., powershell.exe, wscript.exe, mshta.exe) posting data to webhook endpoints (Discord, Slack, webhook.site) using HTTP POST/PUT requests. Defender perspective: suspicious process lineage followed by outbound HTTPS traffic to webhook domains.", "external_references": [{"external_id": "AN0436", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0153#AN0436"}], "id": "x-mitre-analytic--98bd8e15-68ea-43a3-982b-66fcd1142c9a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0436", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Domains to monitor such as discord.com/api/webhooks, slack.com/api, webhook.site.", "field": "WebhookDomains"}, {"description": "Threshold for abnormal data sent via webhook requests.", "field": "UploadSizeThreshold"}, {"description": "List of approved business apps using webhooks to reduce noise.", "field": "ApprovedApps"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3285', 0, 126, '09-mitre-attack', 'retrieved', '50B7C7BD83EA3A5A0BC3D002911F8098C8A3A4E48DE473DFBF1B4385C2D7F257', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
