VALUES ('doc-09-mitre-attack-p0-3286', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects user or root invocation of `at` command to schedule a job, followed by job execution using LaunchServices and activity in /usr/lib/cron/at.", "external_references": [{"external_id": "AN0945", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0333#AN0945"}], "id": "x-mitre-analytic--98ce32fb-1b91-4487-9e5a-951375f2380e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0945", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process: at, job runner", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file access to /usr/lib/cron/at and job execution path", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether `at.allow` and `at.deny` are properly configured.", "field": "AtPermissions"}, {"description": "Target binary executed via the at job.", "field": "ExecutionCommand"}, {"description": "Detection of root user scheduling job with unusual command.", "field": "RunUser"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3286', 0, 121, '09-mitre-attack', 'retrieved', 'D52E91FAA276D89C11A7ED8C8BA3BD06954214B46D046