INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3288', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of Homebrew, pip3, npm, or manually downloaded PKGs from Terminal or shell, followed by the creation of startup agents, interpreter spawns, or outbound connections to unfamiliar domains. Defender links Terminal commands to plist creation, unsigned binary launches, and `python3` or `node` processes connecting to remote endpoints.", "external_references": [{"external_id": "AN0700", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0252#AN0700"}], "id": "x-mitre-analytic--98f18ad5-0def-4ac3-8822-7538f0a8d64d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0700", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Command line invocation of pip3, brew install, npm install from interactive Terminal", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Creation of new LaunchAgent or LoginItem plist files in ~/Library/LaunchAgents/", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Outbound HTTP/S initiated by newly installed interpreter process", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter user persistence plist directories like ~/Library/LaunchAgents", "field": "StartupAgentPaths"}, {"description": "Enable alerting for new binaries lacking Apple or organization signature", "field": "UnsignedBinaryAlerting"}, {"description": "Correlate install action to interpreter-based network behavior", "field": "InstallToNetWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3288', 0, 164, '09-mitre-attack', 'retrieved', 'B4E56197AD3A99E4514923C4E16EB11D45F19530BD149BA826AE8628C31D3687', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
