VALUES ('doc-09-mitre-attack-p0-3289', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Inspect resolver and audit logs for processes initiating outbound connections to ports calculated from DNS response IPs. Abnormal ephemeral port usage shortly after DNS queries can indicate DNS calculation behavior.", "external_references": [{"external_id": "AN0729", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0262#AN0729"}], "id": "x-mitre-analytic--98f5c157-17c8-4ab8-943d-8d4c54dc3d6d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0729", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "DNS response IPs followed by connections to non-standard calculated ports", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Configured ephemeral port ranges per environment to reduce false positives", "field": "EphemeralPortRange"}, {"description": "Exclude trusted resolvers or internal services from analysis", "field": "ResolverWhitelist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3289', 0, 114, '09-mitre-attack', 'retrieved', '6C88BF3A75882B3DA7C6C5C29E1D1CB89987FB2878D956DA6BE0B33A8E9E4899', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
