VALUES ('doc-09-mitre-attack-p0-3290', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of modified or newly created /etc/rc.local or /etc/init.d scripts followed by suspicious execution during system startup.", "external_references": [{"external_id": "AN0658", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0237#AN0658"}], "id": "x-mitre-analytic--98f8728d-ff74-47cb-b884-25071a21f77e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0658", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "boot logs", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific path of init script (e.g., /etc/rc.local, /etc/init.d/*) may vary by distribution", "field": "script_path"}, {"description": "Root vs. non-root modification context depending on configuration", "field": "user_context"}, {"description": "Tuning window for script creation or modification relative to system boot", "field": "time_window"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3290', 0, 109, '09-mitre-attack', 'retrieved', 'C47C4F94D29A372A707366CC4BD40443CBD62A3B137D1E054EAAD734BB52228A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
