VALUES ('doc-09-mitre-attack-p0-3291', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the use of mail utilities like `mail` or `mailx` to delete mailbox content, or file-level deletion of inbox files from `/var/spool/mail/` or `/var/mail/` following suspicious sessions.", "external_references": [{"external_id": "AN0738", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0266#AN0738"}], "id": "x-mitre-analytic--9933242a-f96e-4b3e-896f-e7335f410a4f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0738", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unlink/unlinkat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common inbox file locations like /var/spool/mail/, /var/mail/", "field": "MailFolderPath"}, {"description": "Usage of mailx or echo piped to mail followed by deletion", "field": "CommandPattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3291', 0, 102, '09-mitre-attack', 'retrieved', '5D45CCAAFABFA6C4F561C4AB0C82B3F19F360EFEA27DBE09BD868C46678167E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
