INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3292', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Non-standard or rare users/locations issue CLI commands like \"show clock detail\" or \"show timezone\"; optionally followed by configuration of time/timezone or NTP sources. AAA/TACACS+ accounting and syslog correlate execution to identity, source IP, and privilege level.", "external_references": [{"external_id": "AN0434", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0151#AN0434"}], "id": "x-mitre-analytic--99ab1534-79b5-4660-83ed-3604bcb320f2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0434", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command-exec: CLI commands containing \"show clock\", \"show clock detail\", \"show timezone\" executed by suspicious user/source", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "config-change: timezone or ntp server configuration change after a time query command", "name": "networkdevice:config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Only alert on access from outside the NOC/management subnets.", "field": "AllowedAdminSubnets"}, {"description": "Whitelist known automation/orchestration accounts.", "field": "KnownMaintenanceUsers"}, {"description": "Correlation window between time query and config change.", "field": "TimeWindow"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3292', 0, 143, '09-mitre-attack', 'retrieved', '23B98179950CD05FE68B7EBCD4987B25669A9E98CC654297E0C27F150BF90F31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
