VALUES ('doc-09-mitre-attack-p0-3294', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects downloaded SVG files followed by execution of browser processes or tools like xdg-open, and rapid follow-on network connections or process spawns to interpreters like python or bash.", "external_references": [{"external_id": "AN1408", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0510#AN1408"}], "id": "x-mitre-analytic--99bfd95b-256a-4b1d-bf1d-481f47642c15", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1408", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound HTTP/S", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Suspicious write locations such as /tmp/, ~/Downloads/", "field": "TargetPaths"}, {"description": "Processes spawned by browsers or svg-viewing apps that invoke interpreters", "field": "ExecutionContext"}, {"description": "URLs/IPs contacted post-SVG access – may reflect initial C2", "field": "NetworkDestinations"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3294', 0, 122, '09-mitre-attack', 'retrieved', 'E74DEC3D278D6CA3A9ECEA5DB397A7E03A2C52A4148F8FEC9BCE3E9B70E93F6A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
