VALUES ('doc-09-mitre-attack-p0-3295', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect unauthorized `trap` command registrations in shell startup files (e.g., .zprofile, .bash_profile, .zshrc) followed by execution chains during user terminal interaction. Use Unified Logs and EDR telemetry to correlate shell command parsing and process tree anomalies.", "external_references": [{"external_id": "AN1039", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0369#AN1039"}], "id": "x-mitre-analytic--99c42b1f-1716-413b-8c23-5f7e1d997ab2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1039", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Command line containing `trap` or `echo ''trap` written to login shell files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "File write or append to .zshrc, .bash_profile, .zprofile, etc.", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Startup files vary by shell (.bash_profile, .zshrc, etc.)", "field": "LoginShellConfigPaths"}, {"description": "Short benign traps may differ from longer/multi-command malicious traps", "field": "TrapCommandLengthThreshold"}, {"description": "Score or detect if new child process deviates from shell’s typical behavior", "field": "ParentProcessAnomalyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3295', 0, 144, '09-mitre-attack', 'retrieved', '2408B74BFF44DBF0CA5830068C3F1EFAAED192E3C6CDE85303AF39A95AEBD525', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
