INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Forged cookies in IaaS environments may appear as authentication attempts that bypass MFA, leveraging AssumeRole or session APIs with cookies that were never legitimately issued. Defenders should correlate cloud logs for cookie-based sessions without prior valid authentication, often followed by resource access from unfamiliar IP addresses.", "external_references": [{"external_id": "AN0483", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0171#AN0483"}], "id": "x-mitre-analytic--9a6089cc-92a7-48ea-b4a4-4d4d2b6489e3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0483", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Web console logins using session cookies without corresponding MFA event", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "GetSessionToken, AssumeRoleWithWebIdentity", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag logins from geographically distant locations in a short timeframe.", "field": "GeoVelocityThreshold"}, {"description": "Expected systems and services that may legitimately mint session cookies.", "field": "AuthorizedCookieIssuers"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3297', 0, 133, '09-mitre-attack', 'retrieved', 'FB0B2EC04F84A095EF0597315F6D4CBA0C5385014CF278DCD241390E41A2ABAA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
