INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3299', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized invocation of replication operations (DCSync) via Directory Replication Service (DRS), often executed by threat actors using Mimikatz or similar tools from non-DC endpoints.", "external_references": [{"external_id": "AN1632", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0594#AN1632"}], "id": "x-mitre-analytic--9a68f1a7-65f0-4eef-a711-888bccbeb0d5", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1632", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4662", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}, {"channel": "EventCode=4929", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9085a576-636a-455b-91d2-c2921bbe6d1d"}, {"channel": "Traffic on RPC DRSUAPI", "name": "NSM:Content", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines the correlation window for unusual account access followed by DRSUAPI traffic.", "field": "TimeWindow"}, {"description": "Allows tuning for specific accounts known to legitimately request replication.", "field": "UserContext"}, {"description": "Expected replication should only come from known DCs; this field allows excluding trusted DCs.", "field": "SourceIP"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3299', 0, 130, '09-mitre-attack', 'retrieved', 'EFD1F5A5BCDA2336ACF7E1542F30ECC31D23B1AD2FEA56C0998187A2CBC1AB66', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
