INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3300', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of `systemd` service units, addition of cron jobs that invoke binaries on boot, or suspicious writes to `/etc/init.d/`. Monitors `chmod +x` and `systemctl` execution paths, especially from non-root parent processes.", "external_references": [{"external_id": "AN1576", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0571#AN1576"}], "id": "x-mitre-analytic--9a73d14c-ce3c-47c5-a6c2-3d6b49c4d009", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1576", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write or rename to /etc/systemd/system or /etc/init.d", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execution of systemctl or service with enable/start/modify", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path-based filters to identify service unit files or init scripts", "field": "ServicePathRegex"}, {"description": "List of expected user contexts that normally perform service changes", "field": "UserContextList"}, {"description": "Binaries used to register/modify services", "field": "CommandNameList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3300', 0, 131, '09-mitre-attack', 'retrieved', '95E6F3724FD794E62563B7AD2712D595B6CCE201ED5EF6EF829F5103466DA3CA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
