VALUES ('doc-09-mitre-attack-p0-3301', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary attaches USB drive and accesses sensitive files using Finder, cp, or bash scripts.", "external_references": [{"external_id": "AN1412", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0511#AN1412"}], "id": "x-mitre-analytic--9abfb75c-2051-4549-b458-f09c4e6f4ad3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1412", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate ''eventMessage contains \"USBMSC\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "file reads/writes from /Volumes/", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune by filtering removable media mounted under /Volumes", "field": "VolumePath"}, {"description": "Correlate activity to admin or service accounts for priority", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3301', 0, 102, '09-mitre-attack', 'retrieved', 'CCD574990496F7348409F31BF0857C75D561D7455CC69DB5D663A093B00DAABF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
