VALUES ('doc-09-mitre-attack-p0-3302', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious Office add-ins loaded via VSTO, COM, or VBA auto-load paths. Upon launch of Word/Excel/Outlook, the add-in executes code without user action. Add-in resides in trusted directory or registered via Office COM/VBE subsystem. Behavior includes unsigned add-in execution, anomalous load context, or add-in spawning interpreter process.", "external_references": [{"external_id": "AN0138", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0050#AN0138"}], "id": "x-mitre-analytic--9ad4670e-f336-454f-960e-4f2f611f3657", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0138", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Office Add-in load errors, abnormal loading context, or unsigned add-in warnings", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Outlook loading add-in via unexpected load path or non-default profile context", "name": "WinEventLog:Microsoft-Office/OutlookAddinMonitor", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Admins may allow or block unsigned add-ins depending on GPO configuration", "field": "UnsignedAddInBehavior"}, {"description": "Different Office versions store trusted paths and add-in configs in version-specific locations", "field": "OfficeProductVersion"}, {"description": "Some add-ins only load on specific actions (new document, open file, etc.)", "field": "AddInTrigger"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3302', 0, 162, '09-mitre-attack', 'retrieved', '2660AFC49209FBE01D00DDDE4A0E7C0ECF9D233EE971C1BC72BE438FD6FBF9FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
