VALUES ('doc-09-mitre-attack-p0-3303', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects modification of system or application binaries by monitoring /usr/bin, /bin, and other privileged directories. Correlates file integrity monitoring (FIM) events with unexpected process executions or service restarts.", "external_references": [{"external_id": "AN0950", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0336#AN0950"}], "id": "x-mitre-analytic--9b2ff34a-1967-46a9-b355-f9584a0715b5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0950", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize monitored directories (e.g., /usr/bin, /usr/sbin, /opt/apps) for binary tampering", "field": "WatchedDirectories"}, {"description": "Maintain golden file hashes for integrity validation", "field": "BaselineHashes"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3303', 0, 103, '09-mitre-attack', 'retrieved', 'D65AF3BAF66B198F64AD62AB45725A068468F1B56AB2396B38244012BD647FFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
