VALUES ('doc-09-mitre-attack-p0-3304', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects access to known browser cookie files (e.g., `~/.mozilla/firefox/*.default/cookies.sqlite`, `~/.config/google-chrome/`) and suspicious reads of browser memory via `/proc/[pid]/mem` or ptrace.", "external_references": [{"external_id": "AN1403", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0509#AN1403"}], "id": "x-mitre-analytic--9bcedfe7-c851-418a-b709-dd8883c7fc5e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1403", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open or read to browser cookie storage", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "ptrace syscall or access to /proc/*/mem", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex paths to known browser cookie locations", "field": "CookieFilePatterns"}, {"description": "Correlated time range between cookie read and web upload or process injection", "field": "TimeWindow"}, {"description": "Expected names for browser processes being accessed", "field": "BrowserProcPatterns"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3304', 0, 117, '09-mitre-attack', 'retrieved', '98F001669F2BBA6CBEA253D7BEA9A8377F1429AC08EB4A59D74646BD0E9DB4AB', 'v1', '{"source_id": "09-mitre-attack", "vers