VALUES ('doc-09-mitre-attack-p0-3305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous usage of local accounts to log into a system, especially accounts not typically used interactively or outside business hours.", "external_references": [{"external_id": "AN1137", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0407#AN1137"}], "id": "x-mitre-analytic--9c53e92a-3659-4137-881a-f4002af9c688", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1137", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=4672", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for normal business hours to reduce false positives from legitimate after-hours work.", "field": "TimeWindow"}, {"description": "Define list of legitimate local users for interactive access.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3305', 0, 101, '09-mitre-attack', 'retrieved', 'F578884307967244B1436E6EF71F6FC9C38D13721A3A6D1EBB8C8728BB99847E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
