VALUES ('doc-09-mitre-attack-p0-3306', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Container processes accessing mounted secrets or configuration paths (e.g., /run/secrets, /mnt/config) followed by network access or credential use.", "external_references": [{"external_id": "AN0859", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0307#AN0859"}], "id": "x-mitre-analytic--9c5d279c-eb09-4592-91a4-8cf6436522b6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0859", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read on secret mount paths", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "process execution involving curl, grep, or awk on secrets", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "outbound connection to internal or external APIs", "name": "cni:netflow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize based on deployment structure (e.g., /mnt/, /run/secrets/)", "field": "SecretMountPaths"}, {"description": "Tune anomaly scoring for container image deviations", "field": "ProcessBaselineDeviation"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3306', 0, 114, '09-mitre-attack', 'retrieved', '1B6C7F61F75A74DFCB1ED076195F7BCACB6B09D25969732878B8C1AFEF