VALUES ('doc-09-mitre-attack-p0-3307', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects internal hosts generating large outbound FTP/TFTP/SMB sessions to external IPs, or file transfers using non-standard ports and application mismatches (e.g., FTP over port 80).", "external_references": [{"external_id": "AN1173", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0416#AN1173"}], "id": "x-mitre-analytic--9c5ef78d-2e02-4201-ba38-ec858e8b6a6f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1173", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ftp.log, conn.log, smb_files.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., FTP/SMB observed over uncommon ports", "field": "AppLayerProtocolMatch"}, {"description": "Bytes transferred outside trusted subnets >100MB", "field": "OutboundDataRateThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3307', 0, 91, '09-mitre-attack', 'retrieved', '6E85E3408B7AD59A3BDE1B5F2906BDD653A629DC312953CC44A4DF692AB0D7E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
