VALUES ('doc-09-mitre-attack-p0-3308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor CLI ''reload'' commands issued without scheduled maintenance, and correlate to TACACS+/AAA logs for privilege validation.", "external_references": [{"external_id": "AN1542", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0559#AN1542"}], "id": "x-mitre-analytic--9c70d5b3-8748-4f88-8fd8-95f79c73d250", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1542", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "reload command issued", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "System reboot scheduled or performed", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "TACACS+/AAA role thresholds for command execution.", "field": "PrivilegeLevel"}, {"description": "Track change control windows or ITSM integration.", "field": "ChangeTicketCorrelation"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3308', 0, 93, '09-mitre-attack', 'retrieved', '9ED7EA2539B417D1328AFB89C4A2BE4DD41542FC0E2F60472400F70B9C6082DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
