VALUES ('doc-09-mitre-attack-p0-3310', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of msiexec.exe running installer packages that result in anomalous process creation. Look for unexpected binaries executed by msiexec or custom action DLLs in the temp directory.", "external_references": [{"external_id": "AN0940", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0330#AN0940"}], "id": "x-mitre-analytic--9c9db399-4f87-477b-be31-536857b7912d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0940", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Could be msiexec.exe or third-party wrapper like setup.exe.", "field": "InstallerParent"}, {"description": "Payload paths vary based on where installer extracts to (e.g., %TEMP%, C:\\Users\\Public).", "field": "ChildImagePath"}, {"description": "Threshold for how soon a payload must run after msiexec to be considered related.", "field": "ExecutionTimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3310', 0, 121, '09-mitre-attack', 'retrieved', 'FD3D0CABA56133D9EA6DEDB979CB4CABB1F3104AB42CACCEA775488582F5ADA7', 'v1', '{"source_id": "09-mitre-attack", "