VALUES ('doc-09-mitre-attack-p0-3311', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects USB block device mount followed by file access in sensitive directories or high-volume copy operations by user-controlled processes.", "external_references": [{"external_id": "AN0617", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0220#AN0617"}], "id": "x-mitre-analytic--9cf3c7bb-296e-445a-ba30-012060b9ccac", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0617", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Kernel Device Events - USB Block Devices", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Look for /media/, /mnt/, /run/media/ paths associated with removable storage.", "field": "MountPath"}, {"description": "Detect rsync, cp, tar, zip activity writing to USB mount point.", "field": "CopyCommandSignature"}, {"description": "Define abnormal access patterns (e.g., >100 files in <5 min).", "field": "AccessRateThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3311', 0, 117, '09-mitre-attack', 'retrieved', 'CCD14DEBC0478F59E70D0C157FBE9B25E69FB784C640411BB595B27F3746615B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
