VALUES ('doc-09-mitre-attack-p0-3312', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor unified logs for manipulation of proxy configurations, DNS resolution, or filtering rules. Adversaries may redirect responses or use trusted domains that later resolve to malicious C2 infrastructure.", "external_references": [{"external_id": "AN1150", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0411#AN1150"}], "id": "x-mitre-analytic--9cf6c89d-73f7-42f8-b5e4-c87bf3abbb7d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1150", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "System process modifications altering DNS/proxy settings", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Suspicious changes in TLS certificate responses or redirected domains", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known hosting/CDN providers often abused to hide malicious C2 infrastructure.", "field": "TrustedHostingProviders"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3312', 0, 105, '09-mitre-attack', 'retrieved', '7D3A191A944ED133A34AC19BB7D11B84D5765FDD77EE8114EAB8654C114A3830', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
