VALUES ('doc-09-mitre-attack-p0-3314', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary invokes ''useradd'', ''adduser'', or equivalent system commands or scripts to create local users. Detection focuses on command execution and audit trail of passwd/shadow file modifications.", "external_references": [{"external_id": "AN1605", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0583#AN1605"}], "id": "x-mitre-analytic--9d70d90c-f318-4318-a18d-e4775ffa229e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1605", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "useradd or adduser executed", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "chmod/chown to /etc/passwd or /etc/shadow", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Custom scripts or renamed binaries may evade simple path-based detection", "field": "BinaryPath"}, {"description": "Account creation outside maintenance windows may indicate compromise", "field": "ExecutionTime"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3314', 0, 108, '09-mitre-attack', 'retrieved', 'D86DC580A9A9E5210767F4C539985AA7B8CE21ED5D6EA2CAF519A3DD36DD9AD9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
