VALUES ('doc-09-mitre-attack-p0-3315', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary attempts to detect monitoring agents such as Little Snitch, KnockKnock, or other system daemons via process listing (`ps -e`), application folder checks, and system extension listing.", "external_references": [{"external_id": "AN0050", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0016#AN0050"}], "id": "x-mitre-analytic--9d76d84b-6393-45cf-b872-eb5921508ee3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0050", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of security-agent detection or enumeration commands", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adversary may search for specific software names; defenders can tune based on local deployments", "field": "ToolNameMatch"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3315', 0, 101, '09-mitre-attack', 'retrieved', '907C593A3A700D5F4D816B7C13FFC21EF993402513D45EC2E647E9F9EBB9DD89', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
