VALUES ('doc-09-mitre-attack-p0-3316', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects external volume mount with Finder, Terminal, or script-initiated file copy from user profiles, sensitive folders, or cloud storage sync directories to USB.", "external_references": [{"external_id": "AN0618", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0220#AN0618"}], "id": "x-mitre-analytic--9d7fd025-d8eb-48ab-8fca-df6b09761aec", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0618", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Volume Mount + Process Trace + File Read", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "Disk Activity Tracing", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag removable volumes with suspicious or default names (e.g., NO NAME, BACKUP_01).", "field": "DriveLabelFilter"}, {"description": "Watch for shell or AppleScript execution tied to USB copy.", "field": "ScriptExecutionContext"}, {"description": "Detect repeated or abnormal device mounts during work hours.", "field": "VolumeMountFrequency"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3316', 0, 129, '09-mitre-attack', 'retrieved', 'BC7F9CDC37E4C811613A39868EA728FD4CD7D8C79CF995AA95B4C022F07AC86D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
