VALUES ('doc-09-mitre-attack-p0-3317', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries using WinRM to remotely execute commands, launch child processes, or access WMI. The detection chain includes service use, network activity, remote session logon, and process creation within a short temporal window.", "external_references": [{"external_id": "AN1313", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0477#AN1313"}], "id": "x-mitre-analytic--9dab17bf-62c7-4187-90f4-7335790df7c0", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1313", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=6", "name": "WinEventLog:WinRM", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "Inbound on ports 5985/5986", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines max time between remote shell creation and child process execution (e.g., 60 seconds)", "field": "TimeWindow"}, {"description": "Scope to unexpected remote user logons (non-admins, service accounts)", "field": "UserContext"}, {"description": "Score for suspicious command usage via WinRM (e.g., encoded PowerShell)", "field": "CommandLineAnomalyScore"}, {"description": "List of trusted systems allowed to use WinRM legitimately", "field": "KnownAdminHosts"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3317', 0, 153, '09-mitre-attack', 'retrieved', 'EB81AED55B7880CCF2BFCD49CEB45E67E6EA933ED3D8BB13B3E7C6545BB0CD2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
