VALUES ('doc-09-mitre-attack-p0-3319', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies CLI interpreter access (e.g., Cisco IOS, Juniper JUNOS) via `enable` mode or scripting-capable sessions used by uncommon accounts or from unknown IPs.", "external_references": [{"external_id": "AN1432", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0516#AN1432"}], "id": "x-mitre-analytic--9e03886b-155c-4483-9d92-dad6a7d8543b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1432", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "shell command", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "authentication & authorization", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Which roles or privilege levels should be monitored for interpreter misuse.", "field": "UserRole"}, {"description": "Support filtering for routers, switches, firewalls depending on network segmentation.", "field": "DeviceType"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3319', 0, 105, '09-mitre-attack', 'retrieved', 'D54926E6C5EC7F8FD2E981E8662FBB3445769EEF62B2C227D7E11012847D1967', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
