VALUES ('doc-09-mitre-attack-p0-3320', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversaries attempting to attach debuggers or memory dump utilities to credential storage daemons analogous to macOS `securityd`. Observes ptrace syscalls, /proc/ /mem access, or gcore dumps against sensitive processes. Correlates anomalies with privilege escalation or credential dumping attempts.", "external_references": [{"external_id": "AN0157", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0057#AN0157"}], "id": "x-mitre-analytic--9e0af3ac-dfeb-48c3-8d15-5f9edd69be69", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0157", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ptrace attach", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "/proc/*/mem read attempt", "name": "auditd:FILE", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "gcore, gdb, strings, hexdump execution", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of credential storage daemons (e.g., securityd, gnome-keyring, kwallet) monitored for memory access attempts", "field": "MonitoredProcesses"}, {"description": "Defines how many chained events (process execution + syscall + file read) to correlate before raising an alert", "field": "CorrelationDepth"}, {"description": "Expected user/group context for processes allowed to access protected memory", "field": "PrivilegeContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3320', 0, 154, '09-mitre-attack', 'retrieved', 'F785AC42CB0B957A34457633D8B16572EBC8C9D33E0B4A2C6A414765A7847273', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
