INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3321', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Attacker disables VM-related services or stops VMs forcibly to target vmdk or logs. Behavioral chain: esxcli or vim-cmd stop + audit log showing user privilege use + datastore file manipulation.", "external_references": [{"external_id": "AN0064", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0021#AN0064"}], "id": "x-mitre-analytic--9e12e1f0-1547-4008-8755-2b3bc1c00279", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0064", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Stop VM or disable service events via vim-cmd", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"channel": "Log entries indicating VM powered off or forcibly terminated", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted virtual machine name", "field": "VMName"}, {"description": "User who issued stop or disable command", "field": "InitiatorUser"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3321', 0, 113, '09-mitre-attack', 'retrieved', '6AC73A07FB42D49689BBA232C2D904C1BA3DC24291E832647B817E6ADE1DA29F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
