INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3322', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "File creation of unauthorized script (e.g., .php, .sh) in /var/www/html followed by execution of unexpected system utilities (e.g., curl, bash, nc) by apache/nginx", "external_references": [{"external_id": "AN1109", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0394#AN1109"}], "id": "x-mitre-analytic--9e80763b-5287-451f-b2ab-37168b159387", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1109", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "new file created in /var/www/html, /srv/http, or similar web root", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "apache2 or nginx spawning sh, bash, or python interpreter", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "POST requests to .php, .jsp, .aspx files with high entropy body", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Web server root varies by distro and hosting configuration", "field": "WebRootPath"}, {"description": "Base64 or XOR encoded shells may exceed this value", "field": "PayloadEntropyThreshold"}, {"description": "Correlate file creation with process spawn within X seconds", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3322', 0, 143, '09-mitre-attack', 'retrieved', 'B2C63EC2BFC0B0A6FA41F30D426E26BF677B8B2FEACB7557F40DD54B2A801581', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
