VALUES ('doc-09-mitre-attack-p0-3325', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects Automator, AppleScript, or Terminal executing curl, lftp, or TFTP for binary transfer to untrusted IPs or unusual ports.", "external_references": [{"external_id": "AN1171", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0416#AN1171"}], "id": "x-mitre-analytic--9e9efdc0-82d3-4046-a4db-e97454f708a6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1171", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "log stream --predicate", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "e.g., ~/Documents, ~/Library/logs/", "field": "FilePathAccessed"}, {"description": "Non-standard FTP/TFTP ports used (e.g., FTP over 443)", "field": "NetworkPortAnomaly"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3325', 0, 89, '09-mitre-attack', 'retrieved', 'E0DEA380C10A67DF53663263A815738228E49D1EACCBFD72BDEBECBD08A7B4C5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
