VALUES ('doc-09-mitre-attack-p0-3326', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary destroys virtual disks (VMDK), images, or VMs by invoking `vim-cmd`, deleting datastore contents, or purging snapshots.", "external_references": [{"external_id": "AN0415", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0146#AN0415"}], "id": "x-mitre-analytic--9ea1e329-691a-43a7-b56d-affbc00fb9e7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0415", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file delete|datastore purge", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--3acecdde-c327-4498-9bb8-33a2e63c6c57"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted deletion of critical VMDKs or VM configuration files.", "field": "DatastorePath"}, {"description": "Detect deletions from users outside normal maintenance windows.", "field": "InitiatingUser"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3326', 0, 87, '09-mitre-attack', 'retrieved', '4CBCEC9C3975E1E76E23C0CA3C3E9C1107E98D844F3FD0FD70F122C5895BEDBE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
