INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3327', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes initiating outbound connections on uncommon ports or using protocols inconsistent with the assigned port. Correlating process creation with subsequent network connections reveals anomalies such as svchost.exe or Office applications using high, atypical ports.", "external_references": [{"external_id": "AN0633", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0227#AN0633"}], "id": "x-mitre-analytic--9ea7f21e-700f-4900-a1d4-dfc171d399fe", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0633", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5156, 5157", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define what constitutes a ''non-standard port'' based on organizational baselines (e.g., allow 443/80/22 but flag 8088/587/3389 changes).", "field": "PortThresholds"}, {"description": "Processes normally allowed to use non-standard ports (e.g., custom apps).", "field": "ProcessAllowList"}, {"description": "Correlate process creation and network activity within N seconds.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3327', 0, 131, '09-mitre-attack', 'retrieved', '99AD319FC885E8C6382A1E144844AAF4427BD4BCF374EB6B0942FD51208058CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
