INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3329', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious updates to conditional access or MFA enforcement policies in identity providers such as Entra ID, Okta, or JumpCloud. Focus is on removal of policy blocks, addition of broad exclusions, or registration of adversary-controlled MFA methods, followed by anomalous login activity that takes advantage of the modified policies.", "external_references": [{"external_id": "AN0088", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0030#AN0088"}], "id": "x-mitre-analytic--9eb2a081-e252-4009-a16e-90c9a85f70f1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0088", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Update conditionalAccessPolicy", "name": "azure:activity", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "Conditional Access policy rule modified or MFA requirement disabled", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific SaaS or cloud apps most sensitive to conditional access changes.", "field": "TargetedApplications"}, {"description": "Risk scores or signals that may be tuned for anomaly detection in login behavior.", "field": "RiskThresholds"}, {"description": "Business roles or expected MFA patterns per user/group to reduce false positives.", "field": "UserContext"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3329', 0, 156, '09-mitre-attack', 'retrieved', 'AD450D9ECC834C9BB548591B291F717A39B163FAEEEF7DF4144AF76D39A9BD4E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
