INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3330', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for queried domain name system (DNS) registry data that may compromise third-party DNS servers that can be used during targeting. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.\nMonitor for logged domain name system (DNS) registry data that may compromise third-party DNS servers that can be used during targeting. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.", "external_references": [{"external_id": "AN2023", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0891#AN2023"}], "id": "x-mitre-analytic--9eb9a81f-cf55-48f8-a8da-217a7684aff4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 2023", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "Domain Name", "x_mitre_data_component_ref": "x-mitre-data-component--2e521444-7295-4dec-96c1-7595b2df7811"}, {"channel": "None", "name": "Domain Name", "x_mitre_data_component_ref": "x-mitre-data-component--cc150ad8-ecfa-4340-9aaa-d21165873bd4"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3330', 0, 169, '09-mitre-attack', 'retrieved', '97112EF56A5505EF6008661E73F817E7294745C4FD45C17CBDE8E7E5CF00C2A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
