INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3332', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process (often spawned by a shell, interpreter, or malware implant) executes time discovery via commands (date, timedatectl, hwclock, cat /etc/timezone, /proc/uptime) or direct syscalls (time(), clock_gettime) and is (optionally) followed by scheduled task creation/modification (crontab, at) or conditional sleep logic.", "external_references": [{"external_id": "AN0431", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0151#AN0431"}], "id": "x-mitre-analytic--9f2278c6-2e45-42fb-a1f9-00f02d496c53", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0431", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "type=EXECVE or SYSCALL for /bin/date, /usr/bin/timedatectl, /sbin/hwclock, /bin/cat /etc/timezone, /bin/cat /proc/uptime", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Rules capturing clock_gettime, time, gettimeofday syscalls when enabled", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "sudo/date/timedatectl execution by non-standard users", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "cron activity", "name": "linux:cron", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope of syscalls (time, clock_gettime, gettimeofday) monitored; may be performance-sensitive.", "field": "AuditRulesSyscalls"}, {"description": "List of legitimate automation/orchestration tools frequently querying time.", "field": "AllowedBinaries"}, {"description": "Correlation window (e.g., 5–20 minutes) to link time discovery to follow-on cron/at changes.", "field": "TimeWindow"}, {"description": "Ignore root-owned maintenance agents if desired; focus on interactive or newly created users.", "field": "UserContextScope"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3332', 0, 182, '09-mitre-attack', 'retrieved', 'C0CCB36FD419C24CC77537D5C1F04A18F0E822DD6AAE32785223F1704431B145', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
