INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3334', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of ESXi escape attempts by monitoring for anomalies in hypervisor logs such as unexpected VM operations, privilege escalation events, or attempts to load malicious kernel modules within the hypervisor environment.", "external_references": [{"external_id": "AN0615", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0219#AN0615"}], "id": "x-mitre-analytic--9f5f193f-6aef-4586-a047-492b0c651001", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0615", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "VM exit/entry anomalies, unexpected hypercalls, or kernel module loading", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--23e4ee78-26f3-4fcf-ba43-ab953962f96c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Modules permitted in the hypervisor. Loading any module outside of this list may indicate compromise.", "field": "AllowedKernelModules"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3334', 0, 102, '09-mitre-attack', 'retrieved', 'EF39859BEF47AEF1709824ADA12A42FA7C183DC38422AEA7A1F305D365B094EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
