VALUES ('doc-09-mitre-attack-p0-3335', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious registration of new password filter DLLs into the authentication process. Correlates registry modifications to LSASS Notification Packages with subsequent DLL creation and loading events. Observes anomalous file placement of DLLs in system directories followed by LSASS loading the new filter during logon/password change activity.", "external_references": [{"external_id": "AN1303", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0472#AN1303"}], "id": "x-mitre-analytic--9fb6bb78-418a-483f-ae23-518ffde414d1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1303", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific registry path monitored for modification (e.g., HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Notification Packages).", "field": "RegistryPath"}, {"description": "Known and approved password filter DLLs; deviations from baseline may indicate malicious injection.", "field": "AllowedDLLs"}, {"description": "Time window for correlating registry modification, file creation, and module load events.", "field": "TimeWindow"}, {"description": "Expected directories for legitimate password filter DLLs; anomalous paths may signal compromise.", "field": "FilePathPatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3335', 0, 161, '09-mitre-attack', 'retrieved', '7F0B1A14FF572C0C1478FDB61D309DDA1DEDA867E0236EB28C9614F938D77CCA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
