VALUES ('doc-09-mitre-attack-p0-3336', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Drive enumeration using PowerShell (`Get-PSDrive`), `wmic logicaldisk`, or Win32 API indicative of local volume enumeration by non-admin users or executed outside of baseline system inventory scripts.", "external_references": [{"external_id": "AN0536", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0188#AN0536"}], "id": "x-mitre-analytic--9ffd3332-fcc0-440d-b717-ef98e140c543", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0536", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-system accounts performing drive enumeration may be higher fidelity indicators", "field": "user_context"}, {"description": "Baseline parent-child process lineage can help distinguish admin tools from malicious scripts", "field": "parent_process_name"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3336', 0, 99, '09-mitre-attack', 'retrieved', '8FE8F04B46CD4B7754ACA2795F0A5799CB41D6D0985F6A5890B2011DA9389FF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
