VALUES ('doc-09-mitre-attack-p0-3337', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary tampering of shared directories via file drops (e.g., malicious LNK, EXE, VBS) followed by user execution or suspicious network activity.", "external_references": [{"external_id": "AN1298", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0471#AN1298"}], "id": "x-mitre-analytic--a0554596-7100-4f8b-a4dd-165f528fe6a1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1298", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=5145", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines monitored shared directories (e.g., \\\\server\\HR\\).", "field": "SharedPathPrefix"}, {"description": "Monitored file types dropped in shared paths (e.g., .lnk, .exe, .vbs).", "field": "ExecutableExtensions"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3337', 0, 96, '09-mitre-attack', 'retrieved', '4754B69F0641250923F406A15404779FB1F2669A77E7C69D7D61CA8F61936313', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
