VALUES ('doc-09-mitre-attack-p0-3339', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual OAuth app registration followed by user-granted OAuth tokens and subsequent high-privilege resource access via those tokens.", "external_references": [{"external_id": "AN1425", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0515#AN1425"}], "id": "x-mitre-analytic--a064fdd2-4293-4aff-a91b-e06ac8bf9262", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1425", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "App registrations or consent grants by abnormal users or at unusual times", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable based on risky or privileged scopes in the environment", "field": "ConsentScope"}, {"description": "Threshold of how many users have authorized a given app", "field": "AppUserRatio"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3339', 0, 100, '09-mitre-attack', 'retrieved', '200ED4466AE5CCCE376ECD828D9C4379CCBF8523A0F510AFFBB785A3C43FB181', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
