VALUES ('doc-09-mitre-attack-p0-3340', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects DLL injection through correlation of memory allocation and writing to remote process memory (e.g., VirtualAllocEx, WriteProcessMemory), followed by remote thread creation (e.g., CreateRemoteThread) that loads a suspicious or unsigned DLL using LoadLibrary or reflective loading.", "external_references": [{"external_id": "AN1095", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0389#AN1095"}], "id": "x-mitre-analytic--a06e9154-5584-4f5d-be47-b420d79674c7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1095", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=17", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether the DLL is unsigned, untrusted, or loaded from a non-standard path", "field": "InjectedDLLSignatureStatus"}, {"description": "Temporal correlation threshold between memory operations and thread creation", "field": "TimeWindow"}, {"description": "List of sensitive or high-value processes targeted for injection (e.g., explorer.exe, winlogon.exe)", "field": "TargetProcessList"}, {"description": "Degree of deviation from expected parent-child lineage", "field": "ParentProcessAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3340', 0, 151, '09-mitre-attack', 'retrieved', '674E512A08B091A11DBD5CB2CAA845B89B1FBBA3664B025C296EEA9F22631068', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
