VALUES ('doc-09-mitre-attack-p0-3341', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of scheduled tasks using schtasks.exe, at.exe, or COM objects followed by execution of outlier processes tied to the scheduled job.", "external_references": [{"external_id": "AN0258", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0094#AN0258"}], "id": "x-mitre-analytic--a0714b4d-5dbf-499e-a737-7b00478267ee", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0258", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4698", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unexpected user or account context initiating the task.", "field": "TaskAuthor"}, {"description": "Suspicious binaries or script usage tied to scheduled tasks.", "field": "CommandLineRegex"}, {"description": "Lookback window to correlate process execution after task registration.", "field": "ExecutionWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3341', 0, 116, '09-mitre-attack', 'retrieved', '2EECB82F4DFFBCF87DD1635128819931E0EDD62879EB8BA0363728E5831FE796', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
