VALUES ('doc-09-mitre-attack-p0-3342', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Discovery of connected SaaS applications, APIs, or configurations within platforms like Salesforce, Slack, or Zoom. Defender perspective includes enumeration of available integrations, abnormal querying of service metadata, and follow-on attempts to exploit or persist via discovered services.", "external_references": [{"external_id": "AN1130", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0402#AN1130"}], "id": "x-mitre-analytic--a0730d9f-0a05-4153-8c6a-6f04f9f7346c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1130", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ListIntegrations, ListServices: Repeated service discovery requests from accounts without administrative responsibilities", "name": "saas:adminapi", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "Login, TokenGranted: Discovery actions tied to anomalous login sessions or tokens", "name": "saas:auth", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of SaaS integrations enumerated before triggering detection.", "field": "IntegrationDiscoveryThreshold"}, {"description": "Expected permissions for service accounts to distinguish benign from malicious discovery.", "field": "ServiceAccountScope"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3342', 0, 133, '09-mitre-attack', 'retrieved', '8C8F458E7DE9C45CAF6A833CFE636457E6674C6B10964BC17E0789E0F4312E6B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
