VALUES ('doc-09-mitre-attack-p0-3343', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious creation or modification of inbox rules through PowerShell (New-InboxRule, Set-InboxRule) to automatically delete, move, or hide emails. Defender perspective: unusual rule activity correlated with mailbox access and filtering patterns.", "external_references": [{"external_id": "AN0551", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0192#AN0551"}], "id": "x-mitre-analytic--a09ed72b-be04-475f-8c0a-11ed47b40bd1", "modified": "2026-05-12T16:30:18.381Z", "name": "Analytic 0551", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "New-InboxRule or Set-InboxRule events recorded in Exchange Online", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Keywords like ''phish'', ''malware'', ''suspicious'' used in inbox rules to hide emails.", "field": "SuspiciousKeywords"}, {"description": "Scope mailbox monitoring to high-value users such as executives or admins.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3343', 0, 122, '09-mitre-attack', 'retrieved', '3AF74F200E54B5E7AA34E0E2D70833817B5B9564CA0A49D5F4D1E3151FA6491B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
