VALUES ('doc-09-mitre-attack-p0-3344', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of VSCode tunnel configuration file combined with interactive remote session via code CLI or ssh with JetBrains gateway.", "external_references": [{"external_id": "AN0376", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0133#AN0376"}], "id": "x-mitre-analytic--a0a0f8e9-7a55-4450-8569-7a0e1c0aac0b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0376", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve on code or jetbrains-gateway with remote flags", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open: Write to ~/.vscode-cli/code_tunnel.json", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Connections to *.devtunnels.ms or tunnels.api.visualstudio.com", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex patterns for user home directory file paths may vary by distro or user.", "field": "PathRegex"}, {"description": "Tunnel flags used by CLI tools can be customized or obfuscated by adversaries.", "field": "TunnelCLIFlags"}, {"description": "The Linux user account associated with tunnel initiation; may vary across developer environments", "field": "Username"}, {"description": "The filepath to the .vscode-cli/code_tunnel.json file may vary by distribution or IDE version", "field": "TunnelArtifactPath"}, {"description": "Different IDEs or wrapper scripts may launch with different tunnel-related CLI options (e.g., --remote, --host)", "field": "CommandLineFlags"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3344', 0, 173, '09-mitre-attack', 'retrieved', 'A9BDF2C4D58A9B62A9CE1062131AE82869B36AA6400DD113DFECB5BA4A74A0BB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
