VALUES ('doc-09-mitre-attack-p0-3345', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects login to admin consoles (e.g., Microsoft 365 Admin Center) from unrecognized users, devices, or geolocations followed by non-API data review or configuration read actions that suggest GUI dashboard use.", "external_references": [{"external_id": "AN0810", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0291#AN0810"}], "id": "x-mitre-analytic--a0bfcae2-1936-466d-91b4-f72fcae730b6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0810", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "UserLoginSuccess", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "ViewAdminReport", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Read-only configuration review from GUI", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Roles allowed to access dashboard views", "field": "AdminRoleList"}, {"description": "Pageview paths or clickstreams indicating use of GUI admin console", "field": "DashboardNavigationSequence"}, {"description": "List of high-risk regions or unexpected geos", "field": "GeoLocationRisk"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3345', 0, 124, '09-mitre-attack', 'retrieved', '4E3980BFE37A214A58EDA8A9601604DB790662344E62DA84F4BD8483ED8B0FB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
