VALUES ('doc-09-mitre-attack-p0-3346', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Firmware flash utility invoked with elevated privileges followed by raw access to firmware device path or changes to boot configuration.", "external_references": [{"external_id": "AN0474", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0167#AN0474"}], "id": "x-mitre-analytic--a0ecdd41-a051-4ada-9ec1-c29dc0c4ac61", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0474", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"channel": "Firmware integrity validation failed or boot configuration tampered", "name": "WinEventLog:Microsoft-Windows-Kernel-Boot", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common legitimate flash tool chains can be allowlisted", "field": "ParentImage"}, {"description": "Flags indicating silent or forced flash may vary", "field": "CommandLine"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3346', 0, 106, '09-mitre-attack', 'retrieved', '1D6047E8E066DB7EDC5C2B34200529C7122E33F5517B4F7B28FC7DB165B4CC99', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
