VALUES ('doc-09-mitre-attack-p0-3347', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Excessive login attempts followed by success from SaaS apps like O365, Dropbox, etc.", "external_references": [{"external_id": "AN1279", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0463#AN1279"}], "id": "x-mitre-analytic--a1436a64-ffc4-4e39-a7c8-140e78336ffa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1279", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Sign-in logs", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect brute force attempts targeting specific apps", "field": "AppName"}, {"description": "Limit alert scope to high-value user groups", "field": "UserGroup"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3347', 0, 79, '09-mitre-attack', 'retrieved', '9743698FC38ACE733D9854F7CCB65D5697A12BC44C89C08B7BE9544D608AEE3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
