VALUES ('doc-09-mitre-attack-p0-3348', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary runs ''system_profiler SPApplicationsDataType'' or queries plist files to enumerate software via Terminal or scripts.", "external_references": [{"external_id": "AN1102", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0392#AN1102"}], "id": "x-mitre-analytic--a1619e8f-10aa-46ab-8776-898e8c3d5b43", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1102", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of system_profiler or osascript invoking enumeration", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Command line arguments including SPApplicationsDataType", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether enumeration targets user apps or system apps.", "field": "AppScope"}, {"description": "Parent process or scripting environment (e.g., Python, osascript).", "field": "ProcessGroup"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3348', 0, 98, '09-mitre-attack', 'retrieved', '3C46C0D2B5919BBA4B50BBB52E35DEE76C5453EF24F36B76CD08601178934874', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
