INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3350', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects staged file access (e.g., archive or obfuscation), followed by an encrypted outbound connection (TLS/HTTPS) from unusual processes such as curl/wget, Python scripts, or custom binaries.", "external_references": [{"external_id": "AN1414", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0512#AN1414"}], "id": "x-mitre-analytic--a2309590-988e-4116-85e6-59bfc5357726", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1414", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "ssl.log, conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "open, read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict outbound connections to non-corporate domains or IPs.", "field": "ConnectionDestinationScope"}, {"description": "List of extensions considered sensitive or exfil-worthy (e.g., .zip, .db, .xlsx).", "field": "FileAccessExtensionList"}, {"description": "Define normal encrypted-traffic-capable binaries.", "field": "SSLClientProcessBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3350', 0, 123, '09-mitre-attack', 'retrieved', 'B7624F016B69047DCDC8530C95A7E3B49BC7C0F51BEB080ABB0BDA3DCD6020D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
