VALUES ('doc-09-mitre-attack-p0-3351', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary activity aimed at accessing LSA Secrets, including registry key export of HKEY_LOCAL_MACHINE\\SECURITY\\Policy\\Secrets or memory scraping via tools such as Mimikatz or PowerSploit''s Invoke-Mimikatz.", "external_references": [{"external_id": "AN1212", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0437#AN1212"}], "id": "x-mitre-analytic--a29288f5-c5d8-4e2d-8370-c4e21a64fc95", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1212", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Target registry paths like HKLM\\SECURITY\\Policy\\Secrets or variants can be tuned depending on OS version or registry redirection settings.", "field": "TargetObject"}, {"description": "Module names such as `lsasrv.dll`, `sechost.dll`, or suspicious DLLs loaded by user processes may require tuning for known-good service operations.", "field": "ImageLoaded"}, {"description": "Tuning based on whether processes are using specific sensitive access rights (e.g., 0x2 or 0x4).", "field": "AccessMask"}, {"description": "Temporal window between registry access and command-line tool execution.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3351', 0, 164, '09-mitre-attack', 'retrieved', '7B87B0B755B4BF78BFC0B7AEB537AF120CC0D7CE989D5C26CB175B2C0B4AF4AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
