VALUES ('doc-09-mitre-attack-p0-3352', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary adds federated identity provider (IdP) or modifies tenant domain authentication from Managed to Federated. Detected via API, PowerShell, or Admin Portal through federation events like `Set domain authentication`, `Add federated identity provider`, or `Update-MsolFederatedDomain`.", "external_references": [{"external_id": "AN1260", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0458#AN1260"}], "id": "x-mitre-analytic--a2d3072a-0f3a-46a1-a92e-f0d7ae030b48", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1260", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set federation settings on domain|Set domain authentication|Add federated identity provider", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "OperationName=SetDomainAuthentication OR Update-MsolFederatedDomain", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify rare trust-modification operations (SetDomainAuthentication, Update-MsolFederatedDomain).", "field": "OperationName"}, {"description": "Flag federated trust changes performed by unknown users, service principals, or tokens.", "field": "InitiatedBy"}, {"description": "Separate scripted/API interactions from GUI-based administrative changes.", "field": "UserAgent"}, {"description": "Correlate trust change to federated login or SAML token injection within short window.", "field": "TimeWindow"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3352', 0, 148, '09-mitre-attack', 'retrieved', 'A032EB8D9DA4C8ED83D47118D9DDB4DEE57789F4932074BC44ACD4B5A9823EA2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
