VALUES ('doc-09-mitre-attack-p0-3353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects non-interactive or script-driven email transmission using tools like `sendmail`, `mailx`, or custom SMTP scripts by background processes, especially when sending attachments or large payloads.", "external_references": [{"external_id": "AN0380", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0135#AN0380"}], "id": "x-mitre-analytic--a311af7c-2302-4113-8cc3-d5d599fa908a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0380", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "smtp.log, conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Bytes transferred via SMTP session", "field": "TransferSizeThreshold"}, {"description": "e.g., base64 encoded mailer scripts or one-liners in cron", "field": "ScriptNameFilter"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3353', 0, 97, '09-mitre-attack', 'retrieved', '71625B27BA28680C1FDF933D93554ED2045267E94A5CBF797F58C138A1D72EE8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
