VALUES ('doc-09-mitre-attack-p0-3354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes that utilize AppleScript, `CGWindowListCopyWindowInfo`, or `NSRunningApplication` APIs to list active application windows and foreground processes.", "external_references": [{"external_id": "AN0273", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0097#AN0273"}], "id": "x-mitre-analytic--a31400ee-ac3e-408e-aa4d-fb2b470142ab", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0273", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable to ignore benign scripting like automation by known apps.", "field": "AppleScriptTarget"}, {"description": "Useful to suppress expected automation processes.", "field": "ParentProcess"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3354', 0, 89, '09-mitre-attack', 'retrieved', '8B3AFE2E011BCE1CBBD309702CCD419FFFD7499EF4A4FDA1A26D9B7534D8CB77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
