VALUES ('doc-09-mitre-attack-p0-3356', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "SSH session from new source IP followed by interactive shell or privilege escalation (e.g., sudo, su) and outbound lateral connection.", "external_references": [{"external_id": "AN0751", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0269#AN0751"}], "id": "x-mitre-analytic--a366262a-ba79-4b74-be16-0b139d546651", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0751", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "sshd: Accepted password/publickey", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "execve, USER_CMD", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit to new/unexpected SSH source IPs", "field": "SourceIP"}, {"description": "Flag suspicious post-SSH command patterns", "field": "CommandList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3356', 0, 91, '09-mitre-attack', 'retrieved', '32532344F1FFA39D27D5CA4887F7B9A8DEBBF052F2A4D083D3D7B6675C04EDD2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
