VALUES ('doc-09-mitre-attack-p0-3357', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of inbound emails with embedded links followed by user-driven browser navigation to suspicious or obfuscated domains. Detection chain includes malicious URL in email → user click recorded in Office logs → browser process spawning unusual child processes (e.g., PowerShell, cmd) or download activity.", "external_references": [{"external_id": "AN0298", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0107#AN0298"}], "id": "x-mitre-analytic--a39fccda-e5ea-49de-80f9-d67ae3b8c799", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0298", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Send/Receive: Inbound emails containing embedded or shortened URLs", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of monitored top-level domains commonly abused in phishing (e.g., .xyz, .top, .tk).", "field": "SuspiciousTLDs"}, {"description": "Domains like bit.ly, tinyurl.com flagged for deeper expansion/inspection.", "field": "URLShortenerDomains"}, {"description": "Time threshold between URL click and suspicious process execution.", "field": "ClickToExecutionWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3357', 0, 148, '09-mitre-attack', 'retrieved', 'EDE5F2C5534A10C05351DE485405578FA3C7AB32E04208E213F0163A684E11B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
