VALUES ('doc-09-mitre-attack-p0-3359', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of VMFS or ESXi shell to hide datastore files, renaming/moving VMDK or VMX files into hidden directories. Defender view: anomalous ESXi shell commands or file operations obscuring VM artifacts.", "external_references": [{"external_id": "AN1387", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0502#AN1387"}], "id": "x-mitre-analytic--a3c087a6-b7dc-464f-9e84-278bf3076ed1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1387", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "mv, rename, or chmod commands moving VM files into hidden directories", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Datastore file hidden or renamed unexpectedly", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict to VMDK, VMX, or log files critical for VM operations.", "field": "VMFileScope"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3359', 0, 110, '09-mitre-attack', 'retrieved', 'CA82E8DC4E61DF38146B597510E8152D69F960BCE6192E74BDAD5C0DA753CF40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
