VALUES ('doc-09-mitre-attack-p0-3361', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary use of bash/zsh or AppleScript to locate files and exfil targets like user keychains or documents.", "external_references": [{"external_id": "AN1072", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0380#AN1072"}], "id": "x-mitre-analytic--a48f36c7-e946-4270-ae23-1a2e52ae2e24", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1072", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process:spawn", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "read/write", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Useful for excluding known admin or scheduled jobs.", "field": "UserContext"}, {"description": "Focus monitoring on removable drives or external paths.", "field": "TargetVolume"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3361', 0, 90, '09-mitre-attack', 'retrieved', '7FB99BBB4C2C07234E611B717AA056419357705E2DB8FB17D7D1865ACDEFF8A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
