VALUES ('doc-09-mitre-attack-p0-3362', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary exploits Apache/Nginx/app servers. Chain: (1) suspicious requests in access logs → (2) spike of 5xx or WAF blocks → (3) web server or interpreter (apache2/nginx/php-fpm/node/python) spawns /bin/sh, curl, wget, socat, or writes webshell → (4) outbound callback.", "external_references": [{"external_id": "AN0220", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0080#AN0220"}], "id": "x-mitre-analytic--a4ce8f28-db09-4b0d-bb8d-a77ba3cef3c0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0220", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/httpd/access_log, /var/log/apache2/access.log, /var/log/nginx/access.log with exploit indicators and burst errors", "name": "ApplicationLog:WebServer", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "HTTP payloads with SQLi/LFI/JNDI/deserialization indicators", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "server/interpreter names to watch (apache2, httpd, nginx, php-fpm, uwsgi, gunicorn, node).", "field": "WebProcList"}, {"description": "post-exploitation binaries (sh, bash, curl, wget, python, perl, socat, nc).", "field": "ChildToolList"}, {"description": "Rate of errors/requests per src_ip/uri to flag reconnaissance/exploit spray.", "field": "BurstThreshold"}, {"description": "Exec/network correlation window.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3362', 0, 152, '09-mitre-attack', 'retrieved', 'DC74AD148EE6BA5B5C38E3032CF727EDC49AE7665186AF10D88333D12567B244', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
