VALUES ('doc-09-mitre-attack-p0-3363', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of outbound connections on alternate ports or using covert transport (e.g., ICMP, DNS) from non-network-intensive processes, following known disruption or blocked traffic.", "external_references": [{"external_id": "AN1377", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0499#AN1377"}], "id": "x-mitre-analytic--a50c90f1-51b1-4948-8945-4b89735d4750", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1377", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "outbound connections", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "alternate ports", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can filter for rare fallback channel types (e.g., ICMP, DNS over HTTP).", "field": "ProtocolType"}, {"description": "Tuning by user (e.g., root vs. service account) helps suppress noise.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3363', 0, 105, '09-mitre-attack', 'retrieved', '2A68A5B09D0B45920FE2B6F588541D5E99D9412166CC824B6FCCFBEE6D89216F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
