VALUES ('doc-09-mitre-attack-p0-3364', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Behavioral chain of a user being granted elevated privileges or roles in Entra ID or Okta following suspicious login or account creation activity.", "external_references": [{"external_id": "AN0772", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0277#AN0772"}], "id": "x-mitre-analytic--a52321d0-5961-497b-8212-61602e05420b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0772", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add member to role, Add app role assignment", "name": "m365:audit", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of accounts allowed to hold sensitive roles like Global Admin", "field": "AdminRoleThreshold"}, {"description": "Mechanism by which role was added (PowerShell, API, UI)", "field": "RoleAssignmentMethod"}, {"description": "Expected user-to-role mapping defined by org policy", "field": "GrantContext"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3364', 0, 112, '09-mitre-attack', 'retrieved', 'B55AC8C2718051F545CAECA628A8A164D0D455C1EBB73734FAE40637CA2BA3C9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
