VALUES ('doc-09-mitre-attack-p0-3365', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Inbound binary payloads transferred over HTTP/S with compressed or encoded headers, lacking signature markers or metadata indicative of compiler/toolchain.", "external_references": [{"external_id": "AN0058", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0019#AN0058"}], "id": "x-mitre-analytic--a53e2979-2c41-44bc-b46e-13a19305e00d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0058", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "http.log, files.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune for octet-stream or mismatched Content-Type headers", "field": "MIMEType"}, {"description": "Payload threshold for executable-sized artifacts", "field": "PayloadSize"}, {"description": "Suspicious base64 or chunked encoding not matching normal app behavior", "field": "TransferEncoding"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3365', 0, 97, '09-mitre-attack', 'retrieved', 'A3043DAB53B4E3DDE9CF6206A4434D05E35D73A69E5A80B434972C9B6120B1F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
