VALUES ('doc-09-mitre-attack-p0-3366', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary exploits containerized app via ingress or service. Chain: (1) suspicious request in ingress/app logs → (2) container process spawns a shell/exec/sidecar (kubectl exec/docker exec) → (3) egress to Internet or metadata service (169.254.169.254).", "external_references": [{"external_id": "AN0222", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0080#AN0222"}], "id": "x-mitre-analytic--a57ad75c-331e-4607-b358-61f4cddb8a5d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0222", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Kubernetes NGINX/Envoy ingress controller logs with anomalous payloads and 5xx spikes", "name": "ApplicationLog:Ingress", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Docker/Kubernetes audit of exec/attach (kubectl exec) or unexpected child processes inside container", "name": "docker:events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Requests towards cloud metadata or command & control from pod IPs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Namespaces that are Internet-facing.", "field": "IngressNamespaces"}, {"description": "Cloud metadata IPs/hostnames for exfil of credentials.", "field": "MetadataEndpoints"}, {"description": "Join period between ingress request and pod exec/egress.", "field": "TimeWindow"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3366', 0, 150, '09-mitre-attack', 'retrieved', '6B8925902486782744FE47A52B1C1F1026918C0EAC000AB8ED0D754F5E5CF186', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
