VALUES ('doc-09-mitre-attack-p0-3367', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of SyncAppvPublishingServer.vbs through wscript.exe with a command-line containing embedded PowerShell, proxying malicious PowerShell execution through a Microsoft-signed VBScript interpreter to evade detection and restrictions.", "external_references": [{"external_id": "AN1220", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0440#AN1220"}], "id": "x-mitre-analytic--a59042de-ecac-45bf-a852-af3df41b86d8", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1220", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detects embedded PowerShell commands in SyncAppvPublishingServer.vbs invocation, e.g., `{powershell -nop -enc ...}`", "field": "CommandLineRegex"}, {"description": "May vary between `wscript.exe`, `cscript.exe`, or called via `cmd.exe`", "field": "ScriptInterpreter"}, {"description": "Used to detect encoding, obfuscation, or entropy level in embedded PowerShell payloads", "field": "PowerShellObfuscationScore"}, {"description": "Time delta between VBScript proxy invocation and PowerShell payload execution", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3367', 0, 146, '09-mitre-attack', 'retrieved', '1B4B99AF069EA577DD04A39D083FB45467BFECF2C4F5462A706171C257CA7BFD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
