VALUES ('doc-09-mitre-attack-p0-3368', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary executes CLI commands like `show users`, `show ssh`, or attempts to dump AAA user lists from routers or switches.", "external_references": [{"external_id": "AN0257", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0093#AN0257"}], "id": "x-mitre-analytic--a5cc0eac-af18-4fe2-ac06-88a5cfddf014", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0257", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "aaa privilege_exec", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "eventlog", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected command set per device role/user role combination", "field": "CLICommandBaseline"}, {"description": "Correlate access with core vs. edge vs. management plane sensitivity", "field": "DeviceRoleSensitivity"}, {"description": "Detect burst usage of `show` or `debug` commands by non-admin users", "field": "CommandFrequencyThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3368', 0, 111, '09-mitre-attack', 'retrieved', 'EAB1DDE2B5AAD213C8D2146FBA662B0294E2B65475EFD1167CAB8F908474CFD0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type":