INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3369', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of Regsvcs.exe or Regasm.exe to execute arbitrary code embedded in .NET assemblies via [ComRegisterFunction]/[ComUnregisterFunction]. Behavioral chain: (1) Process creation of regsvcs/regasm with suspicious assembly paths/flags → (2) Assembly/DLL load inside regsvcs/regasm → (3) Registry writes to HKCR\\CLSID/ProgID during COM registration → (4) Optional child process or network activity spawned by installer/registration code.", "external_references": [{"external_id": "AN1028", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0361#AN1028"}], "id": "x-mitre-analytic--a5e9fb06-ab75-415d-beff-206aa059e096", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1028", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment-specific paths to flag (e.g., %TEMP%, Downloads, OneDrive, SMB shares). Helps suppress known-good installers.", "field": "AssemblyPathRegex"}, {"description": "Arguments like /unregister (/u), /codebase, /regfile which may indicate abuse. Tune per enterprise use of regasm/regsvcs.", "field": "SuspiciousFlags"}, {"description": "Legitimate parents (e.g., setup.exe, msiexec.exe). Analyst can prune false positives from Office or script hosts.", "field": "ParentProcessAllowList"}, {"description": "Hashes or publisher info for approved assemblies commonly registered in the environment.", "field": "KnownGoodAssemblies"}, {"description": "Approved CLSIDs/ProgIDs written during sanctioned software installs.", "field": "RegistryKeyAllowList"}, {"description": "Correlation window (e.g., 5–10 min) between file drop → regasm/regsvcs exec → registry writes → child activity.", "field": "TimeWindow"}, {"description": "Alert if Microsoft-signed regasm/regsvcs loads or triggers unsigned assemblies/children.", "field": "SignedToUnsignedTransition"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3369', 0, 250, '09-mitre-attack', 'retrieved', 'D8BC94CCAFAC2B24FEA68BEABCA5DDCE1BA47F989848C898B6E5B0913BDE275F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
