VALUES ('doc-09-mitre-attack-p0-3370', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious macros or embedded objects hidden within Office documents by renaming streams or using hidden OLE objects. Defender view: detection of hidden macro streams or objects in documents correlated with anomalous execution.", "external_references": [{"external_id": "AN1388", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0502#AN1388"}], "id": "x-mitre-analytic--a6299804-cf50-4496-a242-1394ff89c147", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1388", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Detection of hidden macro streams or SetHiddenAttribute actions", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune detection to specific Office apps and document types where macros are disallowed.", "field": "MacroScope"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3370', 0, 101, '09-mitre-attack', 'retrieved', 'CC4B349A9F5CF94F0B635D7D5CAEF65828EC9F10272BFD84594E0CDFE3004044', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
