VALUES ('doc-09-mitre-attack-p0-3371', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects enumeration of local groups using common binaries (groups, getent, cat /etc/group) or scripting with suspicious lineage.", "external_references": [{"external_id": "AN0318", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0114#AN0318"}], "id": "x-mitre-analytic--a62a2b36-00e9-481c-9a3a-14c14cd42dae", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0318", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection tuning for binaries like `groups`, `getent`, `awk`, or `cut` that may be used in pipelines.", "field": "ProcessName"}, {"description": "Used to determine whether enumeration was triggered by a script or terminal.", "field": "ParentProcess"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3371', 0, 96, '09-mitre-attack', 'retrieved', '42C8D2B03ED89429C9F4E4A8C14C4D097354DE57FDED548AF3907E7E4586F095', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
