INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3373', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of unauthorized modifications to Windows root certificate stores by monitoring registry keys, certificate installation processes, and creation of new certificate entries not in baseline trusted lists.", "external_references": [{"external_id": "AN0153", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0056#AN0153"}], "id": "x-mitre-analytic--a65545d7-fa1b-4d6f-b19c-fa03862c6210", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0153", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline list of root certificate hashes; defenders can tune based on organizational certificate policies.", "field": "TrustedRootHashList"}, {"description": "Processes associated with certificate management that should be flagged if executed by non-admin users or in unusual contexts.", "field": "MonitoredProcesses"}, {"description": "Correlation window for registry modifications, certificate installation, and process creation to strengthen detection.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3373', 0, 138, '09-mitre-attack', 'retrieved', 'E8050DEAA0EDB196BFFA6331ADF4F1F25869D44CF9F5FD4B9AE1A7C382A528D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
