INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3374', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Office application auto-loads a non-standard DLL during startup triggered via Office Test Registry key, often without macro warning banners. DLL persistence mechanism circumvents traditional macro defenses.", "external_references": [{"external_id": "AN0881", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0315#AN0881"}], "id": "x-mitre-analytic--a677cebe-06e8-4993-bd4c-6a6884862444", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0881", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Non-standard Office startup component detected (e.g., unexpected DLL path)", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "Startup execution includes non-default component", "name": "m365:office", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "DLL may be placed in location trusted by Office configuration or signed to evade alerts", "field": "TrustedLocationBypass"}, {"description": "Only specific tenants or users may have Office auditing enabled at granular DLL load level", "field": "AuditPolicyScope"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3374', 0, 126, '09-mitre-attack', 'retrieved', '259FEDEFD36E2C508D9A1BADA8C2FA83E1BCEC248F80A0910FD9B990707478C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
