VALUES ('doc-09-mitre-attack-p0-3375', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects AppleScript execution via ''osascript'', NSAppleScript/OSAScript APIs, and abnormal application control events across user sessions. Focuses on causal chains such as osascript spawning child processes, script-induced keystrokes, or API-backed dialog spoofing.", "external_references": [{"external_id": "AN1164", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0414#AN1164"}], "id": "x-mitre-analytic--a67ac8ec-2748-4fe6-8dd7-bd570af1e104", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1164", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process: spawn, exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify rare or suspicious parent processes launching AppleScript (e.g., Safari, Mail, msedge).", "field": "ScriptInvocationParent"}, {"description": "Flag AppleScript execution during user-inactive hours, especially for automation frameworks.", "field": "TimeWindow"}, {"description": "Filter AppleEvent-based automation involving UI interaction, keystrokes, or remote control.", "field": "AppleEventActionType"}, {"description": "Scope AppleScript use toward security-sensitive apps (e.g., Terminal, ssh, Keychain Access).", "field": "TargetApplicationSet"}, {"description": "Restrict to unusual paths like /tmp/, ~/Library/, or embedded in Automator workflows.", "field": "ExecutionPathRegex"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3375', 0, 148, '09-mitre-attack', 'retrieved', '03A316C59857F1818AC96CE420E1E4F57FCF55F0B8DA89D91E57CB1F3E4AFDC6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
