INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3376', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Encrypted traffic or ICMP tunneling from border routers to internal routers or unknown external IPs. Forwarded traffic shows consistent hop-to-hop relaying without matching configured VPN or expected network topology.", "external_references": [{"external_id": "AN1024", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0359#AN1024"}], "id": "x-mitre-analytic--a691ee45-94bf-4244-a286-b80c21859d2e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1024", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Relayed session pathing (multi-hop)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Outbound encrypted traffic", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Custom firmware or routing changes", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define allowed internal router communication paths.", "field": "VPNConfigWhitelist"}, {"description": "High entropy ICMP payloads may indicate tunneling activity.", "field": "ICMPPayloadEntropy"}, {"description": "Track known multi-hop pattern signatures or port hopping techniques.", "field": "RelayChainSignature"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3376', 0, 128, '09-mitre-attack', 'retrieved', 'FE68AC33C26D716403B180D75819BE5520EA61C5B8E7A7CB443AB78DD42D1B03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
