INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "1) New or updated software is delivered/installed from atypical sources or with signature/hash mismatches; 2) installer/updater writes binaries to unexpected paths or replaces existing signed files; 3) first run causes unsigned/abnormally signed modules to load or child processes to execute, optionally followed by network egress to new destinations.", "external_references": [{"external_id": "AN1480", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0537#AN1480"}], "id": "x-mitre-analytic--a6b1e74e-6c05-4d9f-928c-63ddf558798b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1480", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "CodeIntegrity reports ''Invalid image hash'' or ''Unsigned image'' for new/updated binaries", "name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "First-time egress from host after new install to unknown update endpoints", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window between install events and first-run activity (default 2h; adjust for staged rollouts).", "field": "TimeWindow"}, {"description": "Publisher/Signer allow-list to suppress expected updates.", "field": "TrustedPublishers"}, {"description": "Known update CDNs/APIs (e.g., download.microsoft.com) to reduce egress false positives.", "field": "TrustedUpdateHosts"}, {"description": "Score cut-off for alerting when combining path, signer, and reputation features.", "field": "RiskScoreThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3377', 0, 190, '09-mitre-attack', 'retrieved', '1D049BB00F3415AC2CD65BEA61040A544B1DF6C2CAEF190B828D68F6E7B3A1A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
