VALUES ('doc-09-mitre-attack-p0-3379', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual processes (e.g., powershell.exe, excel.exe) accessing large local files and subsequently initiating HTTPS POST requests to domains associated with cloud storage services (e.g., dropbox.com, drive.google.com, box.com). Defender perspective: correlation between file reads in sensitive directories and high outbound traffic volume to known storage APIs.", "external_references": [{"external_id": "AN1571", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0570#AN1571"}], "id": "x-mitre-analytic--a74c34c2-f4bf-4bd0-9f23-7c04c45b93ca", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1571", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of monitored domains for cloud services (dropbox.com, drive.google.com, onedrive.live.com).", "field": "CloudStorageDomains"}, {"description": "Data volume threshold (e.g., >10MB in single session) used to flag abnormal transfers.", "field": "ExfilVolumeThreshold"}, {"description": "User accounts permitted to use sanctioned cloud services versus unexpected accounts.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3379', 0, 147, '09-mitre-attack', 'retrieved', '1EAD41EF63E223DDC5519D38E954BAD8794E6B99CB8E9D2822027C4C9584FF62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
