VALUES ('doc-09-mitre-attack-p0-3380', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution of image viewers or PowerShell scripts accessing or decoding files with mismatched MIME headers or embedded script-like byte patterns; often correlated with suspicious parent-child process lineage and outbound connections.", "external_references": [{"external_id": "AN0331", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0119#AN0331"}], "id": "x-mitre-analytic--a7666a4d-ece8-4e5b-ae85-d2987f14b950", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0331", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to identify image editors/viewers invoking script interpreters (e.g., `mspaint.exe` > `powershell.exe`)", "field": "ParentProcessImage"}, {"description": "Adjust tolerance for image file headers that do not match file extensions or content structure", "field": "MimeHeaderMismatchTolerance"}, {"description": "Define the temporal range to correlate decoding → execution → network beaconing", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3380', 0, 139, '09-mitre-attack', 'retrieved', 'C862DAEC0B9A7F68FDC5B0F45C425AAEBE07B83E43325E4048522692564669BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
