VALUES ('doc-09-mitre-attack-p0-3381', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud API events where logging services are stopped, deleted, or modified in a way that disables audit visibility. Defender view: unauthorized StopLogging, DeleteTrail, or UpdateSink operations correlated with privileged user activity.", "external_references": [{"external_id": "AN0801", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0289#AN0801"}], "id": "x-mitre-analytic--a788e3ed-8faf-4443-bb26-fd530ca930d1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0801", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Stop logging for an existing CloudTrail", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}, {"channel": "UpdateSink request modifying log export destinations", "name": "gcp:config", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define which roles are authorized to stop or modify logging.", "field": "AdminRoles"}, {"description": "Adjust monitoring to ensure multi-region logging tampering is caught.", "field": "RegionScope"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3381', 0, 117, '09-mitre-attack', 'retrieved', '10A8192C043AB96DDC07641DBAB25DDF65D9978FF767981FE84517C5FB1D5B2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
