VALUES ('doc-09-mitre-attack-p0-3382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Persistent high CPU utilization combined with suspicious command-line execution (e.g., mining tools or obfuscated scripts) and outbound connections to mining/proxy networks.", "external_references": [{"external_id": "AN0741", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0267#AN0741"}], "id": "x-mitre-analytic--a789e535-cab9-49b4-9685-c10a5d3642b4", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0741", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "High sustained CPU usage by a single process", "name": "Windows:perfmon", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Duration threshold for sustained CPU activity (e.g., >15 minutes)", "field": "TimeWindow"}, {"description": "Known mining pool IPs or proxy service endpoints", "field": "DestinationIPList"}, {"description": "Regex list of suspicious or known mining tools", "field": "ExecutableNamePatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3382', 0, 120, '09-mitre-attack', 'retrieved', 'C7B7B895