VALUES ('doc-09-mitre-attack-p0-3383', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Dynamic or static port forwarding rules added to route traffic through an internal host, or configuration changes to proxy firewall rules not aligned with baselined policy.", "external_references": [{"external_id": "AN1233", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0445#AN1233"}], "id": "x-mitre-analytic--a79ae1d1-1a8d-427d-aa6d-261ea63d5650", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1233", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Policy Change / Rule Update", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"channel": "Flow Creation (NetFlow/sFlow)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Interface commands", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on new allow/permit rules with dynamic NAT or port forwarders.", "field": "RuleType"}, {"description": "Flag any non-admins initiating proxy config changes.", "field": "ChangeUser"}, {"description": "Detect sharp changes in bi-directional traffic patterns.", "field": "FlowVolumeDelta"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3383', 0, 125, '09-mitre-attack', 'retrieved', 'ACF9B2EFBA1F3F6DBE44259C6A177770B5FCDF9A425AC82E9D1E0F8D94E89F1E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
