VALUES ('doc-09-mitre-attack-p0-3384', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disabling of security macros or safe mode settings within Word/Excel/Outlook. Detect registry edits or configuration file changes that weaken macro enforcement.", "external_references": [{"external_id": "AN0894", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0317#AN0894"}], "id": "x-mitre-analytic--a807fb55-1c4f-4353-90d6-1a05aa05f2c9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0894", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "MacroSecuritySettingsChanged or SafeModeDisabled", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify which Office applications are monitored for macro security configuration changes.", "field": "ApplicationScope"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3384', 0, 83, '09-mitre-attack', 'retrieved', 'B2729CB7F3B411876E66C5DFE6BEE84470C3BF6A5E66851F0A6E9AEA683B0637', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
