INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3386', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous use of macOS XPC services for code execution. Monitors for processes invoking privileged XPC daemons with abnormal parameters, unexpected binaries communicating over NSXPCConnection, or helper tools executing code outside of their expected parent process lineage. Correlates process access attempts to system-level daemons, privilege escalations via XPC misconfigurations, and injection of malicious payloads through inter-process communication.", "external_references": [{"external_id": "AN0948", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0335#AN0948"}], "id": "x-mitre-analytic--a8284241-0d8e-42da-b86d-48f0d660df6c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0948", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unexpected NSXPCConnection calls by non-Apple-signed or abnormal binaries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "execve: Helper tools invoked through XPC executing unexpected binaries", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "XPC messages requesting privileged actions from untrusted or unsigned clients", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Maintain allowlist of binaries permitted to invoke specific XPC services to minimize false positives.", "field": "AllowedXPCClients"}, {"description": "Threshold for correlating abnormal XPC requests with subsequent privilege escalation or process creation.", "field": "TimeWindow"}, {"description": "Adjust sensitivity of alerts for unsigned or non-Apple-signed clients initiating XPC communication.", "field": "UnsignedBinaryAlertLevel"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3386', 0, 186, '09-mitre-attack', 'retrieved', '4D0D21A1C46A584CBC8706F233870357FAEB9CCE438E44D3E3261F2B7209A6D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
