INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3388', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of known default service accounts or root-level cloud accounts performing authentication or changes to IAM policy.", "external_references": [{"external_id": "AN1285", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0465#AN1285"}], "id": "x-mitre-analytic--a8ed4e86-c79a-40db-84e5-1b4cf0e917d3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1285", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ConsoleLogin or AssumeRole", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organizations may rename or rotate default IAM accounts; detection logic should be updated with any renamed or aliased default identities.", "field": "AccountList"}, {"description": "Authentication attempts from unusual geographic regions should trigger anomaly detection.", "field": "GeoLocation"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3388', 0, 101, '09-mitre-attack', 'retrieved', 'E1AF664B32E9958DD40C6349A7EAC005F363F52487580E4B2F132E75D9407321', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
