VALUES ('doc-09-mitre-attack-p0-3390', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Password changes or account deletions via ''passwd'', ''userdel'', or ''chage'' preceded by interactive shell or remote command execution from non-privileged accounts.", "external_references": [{"external_id": "AN0335", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0120#AN0335"}], "id": "x-mitre-analytic--a941dd04-5626-4091-9eed-300d7d7f0a1f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0335", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SYSCALL record where exe contains passwd/userdel/chage and auid != root", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Accepted password or publickey for user from remote IP", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Binary path for passwd or userdel, which may vary by distro", "field": "ExecPath"}, {"description": "Alert only if auid != root or expected service account", "field": "NonRootUIDThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3390', 0, 116, '09-mitre-attack', 'retrieved', '644EAA1146DB96182CDB0407AD80D8915166039A2BEBD8FD15210AF92CC47DAA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
