VALUES ('doc-09-mitre-attack-p0-3391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Kernel or userland processes generating high-rate network traffic (ICMP, UDP, TCP SYN) beyond expected interface throughput or user behavior norms.", "external_references": [{"external_id": "AN0970", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0343#AN0970"}], "id": "x-mitre-analytic--a94c1081-d66b-4009-95a9-247721fcd394", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0970", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connect or sendto system call with burst pattern", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold of repeated socket calls within a short interval indicating flood behavior.", "field": "SyscallBurstCount"}, {"description": "Restrict to non-admin user traffic unless elevated access is detected.", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3391', 0, 106, '09-mitre-attack', 'retrieved', '47E9CCCC402415E745C28626B0A79A55E78223DC1BA1D3A0337107F940CE26C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
