VALUES ('doc-09-mitre-attack-p0-3392', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unquoted service or shortcut paths that contain spaces and allow path interception by higher-level executables. Defender observes registry service configurations with unquoted paths, file creation of executables in parent directories of unquoted paths, and subsequent process execution from unexpected locations.", "external_references": [{"external_id": "AN0176", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0064#AN0176"}], "id": "x-mitre-analytic--a972f507-cf1b-4e2f-acdc-877a7891b7cf", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0176", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of critical services to check for unquoted paths in ImagePath registry keys.", "field": "MonitoredServices"}, {"description": "Executables with names matching potential interception targets (e.g., program.exe, net.exe).", "field": "SuspiciousBinaryList"}, {"description": "Correlation interval between file creation in parent directories and execution of unquoted path process.", "field": "TimeWindow"}, {"description": "Known good service paths for comparison against modified or unquoted values.", "field": "BaselineServiceConfig"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3392', 0, 163, '09-mitre-attack', 'retrieved', '862445ECBF7EC78837284AB4471D2224AF8FAAE65E2FA76D44683B4ECB4CDDD9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
