VALUES ('doc-09-mitre-attack-p0-3393', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious enumeration of attached peripherals via WMI, PowerShell, or low-level API calls potentially chained with removable device interactions.", "external_references": [{"external_id": "AN1353", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0491#AN1353"}], "id": "x-mitre-analytic--a986c8fd-6779-4769-895a-e6d167d9f1a9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1353", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex patterns for device enumeration utilities (e.g., ''Get-PnpDevice'', ''wmic path Win32_USBController'')", "field": "CommandLineRegex"}, {"description": "Time threshold for grouping device discovery with follow-on access or manipulation", "field": "TimeWindow"}, {"description": "Filter privileged or service accounts known to legitimately execute enumeration scripts", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3393', 0, 111, '09-mitre-attack', 'retrieved', '5CA5149B769A05E632A959F1BFDD43B7C80524DB4286BDA2397218A57A2CC254', 'v1', '{"source_id": "09-mitre-attack", "v