VALUES ('doc-09-mitre-attack-p0-3394', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disk enumeration via `diskutil list` or `system_profiler SPStorageDataType` run outside of user login or not associated with system inventory tools", "external_references": [{"external_id": "AN0538", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0188#AN0538"}], "id": "x-mitre-analytic--a98fc9c5-9c4c-47c5-a773-d68b523c7304", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0538", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process launch of diskutil or system_profiler with SPStorageDataType", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "log messages related to disk enumeration context or Terminal session", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unexpected use of disk enumeration tools from GUI apps or LaunchAgents may indicate abuse", "field": "launch_agent_context"}, {"description": "Filter known baseline volume names or identifiers used by common device configurations", "field": "volume_name_filter"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3394', 0, 119, '09-mitre-attack', 'retrieved', 'FE5AA9D1E7CC6D895F107A06FBAADF1DC625D8C655C244D48D38F009F7BCAF77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_ve