VALUES ('doc-09-mitre-attack-p0-3396', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for runtime manipulation by observing changes in application bundles, unexpected signing modifications, and runtime API calls that inject or alter how data is displayed. Detect alterations in CFNetwork or CoreFoundation frameworks responsible for rendering data.", "external_references": [{"external_id": "AN1099", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0391#AN1099"}], "id": "x-mitre-analytic--a9c30b9d-6810-47d3-8bf5-ca787836e7ef", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1099", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Unexpected application binary modifications or altered signing status", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "CALCULATE: Mismatch in file integrity of critical macOS applications", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelisted applications expected to handle sensitive runtime data.", "field": "AllowedApps"}, {"description": "Policy enforcement for validating application code signing integrity.", "field": "SignatureEnforcement"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3396', 0, 124, '09-mitre-attack', 'retrieved', '5F8BA5E824888E181058D458C328DBB7028694BA6D420BB8A06DA9B18F82171A',