VALUES ('doc-09-mitre-attack-p0-3397', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlation of registry key modification for Run/RunOnce with abnormal parent-child process relationships and outlier execution at user logon or system startup", "external_references": [{"external_id": "AN0764", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0274#AN0764"}], "id": "x-mitre-analytic--aa12f037-f724-43a6-97ca-e2e706859c1a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0764", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Customize based on expected parent-child process lineage for autostarts", "field": "ParentProcessName"}, {"description": "May vary based on organization policy or installed software", "field": "StartupRegistryPath"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3397', 0, 97, '09-mitre-attack', 'retrieved', 'BB0F67C6E96DB41C7E8B14418B930F8B3E990DD38E3A9AEB16F3EF3B65CB6D95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
