VALUES ('doc-09-mitre-attack-p0-3399', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of utilities (e.g., ping, tracert, Test-NetConnection) or scripted methods to test Internet connectivity by interacting with external IPs/domains.", "external_references": [{"external_id": "AN1015", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0357#AN1015"}], "id": "x-mitre-analytic--aa2dc7aa-0cc5-4a75-96b2-8c089c46944b", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1015", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=5156, 5157", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable external IP ranges or domains used to verify Internet access (e.g., 8.8.8.8, example.com)", "field": "DestinationIP"}, {"description": "Cluster rapid test connections with command execution in < 60 seconds", "field": "TimeWindow"}, {"description": "Filter out known admin/script contexts to reduce false positives", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3399', 0, 123, 