VALUES ('doc-09-mitre-attack-p0-3401', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "AppleScript, LaunchAgents, or remote login services (`ssh`, `networksetup`) establishing proxy tunnels or dynamic port forwards to external IPs or alternate local hosts.", "external_references": [{"external_id": "AN1231", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0445#AN1231"}], "id": "x-mitre-analytic--aace8c0e-4534-432b-9a84-6e01c19570b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1231", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "pf firewall logs", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "connection attempts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identify suspicious domains often associated with CDN-routed or anonymized endpoints (e.g., Cloudflare, Fastly).", "field": "TargetDomain"}, {"description": "Alert when AppleScript or Automator tools are used for network tunneling tasks.", "field": "AppleScriptUsage"}, {"description": "Monitor for LaunchAgents executing proxy tools or dynamic ports.", "field": "LaunchAgentSource"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3401', 0, 125, '09-mitre-attack', 'retrieved', 'BEB5859338B2B914C18C0BF6B5CF85154F2AA2A8AC8EF97812D43FD651050189', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
