VALUES ('doc-09-mitre-attack-p0-3402', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of discovery commands like `show cdp neighbors`, `show arp`, and other interface-level introspection on Cisco or Juniper devices.", "external_references": [{"external_id": "AN1587", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0574#AN1587"}], "id": "x-mitre-analytic--aad71d3e-93b0-4cb6-8240-274369f8ad34", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1587", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "syslog facility LOCAL7 or trap messages", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Device-specific recon commands to monitor based on make/model", "field": "CommandList"}, {"description": "Trigger detection for privilege escalation prior to recon commands", "field": "PrivLevel"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3402', 0, 93, '09-mitre-attack', 'retrieved', '7B522DBC1A52C049EE344FB1A25B59B6DEBE83B24A1DB15CECD6DB163928619B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
