VALUES ('doc-09-mitre-attack-p0-3403', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of esxcli commands to enumerate datastore, configuration files, or directory structures by unauthorized or remote users.", "external_references": [{"external_id": "AN1043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0370#AN1043"}], "id": "x-mitre-analytic--aaddc766-52bb-428b-98c4-3a742d10befa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1043", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Shell Access/Command Execution", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "vSphere File API Access", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Match on esxcli storage|filesystem commands", "field": "CLICommandPattern"}, {"description": "Limit alerting to non-vCenter or remote IPs", "field": "AccessSource"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3403', 0, 91, '09-mitre-attack', 'retrieved', 'CC0A717DE44D1C70FD22944E9ACFE9A22B12C04AA772EFC8575B5D884B64871C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
