VALUES ('doc-09-mitre-attack-p0-3404', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).", "external_references": [{"external_id": "AN0161", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0058#AN0161"}], "id": "x-mitre-analytic--aae03a6c-b308-49cb-bb85-7be4a5c2a4bb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0161", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Network Events", "name": "esxi:vobd", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Outbound Connections", "name": "NSM:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identifies unusual IP destinations embedded in traffic", "field": "DestinationIP"}, {"description": "Used to detect uncommon protocols (e.g., DNS over HTTPS)", "field": "Protocol"}, {"description": "Used to correlate outbound web requests with process execution", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3404', 0, 114, '09-mitre-attack', 'retrieved', '3A52601C1A54BBDBF1D6187544637B2AAE511BD0E0EDDC5BBF390BAB1B0C26D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
