INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3406', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders may detect abuse of container administration commands by observing anomalous use of management utilities (`docker exec`, `kubectl exec`, or API calls to kubelet) correlated with unexpected process creation inside containers. Behavioral chains include unauthorized API requests followed by command execution within running pods or containers, often originating from unusual user accounts, automation scripts, or IP addresses outside the expected cluster management plane.", "external_references": [{"external_id": "AN0177", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0065#AN0177"}], "id": "x-mitre-analytic--ab1122c5-f459-4097-8ba7-f5a7960d2da5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0177", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "docker exec or docker run with unexpected command/entrypoint", "name": "docker:daemon", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "kubectl exec or kubelet API calls targeting running pods", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected admin accounts allowed to use exec commands; anomalies outside this list indicate possible abuse.", "field": "AuthorizedAdminUsers"}, {"description": "Defines how often `docker exec` or `kubectl exec` is normally observed; sudden spikes may indicate adversary behavior.", "field": "ExecFrequencyThreshold"}, {"description": "Expected IP ranges for management actions (e.g., cluster control plane). Requests from external/unexpected ranges may indicate compromise.", "field": "SourceIPRange"}, {"description": "Defines which namespaces typically allow exec operations; anomalous activity outside these may indicate lateral movement.", "field": "NamespaceScope"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3406', 0, 205, '09-mitre-attack', 'retrieved', '7A4E4EE7924A3A31B022356CE9FCA9BFE380840C17A67FC0B4B5248294078D88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
