VALUES ('doc-09-mitre-attack-p0-3407', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access (ex: [Phishing](https://attack.mitre.org/techniques/T1566)).", "external_references": [{"external_id": "AN1993", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0861#AN1993"}], "id": "x-mitre-analytic--ab74118c-05e1-4acd-b1c2-445d1f7c5fd1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1993", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3407', 0, 76, '09-mitre-attack', 'retrieved', '74236C62B2DBA7ABF1B1B78C5314BDD8714710790829BBE0279E0ECA4F6C3A8C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
