INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3408', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of xclip or xsel access to clipboard buffers outside of user terminal context, especially when chained to staging (gzip, base64) or network exfiltration (curl, scp).", "external_references": [{"external_id": "AN0967", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0341#AN0967"}], "id": "x-mitre-analytic--ab9a4c72-f7ce-4721-8c9f-c5d9c966b600", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0967", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tool used (xclip, xsel, custom clipboard-read binary).", "field": "ClipboardCommand"}, {"description": "Temporal window to chain staging or network activity with clipboard access.", "field": "CorrelationWindow"}, {"description": "Was access linked to interactive user TTY?", "field": "TTYLinked"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3408', 0, 105, '09-mitre-attack', 'retrieved', '2FB78E49396442A985E3536BCAB621398A4AAE85190924319D2BFDD8CD67EBBD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
