VALUES ('doc-09-mitre-attack-p0-3410', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account created in a running container (e.g., via ''useradd'' or by modifying /etc/passwd directly). Detectable via runtime telemetry (e.g., Falco or eBPF hooks).", "external_references": [{"external_id": "AN1239", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0447#AN1239"}], "id": "x-mitre-analytic--ac204e03-5c8c-4e29-929c-780145a98669", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1239", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "useradd or /etc/passwd modified inside container", "name": "ebpf:syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Distinguish between ephemeral containers and long-lived service containers", "field": "ContainerContext"}, {"description": "Determine if account was added inside host, user, or PID namespace", "field": "NamespaceScope"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3410', 0, 98, '09-mitre-attack', 'retrieved', '8F45C0C42CF047F137A554D7D6A18C29DCD1B4FF6832008444CC12E9BDA222D9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
