VALUES ('doc-09-mitre-attack-p0-3411', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unexpected access or usage of cloud productivity tools (e.g., downloading large numbers of files, creating external shares) by internal users.", "external_references": [{"external_id": "AN1505", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0546#AN1505"}], "id": "x-mitre-analytic--ac36f883-9a5b-4796-9f2e-18f1cce8fc0b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1505", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FileAccessed, SharingSet", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "drive.activity", "name": "gcp:audit", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines excessive access based on number or size of downloads.", "field": "FileDownloadThreshold"}, {"description": "Defines external sharing behaviors that violate policy.", "field": "SharingPolicyViolationThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3411', 0, 96, '09-mitre-attack', 'retrieved', '3C4FBBF17C5442C01280DD3663E91E1EBD090A4D9BC338331BEFF8AFCC299162', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
