INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3412', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.", "external_references": [{"external_id": "AN1998", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0866#AN1998"}], "id": "x-mitre-analytic--ac4bf64e-da14-4416-8961-f0736eb4d9be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1998", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["PRE"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3412', 0, 70, '09-mitre-attack', 'retrieved', 'E9F359195AA0D9C7AB6D750CE4A2A575530EE0873F0F9BA3B179F33FC4099878', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
