VALUES ('doc-09-mitre-attack-p0-3413', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud control plane actions disabling security services (CloudTrail logging, GuardDuty, Security Hub). Detect IAM role abuse correlating with service disable events.", "external_references": [{"external_id": "AN0891", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0317#AN0891"}], "id": "x-mitre-analytic--ac692681-2851-41b4-aff9-4b5efc4c40c8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0891", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "StopLogging, DeleteTrail, or DisableSecurityService", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify which cloud services (logging, monitoring, threat detection) must never be disabled.", "field": "ServiceScope"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3413', 0, 84, '09-mitre-attack', 'retrieved', '204E3FE4F54A37BC2E9D39E154CAFDACD824F1B857BD21D4FBC751B12935639E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
