INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3414', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Crafted ‘synful knock’ patterns toward routers/switches (same src hits interface/broadcast/network address on same port in short order) followed by ACL/telnet/SSH enablement or module change. Detect device image/ACL updates then a new mgmt session.", "external_references": [{"external_id": "AN1451", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0524#AN1451"}], "id": "x-mitre-analytic--ac933d77-bdb6-45ed-8fb5-87bae6f225cb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1451", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Config/ACL/line vty changes, service enable (telnet/ssh/http(s)), module reloads", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Port-knock pattern from one src to device unicast,broadcast,network addresses on same port within TimeWindowKnock", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Ports whose sudden enablement should alert (23, 22, 2323, 80/443, 4786).", "field": "MgmtPortSet"}, {"description": "Applies different thresholds to core/edge/branch devices.", "field": "DeviceRole"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3414', 0, 128, '09-mitre-attack', 'retrieved', '3D4DDBBFCC732268AA5437BA0527DD190C345AEDF43357BD019FB619C14E55FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
