VALUES ('doc-09-mitre-attack-p0-3415', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects mounting of external volumes followed by high-volume or sensitive file access via Finder, terminal, or third-party apps (e.g., rsync, zip).", "external_references": [{"external_id": "AN0344", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0123#AN0344"}], "id": "x-mitre-analytic--acaabb0b-6cfc-45cd-8bd9-08ad49e1096c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0344", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Volume Mount + File Read", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "file system activity monitor", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect suspicious or unrecognized drive labels (e.g., UNTITLED, BACKUP_VOL).", "field": "VolumeNamePattern"}, {"description": "Detect CLI-based copy operations vs. expected GUI usage.", "field": "ProcessOrigin"}, {"description": "Alert if process and session context are mismatched (e.g., script from screensaver context).", "field": "UserSessionCheck"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3415', 0, 124, '09-mitre-attack', 'retrieved', '8D56608ABB96775EEE4F50EAF595DB2AFC98370BC24BEBEF59C61EFA3D39D75B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
