VALUES ('doc-09-mitre-attack-p0-3419', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of dscl or sysadminctl commands to disable, delete, or modify users combined with anomalous process ancestry or terminal session launch.", "external_references": [{"external_id": "AN0336", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0120#AN0336"}], "id": "x-mitre-analytic--adbe8ef2-15e5-4fb9-83d8-4c67b7b1be78", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0336", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "command includes dscl . delete or sysadminctl --deleteUser", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "successful sudo or authentication for account not normally associated with admin actions", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allow variation in dscl/sysadminctl command structure", "field": "CommandLinePattern"}, {"description": "Detect new or rarely seen users performing user removal", "field": "AnomalousUserFlag"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3419', 0, 111, '09-mitre-attack', 'retrieved', '7C2D257FDB66D33A8A7C87D64B75864DC02091AF236E1599A7F62A3C3ADC9E6A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
