VALUES ('doc-09-mitre-attack-p0-3420', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Repetitive triggering of GUI or backend application workflows that cause increased CPU/memory usage, logged in unified logs as spin reports or crash dumps.", "external_references": [{"external_id": "AN1167", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0415#AN1167"}], "id": "x-mitre-analytic--ade844ef-f156-4db2-bc11-9dbdc006c8d6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1167", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Application errors or resource contention from excessive frontend or script invocation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Rapid spawning of resource-heavy applications (e.g., Preview, Safari, Office)", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for number of system spin/crash reports in a defined window.", "field": "SpinReportCount"}, {"description": "Frequency of user or script reopening GUI-heavy apps.", "field": "HeavyAppReopenRate"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3420', 0, 117, '09-mitre-attack', 'retrieved', 'F64ED358A68EDA6D7969A92EC9197D70D8FA75215A2E5A7C042CF023582B33AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_