VALUES ('doc-09-mitre-attack-p0-3422', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multiple AWS CloudTrail events indicating temporary privilege escalation via PassRole and AssumeRole targeting newly created services or non-interactive infrastructure.", "external_references": [{"external_id": "AN1105", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0393#AN1105"}], "id": "x-mitre-analytic--adfcc782-0285-43ef-af18-127dd60d1dff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1105", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PassRole", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define which roles are allowed to be assumed or passed; restrict highly privileged roles.", "field": "targetRoleName"}, {"description": "Time range between PassRole and AssumeRole events to link the privilege chain.", "field": "TimeWindow"}, {"description": "Restrict which services are authorized to invoke role passing (e.g., Lambda, EC2).", "field": "invokingService"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3422', 0, 111, '09-mitre-attack', 'retrieved', 'CAE0D4954E2D9A6404DA6A518B8F40FA23DF0A0C2816DB511710644FA738CE26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
