VALUES ('doc-09-mitre-attack-p0-3425', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors Mail.app database or maildir file access, automation via AppleScript, and abnormal mail rule creation using scripting or UI automation frameworks.", "external_references": [{"external_id": "AN1311", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0476#AN1311"}], "id": "x-mitre-analytic--ae581308-5c1f-40b9-ae6e-51c375821476", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1311", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Mail or AppleScript subsystem", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "es_event_open, es_event_exec", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Script interpreters or automation tools (osascript, Automator, etc.)", "field": "ScriptProcessNameList"}, {"description": "Mail.app SQLite DB or .emlx directory", "field": "WatchedMailFiles"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3425', 0, 96, '09-mitre-attack', 'retrieved', 'F8F1C6D465D5B670F94D94F9D4F1A2D2C77E417AABAF8F5DA5F39593035B36DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
