INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3426', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain: (1) a user or service spawns a shell/PowerShell that queries local/domain password policy via commands/cmdlets (e.g., `net accounts`, `Get-ADDefaultDomainPasswordPolicy`, `secedit /export`); (2) optional directory/LDAP reads from DCs; (3) same principal performs adjacent Discovery or credential-related actions within a short window. Correlate sysmon process creation with PowerShell ScriptBlock and Security logs.", "external_references": [{"external_id": "AN0455", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0161#AN0455"}], "id": "x-mitre-analytic--ae82099a-0baf-4887-953c-67ef5e2d4470", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0455", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=4662", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window between policy query and adjacent suspicious activity (e.g., 15–30 minutes).", "field": "TimeWindow"}, {"description": "Accounts (e.g., Helpdesk) allowed to run policy queries routinely.", "field": "PrivilegedUserAllowList"}, {"description": "Limit alerts on DCs/management servers; raise on user workstations/VDI.", "field": "HostRoleScope"}, {"description": "Cmdlet/function names to treat as high-signal in your environment.", "field": "PS_ScriptBlockPatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3426', 0, 163, '09-mitre-attack', 'retrieved', '01AD5FE3CD1BE439BB230FBFA2476FE2DE2F33979B63DE4ED7B545FC5A364C76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
