INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-3427', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abuse of UNIX domain sockets, pipes, or message queues for unauthorized code execution. Correlates unexpected socket creation with suspicious binaries, abnormal shell pipelines, or injected processes establishing IPC channels.", "external_references": [{"external_id": "AN1358", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0493#AN1358"}], "id": "x-mitre-analytic--ae8e028c-2c3a-4ac0-964f-d0b59533190d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1358", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket: Suspicious creation of AF_UNIX sockets outside expected daemons", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open: Access to named pipes or FIFO in /tmp or /dev/shm by unexpected processes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected UNIX socket paths used by system services and applications.", "field": "SocketPathBaseline"}, {"description": "Legitimate processes expected to open pipes in shared directories.", "field": "FIFOAccessPatterns"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3427', 0, 127, '09-mitre-attack', 'retrieved', '176D9B717329168F5164135D3B84F5086EB7AD5BD8E76F2B55B753556FF81325', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
