VALUES ('doc-09-mitre-attack-p0-3428', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unauthorized use of SMTP/IMAP/POP3 by suspicious binaries (e.g., PowerShell, rundll32) to exfiltrate data or beacon via email, often bypassing proxy or content filters.", "external_references": [{"external_id": "AN0379", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0135#AN0379"}], "id": "x-mitre-analytic--aef3d563-19f5-4d52-b7ad-4c4abadcb568", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0379", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "smtp.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit to uncommon clients (e.g., scripts or CLI tools using .NET SMTP libraries)", "field": "ProcessImageName"}, {"description": "Typically 25, 587, 993, 995, or 465 – flag anomalies", "field": "DestPortFilter"}, {"description": "Flag suspicious attachments (e.g., .zip, .7z, .bin)", "field": "AttachmentType"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3428', 0, 121, '09-mitre-attack', 'retrieved', '4C352CCAF0BE75553F0D303C5057EC76C10FA1603C0B268EA05B3799C7167995', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
