VALUES ('doc-09-mitre-attack-p0-3429', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects JavaScript for Automation (JXA) via osascript or compiled scripts using OSAKit APIs. Flags execution involving system modification, inter-process scripting, or browser abuse.", "external_references": [{"external_id": "AN0734", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0264#AN0734"}], "id": "x-mitre-analytic--af3dff40-40be-40dd-9a0e-a47cf052880b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0734", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream with predicate ''eventMessage CONTAINS \"osascript\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/system.log", "name": "macos:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Execution of JXA from user-controlled paths like ~/Downloads or /Volumes.", "field": "ScriptLocation"}, {"description": "osascript invoked by third-party apps (VSCode, browsers, etc.).", "field": "ParentProcess"}, {"description": "Use of OSAKit API by apps not typically scripting-enabled.", "field": "APIInvocation"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3429', 0, 122, '09-mitre-attack', 'retrieved', '6C0E5157D557CF4A93F74D7B90B23CA400761C700F376A2613DF4420C97F8BB0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
