VALUES ('doc-09-mitre-attack-p0-3430', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Deletion or disablement of user accounts in platforms like Okta, Salesforce, or Zoom with anomalies in admin session attributes or mass actions within short duration.", "external_references": [{"external_id": "AN0339", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0120#AN0339"}], "id": "x-mitre-analytic--af7bff30-45c5-4baf-9ced-68208b7ae836", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0339", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "user.lifecycle.delete, user.account.lock", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Trigger if multiple deletions occur within a short period", "field": "BulkActionThreshold"}, {"description": "Alert on deletions initiated from unfamiliar device contexts", "field": "SessionDeviceType"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-3430', 0, 94, '09-mitre-attack', 'retrieved', '70271B0C09CF6C258A9FE1B68625D2A9D893429D864016BB4AAD5E353EE5F2CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
