VALUES ('doc-09-mitre-attack-p0-3432', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Privileged or rarely used accounts performing bulk access to SharePoint files or metadata over a short time window, indicating potential scripted collection of sensitive internal documents.", "external_references": [{"external_id": "AN1380", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0500#AN1380"}], "id": "x-mitre-analytic--afb1860a-e29a-4ce8-9524-ab371c5f8d4f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1380", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FileAccessed, FileDownloaded, SearchQueried", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "UserLogin, ConditionalAccessPolicyEvaluated", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Multiple file download operations on a site by a privileged account in a short time window", "name": "m365:sharepoint", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be adjusted to focus on specific high-privilege or rarely-used service accounts", "field": "UserContext"}, {"description": "Defines the aggregation period for multiple download events (e.g., 10 minutes)", "field": "TimeWindow"}, {"description": "Minimum number of documents accessed/downloaded to trigger alert", "field":